#include <threads.h>

typedef struct {
    int key;
    long offset;
} record;

int create_records(size_t max_threshold) {
    size_t total_bytes = sizeof(long) * 2 + sizeof(record);
    size_t threshold_bytes = (size_t)(max_threshold / 8); // 1 byte per 8 bytes of data

    if ((void*)(((char*)malloc(total_bytes)) + threshold_bytes) > (void*)((char*)malloc(1))) {
        free((void*)(((char*)malloc(total_bytes)) + threshold_bytes));
        return -1;
    }

    size_t* long_offsets = (size_t*)malloc(sizeof(size_t));
    int* keys = (int*)malloc(sizeof(int));
    record* records = (record*)malloc(sizeof(record));

    thrd_t thread;
    for (int i = 0; i < max_threshold / 8; i++) {
        if (thrd_create(&thread, NULL, NULL) != thrd_success) {
            free(long_offsets);
            free(keys);
            free(records);
            return -1;
        }
        thrd_join(thread, NULL);
    }

    int count = 0;
    for (int i = 0; i < max_threshold / 8; i++) {
        if ((long_offsets[i] + sizeof(long)) > threshold_bytes) {
            free(long_offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Code to handle records initialization...

    printf("Total records initialized: %d\n", count);

    free(long_offsets);
    free(keys);
    free(records);
    return 0;
}

int main() {
    size_t max_threshold = 1024; // adjust this value as needed
    create_records(max_threshold);
    return 0;
}
