#include <resolv.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16
#define MAX_LINE 1024

typedef struct {
    char* hostname;
    u_char ip_address[MAX_IP_ADDRESS];
} DNSResult;

DNSResult* perform_dns_resolution(const char* hostname) {
    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd == -1) {
        return NULL;
    }

    struct hostent* host_info = gethostbyname(hostname);
    if (!host_info) {
        close(socket_fd);
        return NULL;
    }

    char* ip_address = inet_ntoa(*((struct in_addr*)host_info->h_addr));
    DNSResult* result = (DNSResult*)malloc(sizeof(DNSResult));
    strcpy(result->hostname, hostname);
    strncpy((char*)result->ip_address, ip_address, MAX_IP_ADDRESS);

    close(socket_fd);
    return result;
}

int main() {
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        return 1;
    }

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), file)) {
        size_t i = 0;
        for (; i < strlen(line); i++) {
            if (line[i] == ',') {
                line[i] = '\0';
                break;
            }
        }

        double num1 = strtod(line, NULL);
        fgets(line, sizeof(line), file);
        double num2 = strtod(line, NULL);

        char buffer[256];
        sprintf(buffer, "%f,%f", num1, num2);

        printf("%s\n", buffer);
    }

    fclose(file);
    return 0;
}
