int process_integers(int *max_val) {
    int i = 0;
    int size = 10; // Initial array size
    int *arr = (int *)malloc(size * sizeof(int));

    while(1) {
        int input;
        if(scanf("%d", &input) != 1) { // Handle non-integer values
            if(feof(stdin)) { // Handle end of file
                free(arr);
                return 0; // No more integers to process
            } else {
                printf("Invalid input. Please enter an integer.\n");
                continue;
            }
        }

        if(input < -1000 || input > 1000) { // Validate range
            printf("Integer out of range. Valid range is -1000 to 1000.\n");
            continue;
        }

        arr[i++] = input; // Store valid integer

        if(i >= size) {
            size *= 2; // Dynamically allocate memory
            arr = (int *)realloc(arr, size * sizeof(int));
        }

        if(feof(stdin)) { // Handle end of file
            free(arr);
            return i; // Number of valid integers processed
        }
    }

    free(arr); // Free dynamically allocated memory
    return 0;
}
