#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define LOG_BUFFER_SIZE 1024
#define MAX_LOG_LEVELS 5 // DEBUG, INFO, WARNING, ERROR, FATAL
#define MAX_FORMAT_STRING_LENGTH 256

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    FATAL
} log_level_t;

// Circular buffer structure
typedef struct {
    char *buf;
    size_t size;
    pthread_mutex_t mutex;
    size_t head, tail;
} log_buffer_t;

// Function prototypes
void log_append(log_buffer_t *buffer, const char *fmt, ...);
log_buffer_t* init_log_buffer();
void free_log_buffer(log_buffer_t *buffer);

// Initialize the log buffer
log_buffer_t* init_log_buffer() {
    log_buffer_t *buffer = (log_buffer_t*) malloc(sizeof(log_buffer_t));
    if (!buffer) return NULL;
    buffer->buf = (char*) malloc(LOG_BUFFER_SIZE);
    if (!buffer->buf) {
        free(buffer);
        return NULL;
    }
    buffer->size = LOG_BUFFER_SIZE;
    pthread_mutex_init(&buffer->mutex, NULL);
    buffer->head = buffer->tail = 0;
    return buffer;
}

// Free the log buffer
void free_log_buffer(log_buffer_t *buffer) {
    if (!buffer) return;
    free(buffer->buf);
    free(buffer);
}

// Append a formatted log entry to the circular buffer
void log_append(log_buffer_t *buffer, const char *fmt, ...) {
    pthread_mutex_lock(&buffer->mutex);

    // Check for buffer overflow and wrap around if necessary
    size_t current_size = buffer->size - (buffer->head - buffer->tail);
    if (current_size < sizeof(char) + strlen(fmt)) {
        if (current_size > 0) {
            memmove(buffer->buf, &buffer->buf[buffer->tail], current_size);
        } else {
            memset(buffer->buf, '\0', buffer->size);
            buffer->head = buffer->tail = 0;
        }
    }

    va_list ap;
    va_start(ap, fmt);
    size_t len = vsnprintf(&buffer->buf[buffer->tail], current_size, fmt, ap) + 1;
    va_end(ap);

    // Wrap around if necessary
    if (len > current_size) {
        buffer->head = 0;
        buffer->tail = len;
    } else {
        buffer->tail += len;
    }

    pthread_mutex_unlock(&buffer->mutex);
}
