import hashlib
import os
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
import json

class FileHasher:
    def __init__(self):
        self.config = self.load_config()
        self.logger = logging.getLogger('file_hasher')

    def load_config(self):
        try:
            with open('config.json') as f:
                return json.load(f)
        except FileNotFoundError:
            return {'ignore_extensions': ['txt', 'log']}

    def hash_file(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                chunk_size = 4096
                md = hashlib.sha256()
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break
                    md.update(chunk)
                return md.hexdigest()
        except FileNotFoundError:
            self.logger.error(f"File '{file_path}' not found")
            return None

    def hash_directory(self, directory_path):
        files_to_process = []
        for root, dirs, files in os.walk(directory_path):
            for file in files:
                if os.path.splitext(file)[1][1:] not in self.config['ignore_extensions']:
                    files_to_process.append(os.path.join(root, file))

        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = {executor.submit(self.hash_file, file): file for file in files_to_process}

            total_files = len(files_to_process)
            success_count = 0
            failed_files = []

            for future in as_completed(futures):
                file_path = futures[future]
                try:
                    hash_result = future.result()
                    if hash_result is not None:
                        self.logger.info(f"File '{file_path}' hashed successfully")
                        success_count += 1
                    else:
                        failed_files.append(file_path)
                except Exception as e:
                    self.logger.error(f"Error hashing file '{file_path}': {str(e)}")
                    failed_files.append(file_path)

            self.logger.info(f"Total files processed: {total_files}")
            self.logger.info(f"Files hashed successfully: {success_count}")
            self.logger.info(f"Failed files: {failed_files}")

if __name__ == "__main__":
    file_hasher = FileHasher()
    file_hasher.hash_directory('/path/to/directory')
