public class PokemonReporter {
    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/{pokemon_id}/";
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MILLISECONDS = 1000;

    public List<PokemonReport> generateReports(List<Pokemon> pokemons) throws IOException, InterruptedException {
        List<PokemonReport> reports = new ArrayList<>();
        HttpClient client = HttpClient.newHttpClient();
        ObjectMapper mapper = new ObjectMapper();

        for (Pokemon pokemon : pokemons) {
            PokemonReport report = new PokemonReport();
            report.setName(pokemon.getName());

            // Fetch Pokémon data from API
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(API_URL.replace("{pokemon_id}", String.valueOf(pokemon.getId()))))
                    .get()
                    .build();
            HttpResponse<String> response;
            int retries = 0;
            while (retries < MAX_RETRIES) {
                try {
                    response = client.send(request, HttpResponse.BodyHandlers.ofString());
                    break;
                } catch (IOException | InterruptedException e) {
                    if (retries >= MAX_RETRIES - 1) {
                        throw new IOException("Failed to retrieve Pokémon data", e);
                    }
                    Thread.sleep(RETRY_DELAY_MILLISECONDS);
                    retries++;
                }
            }

            // Validate API response
            JsonNode json = mapper.readTree(response.body());
            if (!json.has("name") || !json.has("types")) {
                throw new IOException("Invalid or missing fields in API response");
            }

            // Process Pokémon data
            ObjectNode pokemonJson = (ObjectNode) json;
