            for (JsonNode type : types) {
                String primaryType = type.get("type").asText();
                String secondaryType = type.get("secondary_type") != null ? type.get("secondary_type").asText() : null;
                report.setPrimaryWeakness(getWeakness(primaryType));
                report.setSecondaryWeakness(secondaryType == null ? getWeakness(secondaryType) : secondaryType);
