            int defense = pokemonJson.get("stats").get(1).get("base_stat").asInt();
            int specialAttack = pokemonJson.get("stats").get(2).get("base_stat").asInt();
            int specialDefense = pokemonJson.get("stats").get(3).get("base_stat").asInt();
            int speed = pokemonJson.get("stats").get(4).get("base_stat").asInt();
            report.setCombatStats(Map.of(
                    "attack", attack,
                    "defense", defense,
                    "special_attack", specialAttack,
                    "special_defense", specialDefense,
                    "speed", speed
            ));

            reports.add(report);
        }

        return reports;
    }

