#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

// Structure to hold semaphore data
typedef struct {
    sem_t *sem;
    char name[20];
} SemaphoreData;

// Array of semaphore data, dynamically sized
SemaphoreData **semaphores = NULL;
int num_semaphores = 0;

// Function to create a new semaphore with the given initial value and name
void* create_semaphore(void* id) {
    int initial_value = *((int*)id);
    char identifier[10];
    sprintf(identifier, "semaphore-%d", *((int*)id));

    // Check if semaphore already exists
    for (int i = 0; i < num_semaphores; i++) {
        if (!strcmp(semaphores[i]->name, identifier)) {
            // Append version number to the name
            sprintf(identifier, "%s-v%d", identifier, i);
            break;
        }
    }

    semaphores = realloc(semaphores, (num_semaphores + 1) * sizeof(SemaphoreData*));
    semaphores[num_semaphores] = malloc(sizeof(SemaphoreData));
    strcpy(semaphores[num_semaphores]->name, identifier);
    semaphores[num_semaphores]->sem = sem_open(identifier, O_CREAT | O_EXCL, 0644, initial_value);

    num_semaphores++;
    return NULL;
}

// Function to acquire a semaphore
void* acquire_semaphore(void* semaphore_id) {
    int id = *((int*)semaphore_id);
    SemaphoreData* semaphore = semaphores[id];

    // Acquire the semaphore
    if (sem_wait(semaphore->sem) == -1) {
        // Handle error
        printf("Error acquiring semaphore %s\n", semaphore->name);
    }

    return NULL;
}

// Function to release a semaphore
void* release_semaphore(void* semaphore_id) {
    int id = *((int*)semaphore_id);
    SemaphoreData* semaphore = semaphores[id];

    // Release the semaphore
    if (sem_post(semaphore->sem) == -1) {
        // Handle error
        printf("Error releasing semaphore %s\n", semaphore->name);
    }

    return NULL;
}

// Function to delete a semaphore and its resources
void* delete_semaphore(void* semaphore_id) {
    int id = *((int*)semaphore_id);
    SemaphoreData* semaphore = semaphores[id];

    // Close the semaphore
    if (sem_close(semaphore->sem) == -1) {
        // Handle error
        printf("Error closing semaphore %s\n", semaphore->name);
    }

    // Remove the semaphore from the list and free its memory
    for (int i = id; i < num_semaphores; i++) {
        semaphores[i]->sem = semaphores[i + 1]->sem;
        strcpy(semaphore->name, semaphores[i]->name);
    }
    semaphores = realloc(semaphores, (num_semaphores - 1) * sizeof(SemaphoreData*));
    free(semaphore);
    num_semaphores--;

    return NULL;
}

// Function to initialize the semaphore system
void init_semaphore_system() {
    // Initialize the array of semaphore data with a default size
    semaphores = malloc(sizeof(SemaphoreData*) * 10);
    num_semaphores = 0;
}

// Function to clean up the semaphore system
void cleanup_semaphore_system() {
    for (int i = 0; i < num_semaphores; i++) {
        delete_semaphore(&i);
    }
    free(semaphores);
}
