#include <vector>
#include <memory>
#include <iostream>

class Config {
public:
    int targetCapacityThreshold;
    int memoryUsageLimit;
};

int insertOrAppend(std::vector<std::unique_ptr<int>>& vec, int valueToInsert, int valueToFind, const Config& config) {
    int totalInsertions = 0;

    // Find the first occurrence of the value to find
    auto it = std::find_if(vec.begin(), vec.end(),
        [valueToFind](const auto& ptr) { return *ptr == valueToFind; });

    if (it != vec.end()) {
        // Calculate the new capacity based on the target threshold and memory limit
        int newCapacity = std::max(int(vec.capacity() * 1.5f), config.targetCapacityThreshold);
        newCapacity = std::min(newCapacity, config.memoryUsageLimit);

        vec.reserve(newCapacity);

        // Insert the value to insert after the found element
        vec.insert(it + 1, std::make_unique<int>(valueToInsert));
        totalInsertions++;
    } else {
        // Append the value to insert if not found
        vec.push_back(std::make_unique<int>(valueToInsert));
        totalInsertions++;
    }

    return totalInsertions;
}
