class BackendServer {
public:
    virtual ~BackendServer() {}
    virtual std::string makeRequest(const std::string& request) = 0;
};

class InterfaceTable {
public:
    virtual ~InterfaceTable() {}
    virtual bool isAvailable(int serverId) = 0;
    virtual int getResponseTime(int serverId) = 0;
};

class LoadBalancedClient {
private:
    std::vector<std::unique_ptr<BackendServer>> servers;
    InterfaceTable& interfaceTable;
    int timeoutSecs;
    int maxRetries;

public:
    LoadBalancedClient(InterfaceTable& table, int timeoutSecs = 10, int maxRetries = 3)
        : interfaceTable(table), timeoutSecs(timeoutSecs), maxRetries(maxRetries) {}

    void makeRequest(const std::string& request) {
        int bestServerId;
        for (int i = 0; i < servers.size(); ++i) {
            if (interfaceTable.isAvailable(i)) {
                bestServerId = i;
                break;
            }
        }

        if (!bestServerId) {
            // No available server, retry later
            return;
        }

        int retriesLeft = maxRetries;
        while (true) {
            std::string response = servers[bestServerId]->makeRequest(request);
            if (response.size() > 0) {
                // Response received successfully
                break;
            } else if (--retriesLeft > 0) {
                // Server unavailable, try another one
                bestServerId = getBestAvailableServer();
                if (!bestServerId) {
                    // No available server after max retries, give up
                    return;
                }
            } else {
                // Max retries exceeded, fail request
                return;
            }

            // Wait for some time before retrying
            std::this_thread::sleep_for(std::chrono::seconds(timeoutSecs));
        }

        // Log response and update server metrics
    }

private:
    int getBestAvailableServer() {
        int bestServerId = -1;
        int minResponseTime = interfaceTable.getResponseTime(0);

        for (int i = 0; i < servers.size(); ++i) {
            if (interfaceTable.isAvailable(i)) {
                int responseTime = interfaceTable.getResponseTime(i);
                if (responseTime < minResponseTime) {
                    bestServerId = i;
                    minResponseTime = responseTime;
                }
            }
        }

        return bestServerId;
    }
};

int main() {
    InterfaceTable table; // Mock object for testing

    LoadBalancedClient client(table);

    // Simulate requests and logging
    // ...

    return 0;
}
