class Logger {
public:
    enum LogLevel { DEBUG, INFO, WARN, ERROR };

    void setLevel(LogLevel level) {
        this->level = level;
    }

    template <typename T>
    void log(LogLevel level, const std::string& message, T&& arg) {
        if (this->level <= level) {
            std::lock_guard<std::mutex> lock(mutex);
            std::unique_lock<std::mutex> uniqueLock(uniqueMutex);

            // Use a condition variable to ensure that logging is thread-safe
            cv.wait(uniqueLock, [this]() { return this->isThreadSafe; });

            // Perform actual logging here
            std::cout << message << " " << arg << std::endl;

            // Release the lock after logging
            cv.notify_all();
        }
    }

private:
    LogLevel level;
    std::mutex mutex;
    std::condition_variable cv;
    bool isThreadSafe = true;

    void setThreadSafety(bool threadSafe) {
        this->isThreadSafe = threadSafe;
    }
};

class LogOutput {
public:
    virtual ~LogOutput() {}
    virtual void write(const std::string& message) = 0;
};

class ConsoleLogOutput : public LogOutput {
public:
    void write(const std::string& message) override {
        std::cout << message << std::endl;
    }
};

class FileLogOutput : public LogOutput {
public:
    FileLogOutput(const std::string& filePath)
        : filePath_(filePath), fileStream_(filePath_.c_str()) {}

    void write(const std::string& message) override {
        fileStream_ << message << std::endl;
    }

private:
    std::string filePath_;
    std::ofstream fileStream_;
};

class NetworkLogOutput : public LogOutput {
public:
    void write(const std::string& message) override {
        // Implement network log output here
    }
};

class LoggerConfig {
public:
    enum OutputType { CONSOLE, FILE, NETWORK };

    LoggerConfig() : level_(Logger::DEBUG), outputs_({}) {}

    void setLevel(Logger::LogLevel level) {
        this->level_ = level;
    }

    void addOutput(LogOutput* output) {
        this->outputs_.insert(output);
    }

private:
    Logger::LogLevel level_;
    std::map<LogOutput*, bool> outputs_;
};

int main() {
    // Create a logger and configure it
    LoggerConfig config;
    config.setLevel(Logger::INFO);

    LogOutput* consoleOutput = new ConsoleLogOutput();
    LogOutput* fileOutput = new FileLogOutput("log.txt");

    config.addOutput(consoleOutput);
    config.addOutput(fileOutput);

    // Use the logger
    Logger logger;
    logger.log(Logger::INFO, "Hello, world!", 42);

    return 0;
}
