namespace GameConfigurator
{
    public class GameEnvironment
    {
        public int Resolution { get; set; }
        public int FrameRateLimit { get; set; }
        public int NetworkLatency { get; set; }
        public string ServerConnectionString { get; set; }
    }

    class Program
    {
        static void Main(string[] args)
        {
            GameEnvironment gameEnv = new GameEnvironment();

            // Get environment variables
            gameEnv.Resolution = Convert.ToInt32(Environment.GetEnvironmentVariable("RESOLUTION"));
            gameEnv.FrameRateLimit = Convert.ToInt32(Environment.GetEnvironmentVariable("FRAMERATELIMIT"));
            gameEnv.NetworkLatency = Convert.ToInt32(Environment.GetEnvironmentVariable("NETWORKLATENCY"));

            // Load JSON configuration file
            string jsonConfig = File.ReadAllText("config.json");
            GameConfiguration config = JsonConvert.DeserializeObject<GameConfiguration>(jsonConfig);
            gameEnv.ServerConnectionString = config.ServerConnectionString;

            // Call remote API endpoint to fetch additional settings
            var client = new RestClient("https://api.example.com");
            var request = new RestRequest("/game_settings", Method.GET);
            IRestResponse response = client.Execute(request);

            if (response.StatusCode == System.Net.HttpStatusCode.OK)
            {
                GameSettings apiConfig = JsonConvert.DeserializeObject<GameSettings>(response.Content);
                gameEnv.Resolution += apiConfig.ResolutionAdjustment;
                gameEnv.FrameRateLimit += apiConfig.FrameRateLimitAdjustment;
                gameEnv.NetworkLatency += apiConfig.LatencyAdjustment;
            }

            // Handle network disruptions and server timeouts
            if (gameEnv.ServerConnectionString == null || response.StatusCode != System.Net.HttpStatusCode.OK)
            {
                // Degrade to minimal viable state
                gameEnv.Resolution = 800;
                gameEnv.FrameRateLimit = 30;
                gameEnv.NetworkLatency = 100;

                Console.WriteLine("Game environment initialized with degraded settings.");
            }
            else
            {
                Console.WriteLine("Game environment initialized successfully.");
            }

            // Optimize for performance and responsiveness
            Console.WriteLine($"Resolution: {gameEnv.Resolution}");
            Console.WriteLine($"Frame Rate Limit: {gameEnv.FrameRateLimit}");
            Console.WriteLine($"Network Latency: {gameEnv.NetworkLatency}");
        }
    }

    public class GameConfiguration
    {
        public string ServerConnectionString { get; set; }
    }

    public class GameSettings
    {
        public int ResolutionAdjustment { get; set; }
        public int FrameRateLimitAdjustment { get; set; }
        public int LatencyAdjustment { get; set; }
    }
}
