use std::env;
use std::fs::{self, DirBuilder};
use rand::thread_rng;
use rand::seq::SliceRandom;

pub fn create_directory_with_env_var(root_path: &str) -> String {
    let target_dir = env::var("TARGET_DIR").unwrap_or_else(|_| {
        let mut rng = thread_rng();
        let timestamp = chrono::Utc::now().to_string();
        let dir_name = format!("target-{}-{}", timestamp, rng/sample::<u32>(rand::thread_rng()));
        DirBuilder::new()
            .create(&format!("{}/{}", root_path, &dir_name))
            .unwrap();
        env::set_var("TARGET_DIR", format!("{}/{}", root_path, &dir_name));
    });
    target_dir
}
