using System;
using System.Net.Http;
using System.Threading.Tasks;

public class UpdateService
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly IDatabaseService _databaseService;
    private readonly ICdnService _cdnservice;
    private readonly int _maxContentSizeLimit;

    public UpdateService(IHttpClientFactory httpClientFactory, 
                         IDatabaseService databaseService, 
                         ICdnService cdnService, 
                         int maxContentSizeLimit)
    {
        _httpClientFactory = httpClientFactory;
        _databaseService = databaseService;
        _cdnservice = cdnService;
        _maxContentSizeLimit = maxContentSizeLimit;
    }

    public async Task HandleUpdateRequest(string pageSectionId, string elementId, string htmlContent)
    {
        // Check if the request is valid
        if (string.IsNullOrEmpty(pageSectionId) || 
            string.IsNullOrEmpty(elementId) || 
            string.IsNullOrEmpty(htmlContent))
        {
            throw new ArgumentException("Invalid request parameters");
        }

        // Validate HTML content size limit
        if (htmlContent.Length > _maxContentSizeLimit)
        {
            await HandleContentSizeExceededException(pageSectionId, elementId);
            return;
        }

        // Batch updates for same page section within a transaction
        using (var databaseTransaction = _databaseService.BeginTransaction())
        {
            try
            {
                // Update the HTML content
                await _databaseService.UpdatePageElement(pageSectionId, elementId, htmlContent);

                // Invalidate CDN cache entries
                await _cdnservice.InvalidateCacheEntriesForPageSection(pageSectionId);

                // Commit the transaction
                databaseTransaction.Commit();
            }
            catch (Exception ex)
            {
                // Roll back the transaction on error
                databaseTransaction.Rollback();

                // Log the error and handle it as needed
                await HandleUpdateFailure(ex, pageSectionId, elementId);
            }
        }
    }

    private async Task HandleContentSizeExceededException(string pageSectionId, string elementId)
    {
        // Log the error
        await _logger.LogError($"Content size exceeded for page section {pageSectionId} and element {elementId}");

        // Return a 413 response with an error message
        return await _httpClientFactory.CreateClient().SendAsync(new HttpRequestMessage(HttpMethod.Put, $"api/update/{pageSectionId}/{elementId}"))
            .ContinueWith(responseTask =>
            {
                if (responseTask.Result.IsSuccessStatusCode)
                    return;

                var responseBody = await responseTask.Result.Content.ReadAsStringAsync();
                throw new Exception($"Failed to update content: {responseBody}");
            });
    }

    private async Task HandleUpdateFailure(Exception ex, string pageSectionId, string elementId)
    {
        // Log the error
        await _logger.LogError($"Update failed for page section {pageSectionId} and element {elementId}: {ex.Message}");

        // Retry the update up to a configurable threshold
