async function readFiles(directory, extension) {
  const files = [];
  const startTime = Date.now();

  try {
    await fs.readdir(directory);
  } catch (error) {
    console.error(`Error reading directory: ${error.message}`);
    return [];
  }

  const filewalker = async (path) => {
    try {
      const filesInDir = await fs.readdir(path);

      for (const file of filesInDir) {
        const filePath = path + '/' + file;
        if (!file.includes('.')) continue;

        if (file.endsWith(extension)) {
          try {
            const fileContent = await fs.readFileSync(filePath, 'utf8');
            files.push(fileContent);
          } catch (error) {
            console.error(`Error reading file: ${filePath} - ${error.message}`);
          }
        }

        if (fs.lstatSync(filePath).isDirectory()) {
          await filewalker(filePath);
        }
      }
    } catch (error) {
      console.error(`Error processing directory: ${path} - ${error.message}`);
    }
  };

  await filewalker(directory);

  const endTime = Date.now();
  console.log(`Files read in ${endTime - startTime} ms`);

  return files;
}
