const { Worker } = require('worker_threads');
const blueslip = require('blueslip');

function loadAndExecuteTests(moduleName, label, f, maxConcurrency) {
  const concurrencyQueue = [];
  let activeWorkers = 0;
  let workerThreads = [];

  function executeTest() {
    if (concurrencyQueue.length >= maxConcurrency) return;

    const test = concurrencyQueue.shift();
    const worker = new Worker(`require(${moduleName}); ${test.f.toString()};`);
    worker.on('exit', () => {
      activeWorkers--;
      blueslip.reset();
    });

    worker.on('error', (err) => {
      console.error(`Error running test: ${label}`, err);
    });

    workerThreads.push(worker);

    if (!--activeWorkers) {
      concurrencyQueue = [];
      workerThreads.forEach((worker) => worker.disconnect());
      workerThreads = [];
    }
  }

  executeTest();

  return {
    addTest(label, f) {
      concurrencyQueue.push({ label, f });
      if (concurrencyQueue.length >= maxConcurrency) {
        executeTest();
      }
    },
  };
}

const testRunner = require('test-runner');

function runTests() {
  const testsModule = require('./tests');
  const testRunnerInstance = testRunner();

  for (let i = 0; i < 100; i++) {
    const label = `Test-${i}`;
    const f = testsModule[i];
    loadAndExecuteTests('./tests', label, f, 5).addTest(label, f);
  }

  testRunnerInstance.run();
}

runTests();
