function processPaymentMethods(formData) {
  const paymentMethods = {};
  const threeMonthsAgo = new Date(Date.now() - (3 * 30 * 24 * 60 * 60 * 1000));

  formData.forEach((paymentMethod, index) => {
    if (!paymentMethods[paymentMethod.type]) {
      paymentMethods[paymentMethod.type] = {
        transactions: [],
        metadata: {},
      };
    }

    const transactionMetadata = {
      date: paymentMethod.transactionDate,
      frequency: paymentMethod.frequency,
      merchant: paymentMethod.merchant,
    };

    paymentMethods[paymentMethod.type].transactions.push(transactionMetadata);
  });

  Object.keys(paymentMethods).forEach((paymentType) => {
    const transactions = paymentMethods[paymentType].transactions;
    const totalTransactions = transactions.length;

    let totalAmount = 0;
    let mostFrequentAmount = null;
    const frequencyMap = {};

    transactions.forEach((transaction) => {
      if (!frequencyMap[transaction.frequency]) {
        frequencyMap[transaction.frequency] = 1;
      } else {
        frequencyMap[transaction.frequency]++;
      }

      totalAmount += transaction.date.getTime() - threeMonthsAgo.getTime();
    });

    const averageTransactionAmount = totalAmount / transactions.length;

    let mostFrequentFrequency = null;
    let maxFrequency = 0;

    Object.keys(frequencyMap).forEach((frequency) => {
      if (frequencyMap[frequency] > maxFrequency) {
        maxFrequency = frequencyMap[frequency];
        mostFrequentFrequency = frequency;
      }
    });

    paymentMethods[paymentType].metadata = {
      totalTransactions,
      averageTransactionAmount,
      mostFrequentAmount: transaction.amount,
      mostFrequentFrequency,
    };
  });

  return paymentMethods;
}
