function generateFooter(scripts) {
  const SUPPORTED_TYPES = ['application/javascript', 'text/javascript', 'module'];
  const EXTENSIONS = ['.js', '.mjs'];

  function isValidScript(script) {
    if (!script.src && !script.code) throw new Error('Invalid script');
    if (script.src) {
      const url = new URL(script.src);
      if (!url.pathname.endsWith(...EXTENSIONS)) return false;
      const response = await fetch(url);
      if (response.ok) {
        const contentType = response.headers.get('Content-Type');
        if (!SUPPORTED_TYPES.includes(contentType)) return false;
      } else {
        console.error(`Failed to load script: ${script.src}`);
        return false;
      }
    } else {
      const code = script.code;
      if (!code || !code.trim()) throw new Error('Invalid JavaScript code');
      for (const type of SUPPORTED_TYPES) {
        if (code.includes(type)) return true;
      }
      throw new Error(`Unsupported MIME type: ${script.src}`);
    }
  }

  function cacheScript(script) {
    const cache = {};
    function getScript(url) {
      if (!cache[url]) {
        cache[url] = fetch(url).then(response => response.text());
      }
      return cache[url];
    }
    return { src: script.src, code: script.code, getScript };
  }

  function generateScript(script) {
    const cachedScript = cacheScript(script);
    return `
      <script${script.src ? ` src="${script.src}"` : ''}>
        ${cachedScript.code || await cachedScript.getScript()}
      </script>
    `;
  }

  let footerHTML = '';
  for (const script of scripts) {
    try {
      if (!isValidScript(script)) throw new Error('Invalid script');
      footerHTML += generateScript(script);
    } catch (error) {
      console.error(error);
      footerHTML += `<p>Error loading script: ${script.src}</p>`;
    }
  }

  return `
    <footer>
      ${footerHTML}
    </footer>
  `;
}']

