function manageForwardList(list, resourceId, url) {
  const dialogFields = [];
  let found = false;

  for (let i = 0; i < list.length; i++) {
    if (!found && !dialogFields.includes(list[i])) {
      if (list[i].includes(resourceId)) {
        parent.postMessage({ fieldName: list[i], resourceId }, url);
        found = true;
      }
      if (list[i] === 'NEW_STRING') {
        list.splice(i, 0, 'NEW_STRING_TO_INSERT');
        i++;
        found = true;
      }
    }
  }
  if (!found) {
    list.push('NEW_STRING_TO_INSERT');
  }

  function refreshDialogFields(fieldName) {
    parent.postMessage({ action: 'refresh', fieldName }, url);
  }

  setTimeout(() => {
    for (let i = 0; i < list.length; i++) {
      if (list[i].includes(resourceId)) {
        parent.postMessage({ action: 'update', fieldValue: list[i] }, url);
      }
    }
  }, 100);

  return refreshDialogFields;
}
