class DataProcessor {
  constructor(bufferSize = 1024 * 1024) {
    this.bufferSize = bufferSize;
    this.buffer = new Buffer(this.bufferSize);
    this.chunks = [];
    this.processedChunks = 0;
    this.errorHandler = (err) => console.error('Error processing data:', err);
  }

  async mergeChunks(chunks) {
    for await (const chunk of chunks) {
      try {
        await this.handleChunk(chunk);
      } catch (error) {
        this.errorHandler(error);
      }
    }
  }

  async handleChunk(chunk) {
    if (!Buffer.isBuffer(chunk)) {
      throw new Error('Invalid data format');
    }

    const chunkSize = chunk.length;
    if (chunkSize > this.bufferSize || chunkSize === 0) {
      throw new Error('Data size mismatch');
    }

    let bufferOffset = 0;
    while (bufferOffset < this.bufferSize && chunkSize > 0) {
      const offset = Math.min(chunkSize, this.bufferSize - bufferOffset);
      this.buffer.copy(chunk, 0, this.buffer, bufferOffset, offset);
      chunkSize -= offset;
      bufferOffset += offset;
    }

    this.chunks.push({ chunk, bufferOffset });
    this.processedChunks++;
  }

  async flushBuffer() {
    if (this.chunks.length === 0) return;

    const bufferData = Buffer.alloc(this.bufferSize);
    let bufferOffset = 0;
    for (const { chunk, offset } of this.chunks) {
      bufferData.copy(chunk, 0, bufferData, bufferOffset, chunk.length);
      bufferOffset += chunk.length;
    }

    // Flush data to an external storage or send it over the network
    // ...

    this.buffer = Buffer.alloc(this.bufferSize);
    this.chunks = [];
    this.processedChunks = 0;
  }
}

module.exports = DataProcessor;
