function traverseDOM(selector, callback) {
  const cache = {};
  let maxRecursionDepth = Infinity;

  function traverse(node, currentPath = '', parentCallbackResults = []) {
    if (currentPath.length > maxRecursionDepth) return;
    const cachedNode = cache[currentPath];
    if (cachedNode) return [...cachedNode];

    const results = [];
    const currentNodeMatchesSelector = node.matches(selector);

    if (currentNodeMatchesSelector) {
      const callbackResults = callback(node);
      parentCallbackResults.push(...callbackResults);
    }

    for (let child of node.children) {
      const path = `${currentPath} > ${child.nodeName}`;
      const resultsForChild = traverse(child, path, [...parentCallbackResults]);
      if (resultsForChild.length) results.push(...resultsForChild);
    }

    cache[currentPath] = results;
    return results;
  }

  return traverse(document.body.querySelector(selector), '', []);
}

