const sprintf = require('sprintf-js');

function modifyScriptName(filename) {
  const extIndex = filename.lastIndexOf('.');
  const baseName = filename.substring(0, extIndex);
  const suffixCount = parseInt(baseName.split('-').pop().split('.')[1], 10) || 0;
  const newSuffix = sprintf('%03d', suffixCount + 1);
  return `${baseName}-${newSuffix}.js`;
}

function loadAndExecuteScripts(scripts, callback) {
  let scriptCount = 0;
  function executeScript(filename) {
    fs.readFile(filename, 'utf8', (err, content) => {
      if (err) {
        console.error(`Error loading ${filename}: ${err}`);
      } else {
        try {
          const newFilename = modifyScriptName(filename);
          fs.writeFile(newFilename, content, 'utf8', () => {
            scriptCount++;
            console.log(`Loaded and executed ${newFilename}`);
          });
        } catch (error) {
          console.error(`Error executing ${filename}: ${error}`);
        }
      }
    });
  }

  scripts.forEach(executeScript);
  setTimeout(() => {
    if (scriptCount === scripts.length) {
      callback();
    } else {
      console.error('Not all scripts were loaded and executed');
    }
  }, scriptCount * 1000); // Simulate some delay
}

// Example usage:
const scripts = ['plugin1.js', 'plugin2.js', 'plugin3.js'];
loadAndExecuteScripts(scripts, () => {
  console.log('All scripts loaded and executed');
});
