public class FileProcessor {

    public static void processFilePaths(String filePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            List<String> filePathsList = new ArrayList<>();
            Set<String> uniqueFilePaths = new TreeSet<>((o1, o2) -> o1.compareToIgnoreCase(o2));

            int totalFiles = 0;
            long fileSize = getSizeOfExternalFileService();
            boolean isFilesizeRetrievalSuccessful = true;

            String line;
            int processedFiles = 0;
            long startTime = System.currentTimeMillis();

            while ((line = reader.readLine()) != null) {
                totalFiles++;
                if (uniqueFilePaths.add(line.toLowerCase())) {
                    filePathsList.add(line);
                    processedFiles++;

                    if ((processedFiles % (totalFiles / 10)) == 0) {
                        long currentTime = System.currentTimeMillis();
                        long timeTakenSoFar = currentTime - startTime;
                        double percentageCompleted = ((double) processedFiles / totalFiles) * 100;
                        System.out.println("Files processed: " + processedFiles +
                                ", Time taken so far: " + timeTakenSoFar + "ms, Percentage completed: " + percentageCompleted);
                    }
                } else {
                    isFilesizeRetrievalSuccessful = false;
                }

                if (filePathsList.size() >= fileSize * 1024 && !isFilesizeRetrievalSuccessful) {
                    break;
                }
            }

            if (!isFilesizeRetrievalSuccessful) {
                System.out.println("Service failure occurred. Unable to process all files.");
            } else {
                System.out.println("All files processed successfully.");
            }
        }
    }

