import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class FileTransferService {
    private static final int BUFFER_SIZE = 4096;
    private static final ExecutorService EXECUTOR_SERVICE = Executors.newCachedThreadPool();

    public void startTransfer(String remoteFileUrl, String localFilePath) throws Exception {
        // Create a new thread to handle the file transfer
        EXECUTOR_SERVICE.submit(() -> {
            try (BufferedInputStream in = new BufferedInputStream(new URL(remoteFileUrl).openStream());
                 FileOutputStream out = new FileOutputStream(localFilePath)) {
                byte[] buffer = new byte[BUFFER_SIZE];
                int bytesRead;
                while ((bytesRead = in.read(buffer, 0, BUFFER_SIZE)) != -1) {
                    out.write(buffer, 0, bytesRead);
                }
            } catch (IOException e) {
                // Handle error
                System.out.println("Error transferring file: " + e.getMessage());
            } finally {
                EXECUTOR_SERVICE.shutdown();
            }
        });
    }
}
