        }, 0, 10000); // Run every 10 seconds

        // Scale service instances based on performance metrics
        while (true) {
            scaleServiceInstances();
            try {
                Thread.sleep(60000); // Check every minute
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    private static void evaluateServiceInstances() {
        // Iterate over all service instances and check their health
        for (Map.Entry<String, ServiceInstance> entry : serviceInstances.entrySet()) {
            String serviceName = entry.getKey();
            ServiceInstance instance = entry.getValue();

            if (!instance.isHealthy()) {
                // If the instance is unhealthy, scale it down or remove it
                scaleServiceInstance(serviceName);
            } else {
                // If the instance is healthy, consider scaling it up
                scaleServiceInstance(serviceName);
            }
        }
    }

    private static void scaleServiceInstances() {
        // Check the overall system performance and adjust the number of instances accordingly
        int totalRequests = 0;
        for (Map.Entry<String, ServiceInstance> entry : serviceInstances.entrySet()) {
            totalRequests += entry.getValue().getTotalRequests();
        }

        if (totalRequests > 10000) { // If there are more than 10,000 requests
            // Scale up the number of instances to handle the load
            for (Map.Entry<String, ServiceInstance> entry : serviceInstances.entrySet()) {
                entry.getValue().scaleUp();
            }
        } else if (totalRequests < 5000) { // If there are less than 5,000 requests
            // Scale down the number of instances to save resources
            for (Map.Entry<String, ServiceInstance> entry : serviceInstances.entrySet()) {
                entry.getValue().scaleDown();
            }
        }
    }

    private static void scaleServiceInstance(String serviceName) {
        // Determine if the instance should be scaled up or down based on its performance and the overall system load
        int totalRequests = 0;
        for (Map.Entry<String, ServiceInstance> entry : serviceInstances.entrySet()) {
            if (entry.getKey().equals(serviceName)) {
                totalRequests = entry.getValue().getTotalRequests();
                break;
            }
        }

        if (totalRequests > 2000) { // If there are more than 2,000 requests
            // Scale up the instance to handle the load
            serviceInstances.get(serviceName).scaleUp();
        } else if (totalRequests < 1000) { // If there are less than 1,000 requests
            // Scale down the instance to save resources
            serviceInstances.get(serviceName).scaleDown();
        }
    }

