extern crate hyper;
extern crate tokio;
use hyper::Client;
use hyper::client::HttpConnector;
use tokio::sync::mpsc;

#[derive(Debug)]
pub struct RequestBuilder {
    url: String,
    method: String,
    headers: Vec<(String, String)>,
}

impl RequestBuilder {
    pub fn new(url: &str, method: &str) -> Self {
        RequestBuilder {
            url: url.to_string(),
            method: method.to_string(),
            headers: vec![],
        }
    }

    pub fn set_header(&mut self, key: &str, value: &str) {
        self.headers.push((key.to_string(), value.to_string()));
    }

    pub async fn send(self) -> Result<hyper::response::Response, hyper::error::Error> {
        let client = Client::builder()
            .connector(HttpConnector::new())
            .build();
        let request = client.request(self.method.clone(), self.url.clone());
        for (key, value) in &self.headers {
            request.header(key.to_string(), value.to_string()).await?;
        }
        let response = request.send().await?;
        Ok(response)
    }
}

#[derive(Debug)]
pub enum RequestError {
    Io(std::io::Error),
    Hyper(hyper::error::Error),
}

impl std::fmt::Display for RequestError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            RequestError::Io(e) => write!(f, "IO Error: {}", e),
            RequestError::Hyper(e) => write!(f, "HTTP Error: {}", e),
        }
    }
}

impl std::error::Error for RequestError {}

#[derive(Debug)]
pub struct HttpClient {
    client: Client,
    session_token: Option<String>,
    max_retries: usize,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient {
            client: Client::builder()
                .connector(HttpConnector::new())
                .build(),
            session_token: None,
            max_retries: 3,
        }
    }

    pub async fn request(&self, url: &str) -> Result<hyper::response::Response, RequestError> {
        let mut builder = self.client.request(b"GET", url).await?;
        if let Some(token) = &self.session_token {
            builder.header("Authorization", format!("Bearer {}", token)).await?;
        }
        loop {
            match builder.send().await {
                Ok(response) => return Ok(response),
                Err(e) => {
                    if self.max_retries > 0 && e.is_transient() {
                        self.max_retries -= 1;
                        continue;
                    } else {
                        return Err(RequestError::Hyper(e));
                    }
                }
            }
        }
    }

    pub fn set_session_token(&mut self, token: &str) {
        self.session_token = Some(token.to_string());
    }
}
