        } else {
            self.successes.insert(path.to_path_buf(), result.to_string());
        }
    }

    fn summarize(&self) -> String {
        let mut successes = 0;
        let mut failures = 0;

        for (_, result) in &self.successes {
            if result.contains("error") {
                failures += 1;
            } else {
                successes += 1;
            }
        }

        format!("Built {} projects successfully, {} failed.\nTotal memory usage: {}\nTotal compile time: {:.2}", successes, failures, self.total_memory_usage, self.total_compile_time)
    }
