const { createInterface } = require('readline');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

function processOAuthRequestForCertificate(oauthRequest) {
  const privatekeyPath = oauthRequest.privateKeyLocation;
  const certificatePath = oauthRequest.certificateLocation;

  let privateKey;
  let certificate;

  try {
    privateKey = fs.readFileSync(privatekeyPath, 'utf8');
    certificate = fs.readFileSync(certificatePath, 'utf8');
  } catch (error) {
    console.error('Failed to read private key or certificate:', error);
    return null;
  }

  const pemFile = crypto.createPrivateKey(privateKey).concat(crypto.createCertificate(certificate));
  const pki = crypto.publicKeyToPEM(pemFile, 'pem');

  try {
    fs.writeFileSync(oauthRequest.outputFile, pki);
  } catch (error) {
    console.error('Failed to write PEM file:', error);
    return null;
  }

  return pki;
}

module.exports = processOAuthRequestForCertificate;

