void* dns_resolve(char* hostname, int timeout) {
    struct hostent *host;
    char buffer[1024];

    // Perform DNS resolution using gethostbyname
    host = gethostbyname(hostname);
    if (host == NULL) {
        return NULL;
    }

    // Convert IP address to string
    inet_ntop(AF_INET, &host->h_addr, buffer, sizeof(buffer));

    // Handle potential network errors and timeouts gracefully
    if (timeout > 0 && send(, timeout)) {
        // Network error or timeout occurred; return NULL
        return NULL;
    }

    return buffer;
}

int main() {
