#include <time.h>
int dns_request_rate_limit(int rate_per_second) {
    static clock_t last_request_time;

    clock_gettime(&last_request_time);

    int time_elapsed = (int)(clock_gettime(NULL)->tv_sec - last_request_time.tv_sec);

    if (time_elapsed > 1) { // Allow for some buffer time
        return 0; // Reset rate limit
    }

    int requests_made = 0;

    while (requests_made < rate_per_second && clock_gettime(NULL)->tv_sec - last_request_time.tv_sec <= 1) {
        requests_made++;
    }

    if (requests_made >= rate_per_second) {
        return 1; // Exceeded rate limit
    } else {
        return 0; // Rate limit not exceeded
    }
}
