// Define the structure representing a state in the FSA
typedef struct State {
    int id;
    bool isFinal;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} State;

// Define the structure representing an FSA
typedef struct FiniteStateMachine {
    State* states;
    int currentState;
    int currentStateIndex;
} FSA;

// Function to dynamically manage the list of states in the FSA
State** modifyFsaStates(State** states, int numStates, FSA* fsa, int lastIndex, bool addOrRemove) {
    // Create a new state if adding or update an existing one if removing
    State* newState = NULL;
    pthread_mutex_lock(&states[lastIndex]->lock);
    if (addOrRemove) {
        newState = (State*)malloc(sizeof(State));
        if (!newState) return NULL; // Memory allocation failed
        states[lastIndex]->next = newState;
        states[lastIndex] = newState;
    } else {
        free(states[lastIndex]);
        states[lastIndex] = NULL;
    }
    pthread_mutex_unlock(&states[lastIndex]->lock);

    // Update the 'next' pointer of the last state in the list
    fsa->currentState = lastIndex;
    fsa->currentStateIndex = numStates;

    return states;
}

int main() {
    // Initialize the FSA and its states
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    fsa->states = NULL;
    int currentState = 0;
    int currentStateIndex = 0;

    // Test the function with different scenarios
    State** states = modifyFsaStates(NULL, 0, fsa, -1, true); // Add a new state
    printf("Added a new state\n");

    states = modifyFsaStates(states, 3, fsa, currentStateIndex, false); // Remove an existing state
    printf("Removed an existing state\n");

    return 0;
}
