        : featureSize_(featureSize), numLeafNodes_(numLeafNodes), dataCapacity_(dataCapacity) {}

    ~Octree() {
        if (root_ != nullptr) {
            destroyTree(root_);
        }
    }

    Status init();

    void clear();

private:
    int featureSize_;
    int numLeafNodes_;
    int dataCapacity_;

    struct Node {
        bool isFull;
        std::vector<Node*> children;

        Node() : isFull(false), children(8, nullptr) {}
    };

    Node* root_ = nullptr;
    std::unique_ptr<int[]> dataArray_; // dynamic memory allocation
    std::vector<std::unique_ptr<int[]>> prefixArrays_; // dynamic memory allocation

    void destroyTree(Node* node);
};

Octree::Status Octree::init() {
    if (numLeafNodes_ > 0) {
        root_ = new Node();
        dataArray_.reset(new int[dataCapacity_]);
        prefixArrays_.resize(numLeafNodes_);
        for (auto& array : prefixArrays_) {
            array.reset(new int[dataCapacity_]);
        }
    } else {
        return FAILURE;
    }

    // implement efficient memory allocation and management
    // strategy to monitor and limit maximum memory usage

    return SUCCESS;
}

void Octree::clear() {
    if (root_ != nullptr) {
        destroyTree(root_);
        root_ = nullptr;
        dataArray_.reset(nullptr);
        prefixArrays_.clear();
    }
}

void Octree::destroyTree(Node* node) {
    for (auto child : node->children) {
        if (child != nullptr) {
            destroyTree(child);
        }
    }

    delete node;
}
