#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 10000
#define REQUEST_FREQUENCY_THRESHOLD 10
#define UPDATE_INTERVAL 60 // in seconds

typedef struct {
    int id;
    time_t timestamp;
} Request;

Request *cache = NULL;
int cache_size = 0;
int request_count = 0;
int oldest_exceeded_request_id = -1;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* handle_request(void* arg) {
    // Handle the request and update the cache
    pthread_mutex_lock(&mutex);
    // Check if the request exceeded the frequency threshold
    if (request_count % REQUEST_FREQUENCY_THRESHOLD == 0 && oldest_exceeded_request_id != -1) {
        // Identify the oldest request that exceeded the frequency threshold
        int i;
        for (i = 0; i < cache_size; i++) {
            if (cache[i].id == oldest_exceeded_request_id) {
                break;
            }
        }
        // Evict the oldest request from the cache
        memmove(cache + i, cache + i + 1, (cache_size - i - 1) * sizeof(Request));
        cache_size--;
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int add_request_to_cache(int id) {
    // Add the request to the cache and update statistics
    pthread_mutex_lock(&mutex);
    if (cache_size < MAX_CACHE_SIZE) {
        Request new_request = {id, time(NULL)};
        cache[cache_size++] = new_request;
        request_count++;
    } else {
        // Evict the least recently used request from the cache
        int i;
        for (i = 0; i < cache_size - 1; i++) {
            Request old_request = cache[i];
            memmove(cache + i, cache + i + 1, sizeof(Request));
        }
        cache[cache_size - 1] = new_request;
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

int main() {
    // Initialize the cache
    cache = (Request*) malloc(MAX_CACHE_SIZE * sizeof(Request));

    // Start handling requests concurrently
    pthread_t threads[MAX_REQUESTS];
    for (int i = 0; i < MAX_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, handle_request, NULL);
