using System;
using UnityEngine;

public class ValueGenerator
{
    public float MinValue { get; private set; }
    public float MaxValue { get; private set; }

    public ValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("MinValue cannot exceed MaxValue");

        MinValue = minValue;
        MaxValue = maxValue;
    }

    public float GenerateUniformRandomFloat()
    {
        return UnityEngine.Random.Range(MinValue, MaxValue + 1);
    }

    public int GenerateUniformRandomInt()
    {
        if (MaxValue - MinValue > int.MaxValue)
            throw new OverflowException("Range is too large for integer representation");

        return UnityEngine.Random.Range(Mathf.FloorToInt(MinValue), Mathf.CeilToInt(MaxValue));
    }

    public float GenerateGaussianRandomFloat(float mean, float stdDev)
    {
        if (stdDev < 0)
            throw new ArgumentException("Standard deviation cannot be negative");

        return mean + UnityEngine.Random.Gaussian() * stdDev;
    }

    public int GenerateGaussianRandomInt(float mean, float stdDev)
    {
        int value = (int)(mean + UnityEngine.Random.Gaussian() * stdDev);
        if (value < MinValue) value = Mathf.CeilToInt(MinValue);
        else if (value > MaxValue) value = Mathf.FloorToInt(MaxValue);

        return value;
    }

    public override string ToString()
    {
        return $"Range[{MinValue}, {MaxValue}]";
    }

    public void AdjustRange(float newMin, float newMax)
    {
        if (newMin > newMax)
            throw new ArgumentException("New min value cannot exceed new max value");

        MinValue = newMin;
        MaxValue = newMax;
    }
}
