class TransformationQueue {
  constructor(concurrencyLimit = 10) {
    this.concurrencyLimit = concurrencyLimit;
    this.queue = [];
    this.transformations = [];
    this.logger = new Logger();
  }

  async process(data, aggregationValue) {
    if (!Array.isArray(data)) throw new Error("Invalid input: Expected array of numbers");

    this.transformations = data.map((num) => ({ value: num }));

    await this.runTransformations(aggregationValue);
  }

  async runTransformations(aggregationValue) {
    for (const transformation of this.transformations) {
      if (!this.transformations.length) break;

      const task = {
        id: this.transformations.indexOf(transformation),
        status: 'pending',
        value: transformation.value,
      };

      this.queue.push(task);

      while (this.queue.length >= this.concurrencyLimit) {
        await this.processOneTransformation();
      }
    }

    await this.waitForAllTransformations();
  }

  async processOneTransformation() {
    const task = this.queue.shift();
    if (!task) return;

    try {
      task.status = 'transformed';

      // Add the transformation logic here
      await new Promise((resolve, reject) => setTimeout(() => resolve(), 1000));

      task.value = 10; // Replace with actual transformation result
    } catch (error) {
      task.status = 'failed';
    }

    this.logger.log({ task: task.id, status: task.status, value: task.value });

    await this.processOneTransformation();
  }

  async waitForAllTransformations() {
    while (this.queue.length > 0) {
      await new Promise((resolve, reject) => setTimeout(() => resolve(), 100));
    }

    const results = this.transformations.map((transformation) => transformation.value);
    return aggregationValue + results.reduce((acc, val) => acc + val, 0);
  }
}

class Logger {
  log({ task, status, value }) {
    // Implement logging mechanism here
  }
}
