char* processString(char* str, int sizeLimit) {
    if (strlen(str) <= sizeLimit) {
        char* modifiedStr = malloc((sizeLimit + 2) * sizeof(char));
        strcpy(modifiedStr, str);
        modifiedStr[sizeLimit] = '/';
        modifiedStr[sizeLimit + 1] = '\0';
        return modifiedStr;
    } else {
        return NULL;
    }
}

typedef struct Node {
    char* value;
    struct Node* next;
} Node;

Node* traverseDOM(Node* root, const char* selector, void (*callback)(const char*)) {
    if (root == NULL) {
        return NULL;
    }

    if (strcmp(root->value, selector) == 0 || strcmp(root->value, "*") == 0) {
        callback(root->value);
    }

    Node* current = root;
    while (current != NULL) {
        Node* next = current->next;
        current->next = traverseDOM(next, selector, callback);
        current = next;
    }
    return root;
}

int main() {
    // Example usage
    char* str1 = "Hello";
    int sizeLimit = 5;
    char* processedStr1 = processString(str1, sizeLimit);
    printf("Processed string: %s\n", processedStr1);

    Node* node1 = malloc(sizeof(Node));
    node1->value = "button";
    node1->next = NULL;

    Node* node2 = malloc(sizeof(Node));
    node2->value = "input";
    node2->next = NULL;

    Node* root = node1;
    root->next = node2;

    const char* selector = "button";
    void (*callback)(const char*) = (void (*)(const char*))printf;
    traverseDOM(root, selector, callback);

    return 0;
}
