void process_file(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    char *line = malloc(MAX_LINE_LENGTH);
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        int fields = 0;
        char *field = strtok(line, " ");
        while (field != NULL) {
            if (strspn(field, "0123456789.") == strlen(field)) {
                // Last two numerical fields
                int last_two_fields = atoi(&field[strlen(field) - 2]);
                int second_last_field = atoi(&field[strlen(field) - 4]);

                // Compute average of the last two numerical fields
                int avg = (last_two_fields + second_last_field) / 2;
                sprintf(&field[strlen(field) - 2], "%d", avg);

                break;
            }
            field = strtok(NULL, " ");
            fields++;
        }

        if (fields > 0 && line[fields * strlen(line)] != '\n') {
            // Store the updated line
            rewind(file);
            int bytes_written = fwrite(line, 1, strlen(line), file);
            if (bytes_written < strlen(line)) {
                printf("Error writing to file: %s\n", filename);
            }
        }

        free(line);
        line = malloc(MAX_LINE_LENGTH);
    }

    fclose(file);
}

int main() {
    char theme_dir[256] = DEFAULT_THEME_DIR;
    // Initialize the default theme directory

    process_file("theme_bitmap_info.txt");

    return 0;
}
