#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <md5.h>

typedef struct {
    uint16_t bit_depth;
    uint16_t samples_per_pixel;
    uint8_t extra_samples;
} ImageMetadata;

ImageMetadata ProcessImageAndComputeHash(const char* filename, const char* input_string) {
    TIFF *t = fopen(filename, "rb");
    if (!t) return (ImageMetadata){.bit_depth = 0, .samples_per_pixel = 0, .extra_samples = 0};

    uint16_t bit_depth;
    uint16_t samples_per_pixel;
    uint8_t extra_samples;

    if (tiff_get_field(t, TIFF_FIELD_BIT_DEPTH, &bit_depth) != 1)
        return (ImageMetadata){.bit_depth = 0, .samples_per_pixel = 0, .extra_samples = 0};
    if (bit_depth > 16 || bit_depth < 1) {
        fclose(t);
        return (ImageMetadata){.bit_depth = 0, .samples_per_pixel = 0, .extra_samples = 0};
    }

    if (tiff_get_field(t, TIFF_FIELD_SAMPLESPERPIXEL, &samples_per_pixel) != 1)
        samples_per_pixel = 0;
    if (tiff_get_field(t, TIFF_FIELD_EXTRASAMPLES, &extra_samples) != 1)
        extra_samples = 0;

    fclose(t);

    MD5_CTX md5ctx;
    char buffer[1024];
    sprintf(buffer, "%s", input_string);
    size_t len = strlen(buffer);
    unsigned char hash[16];

    MD5_Init(&md5ctx);
    for (size_t i = 0; i < len; ++i) {
        MD5_Update(&md5ctx, buffer + i, 1);
    }
    MD5_Final(hash, &md5ctx);

    // Convert the hash to a hexadecimal string
    char* hex_string = malloc(33 * sizeof(char)); // 32 characters for the hash and an extra for null termination
    for (int i = 0; i < 16; ++i) {
        sprintf(hex_string + i * 2, "%02x", hash[i]);
    }
    free(hex_string);

    return (ImageMetadata){.bit_depth = bit_depth, .samples_per_pixel = samples_per_pixel, .extra_samples = extra_samples};
}
