char* rename_files(char* dir_path, char* filename) {
    DIR *dir;
    struct dirent *ent;
    int count = 0;
    char new_filename[255];

    // Open directory
    dir = opendir(dir_path);
    if (dir == NULL) {
        return "Error: Cannot open directory.";
    }

    // Iterate through files in the directory
    while ((ent = readdir(dir)) != NULL) {
        // Check for files with the same name as the target file
        if (strcmp(ent->d_name, filename) == 0) {
            // Count numeric characters in the file name
            for (int i = 0; i < strlen(filename); i++) {
                if (isdigit(filename[i])) {
                    count++;
                }
            }

            // Create new filename with count and extension
            sprintf(new_filename, "%s%d%s", filename, count, ent->d_name + strlen(filename));
        }
    }

    closedir(dir);

    return new_filename;
}
