// Function to initialize AES-256-CBC cipher with given password using OpenSSL library
EVP_CIPHER_CTX* init_aes_cipher(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Set IV length to 16 bytes and key length to 32 bytes
    EVP_CIPHER_CTX_set_iv_length(ctx, 16);
    EVP_CIPHER_CTX_set_key_length(ctx, 32);

    // Derive encryption key from password using SHA-1 and PBKDF2
    const char* salt = "salt_string";
    int iterationCount = 1000;
    unsigned char* derivedKey = NULL;
    int derivedKeyLength;

    if (!PBKDF2_sha1(password, strlen(password), salt, strlen(salt), &derivedKey, &derivedKeyLength, iterationCount)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set key and iv for the cipher context
    if (AES_256_CBC_set_key(ctx, derivedKey, derivedKeyLength) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    EVP_CIPHER_CTX_set_iv(ctx, &ctx->iv[0], 16);

    // Enable the cipher
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_aes_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

