#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

int execute_command(const char *cmd, int timeout) {
    pid_t pid = fork();
    if (pid == -1) {
        return 0; // failure
    }

    if (pid == 0) { // child process
        dup2 fileno("/dev/null"), STDOUT_FILENO);
        dup2 fileno("/dev/null"), STDERR_FILENO);
        execvp(cmd, NULL);
    } else { // parent process
        usleep(timeout * 100000); // wait for the specified amount of time

        kill(pid, SIGTERM); // send a signal to the child process to terminate it

        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status); // 1 on success
        } else {
            return 2; // timeout
        }
    }
}

int main() {
    char *cmd = "/bin/ls";
    int timeout = 60;

    execute_command(cmd, timeout);

    return 0;
}
