using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly CancellationTokenSource _cts = new();
    private readonly ILogger _logger;
    private readonly IConfiguration _config;
    private readonly IProcessService _processService;
    private readonly IMonitoringSystem _monitoringSystem;

    public WebsiteManager(ILogger logger, IConfiguration config, IProcessService processService, IMonitoringSystem monitoringSystem)
    {
        _logger = logger;
        _config = config;
        _processService = processService;
        _monitoringSystem = monitoringSystem;
    }

    public async Task ManageWebsites(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            throw new InvalidOperationException($"Directory '{directoryPath}' does not exist.");
        }

        var websites = Directory.GetFiles(directoryPath, "*.config");

        foreach (var websiteConfig in websites)
        {
            try
            {
                await StartWebsite(websiteConfig);
            }
            catch (Exception ex) when (_cts.Token.IsCancellationRequested)
            {
                _logger.Warn("CancellationToken was cancelled. Continuing with remaining websites.");
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to start website");
                _monitoringSystem.RecordFailure(websiteConfig, ex.Message);
            }
        }

        await _cts.Token.WaitHandle.WaitOne();
    }

    private async Task StartWebsite(string websiteConfigPath)
    {
        var processStartInfo = new ProcessStartInfo
        {
            FileName = "your_web_server.exe", // replace with your web server executable name
            Arguments = $"-c {websiteConfigPath}",
            CreateNoWindow = true,
            UseShellExecute = false,
            RedirectStandardError = true,
            RedirectStandardOutput = true
        };

        try
        {
            var process = _processService.Start(processStartInfo);
            await Task.Run(() => process.WaitForExit());
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Failed to start website process");
            _monitoringSystem.RecordFailure(websiteConfigPath, ex.Message);
        }
    }

    public void Dispose()
    {
        _cts.Cancel();
    }
}

public interface ILogger
{
    void Info(string message);
    void Warn(string message);
    void Error(Exception exception, string message);
}

public interface IProcessService
{
    Process Start(ProcessStartInfo startInfo);
}

public interface IMonitoringSystem
{
    void RecordFailure(string websiteConfigPath, string failureReason);
}
