using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Caching.Memory;

public class DatabaseProcessor
{
    private readonly ILogger<DatabaseProcessor> _logger;
    private readonly IMemoryCache _memoryCache;
    private readonly Dictionary<string, SqlConnection> _connections;

    public DatabaseProcessor(ILogger<DatabaseProcessor> logger, IMemoryCache memoryCache)
    {
        _logger = logger;
        _memoryCache = memoryCache;
        _connections = new Dictionary<string, SqlConnection>();
    }

    public async Task<SqlDataReader> ProcessByteArray(byte[] input, string databaseConnectionString, string query)
    {
        var connection = GetSqlConnection(databaseConnectionString);
        if (connection == null)
        {
            throw new ArgumentException("Invalid database connection string");
        }

        using (var command = new SqlCommand(query, connection))
        {
            try
            {
                await command.ExecuteNonQueryAsync();
                return command.ExecuteReader();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing query");
                throw;
            }
            finally
            {
                if (connection.State == ConnectionState.Open)
                {
                    connection.Close();
                }
            }
        }
    }

    private SqlConnection GetSqlConnection(string databaseConnectionString)
    {
        if (!_connections.ContainsKey(databaseConnectionString))
        {
            _connections[databaseConnectionString] = new SqlConnection(databaseConnectionString);
            _connections[databaseConnectionString].Open();
        }
        return _connections[databaseConnectionString];
    }

    public void Dispose()
    {
        foreach (var connection in _connections.Values)
        {
            connection.Close();
        }
        _memoryCache.Dispose();
    }
}
