using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public class MessageDecoder
{
    private readonly string _key = Environment.GetEnvironmentVariable("KEY");

    public async Task<string> DecodeMessageAsync(string jsonMessage, string jsonMetadata)
    {
        try
        {
            var metadata = JsonConvert.DeserializeObject<Metadata>(jsonMetadata);
            var messageJsonBytes = Convert.FromBase64String(jsonMessage);

            // Validate HMAC hash for integrity verification
            if (!ValidateHmac(messageJsonBytes, metadata.HMAC))
            {
                return "Invalid HMAC signature";
            }

            using (var tripleDes = TripleDESCryptoProvider.Create(_key, metadata.IV))
            {
                try
                {
                    var decryptedMessageBytes = Decrypt(tripleDes, messageJsonBytes);
                    return Encoding.UTF8.GetString(decryptedMessageBytes);
                }
                catch (Exception ex)
                {
                    return $"Decryption failed: {ex.Message}";
                }
            }
        }
        catch (Exception ex)
        {
            return $"Failed to decode message: {ex.Message}";
        }
    }

    private bool ValidateHmac(byte[] message, byte[] hmac)
    {
        using (var sha256 = SHA256CryptoProvider.Create())
        {
            var hashBytes = sha256.ComputeHash(message);
            return BitConverter.ToString(hashBytes).Replace("-", "") == Convert.ToBase64String(hmac);
        }
    }

    private byte[] Decrypt(TripleDESCryptoProvider tripleDes, byte[] message)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, tripleDes.CreateDecryptor()))
            {
                cs.Write(message, 0, message.Length);
                cs.FlushFinalBlock();
                return ms.ToArray();
            }
        }
    }

    private class Metadata
    {
        public string HMAC { get; set; }
        public string IV { get; set; }
    }
}

public static class TripleDESCryptoProvider
{
    public static TripleDESCryptoProvider Create(string key, byte[] iv)
    {
        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.Key = Convert.FromBase64String(key);
            tripleDes.IV = iv;
            return tripleDes;
        }
    }
}

public static class SHA256CryptoProvider
{
    public static SHA256CryptoProvider Create()
    {
        using (var sha256 = new SHA256CryptoServiceProvider())
        {
            return sha256;
        }
    }
}
