using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;

public class LargeTextFileProcessor
{
    private readonly DistributedCache _distributedCache;
    private readonly string _cacheKey = "large_text_file_hashes";

    public LargeTextFileProcessor(DistributedCache distributedCache)
    {
        _distributedCache = distributedCache;
    }

    public async Task ProcessLargeTextFileAsync(string filePath)
    {
        using (var fileStream = File.OpenRead(filePath))
        {
            var bytesRead = 0L;
            var chunkSize = 1024 * 1024; // 1MB chunks
            var hashBytes = new byte[32]; // SHA-256 hash size

            while ((bytesRead += chunkSize) <= fileStream.Length)
            {
                using (var chunkStream = new MemoryStream())
                {
                    await fileStream.CopyToAsync(chunkStream);
                    chunkStream.Position = 0;

                    using (var sha256 = SHA256.Create())
                    {
                        await chunkStream.CopyToAsync(sha256.BaseStream);
                        sha256.TransformFinalBlock(new byte[0], 0, 0);

                        var hashBytesChunk = sha256.Hash;
                        _distributedCache.SetString(_cacheKey, Convert.ToBase64String(hashBytesChunk), TimeSpan.FromHours(1));
                    }
                }
            }

            // Flush remaining file data
            await new StreamReader(fileStream).ReadToEndAsync();

            // Periodically flush cache to disk and secondary cache
            while (true)
            {
                await Task.Delay(TimeSpan.FromMinutes(5));
                await _distributedCache.SetString(_cacheKey, "flushed", TimeSpan.FromHours(1));
            }
        }
    }
}
