public class Aescbcp decryption
{
    public static string Decrypt(string ciphertext, string key, int blockSize)
    {
        byte[] cipherBytes = Convert.FromBase64String(ciphertext);
        using (Aes aes = Aes.Create())
        {
            aes.Key = Convert.FromBase64String(key);
            aes.BlockSize = blockSize * 8; // bytes to bits

            ICryptoTransform decryptor = aes.CreateDecryptor();

            using (MemoryStream ms = new MemoryStream(cipherBytes))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    byte[] plainBytes;
                    cs.Read(plainBytes = new byte[cipherBytes.Length], 0, cipherBytes.Length);

                    return Encoding.UTF8.GetString(plainBytes);
                }
            }
        }
    }
}
