public class DeserializationProcessor {
    public static <T> T deserialize(byte[] bytes, Class<T> clazz) throws IOException, InstantiationException, IllegalAccessException, InvocationTargetException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return clazz.cast(ois.readObject());
        } catch (ClassCastException e) {
            throw new RuntimeException("Deserialization failed due to incorrect object type", e);
        }
    }

    public static void deserializeWithFallback(byte[] bytes, Class<?>... classes) throws IOException, InstantiationException, IllegalAccessException, InvocationTargetException, ClassNotFoundException {
        for (Class<?> clazz : classes) {
            try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
                 ObjectInputStream ois = new ObjectInputStream(bais)) {
                return (Object) ois.readObject();
            } catch (ClassCastException e) {
                // Try the next class in the list
            }
        }
        throw new RuntimeException("Failed to deserialize data using all available classes");
    }

    public static void processBytes(byte[] bytes, Class<?> clazz) throws IOException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            // Perform any necessary processing or validation
            T instance = clazz.cast(ois.readObject());
            // Continue with instance handling
        } catch (ClassCastException e) {
            throw new RuntimeException("Deserialization failed due to incorrect object type", e);
        }
    }

    public static void processBytesWithFallback(byte[] bytes, Class<?>... classes) throws IOException {
        for (Class<?> clazz : classes) {
