        numFrames = 0;
        for (const auto& line : fileContent.split('\n')) {
            // Initialize a new frame structure dynamically
            LTE_PHY_PDU_T* frame = new LTE_PHY_PDU_T;

            // Extract and validate configuration parameters for each frame
            // ...

            // Add the validated frame to the array
            if (frame->txFrameInfo.isValid && frame->rxFrameInfo.isValid) {
                std::unique_ptr<LTE_PHY_PDU_T[]> frames(new LTE_PHY_PDU_T[numFrames + 1]);
                frames[numFrames] = frame;
                for (int i = 0; i < numFrames; ++i) {
                    frames[i] = this->frames[i];
                }
                delete[] this->frames;
                this->frames = std::move(frames);
                ++numFrames;
            } else {
                // Handle invalid or incomplete data
                delete frame;
            }
        }
    } catch (...) {
        // Handle any exceptions that may occur during the process
        return nullptr;
    }

