const axios = require('axios');
const zlib = require('zlib');

function executeShellCommandOnRemoteServer(command) {
  const apiEndpoint = 'https://example.com/shellcommands';
  const buffer = Buffer.alloc(0);
  let bytesRead = 0;
  let timerId;

  function startStreaming() {
    axios.post(apiEndpoint, { command })
      .then(response => {
        if (response.data.status === 'running') {
          timerId = setInterval(() => {
            axios.get(`${apiEndpoint}/output`, {
              params: { offset: bytesRead },
              responseType: 'stream',
            })
              .then(response => {
                const stream = response.data;
                let chunk;

                stream.on('data', (chunk) => {
                  buffer.write(chunk);
                  bytesRead += chunk.length;
                });

                stream.on('end', () => {
                  clearInterval(timerId);
                  process.stdout.write(buffer.toString());
                });
              })
              .catch((error) => {
                console.error(error);
                clearInterval(timerId);
              });
          }, 1000); // Update every 1 second
        } else if (response.data.status === 'completed') {
          process.stdout.write(buffer.toString());
        }
      })
      .catch((error) => {
        console.error(error);
      });
  }

  function stopStreaming() {
    clearInterval(timerId);
  }

  return { start: startStreaming, stop: stopStreaming };
}

module.exports = executeShellCommandOnRemoteServer;
