use std::fs::{create_dir_all, File};
use std::io::Write;
use std::path::PathBuf;

pub fn update_directory_config(directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let config_file_path = PathBuf::from("config.txt");
    let mut config_file = match File::create(config_file_path.clone()) {
        Ok(file) => file,
        Err(_) => return Err(format!("Failed to create configuration file: {}", config_file_path.display()).into()),
    };

    // Read existing directory path from configuration file
    let existing_directory_path = read_config_file(&config_file);

    // Create new directory with given name if it doesn't exist or update the existing one
    let directory_path = if let Some(existing_dir) = &existing_directory_path {
        PathBuf::from(existing_dir)
            .join(directory_name)
            .into_os_string()
            .to_str()
            .unwrap_or_default()
    } else {
        create_dir_all(PathBuf::from("directories").join(directory_name))?;
        directory_name.to_string()
    };

    // Update configuration file with the new directory path
    writeln!(config_file, "directory_path = \"{}\"", directory_path)?;
    Ok(())
}

// Helper function to read existing directory path from configuration file
fn read_config_file(file: &File) -> Option<String> {
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    let lines: Vec<_> = contents.lines().collect();
    lines.iter().find_map(|line| line.strip_prefix("directory_path = \"")?.strip_suffix("\"").map(|s| s.to_string())).cloned()
}']

