NFAPI_CRC_INDICATION_PDU_T* populateList(int n, int max_rssi) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % max_rssi;
        list[i].RNTI = rand();
        list[i].CRCFLAG = rand() & 1;
    }
    return list;
}

int main() {
    int* integers = NULL;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int n = 0, max_rssi = 0, largest = 0;
    char delimiter = '\n';
    FILE* file = stdin;

    if (fscanf(file, "%d", &max_rssi) != 1 || max_rssi < 1) {
        fprintf(stderr, "Invalid input: max_rssi\n");
        return -1;
    }

    int count = 0;
    while (fscanf(file, "%d%c", &integers[count], &delimiter) == 2 && delimiter == '\n') {
        if (!integers) {
            integers = (int*)malloc(16 * sizeof(int));
        } else if (count >= sizeof(ints)/sizeof(*ints)) {
            integers = (int*)realloc(integers, (count + 16) * sizeof(int));
        }
        largest = integers[count];
        count++;
    }

    n = count;
    printf("Largest integer: %d\n", largest);

    list = populateList(n, max_rssi);

    free(integers);
    free(list);

    return 0;
}']

