    strcpy(metadata->compression_type, "Unknown");
    metadata->extra_channels = 0;

    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // File not found
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);

    // Check for JPEG header signature
    char buffer[2];
    fread(buffer, 1, 2, file);
    if (buffer[0] != 0xFF || buffer[1] != 0xD8) {
        return -2; // Not a valid JPEG file
    }

    fseek(file, 0, SEEK_SET);

    // Read Exif data
    Metadata exif;
    int exif_size = read_exif_data(file, &exif);
    if (exif_size > 0) {
        metadata->resolution = exif.resolution;
        strcpy(metadata->color_space, exif.color_space);
        strcpy(metadata->compression_type, exif.compression_type);
        metadata->extra_channels = exif.extra_channels;
    }

    // Read ICC profile data
