#include <stdlib.h>
#include <string.h>

typedef struct {
    int offset;
} long_offset_t;

typedef struct {
    int key;
} int_key_t;

typedef struct {
    int value;
} record_t;

void* my_calloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && !realloc(ptr, size)) {
        free(ptr);
        return NULL;
    }
    return ptr;
}

int record_init(long_offset_t** offsets, int_key_t** keys, record_t** records, long max_allowable_memory_usage) {
    size_t offset_size = sizeof(long_offset_t);
    size_t key_size = sizeof(int_key_t);
    size_t record_size = sizeof(record_t);

    long num_offsets = 0;
    long num_keys = 0;
    long num_records = 0;

    // Calculate the maximum number of records that can be initialized
    long max_records = (max_allowable_memory_usage - offset_size * (num_offsets + 1) - key_size * (num_keys + 1)) / record_size;

    while(num_records < max_records && !malloc_error()) {
        // Allocate memory for new offsets, keys, and records
        long_offset_t* temp_offsets = my_calloc(max_records * offset_size);
        int_key_t* temp_keys = my_calloc(max_records * key_size);
        record_t* temp_records = my_calloc(max_records * record_size);

        // Update the counters and pointers
        num_offsets++;
        num_keys++;
        num_records++;

        // Store the allocated memory
        *offsets = temp_offsets;
        *keys = temp_keys;
        *records = temp_records;

        printf("Records initialized: %d\n", num_records);
    }

    if(num_records < max_records) {
        // Deallocate partially allocated resources in case of failure
        free(temp_offsets);
        free(temp_keys);
        free(temp_records);

        return -1;  // Allocation failed
    } else {
        return 0;  // Successful initialization
    }
}

int malloc_error() {
    // Handle memory allocation errors as needed
    return 0;
}
