```java
import java.util.ArrayList;
import java.util.List;

public class DisjointPairCounter {
    public static int countDisjointPairs(int[] arr) {
        List<Integer> disjointSets = new ArrayList<>();
        for (int i : arr) {
            disjointSets.add(i);
        }

        // Union-Find algorithm
        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (!find(disjointSets, i).equals(find(disjointSets, j))) {
                    union(disjointSets, i, j);
                }
            }
        }

        int disjointPairs = 0;
        for (int i = 0; i < arr.length; i++) {
            if (size(disjointSets, i) == 1) {
                disjointPairs++;
            }
        }

        return disjointPairs;
    }

    private static Integer find(List<Integer> sets, int x) {
        // Find the representative of the set containing x
        if (!sets.get(x).equals(sets.get(x))) {
            sets.set(x, find(sets, ((Integer) sets.get(x)).intValue()));
        }
        return sets.get(x);
    }

    private static void union(List<Integer> sets, int x, int y) {
        // Union the sets containing x and y
        Integer representativeX = (Integer) find(sets, x);
        Integer representativeY = (Integer) find(sets, y);
        if (!representativeX.equals(representativeY)) {
            sets.set(x, representativeY);
        }
    }

    private static int size(List<Integer> sets, int x) {
        // Get the size of the set containing x
        return 1 + (sets.get(x).equals(sets.get(x)) ? 0 : size(sets, ((Integer) sets.get(x)).intValue()));
    }
}
