using UnityEngine;

public class DynamicValueGenerator
{
    private float min;
    private float max;
    private float lastGeneratedValue;
    private HashSet<float> uniqueValuesGenerated;
    private int totalUniqueValuesToGenerate;

    public DynamicValueGenerator(float min, float max)
    {
        this.min = min;
        this.max = max;
        this.lastGeneratedValue = 0f;
        this.uniqueValuesGenerated = new HashSet<float>();
        this.totalUniqueValuesToGenerate = 10000; // default to generate 10,000 unique values
    }

    public float GetRandomFloatValue()
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public int GetRandomIntValue()
    {
        return (int)UnityEngine.Random.Range(min, max + 1);
    }

    public void GenerateRandomSequence(int totalUniqueValues)
    {
        if (totalUniqueValues <= 0)
            throw new ArgumentException("Total unique values must be a positive integer.");

        this.totalUniqueValuesToGenerate = totalUniqueValues;
    }

    public float NextValue()
    {
        while (!uniqueValuesGenerated.Add(lastGeneratedValue + 1f))
            lastGeneratedValue += 1f;

        return UnityEngine.Random.Range(min, max + 1);
    }

    public void ResetGenerator()
    {
        min = float.MinValue;
        max = float.MaxValue;
        lastGeneratedValue = 0f;
        uniqueValuesGenerated.Clear();
        totalUniqueValuesToGenerate = 10000; // default to generate 10,000 unique values
    }

    public override string ToString()
    {
        return $"Current State: Last Value - {lastGeneratedValue}, Available Range - ({min} - {max}), Unique Values Left - {totalUniqueValuesToGenerate}";
    }
}
