class SandeshClient {
public:
    SandeshClient(const bfs::path& config_file) : config_(config_file) {}

    void send_get_request() {
        // Read configuration from file
        read_config();

        // Create a new connection to the server
        ba::ip::tcp::socket socket(io_service_);
        connect_to_server(socket);

        // Send GET request with retry logic
