    int RNTI;
    int CRC_INDICATION_REL8_TAG[CRC_INDICATION_PDU_T_SIZE];
} NFAPI_CRC_INDICATION_PDU_T;

int manage_and_execute(int N, char* command, int seed) {
    // Initialize random number generator
    srand(time(NULL) + getpid() + seed);

    // Create and populate array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDATION_PDU_T* pdus = (NFAPI_CRC_INDATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDATION_PDU_T));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 200;
        for (int j = 0; j < CRC_INDICATION_PDU_T_SIZE; j++) {
            pdus[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
    }

    // Set resource limits
    struct rlimit rl;
    rl.rlim_cur = RLIMIT_CPU, rl.rlim_max = RLIMIT_CPU * 2;
    setrlimit(RLIMIT_CPU, &rl);

    // Fork and execute command in background process
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execvp(command, NULL);
    } else if (pid > 0) {
        // Parent process
        waitpid(pid, NULL, 0);

        // Monitor background process performance and health
        int status;
        while (1) {
            pid = waitpid(-1, &status, WNOHANG);
            if (pid == 0) break;

            // Check for errors and restart if necessary
            if (WIFEXITED(status)) {
                if (WEXITSTATUS(status) != 0) {
                    // Restart process with a new seed
                    srand(time(NULL) + getpid() + seed);
                    // Reset resource limits
                    setrlimit(RLIMIT_CPU, &rl);
                    // Re-exec command
                    execvp(command, NULL);
                }
            } else if (WIFSIGNALED(status)) {
                // Handle unhandled signal and notify main application
                printf("Background process terminated unexpectedly.\n");
                // Notify main application through callback function
            }
        }

        free(pdus);
    } else {
        // Error during fork or execvp
        return 0;
    }

    return 1;
}

