#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_INT 2147483647
#define MAX_ARRAY_SIZE 1024

typedef struct {
    int *data;
    int size;
} Array;

Array* array_new(int initial_size) {
    Array* arr = (Array*) malloc(sizeof(Array));
    arr->size = initial_size;
    arr->data = (int*) malloc(arr->size * sizeof(int));
    return arr;
}

void array_free(Array* arr) {
    free(arr->data);
    free(arr);
}

int array_append(Array* arr, int value) {
    if (arr->size == arr->data[0]) {
        arr->size *= 2;
        arr->data = (int*) realloc(arr->data, arr->size * sizeof(int));
    }
    arr->data[arr->size - 1] = value;
    return ++arr->size;
}

void process_stream(int fd) {
    Array* arr = array_new(10);
    int num_invalid = 0;
    while (1) {
        char buffer[5];
        read(fd, buffer, sizeof(buffer));
        for (int i = 0; i < 4; i++) {
            if (buffer[i] == '\n' || buffer[i] == '\r') break;
            int value = atoi(&buffer[i]);
            if (value < 0 || value > MAX_INT) {
                num_invalid++;
                continue;
            }
            array_append(arr, value);
        }
        read(fd, &buffer[4], 1); // consume newline
    }
}

void* process_streams(void* arg) {
    int* fd = (int*) arg;
    process_stream(*fd);
    return NULL;
}

void print_stats(Array* arrs[], int num_arrs) {
    int max_val = INT_MIN;
    for (int i = 0; i < num_arrs; i++) {
        Array* arr = arrs[i];
        printf("Stream %d: invalid entries = %d\n", i, arr->size - 1);
        for (int j = 0; j < arr->size; j++) {
            if (arr->data[j] > max_val) max_val = arr->data[j];
        }
    }
    printf("Largest integer across all streams: %d\n", max_val);
}

int main(int argc, char* argv[]) {
    int num_fds = 0;
    pthread_t* threads = NULL;
    Array* arrs[MAX_ARRAY_SIZE];

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-n")) {
            num_fds = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-b")) {
            int batch_size = atoi(argv[++i]);
            // Initialize threads and arrays
            threads = (pthread_t*) malloc(num_fds * sizeof(pthread_t));
            for (int j = 0; j < num_fds; j++) {
                arrs[j] = array_new(batch_size);
                pthread_create(&threads[j], NULL, process_streams, &argv[i+1]);
                i++;
            }
        } else if (!strcmp(argv[i], "-p")) {
            // Process streams in parallel
            for (int j = 0; j < num_fds; j++) {
                pthread_join(threads[j], NULL);
            }
        } else {
            printf("Invalid command-line option\n");
            return 1;
        }

    print_stats(arrs, num_fds);

    return 0;
}
