    *count = 0;
    char c;
    while ((c = getchar()) != delimiter && *count < MAX_INTS) {
        if (*integers == NULL) {
            *integers = malloc((*count + 1) * sizeof(int));
            if (*integers == NULL) {
                fprintf(stderr, "Memory allocation failed.\n");
                exit(1);
            }
        } else {
            (*integers)[*count] = c - '0';
            (*integers)++;
        }
        (*count)++;
    }
}

