// Define the structure type
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage a dynamically allocated array of structures
int* crcIndicationArray(int* n, NFAPI_CRC_INDICATION_PDU_T** data) {
    // Dynamically allocate memory for the array
    *data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*data == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize CRC flags and indices
    int crcFlags[2] = {0, 1};  // Alternate between 0 and 1 for the first two elements

    for (int i = 0; i < *n; i++) {
        // Generate a random CRC flag value based on the current index
        if (i > 0) {
            crcFlags[0] ^= 1;
            crcFlags[1] ^= 1;
        }
        int crcFlag = crcFlags[i % 2];

        (*data)[i].RX_UE_INFORMATION_TAG = i;
        (*data)[i].RNTI = i * 10;  // Assign a random RNTI value
        (*data)[i].CRC_INDICATION_REL8_TAG = crcFlag;

        if (i > 0) {
            for (int j = i - 1; j >= 0; j--) {
                if ((*data)[j].CRC_INDICATION_REL8_TAG == crcFlag) {
                    // Ensure no two adjacent elements have the same CRC flag value
                    crcFlags[i % 2] ^= 1;
                    break;
                }
            }
        }
    }

    return *n;
}

// Function to retrieve the number of successfully populated structures in the array
int getArraySize(NFAPI_CRC_INDICATION_PDU_T** data) {
    int size = 0;

    for (int i = 0; i < (*data)[0].RX_UE_INFORMATION_TAG; i++) {
        if ((*data)[i].CRC_INDICATION_REL8_TAG != -1) {
            size++;
        }
    }

    return size;
}

// Function to modify an existing structure's CRC flag value based on its index
void modifyCRC(int* n, NFAPI_CRC_INDICATION_PDU_T** data, int idx, int newCRCFlag) {
    if (idx < *n) {
        (*data)[idx].CRC_INDICATION_REL8_TAG = newCRCFlag;
    }
}

// Function to integrate dynamic loading of configuration settings for CRC generation rules
int loadConfig(int* n, NFAPI_CRC_INDICATION_PDU_T** data, FILE* configFile) {
    // Load configuration settings from the file
    int crcFlags[2] = {0, 1};  // Alternate between 0 and 1 for the first two elements

    while (fscanf(configFile, "%d %d %d\n", &(*data)[i].RX_UE_INFORMATION_TAG, &(*data)[i].RNTI, &(*data)[i].CRC_INDICATION_REL8_TAG) == 3) {
        if (i > 0) {
            crcFlags[0] ^= 1;
            crcFlags[1] ^= 1;
        }
        int crcFlag = crcFlags[i % 2];

        // Update the CRC flag value based on the configuration settings
        (*data)[i].CRC_INDICATION_REL8_TAG = crcFlag;

        i++;
    }

    return *n;
}

// Function to free allocated memory and close any open files
void cleanUp(int* n, NFAPI_CRC_INDICATION_PDU_T** data) {
    if (*data != NULL) {
        free(*data);
        *data = NULL;
    }
}
