typedef struct {
    int UE_ID;
    void* RRC_Connection;
    pthread_mutex_t session_list_lock;
    pthread_cond_t session_list_cond;
    void** PDUSession_array;
    int PDUSession_count;
} UEContext;

UEContext* ue_context_create(int UE_ID, void* RRC_Connection) {
    UEContext* new_ue = (UEContext*)malloc(sizeof(UEContext));
    if (!new_ue) {
        return NULL;  // Handle memory allocation failure
    }
    new_ue->UE_ID = UE_ID;
    new_ue->RRC_Connection = RRC_Connection;
    pthread_mutex_init(&new_ue->session_list_lock, NULL);
    pthread_cond_init(&new_ue->session_list_cond, NULL);
    new_ue->PDUSession_array = NULL;
    new_ue->PDUSession_count = 0;
    return new_ue;
}

void ue_context_destroy(UEContext* ue) {
    if (ue) {
        free(ue->PDUSession_array);  // Handle memory deallocation
        pthread_mutex_destroy(&ue->session_list_lock);
        pthread_cond_destroy(&ue->session_list_cond);
        free(ue);
    }
}

int ue_context_add_PDUSession(UEContext* ue, void* PDUSession) {
    pthread_mutex_lock(&ue->session_list_lock);
    if (ue->PDUSession_array == NULL) {
        ue->PDUSession_array = (void**)malloc(sizeof(void*) * 2);  // Allocate initial memory
    }
    int index = ue->PDUSession_count++;
    void** temp_array = realloc(ue->PDUSession_array, sizeof(void*) * (ue->PDUSession_count + 1));  // Handle memory reallocation failure
    if (!temp_array) {
        // Handle memory allocation failure
    }
    ue->PDUSession_array = temp_array;
    ue->PDUSession_array[index] = PDUSession;
    pthread_mutex_unlock(&ue->session_list_lock);
    return index;  // Return the newly added session's index
}

int ue_context_remove_PDUSession(UEContext* ue, int index) {
    pthread_mutex_lock(&ue->session_list_lock);
    if (index < 0 || index >= ue->PDUSession_count) {
        // Handle invalid session index
    }
    void** temp_array = realloc(ue->PDUSession_array, sizeof(void*) * (ue->PDUSession_count - 1));  // Handle memory reallocation failure
    if (!temp_array) {
        // Handle memory allocation failure
    }
    ue->PDUSession_array = temp_array;
    memmove(&ue->PDUSession_array[index], &ue->PDUSession_array[index + 1], sizeof(void*) * (ue->PDUSession_count - index - 1));
    ue->PDUSession_count--;
    pthread_mutex_unlock(&ue->session_list_lock);
    return 0;  // Return success
}

