    for (int i = 0; i < N; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = // random value
        pdu_array[i].RNTI = // random value
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand();
        pdu_array[i].CRCFLAG = rand();

        if (sem_wait(semaphore) != 0) {
            free(pdu_array);
            sem_close(semaphore);
            return -1;
        }
    }

    sem_post(semaphore);

    int created = N;
    for (int i = 0; i < N; i++) {
        // some error handling logic
    }

    free(pdu_array);
    sem_close(semaphore);

    return created;
}
