}

void nfaPi_crc_indication_pdu_collection_compact(NFAPI_CRC_INDICATION_PDU_T_Collection* collection) {
    if (!collection)
        return;

    NFAPI_CRC_INDICATION_PDU_T* newElements = (NFAPI_CRC_INDICATION_PDU_T*)malloc((collection->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < collection->size; ++i)
        newElements[i] = collection->elements[i];
    free(collection->elements);
    collection->elements = newElements;
