}

void nfaPi_crc_indication_pdu_collection_add(NFAPI_CRC_INDICATION_PDU_T_Collection* collection, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!collection || !element)
        return;

    if (collection->size >= collection->capacity / 2 && collection->size * 4 < collection->capacity)
        nfaPi_crc_indication_pdu_collection_compact(collection);

    if (collection->size >= collection->capacity) {
        collection->elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->elements, (collection->capacity * 2 + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        collection->capacity *= 2;
    }

    collection->elements[collection->size] = element;
    ++collection->size;
}

void nfaPi_crc_indication_pdu_collection_remove_at_index(NFAPI_CRC_INDICATION_PDU_T_Collection* collection, int index) {
    if (!collection || index < 0 || index >= collection->size)
        return;

    for (int i = index; i < collection->size - 1; ++i)
        collection->elements[i] = collection->elements[i + 1];

