#include <string.h>

#define MAX_ELEMENTS 1000
#define BUFFER_SIZE 1024

int max_elements = MAX_ELEMENTS;
int buffer[BUFFER_SIZE];
int buffer_size = 0;

void process_data() {
    int max_val = -1, sum = 0;
    for (int i = 0; i < buffer_size; i++) {
        if (buffer[i] > max_val) {
            max_val = buffer[i];
        }
        sum += buffer[i];
    }
    printf("Largest integer: %d\n", max_val);
    printf("Average integer: %.2f\n", (double)sum / buffer_size);
}

int main() {
    int sock, conn;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    // Establish a network socket connection
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket");
        return 1;
    }
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        return 1;
    }
    if (listen(sock, 3) < 0) {
        perror("listen");
        return 1;
    }

    while ((conn = accept(sock, (struct sockaddr *)&client_addr, &client_len)) > 0) {
        int val;
        for (int i = 0; i < max_elements; i++) {
            read(conn, &val, sizeof(int));
            if (i >= buffer_size) {
                buffer_size++;
                buffer = realloc(buffer, buffer_size * sizeof(int));
            }
            buffer[i] = val;
        }

        process_data();

        close(conn);
    }

    return 0;
}
