    sem_t *sem = sem_open("/nfalock", O_CREAT | O_EXCL, 0644, 1);
    if (sem == SEM_FAILED) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* puds = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!puds) {
        sem_close(sem);
        return NULL;
    }

    for (int i = 0; i < list_size; i++) {
        puds[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        puds[i].RNTI = rand() % 1000000;
        puds[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        puds[i].CRCFLAG = rand() % 2;
    }

    sem_close(sem);
    return puds;
}
