import os
import json
import time
import logging
from requests import get, post
from retrying import retry

logging.basicConfig(level=logging.INFO)

class ConfigProcessor:
    def __init__(self):
        self.config_server_url = 'https://config-server.com'
        self.credential_store_url = 'https://secure-storage.com'
        self.placeholder_prefix = '%PLACEHOLDER%'
        self.retries = 3
        self.backoff_time = 2

    @retry(stop_max_attempt_number=self.retries, stop_sleep_first=True, sleep_increase=self.backoff_time)
    def get_config_values(self, config_file):
        try:
            response = get(f'{self.config_server_url}/config/{os.path.basename(config_file)}')
            if response.status_code != 200:
                raise Exception('Failed to retrieve configuration values')
            return json.loads(response.content.decode())
        except Exception as e:
            logging.error(f'Error retrieving configuration values: {e}')
            raise

    @retry(stop_max_attempt_number=self.retries, stop_sleep_first=True, sleep_increase=self.backoff_time)
    def get_credentials(self):
        try:
            response = post(f'{self.credential_store_url}/credentials')
            if response.status_code != 200:
                raise Exception('Failed to retrieve service credentials')
            return json.loads(response.content.decode())
        except Exception as e:
            logging.error(f'Error retrieving service credentials: {e}')
            raise

    def process_config_file(self, config_file):
        try:
            with open(config_file) as f:
                config = json.load(f)
                for section in config:
                    if 'placeholders' in section:
                        values = self.get_config_values(config_file)
                        for placeholder, value in values.items():
                            if placeholder.startswith(self.placeholder_prefix):
                                section['placeholders'][placeholder.replace(self.placeholder_prefix, '')] = value
            return config
        except Exception as e:
            logging.error(f'Error processing configuration file: {e}')
            raise

    def add_credentials_section(self, config):
        try:
            credentials = self.get_credentials()
            if 'credentials' not in config:
                config['credentials'] = {}
            for key, value in credentials.items():
                config['credentials'][key] = value
            return config
        except Exception as e:
            logging.error(f'Error adding service credentials: {e}')
            raise

    def update_config_file(self, config_file):
        try:
            config = self.process_config_file(config_file)
            config = self.add_credentials_section(config)
            with open(config_file, 'w') as f:
                json.dump(config, f, indent=4)
            logging.info(f'Updated configuration file: {config_file}')
        except Exception as e:
            logging.error(f'Error updating configuration file: {e}')

if __name__ == '__main__':
    processor = ConfigProcessor()
    config_files = ['file1.json', 'file2.json']
    for config_file in config_files:
        processor.update_config_file(config_file)
