NFAPI_L1_RXINFO* initialize_and_populate_NFAPI_L1_RXINFO(int n, int ref_crc_value) {
    NFAPI_L1_RXINFO* nfapi_rxinfo_array = (NFAPI_L1_RXINFO*)malloc(n * sizeof(NFAPI_L1_RXINFO));

    if (!nfapi_rxinfo_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int crc_ref_value = ref_crc_value; // Store reference value for validation
    int retry_count = 0;

    for (int i = 0; i < n; i++) {
        NFAPI_L1_RXINFO* nfapi_rxinfo = &nfapi_rxinfo_array[i];

        if (!nfapi_rxinfo) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        nfapi_rxinfo->rx_ue_info_tag = i; // Set rx_ue_info_tag
        nfapi_rxinfo->rnti = i; // Set RNTI

        char* crc_indication_rel8_tag = (char*)malloc(16 * sizeof(char)); // Dynamically allocate CRC_INDICATION_REL8_TAG with a fixed size

        if (!crc_indication_rel8_tag) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        while (1) {
            // Simulate external data source response delay
            sleep(1);

            int crc_value = get_crc_value_from_external_data_source();

            if (crc_value == crc_ref_value) {
                nfapi_rxinfo->crc_indication_rel8_tag = crc_indication_rel8_tag;
                break; // Validation successful, exit loop
            } else {
                retry_count++;

                if (retry_count > 5) { // Exponential backoff with a maximum of 5 retries
                    printf("CRC validation failed after %d retries.\n", retry_count);
                    free(crc_indication_rel8_tag);
                    return NULL;
                }
            }
        }
    }

    return nfapi_rxinfo_array;
}

