#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/rand.h>

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB
} DESMode;

typedef struct {
    uint8_t *key;
    size_t key_len;
    uint8_t mode;
} DESParams;

typedef enum {
    RSA_PKCS1_PADDING,
    RSA_OAEP_PADDING
} RSAPaddingType;

typedef struct {
    uint8_t *n;
    uint8_t *e;
    uint8_t *d;
    RSAPaddingType padding_type;
} RSAParams;

void aes_encrypt(const uint8_t *key, const uint8_t *data, size_t data_len, uint8_t **cipher) {
    AES_KEY aes_key;
    AES_set_encrypt_key(key, 16, &aes_key);
    *cipher = malloc(data_len + AES_BLOCK_SIZE);
    AES_cbc_encrypt(data, *cipher, data_len, &aes_key, NULL, AES_ENCRYPT);
}

void aes_decrypt(const uint8_t *key, const uint8_t *cipher, size_t cipher_len, uint8_t **data) {
    AES_KEY aes_key;
    AES_set_decrypt_key(key, 16, &aes_key);
    *data = malloc(cipher_len - AES_BLOCK_SIZE);
    AES_cbc_encrypt(cipher, *data, cipher_len, &aes_key, NULL, AES_DECRYPT);
}

void des_encrypt(const DESParams *params, const uint8_t *data, size_t data_len, uint8_t **cipher) {
    DES_KEY des_key;
    DES_set_key_checked(params->key, params->key_len, &des_key);
    *cipher = malloc(data_len + DES_BLOCK_SIZE);
    DES_cbc_encrypt(data, *cipher, data_len, &des_key, NULL, params->mode == CFB ? DES_CBC64 : params->mode);
}

void des_decrypt(const DESParams *params, const uint8_t *cipher, size_t cipher_len, uint8_t **data) {
    DES_KEY des_key;
    DES_set_key_checked(params->key, params->key_len, &des_key);
    *data = malloc(cipher_len - DES_BLOCK_SIZE);
    DES_cbc_encrypt(cipher, *data, cipher_len, &des_key, NULL, params->mode == CFB ? DES_CBC64 : params->mode);
}

void rsa_encrypt(const RSAParams *params, const uint8_t *data, size_t data_len, uint8_t **cipher) {
    RSA *rsa;
    BIGNUM *message;
    BIGNUM *encrypted_message;

    rsa = RSA_new();
    message = BN_new();
    encrypted_message = BN_new();

    BN_set_word(message, (BN_long)data);
    RSA_public_encrypt(data_len, message, encrypted_message, params->n, params->e, params->padding_type);

    *cipher = malloc(encrypted_message->top - 1);
    BN_bn2hex(encrypted_message, *cipher);

    RSA_free(rsa);
    BN_free(message);
    BN_free(encrypted_message);
}

void rsa_decrypt(const RSAParams *params, const uint8_t *cipher, size_t cipher_len, uint8_t **data) {
    RSA *rsa;
    BIGNUM *message;
    BIGNUM *decrypted_message;

    rsa = RSA_new();
    message = BN_new();
    decrypted_message = BN_new();

    BN_hex2bn(&message, (char *)cipher);
    RSA_private_decrypt(cipher_len, message, decrypted_message, params->n, params->d);

    *data = malloc(decrypted_message->top - 1);
    BN_bn2hex(decrypted_message, *data);

    RSA_free(rsa);
    BN_free(message);
    BN_free(decrypted_message);
}

int main() {
    // Initialize encryption framework
    OpenSSL_add_all_algorithms();

    // Example usage: AES-128-CBC encryption and decryption
    uint8_t key[AES_KEY_SIZE];
    uint8_t *data = malloc(16); // Fill with plaintext data
    size_t data_len = 16;
    uint8_t *cipher;

    aes_encrypt(key, data, data_len, &cipher);
    printf("Encrypted: %x\n", cipher);

    uint8_t *decrypted_data;
    aes_decrypt(key, cipher, data_len + AES_BLOCK_SIZE, &decrypted_data);
    printf("Decrypted: %x\n", decrypted_data);

    free(data);
    free(cipher);
    free(decrypted_data);

    // Example usage: DES-ECB encryption and decryption
    uint8_t des_key[DES_KEY_SIZE];
    uint8_t *data_des = malloc(8); // Fill with plaintext data
    size_t data_len_des = 8;
    uint8_t *cipher_des;

    DESParams params;
    params.key = des_key;
    params.key_len = 8;
    params.mode = ECB;

    des_encrypt(&params, data_des, data_len_des, &cipher_des);
    printf("Encrypted (DES-ECB): %x\n", cipher_des);

    uint8_t *decrypted_data_des;
    des_decrypt(&params, cipher_des, data_len_des + DES_BLOCK_SIZE, &decrypted_data_des);
    printf("Decrypted (DES-ECB): %x\n", decrypted_data_des);

    free(data_des);
    free(cipher_des);
    free(decrypted_data_des);

    // Example usage: RSA encryption and decryption
    uint8_t rsa_n[RSAPARAMS_N_SIZE];
    uint8_t rsa_e[RSAPARAMS_E_SIZE];
    uint8_t rsa_d[RSAPARAMS_D_SIZE];

    RSAParams params_rsa;
    params_rsa.n = rsa_n;
    params_rsa.e = rsa_e;
    params_rsa.d = rsa_d;
    params_rsa.padding_type = RSA_PKCS1_PADDING;

    uint8_t *data_rsa = malloc(16); // Fill with plaintext data
    size_t data_len_rsa = 16;
    uint8_t *cipher_rsa;

    rsa_encrypt(&params_rsa, data_rsa, data_len_rsa, &cipher_rsa);
    printf("Encrypted (RSA): %x\n", cipher_rsa);

    uint8_t *decrypted_data_rsa;
    rsa_decrypt(&params_rsa, cipher_rsa, data_len_rsa + RSA_BLOCK_SIZE, &decrypted_data_rsa);
    printf("Decrypted (RSA): %x\n", decrypted_data_rsa);

    free(data_rsa);
    free(cipher_rsa);
    free(decrypted_data_rsa);

    // Clean up
    OpenSSL_cleanup();

    return 0;
}
