#define MAX_REQUEST_LENGTH 1024
#define MAX_REDIRECTS 5

typedef struct {
    int sock;
    char *host;
    int port;
} connection_t;

typedef struct {
    char *method;
    char *url;
    char *data;
} request_t;

connection_t *create_connection(char *host, int port) {
    connection_t *conn = (connection_t *)malloc(sizeof(connection_t));
    conn->sock = -1;
    conn->host = host;
    conn->port = port;
    return conn;
}

void destroy_connection(connection_t *conn) {
    if (conn != NULL && conn->sock >= 0) {
        close(conn->sock);
    }
    free(conn);
}

request_t *create_request(char *method, char *url, char *data) {
    request_t *req = (request_t *)malloc(sizeof(request_t));
    req->method = method;
    req->url = url;
    req->data = data;
    return req;
}

void destroy_request(request_t *req) {
    if (req != NULL) {
        free(req->method);
        free(req->url);
        free(req->data);
    }
    free(req);
}

int send_request(connection_t *conn, request_t *req) {
    int sock = conn->sock;
    char buffer[MAX_REQUEST_LENGTH];
    sprintf(buffer, "%s %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\nContent-Length: %zu\r\n\r%s", 
            req->method, req->url, conn->host, strlen(req->data), req->data);
    send(sock, buffer, strlen(buffer), 0);

    return 0;
}

int receive_response(connection_t *conn) {
    int sock = conn->sock;
    char buffer[1024];
    int bytes_received = recv(sock, buffer, sizeof(buffer), 0);

    if (bytes_received > 0) {
        printf("%s\n", buffer);
    }

    return bytes_received;
}

int main() {
    connection_t *conn = create_connection("www.example.com", 80);
    request_t *req = create_request("GET", "/path/to/resource", "");

    send_request(conn, req);

    destroy_request(req);
    destroy_connection(conn);

    return 0;
}
