int main(int argc, char* argv[]) {
    sem_t *semaphore;
    int semaphore_value = 3; // Initial value for semaphore
    pid_t child_pid;

    // Initialize semaphore with initial value
    if (sem_init(&semaphore, 0, semaphore_value) == -1) {
        perror("sem_init");
        return 1;
    }

    try_lock:
    // Acquire the semaphore
    if (sem_wait(&semaphore) == -1) {
        perror("sem_wait");
        goto error;
    }

    // Create a new process to execute the command
    child_pid = fork();
    if (child_pid < 0) {
        perror("fork");
        goto error;
    } else if (child_pid > 0) {
        // Parent process, wait for child to finish
        int status;
        waitpid(child_pid, &status, 0);
        sem_post(&semaphore); // Release the semaphore
        return status;
    }

    // Child process, execute the command
    execvp(argv[1], argv + 1);

error:
    sem_post(&semaphore); // Release the semaphore in case of error
    if (child_pid > 0) {
        waitpid(child_pid, NULL, 0);
    }
    sem_destroy(&semaphore); // Clean up semaphore
    return 1;
}
