pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0, capacity = MAX_SIZE;

void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list_lock);

    if(list_size >= capacity) {
        // Remove oldest element
        NFAPI_CRC_INDICATION_PDU_T* oldest = nfa_list;
        for(int i = 1; i < list_size; i++) {
            oldest = &nfa_list[i];
        }

        free(oldest);
        list_size--;
    }

    // Add new element
    if(list_size < capacity) {
        nfa_list = realloc(nfa_list, (list_size + 2)*sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&nfa_list[list_size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list_size++;
    }

    pthread_mutex_unlock(&list_lock);
}

void generate_crc_flag(NFAPI_CRC_INDICATION_PDU_T* element) {
    // Integrate with external data source for random number generation
    int crc_flag = rand() % 2; // Randomly generate CRCFLAG (0 or 1)
