#include <string.h>
#include <pthread.h>

#define MAX_INTS 1000
#define NFAPI_CRC_INDICATION_PDU_T struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[4];
};

void* largest_int_helper(void* ptr);
NFAPI_CRC_INDICATION_PDU_T* generate_nfapi_crc_indication_pdu_t(int rnti);

void read_and_process_data(int fd, int max_ints) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    int ints[MAX_INTS];
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_ts = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_ints * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_t thread;

    for (int i = 0; i < max_ints; i++) {
        int result;
        pthread_mutex_lock(&lock);
        read(fd, &result, sizeof(int));
        pthread_mutex_unlock(&lock);

        if (result < 0) {
            break;
        }

        ints[i] = result;

        NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_t = generate_nfapi_crc_indication_pdu_t(result);
    }

    for (int i = 0; i < max_ints; i++) {
        if (ints[i] > 0) {
            pthread_create(&thread, NULL, largest_int_helper, &ints[i]);
            pthread_join(thread, NULL);
        }
    }

    free(nfapi_crc_indication_pdu_ts);

    void* largest_int = malloc(sizeof(int));
    for (int i = 0; i < max_ints; i++) {
        pthread_mutex_lock(&lock);
        read(fd, largest_int, sizeof(int));
        pthread_mutex_unlock(&lock);
    }

    printf("Largest integer: %d\n", *(int*)largest_int);

    free(largest_int);

    close(fd);
}

void* largest_int_helper(void* ptr) {
    int* largest = (int*)ptr;
    for (int i = 0; i < MAX_INTS; i++) {
        if (*((int*)malloc(sizeof(int))) > *largest) {
            *largest = *((int*)malloc(sizeof(int)));
        }
        free((int*)malloc(sizeof(int)));
    }

    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfapi_crc_indication_pdu_t(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_t = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < strlen(RX_UE_INFORMATION_TAG); i++) {
        ((char*)nfapi_crc_indication_pdu_t)[i] = ' ';
    }

    strcpy(((char*)nfapi_crc_indication_pdu_t), RX_UE_INFORMATION_TAG);

    nfapi_crc_indication_pdu_t->RNTI = rnti;

    for (int i = 0; i < strlen(CRC_INDICATION_REL8_TAG); i++) {
        ((char*)nfapi_crc_indication_pdu_t)[i] = ' ';
    }

    strcpy(((char*)nfapi_crc_indication_pdu_t), CRC_INDICATION_REL8_TAG);

    uint32_t crcflag = hash(rnti, RX_UE_INFORMATION_TAG) % 256;

    sprintf(((char*)nfapi_crc_indication_pdu_t + strlen(CRC_INDICATION_REL8_TAG)), "%02x", crcflag);

    return nfapi_crc_indication_pdu_t;
}

uint32_t hash(int rnti, char* tag) {
    uint32_t hash = 0;
    for (int i = 0; i < strlen(tag); i++) {
        hash = (hash << 5) ^ (uint8_t)tag[i];
    }
    return (uint32_t)(hash % (1 << 16));
}
