NetworkNotification* create_network_notification(const char* ue_ci, int seq_num, const char* error_status_report) {
    NetworkNotification* notification = (NetworkNotification*)malloc(sizeof(NetworkNotification));
    strcpy(notification->ue_ci, ue_ci);
    notification->seq_num = seq_num;
    strcpy(notification->error_status_report, error_status_report);
    notification->timestamp = time(NULL);
    notification->checksum = 0; // Initialize checksum
    return notification;
}

void validate_network_notification(NetworkNotification* notification) {
    uint32_t calculated_checksum = 0;
    for (int i = 0; i < strlen(notification->ue_ci); i++) {
        calculated_checksum += notification->ue_ci[i];
    }
    calculated_checksum += notification->seq_num;
    for (int i = 0; i < strlen(notification->error_status_report); i++) {
        calculated_checksum += notification->error_status_report[i];
    }
    calculated_checksum += (uint32_t)notification->timestamp;
    if (calculated_checksum != notification->checksum) {
        printf("Invalid checksum detected.\n");
        free(notification);
        notification = NULL;
    }
}

void destroy_network_notification(NetworkNotification* notification) {
    free(notification);
}
