typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[50];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Thread-safe linked list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

// Initialize the linked list
LinkedList* init_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL; // Handle allocation failure

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Insert at the head of the linked list
void insert_head(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return; // Handle allocation failure

    node->data = data;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head = node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Remove from the head of the linked list
void remove_head(LinkedList* list) {
    if (list->head == NULL) return; // Handle empty list

    Node* node = list->head;

    pthread_mutex_lock(&list->lock);
    list->head = node->next;
    if (list->head == NULL) list->tail = NULL;
    pthread_mutex_unlock(&list->lock);

    free(node);
}

// Serialize the linked list to a binary file
int serialize(LinkedList* list, FILE* file) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    return 0; // Assuming success
}

// Deserialize the linked list from a binary file
int deserialize(LinkedList* list, FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        // Check for valid RNTI range and CRCFLAG validity
        if (data.RNTI < 0 || data.RNTI > 255) return -1; // Handle invalid RNTI

        insert_head(list, data);
    }

    return 0; // Assuming success
}

// Log operation status or errors
void log(LinkedList* list, int level, const char* message) {
    // Log to a file with configurable logging level
    // ...

    printf("%d: %s\n", level, message);
}

int main() {
    LinkedList* list = init_linked_list();
    if (!list) return 1; // Handle allocation failure

    insert_head(list, (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG=123,.RNTI=10,.CRC_INDICATION_REL8_TAG="Test",.CRCFLAG=1});
    insert_head(list, (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG=456,.RNTI=20,.CRC_INDICATION_REL8_TAG="Hello",.CRCFLAG=0});

    FILE* file = fopen("example.bin", "wb");
    if (!file) return 1; // Handle file open failure

    serialize(list, file);

    fclose(file);
    remove_head(list); // Remove and free nodes
    free(list);

    return 0;
}
