#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define threshold for switching from array to linked list
#define THRESHOLD 10

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic collection of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    int size;
    int capacity;
    int threshold;
    int is_linked_list;
    struct node* head;
} NFAPICRCINDICATIONPDU_TCollection;

// Node structure for linked list
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} node;

// Initialize collection
NFAPICRCINDICATIONPDU_TCollection* init_collection() {
    NFAPICRCINDICATIONPDU_TCollection* coll = (NFAPICRCINDICATIONPDU_TCollection*)malloc(sizeof(NFAPICRCINDICATIONPDU_TCollection));
    coll->array = NULL;
    coll->size = 0;
    coll->capacity = THRESHOLD;
    coll->threshold = THRESHOLD;
    coll->is_linked_list = 0;
    coll->head = NULL;
    return coll;
}

// Free allocated memory
void free_collection(NFAPICRCINDICATIONPDU_TCollection* coll) {
    if (coll->array != NULL) {
        free(coll->array);
    }
    if (coll->is_linked_list) {
        node* temp = coll->head;
        while (temp != NULL) {
            node* next = temp->next;
            free(temp);
            temp = next;
        }
    }
    free(coll);
}

// Check current capacity
int get_capacity(NFAPICRCINDICATIONPDU_TCollection* coll) {
    return coll->capacity;
}

// Display collection contents
void display_collection(NFAPICRCINDICATIONPDU_TCollection* coll) {
    for (int i = 0; i < coll->size; i++) {
        printf("Element %d: %p\n", i, &coll->array[i]);
    }
}

// Add element to collection
void add_element(NFAPICRCINDICATIONPDU_TCollection* coll, NFAPI_CRC_INDICATION_PDU_T element) {
    if (coll->size >= coll->capacity) {
        // Double capacity and re-allocate array
        coll->capacity *= 2;
        coll->array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(coll->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * coll->capacity);
    }
    if (!coll->is_linked_list && coll->size >= coll->threshold) {
        // Switch to linked list
        coll->is_linked_list = 1;
        node* new_node = (node*)malloc(sizeof(node));
        new_node->data = element;
        new_node->next = NULL;
        if (coll->head == NULL) {
            coll->head = new_node;
        } else {
            node* temp = coll->head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    } else {
        // Add to array
        coll->array[coll->size] = element;
    }
    coll->size++;
}

// Remove element from collection by index
void remove_element(NFAPICRCINDICATIONPDU_TCollection* coll, int index) {
    if (coll->is_linked_list) {
        // Find node to remove in linked list
        node* temp = coll->head;
        for (int i = 0; i < index && temp != NULL; i++) {
            temp = temp->next;
        }
        if (temp == NULL || temp->next == NULL) {
            printf("Index out of bounds\n");
            return;
        }
        // Remove node from linked list
        node* next = temp->next;
        free(temp);
        if (index > 0) {
            coll->head = next;
        } else {
            coll->head = next;
        }
    } else {
        // Remove from array
        if (index >= coll->size || index < 0) {
            printf("Index out of bounds\n");
            return;
        }
        for (int i = index; i < coll->size - 1; i++) {
            coll->array[i] = coll->array[i + 1];
        }
        coll->size--;
    }
}

// Utility function to compact array
void compact_array(NFAPICRCINDICATIONPDU_TCollection* coll) {
    int new_capacity = (int)((double)coll->size * 0.75);
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    int j = 0;
    for (int i = 0; i < coll->size; i++) {
        if (coll->array[i].crcflag != 0) { // Check for valid CRCFLAG
            new_array[j] = coll->array[i];
            j++;
        }
    }
    free(coll->array);
    coll->array = new_array;
    coll->capacity = new_capacity;
}

int main() {
    NFAPICRCINDICATIONPDU_TCollection* collection = init_collection();

    // Add elements
    add_element(collection, (NFAPI_CRC_INDICATION_PDU_T){.rx_ue_info=1,.rnti=2,.crc_indication_rel8_tag=3,.crcflag=rand()%2});
    add_element(collection, (NFAPI_CRC_INDICATION_PDU_T){.rx_ue_info=4,.rnti=5,.crc_indication_rel8_tag=6,.crcflag=rand()%2});

    // Remove elements
    remove_element(collection, 1);

    // Display collection contents
    display_collection(collection);

    free_collection(collection);

    return 0;
}
