// Function to generate and manage linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* nfaPI_CRC_IndicationPDU_Manager(int numUEs, char** RNTIs, int* CRCFLAGS) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    // Initialize random number generator
    srand(time(NULL));

    for (int i = 0; i < numUEs; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newPDU = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!head) { // For the first element, set head and current
            head = newPDU;
            current = newPDU;
        } else {
            current->next = newPDU; // Link to the next node in the list
            current = newPDU; // Move to the next node
        }

        // Initialize RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        newPDU->RX_UE_INFORMATION_TAG = i;
        strcpy(newPDU->RNTI, RNTIs[i]);
        for (int j = 0; j < CRC_FLAG_SIZE; j++) {
            newPDU->CRC_INDICATION_REL8_TAG[j] = rand() % 256; // Generate random CRC flags
        }
    }

    return head;
