typedef struct {
    unsigned long ue_ci;
    int seq_num;
    char* error_status_report;
    time_t timestamp;
    int metadata_type;
    uint32_t checksum;
} Notification;

Notification* create_notification(unsigned long ue_ci, int seq_num, const char* error_status_report, time_t timestamp, int metadata_type) {
    Notification* notification = (Notification*)malloc(sizeof(Notification));
    if (!notification) return NULL;

    notification->ue_ci = ue_ci;
    notification->seq_num = seq_num;
    notification->error_status_report = strdup(error_status_report);
    notification->timestamp = timestamp;
    notification->metadata_type = metadata_type;
    // Calculate checksum
    uint32_t checksum = 0;
    // ...
    notification->checksum = checksum;

    return notification;
}

void free_notification(Notification* notification) {
    if (notification) {
        free(notification->error_status_report);
        free(notification);
    }
}

Notification* process_notifications(int num_notifications, Notification** notifications) {
    for (int i = 0; i < num_notifications; i++) {
        // Validate checksum
        uint32_t calculated_checksum;
        // ...
        if (notifications[i]->checksum != calculated_checksum) {
            printf("Invalid notification %d\n", i);
            free_notification(notifications[i]);
            notifications[i] = NULL;
        }
    }

    return notifications;
}

int main() {
    int num_notifications = 10;
    Notification** notifications = (Notification**)malloc(num_notifications * sizeof(Notification*));

    for (int i = 0; i < num_notifications; i++) {
        notifications[i] = create_notification(i, i + 1, "Error status report", time(NULL), i % 2);
        if (!notifications[i]) break;
    }

    // Process notifications
    process_notifications(num_notifications, notifications);

    for (int i = 0; i < num_notifications; i++) {
        free_notification(notifications[i]);
    }
    free(notifications);

    return 0;
}
