NFAPI_CRC_INDICATION_PDU_T* nfaPiCrcIndicationPduTArray = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int arraySize = 0;
int totalProcessed = 0;
int discarded = 0;
int failedToIntegrate = 0;

void initializeNfaPiCrcIndicationPduTArray(int capacity) {
    if (arraySize == 0) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* newArray = malloc(CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arraySize = CAPACITY;
        nfaPiCrcIndicationPduTArray = newArray;
        pthread_mutex_unlock(&mutex);
    }
}

int addNfaPiCrcIndicationPduTToArray(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (arraySize == 0) {
        initializeNfaPiCrcIndicationPduTArray(1);
    }

    pthread_mutex_lock(&mutex);
    int i = arraySize - 1;
    while (i > 0 && nfaPiCrcIndicationPduTArray[i].crcFlag != pdu->crcFlag) {
        memmove(&nfaPiCrcIndicationPduTArray[i], &nfaPiCrcIndicationPduTArray[--i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    if (i == arraySize - 1) {
        nfaPiCrcIndicationPduTArray[i] = *pdu;
        arraySize--;
    } else {
        pthread_mutex_unlock(&mutex);
        return -1; // failed to integrate
    }

    pthread_mutex_unlock(&mutex);

    totalProcessed++;
    if (arraySize > CAPACITY/2) {
        pthread_mutex_lock(&mutex);
        int j = 0;
        while (j < arraySize && nfaPiCrcIndicationPduTArray[j].crcFlag != NULL_CRCFLAG) {
            memmove(&nfaPiCrcIndicationPduTArray[--j], &nfaPiCrcIndicationPduTArray[1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        arraySize = j + 1;
        pthread_mutex_unlock(&mutex);
    }

    return 0; // successful integration
}

void logMetrics() {
    printf("Total processed: %d\n", totalProcessed);
    printf("Discarded: %d\n", discarded);
    printf("Failed to integrate: %d\n", failedToIntegrate);
}
