void init_list(int max_capacity) {
    capacity = max_capacity;
}

int add_to_list(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&lock);

    if (list_size >= capacity) {
        printf("List overflow! Cannot add more elements.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    int i;
    for (i = 0; i < list_size; i++) {
        if (list[i]->rnti == element->rnti) {
            printf("Duplicate RNTI detected! Cannot add.\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    int j;
    for (j = 0; j < list_size; j++) {
        if (list[j]->add_count >= RNTI_THRESHOLD) {
            printf("RNTI %d has been added more than the threshold. Cannot add.\n", element->rnti);
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    list[list_size] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(list[list_size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list[list_size]->add_count++;
    list_size++;
    pthread_mutex_unlock(&lock);
    return 0;
}

int remove_from_list(RNTI rnti) {
    pthread_mutex_lock(&lock);

    int i;
    for (i = 0; i < list_size; i++) {
        if (list[i]->rnti == rnti) {
            free(list[i]);
            int j;
            for (j = i + 1; j < list_size; j++) {
                memcpy(list[i], list[j], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                i++;
            }
            list_size--;
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    printf("Invalid RNTI. Cannot remove.\n");
    pthread_mutex_unlock(&lock);
    return -1;
}

