// Define the maximum number of notifications that can be stored
#define MAX_NOTIFICATIONS 1000

// Define a structure to represent a network event notification
typedef struct {
    char ue_ci[20]; // User Equipment Context Identifier (UE-CI)
    int sequence_number;
    int error_status; // Detailed error status report
    time_t timestamp;
} Notification;

// Define a callback function type for the logging service
typedef void (*LoggingCallback)(Notification*, int);

// Structure to manage a dynamic list of network event notifications
typedef struct {
    Notification* notifications[MAX_NOTIFICATIONS];
    int size;
    pthread_mutex_t mutex;
    LoggingCallback logging_callback;
    time_t last_notification_time;
} NotificationManager;

// Function to initialize the notification manager
void init_notification_manager(NotificationManager* nm, LoggingCallback callback) {
    nm->size = 0;
    nm->logging_callback = callback;
    pthread_mutex_init(&nm->mutex, NULL);
}

// Function to add a new notification to the list
void add_notification(NotificationManager* nm, Notification* notification) {
    pthread_mutex_lock(&nm->mutex);

    // Check if the list is full and needs to be resized
    if (nm->size >= MAX_NOTIFICATIONS) {
        // Discard the least recently used notifications to make space
        for (int i = 0; i < nm->size - 1; i++) {
            free(nm->notifications[i]);
        }
        nm->size--;
    }

    // Add the new notification and update the last notification time
    nm->notifications[nm->size] = notification;
    nm->last_notification_time = notification->timestamp;
    nm->size++;

    pthread_mutex_unlock(&nm->mutex);
}

// Function to process all notifications in the list, including logging and error handling
void process_notifications(NotificationManager* nm) {
    pthread_mutex_lock(&nm->mutex);

    for (int i = 0; i < nm->size; i++) {
        Notification* notification = nm->notifications[i];

        // Check for invalid UE-CI format or missing sequence number
        if (!notification->ue_ci[0] || !notification->sequence_number) {
            printf("Error: Invalid UE-CI format or missing sequence number\n");
            continue;
        }

        // Validate the checksum of the notification (assuming it has a checksum field)
        if (!validate_checksum(notification)) {
            printf("Error: Failed checksum validation\n");
            continue;
        }

        // Call the logging callback function to log the notification
        nm->logging_callback(notification, i);

        // Release the mutex before processing the next notification
        pthread_mutex_unlock(&nm->mutex);

        // Simulate some processing time for each notification (average 50ms)
        usleep(50000);
    }

    pthread_mutex_unlock(&nm->mutex);
}

// Function to calculate metrics for monitoring performance and resource usage
void monitor_performance(NotificationManager* nm) {
    printf("Average processing time per notification: %.2f ms\n", average_processing_time(nm));
    printf("Memory usage: %d bytes\n", get_memory_usage());
    printf("Discarded notifications due to resource limits: %d\n", discarded_notifications);
}
