#define MAX_RESOURCES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    char RNTI[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *resources[MAX_RESOURCES];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int get_resource_index(char *RNTI) {
    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (!strcmp(resources[i]->RNTI, RNTI)) {
            return i;
        }
    }
    return -1;
}

void put_resource(int index, char *new_RNTI, int new_CRCFLAG) {
    pthread_mutex_lock(&lock);
    if (index < 0 || index >= MAX_RESOURCES) {
        printf("Invalid resource index.\n");
    } else {
        strcpy(resources[index]->RNTI, new_RNTI);
        resources[index]->CRCFLAG = new_CRCFLAG;
    }
    pthread_mutex_unlock(&lock);
}

void delete_resource(int index) {
    pthread_mutex_lock(&lock);
    if (index < 0 || index >= MAX_RESOURCES) {
        printf("Invalid resource index.\n");
    } else {
        for (int i = index; i < MAX_RESOURCES - 1; i++) {
            resources[i] = resources[i + 1];
        }
        resources[MAX_RESOURCES - 1] = NULL;
    }
    pthread_mutex_unlock(&lock);
}

void* handle_put_request(void *arg) {
    int index = *((int*) arg);
    char new_RNTI[10];
    int new_CRCFLAG;
    // Handle PUT request logic here
    put_resource(index, new_RNTI, new_CRCFLAG);
    free(arg);
    return NULL;
}

void* handle_delete_request(void *arg) {
    int index = *((int*) arg);
    // Handle DELETE request logic here
    delete_resource(index);
    free(arg);
    return NULL;
}

void start_server() {
    pthread_t threads[MAX_RESOURCES];
    for (int i = 0; i < MAX_RESOURCES; i++) {
        resources[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!resources[i]) {
            printf("Memory allocation failed.\n");
            return;
        }
        sprintf(resources[i]->RNTI, "RNTI_%d", i);
        resources[i]->CRCFLAG = rand() % 100; // Initialize with random CRCFLAG
    }

    for (int i = 0; i < MAX_RESOURCES; i++) {
        pthread_create(&threads[i], NULL, &handle_put_request, malloc(sizeof(int)));
        pthread_create(&threads[i + 1], NULL, &handle_delete_request, malloc(sizeof(int)));
    }
}

int main() {
    start_server();
    return 0;
}
