void processNFAPackets(std::queue<NFAPI_CRC_INDICATION_PDU_T>& packetQueue, int M) {
    std::random_device rd;  // obtain a random number from hardware
    std::mt19937 eng(rd()); // seed the generator

    while (true) {
        if (packetQueue.size() >= M) {
            NFAPI_CRC_INDICATION_PDU_T packet = packetQueue.front();
            packetQueue.pop();

            bool duplicateRNTI = false;
            for (auto it = packetQueue.begin(); it != packetQueue.end();) {
                auto packet2 = *it;
                if (packet.RNTI == packet2.RNTI) {
                    it = packetQueue.erase(it);
                    duplicateRNTI = true;
                } else {
                    ++it;
                }
            }

            if (!duplicateRNTI) {
                while (cooldownPeriod > 0) {
                    cv.wait_for(mtx, std::chrono::seconds(1));
                    cooldownPeriod--;
                }
                attackCooldown = false;

                int attackNum = eng() % 2 + 1; // select random attack
                std::cout << "Attack " << attackNum << " selected." << std::endl;
            }
        }

        if (packetQueue.size() < M) {
            NFAPI_CRC_INDICATION_PDU_T packet;
            packet.RX_UE_INFORMATION_TAG = ...; // initialize with valid data
            packet.RNTI = eng() % 1000 + 1; // generate random RNTI
            packet.CRCFLAG = static_cast<CRCFLAG>(eng() % 2); // set CRC flag randomly

            while (true) {
                bool duplicateRNTI = false;
                for (auto it = packetQueue.begin(); it != packetQueue.end();) {
                    auto packet2 = *it;
                    if (packet.RNTI == packet2.RNTI) {
                        it = packetQueue.erase(it);
                        duplicateRNTI = true;
                        break;
                    } else {
                        ++it;
                    }
                }

                if (!duplicateRNTI) {
                    packetQueue.push(packet);
                    break;
                }
            }
        }
    }
}

