#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define THRESHOLD 10
#define MAX_CAPACITY 100

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[32];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* array_to_linked_list(Node* arr, int size) {
    Node* head = NULL;
    for (int i = 0; i < size; i++) {
        Node* node = &arr[i];
        if (!head) {
            head = node;
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = node;
        }
    }
    return head;
}

Node* linked_list_to_array(Node* head, int* size) {
    Node* arr = (Node*)malloc(MAX_CAPACITY * sizeof(Node));
    int i = 0;
    for (Node* current = head; current; current = current->next, i++) {
        arr[i] = current->data;
    }
    *size = i + 1;
    return arr;
}

void realloc_array(Node** array, int* size) {
    if (*size < THRESHOLD) {
        Node* new_arr = (Node*)malloc(MAX_CAPACITY * sizeof(Node));
        memcpy(new_arr, *array, *size * sizeof(Node));
        free(*array);
        *array = new_arr;
        *size *= 2;
    }
}

void compaction(Node** array, int* size) {
    if (*size > THRESHOLD && ((double)*size / (double)MAX_CAPACITY) < 0.75) {
        Node* new_arr = (Node*)malloc(*size * sizeof(Node));
        memcpy(new_arr, *array, *size * sizeof(Node));
        free(*array);
        *array = new_arr;
    }
}

void add_element(Node** array, int* size, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    if (*size == 0) {
        *array = &new_node;
    } else {
        Node* current = *array;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    realloc_array(array, size);
}

void remove_element(Node** array, int* size, int index) {
    if (index < 0 || index >= *size) {
        printf("Out-of-bounds access.\n");
        return;
    }
    Node* current = *array;
    for (int i = 0; i < index - 1; i++) {
        current = current->next;
    }
    if (index == 0) {
        Node* temp = current->next;
        free(current);
        *array = temp;
    } else {
        free(current->next);
        current->next = NULL;
    }
    *size -= 1;
}

NFAPI_CRC_INDICATION_PDU_T get_element(Node* array, int index) {
    if (index < 0 || index >= MAX_CAPACITY) {
        printf("Out-of-bounds access.\n");
        return (NFAPI_CRC_INDICATION_PDU_T){};
    }
    Node* current = array;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    return current->data;
}

