typedef struct {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[50];
    unsigned char CRCFLAG : 1;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

void insert(Node** head, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (*head == NULL || new_data.RNTI > (*head)->data.RNTI) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next && temp->next->data.RNTI >= new_data.RNTI)
            temp = temp->next;
        new_node->next = temp->next;
        temp->next = new_node;
    }
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next_temp = current->next;
        free(current);
        current = next_temp;
    }
}

int serialize_to_file(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file)
        return -1;

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    return 0;
}

int deserialize_from_file(Node** head, const char* filename) {
