#define MAX_STRUCTURES 1000
#define CRC_FLAG_SIZE sizeof(uint8_t)
#define STRUCTURE_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    int size;
    int capacity;
} NfaPiCrcIndicationPduArray;

NfaPiCrcIndicationPduArray nfaPiCrcIndicationPduArray;

void init_nfa_pi_crc_indication_pdu_array(int initial_capacity) {
    if (initial_capacity < 1) {
        return;
    }

    nfaPiCrcIndicationPduArray.size = 0;
    nfaPiCrcIndicationPduArray.capacity = initial_capacity;

    nfaPiCrcIndicationPduArray.structures = malloc(STRUCTURE_SIZE * initial_capacity);
}

void grow_nfa_pi_crc_indication_pdu_array(int new_size) {
    if (new_size <= 0 || nfaPiCrcIndicationPduArray.size >= nfaPiCrcIndicationPduArray.capacity) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* old_structures = nfaPiCrcIndicationPduArray.structures;

    int new_capacity = (nfaPiCrcIndicationPduArray.size + new_size <= MAX_STRUCTURES ? nfaPiCrcIndicationPduArray.size + new_size : MAX_STRUCTURES) * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_structures = malloc(STRUCTURE_SIZE * new_capacity);

    memcpy(new_structures, old_structures, STRUCTURE_SIZE * (nfaPiCrcIndicationPduArray.size));

    free(old_structures);
    nfaPiCrcIndicationPduArray.structures = new_structures;
    nfaPiCrcIndicationPduArray.capacity = new_capacity;
}

int get_nfa_pi_crc_indication_pdu_array_size() {
    return nfaPiCrcIndicationPduArray.size;
}

void add_structure_to_nfa_pi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (nfaPiCrcIndicationPduArray.size >= nfaPiCrcIndicationPduArray.capacity) {
        grow_nfa_pi_crc_indication_pdu_array(1);
    }

    memcpy(&nfaPiCrcIndicationPduArray.structures[nfaPiCrcIndicationPduArray.size], structure, STRUCTURE_SIZE);

    // Randomly generate CRC flag
    uint8_t crc_flag = rand() % 256;
    ((NFAPI_CRC_INDICATION_PDU_T*)structure)->CRC_INDICATION_REL8_TAG.crc_flag = crc_flag;

    nfaPiCrcIndicationPduArray.size++;
}

void serialize_nfa_pi_crc_indication_pdu_array_to_disk(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return;
    }

    fwrite(&nfaPiCrcIndicationPduArray.size, sizeof(int), 1, file);
    for (int i = 0; i < nfaPiCrcIndicationPduArray.size; i++) {
        fwrite(&nfaPiCrcIndicationPduArray.structures[i], STRUCTURE_SIZE, 1, file);
    }

    fclose(file);
}

void deserialize_nfa_pi_crc_indication_pdu_array_from_disk(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return;
    }

    int size;
    fread(&size, sizeof(int), 1, file);

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T structure;
        fread(&structure, STRUCTURE_SIZE, 1, file);
        add_structure_to_nfa_pi_crc_indication_pdu_array((NFAPI_CRC_INDICATION_PDU_T*)&structure);
    }

    fclose(file);
}

void compact_nfa_pi_crc_indication_pdu_array() {
    int new_size = 0;
    for (int i = 0; i < nfaPiCrcIndicationPduArray.size; i++) {
        if (((NFAPI_CRC_INDICATION_PDU_T*)nfaPiCrcIndicationPduArray.structures[i])->RX_UE_INFORMATION_TAG != 0) {
            new_size++;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* new_structures = malloc(STRUCTURE_SIZE * new_size);
    int j = 0;
    for (int i = 0; i < nfaPiCrcIndicationPduArray.size; i++) {
        if (((NFAPI_CRC_INDICATION_PDU_T*)nfaPiCrcIndicationPduArray.structures[i])->RX_UE_INFORMATION_TAG != 0) {
            memcpy(&new_structures[j], &nfaPiCrcIndicationPduArray.structures[i], STRUCTURE_SIZE);
            j++;
        }
    }

    free(nfaPiCrcIndicationPduArray.structures);
    nfaPiCrcIndicationPduArray.structures = new_structures;
    nfaPiCrcIndicationPduArray.size = new_size;
}

int main() {
    init_nfa_pi_crc_indication_pdu_array(MAX_STRUCTURES);

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        add_structure_to_nfa_pi_crc_indication_pdu_array((NFAPI_CRC_INDICATION_PDU_T*)malloc(STRUCTURE_SIZE));
    }

    serialize_nfa_pi_crc_indication_pdu_array_to_disk("nfa_pi_crc_indication_pdu_array.bin");

    // Example of deserialization
    deserialize_nfa_pi_crc_indication_pdu_array_from_disk("nfa_pi_crc_indication_pdu_array.bin");

    compact_nfa_pi_crc_indication_pdu_array();

    return 0;
}
