void* createNfalock(int n, int max_size, int timeout) {
    // Initialize the semaphore with the given initial value and timeout
    sem_t *sem = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, 1, timeout);
    if (sem == SEM_FAILED) {
        return NULL;
    }

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        sem_close(sem);
        return NULL;
    }

    // Initialize the CRC indication reference value
    int crc_ref = 0;

    for (int i = 0; i < n && i < max_size; i++) {
        // Create a new structure with valid RX_UE_INFORMATION_TAG and RNTI
        NFAPI_CRC_INDICATION_PDU_T* p = &list[i];
        p->RX_UE_INFORMATION_TAG = i;
        p->RNTI = i;

        // Randomly set CRC_INDICATION_REL8_TAG and CRCFLAG
        p->CRC_INDICATION_REL8_TAG = rand() % 1000;
        p->CRCFLAG = rand() % 2;

        // Validate the integrity of the CRC_INDICATION_REL8_TAG against the reference value
        if (p->CRC_INDICATION_REL8_TAG != crc_ref) {
            printf("Error: CRC indication validation failed.\n");
        }

        crc_ref++;
    }

    sem_close(sem);

    return list;
}

int main() {
    int n = 10; // Number of structures to create
    int max_size = 100; // Maximum size of the list
    int timeout = 5000; // Timeout for the semaphore

    void* result = createNfalock(n, max_size, timeout);

    if (result) {
        printf("List created successfully.\n");
    } else {
        printf("Error creating the list.\n");
    }

    return 0;
}
