    char IMSI[16];
    char RNTI[8];
    UE_Context* ue_context;
} UE_Status_Report;

// Thread-safe doubly linked list node
typedef struct Node {
    UE_Status_Report* data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
int num_allocs = 0;

// Function to initialize and populate the doubly linked list
void init_ue_status_report_list() {
    // Initialize random number generator
    srand(time(NULL));

    // Create a new node for each UE status report
    for (int i = 0; i < 10; ++i) {  // Replace with actual count
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Initialize UE context structure
        UE_Context* ue_context = malloc(sizeof(UE_Context));
        if (!ue_context) {
            free(new_node);
            printf("Memory allocation for UE context failed.\n");
            return;
        }
        ue_context->last_reported_rsrp = rand() % 200 - 100;  // Random RSRP value
        ue_context->last_reported_rssi = rand() % 128 - 64;   // Random RSSI value
        ue_context->last_reported_sinr = rand() % 20 + 5;      // Random SINR value

        new_node->data = malloc(sizeof(UE_Status_Report));
        strcpy(new_node->data->IMSI, " IMSI_" + itoa(i));  // Unique IMSI for each node
        strcpy(new_node->data->RNTI, " RNTI_" + itoa(i));    // Unique RNTI for each node

        new_node->next = NULL;
        if (head) {
            head->prev = &new_node->data;
            new_node->data->prev = head;
            head = &new_node->data;
        } else {
            head = &new_node->data;
        }

        num_allocs++;
        free(ue_context);  // Free UE context memory to manage fragmentation
    }
}
