#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_ELEMS 10000
#define NUM_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int numElems = 0;

void initList() {
    pthread_mutex_lock(&lock);
    head = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    numElems = 1;
    pthread_mutex_unlock(&lock);
}

void addElement() {
    NFAPI_CRC_INDICATION_PDU_T* newNode;
    pthread_mutex_lock(&lock);
    if (numElems >= MAX_ELEMS) {
        fprintf(stderr, "Error: List overflow\n");
        exit(EXIT_FAILURE);
    }
    newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    // Populate newNode with random values
    newNode->RX_UE_INFORMATION_TAG = rand();
    newNode->RNTI = rand();
    for (int i = 0; i < 4; i++) {
        newNode->CRC_INDICATION_REL8_TAG[i] = rand();
    }
    if (head) {
        newNode->next = head;
        head = newNode;
    } else {
        head = newNode;
    }
    numElems++;
    pthread_mutex_unlock(&lock);
}

void printList() {
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: {%d, %d, %d, %d}\n",
               temp->RX_UE_INFORMATION_TAG, temp->RNTI,
               temp->CRC_INDICATION_REL8_TAG[0], temp->CRC_INDICATION_REL8_TAG[1],
               temp->CRC_INDICATION_REL8_TAG[2], temp->CRC_INDICATION_REL8_TAG[3]);
        temp = temp->next;
    }
}

void* threadFunc(void* arg) {
    for (int i = 0; i < 100; i++) {
        addElement();
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    initList();

    // Create and start multiple threads
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, threadFunc, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printList();

    return 0;
}
