// Function to initialize a linked list of DataPacket structures
Node* initLinkedList(int numPackets) {
    Node* head = NULL;
    Node** nodes = (Node**)malloc((numPackets + 1) * sizeof(Node*));
    for (int i = 0; i <= numPackets; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            perror("Memory allocation error");
            free(nodes);
            return NULL;
        }
        node->data.payload = malloc(1); // Initialize payload to zero
        node->data.payload[0] = '\0'; 
        node->next = NULL;
        nodes[i] = node;
    }
    for (int i = 0; i < numPackets; i++) {
        if (i == 0) {
            head = nodes[i];
        } else {
            nodes[i]->data.timestamp = time(NULL); // Set timestamp
            nodes[i - 1]->next = nodes[i]; 
        }
    }
    free(nodes);
    return head;
}

// Function to free the linked list
void freeLinkedList(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        if (current->data.payload) free(current->data.payload);
        free(current);
        current = next;
    }
}

// Function to print the linked list
void printLinkedList(Node* head) {
    Node* current = head;
    while (current) {
        printf("Packet ID: %d, Payload: %s, Timestamp: %ld\n", 
               current->data.packet_id, (char*)current->data.payload, current->data.timestamp);
        current = current->next;
    }
}

// Function to get the size of the linked list
int getSize(Node* head) {
    int size = 0;
    Node* current = head;
    while (current) {
        size++;
        current = current->next;
    }
    return size;
}

int main() {
    Node* head = initLinkedList(5);
    printLinkedList(head);
    printf("Size: %d\n", getSize(head));
    freeLinkedList(head);
    return 0;
}
