    if (frames == NULL || frameCount >= MAX_FRAMES) {
        frames = realloc(frames, sizeof(LTE_DL_FRAME_STRUCT *) * (MAX_FRAMES + 1));
    }
    frames[frameCount++] = newFrame;
    pthread_mutex_unlock(&lock);

    return NULL;
}

