// Add a new entry to the dynamic list
void add_nfaPI_CRC_indication_pdu_list_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);
    if (nfaPI_CRC_indication_pdu_list.size == nfaPI_CRC_indication_pdu_list.capacity) {
        // If the list is full, double its size
        nfaPI_CRC_indication_pdu_list.capacity *= 2;
