    nfaPI_CRC_indication_pdu_list.entries[nfaPI_CRC_indication_pdu_list.size] = new_entry;
    nfaPI_CRC_indication_pdu_list.size++;
    pthread_mutex_unlock(&lock);
}

// Update an existing entry in the dynamic list based on RNTI
void update_nfaPI_CRC_indication_pdu_list_entry(int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < nfaPI_CRC_indication_pdu_list.size; i++) {
        if (nfaPI_CRC_indication_pdu_list.entries[i].RNTI == RNTI) {
            nfaPI_CRC_indication_pdu_list.entries[i].CRCFLAG = CRCFLAG;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Remove an entry from the dynamic list based on RNTI
void remove_nfaPI_CRC_indication_pdu_list_entry(int RNTI) {
    pthread_mutex_lock(&lock);
    size_t i;
    for (i = 0; i < nfaPI_CRC_indication_pdu_list.size; i++) {
        if (nfaPI_CRC_indication_pdu_list.entries[i].RNTI == RNTI) {
            break;
        }
    }
    if (i < nfaPI_CRC_indication_pdu_list.size) {
        // Shift the remaining entries down
        memmove(&nfaPI_CRC_indication_pdu_list.entries[i], &nfaPI_CRC_indication_pdu_list.entries[i + 1],
                (nfaPI_CRC_indication_pdu_list.size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfaPI_CRC_indication_pdu_list.size--;
    }
    pthread_mutex_unlock(&lock);
}

// Get the total number of active entries
