NFAPI_CRC_INDICATION_PDU_T** nfa_list = NULL;
int nfa_count = 0;
int last_cleanup_time = 0;
FILE* log_file = fopen("nfa_log.txt", "w");

void cleanup(void) {
    pthread_mutex_lock(&list_lock);
    int i = 0;
    for (i = 0; i < nfa_count; i++) {
        if ((time(NULL) - last_cleanup_time > CLEANUP_INTERVAL) || (i >= STRUCT_PER_PAGE)) {
            free(nfa_list[i]);
            nfa_list[i] = NULL;
            nfa_count--;
            last_cleanup_time = time(NULL);
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void* create_nfa(void* args) {
    NFAPI_CRC_INDICATION_PDU_T* new_nfa = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
