    int rssi = rand() % 256 - 128; // random value between -128 and 127 dBm
    new_nfa->CRCFLAG = (rssi > RSSI_THRESHOLD) ? 1 : 0;

    pthread_mutex_lock(&list_lock);
    nfa_list[nfa_count++] = &new_nfa;
    pthread_mutex_unlock(&list_lock);

    // Log creation event
    if (LOGGING_ENABLED) {
        fprintf(log_file, "NFA created: RSSI=%d, CRCFLAG=%d\n", rssi, new_nfa->CRCFLAG);
        fflush(log_file);
    }
    return new_nfa;
}

void delete_nfa(NFAPI_CRC_INDICATION_PDU_T* nfa) {
    pthread_mutex_lock(&list_lock);
    int i = 0;
    for (i = 0; i < nfa_count; i++) {
        if (&nfa_list[i]->RX_UE_INFORMATION_TAG == &nfa->RX_UE_INFORMATION_TAG) {
            free(nfa);
            nfa_list[i] = NULL;
            nfa_count--;
            break;
        }
    }
    pthread_mutex_unlock(&list_lock);

    // Log deletion event
    if (LOGGING_ENABLED) {
        fprintf(log_file, "NFA deleted: RSSI=%d, CRCFLAG=%d\n", nfa->RX_UE_INFORMATION_TAG, nfa->CRCFLAG);
        fflush(log_file);
    }
}

int main() {
    pthread_t thread;
    NFAPI_CRC_INDICATION_PDU_T* new_nfa = create_nfa(&thread);
    // ...
    return 0;
}
