#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for DataPacket
typedef struct {
    int packet_id;
    char* payload;
    time_t timestamp;
    void* metadata;
} DataPacket;

// Function to initialize and manage a doubly linked list of DataPackets
void init_packet_list(DataPacket** head, DataPacket** tail) {
    *head = NULL;
    *tail = NULL;
}

// Function to create a new packet with the given parameters
DataPacket* create_packet(int packet_id, char* payload, time_t timestamp, void* metadata) {
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!packet) return NULL;

    packet->packet_id = packet_id;
    packet->payload = (char*)malloc(strlen(payload) + 1);
    strcpy(packet->payload, payload);
    packet->timestamp = timestamp;
    packet->metadata = metadata;

    return packet;
}

// Function to insert a new packet at the end of the list
void insert_packet(DataPacket** head, DataPacket** tail, DataPacket* packet) {
    if (*head == NULL) {
        *head = packet;
        *tail = packet;
    } else {
        packet->next = NULL;
        (*tail)->next = packet;
        *tail = packet;
    }
}

// Function to remove a packet from the list
void remove_packet(DataPacket** head, DataPacket* packet) {
    if (packet == *head) {
        *head = packet->next;
    }

    if (packet == *tail) {
        *tail = packet->prev;
    }

    if (packet->prev) {
        packet->prev->next = packet->next;
    } else {
        *head = packet->next;
    }

    if (packet->next) {
        packet->next->prev = packet->prev;
    } else {
        *tail = packet->prev;
    }
}

// Function to serialize the linked list to a file
void serialize_packet_list(FILE* file, DataPacket* head) {
    DataPacket* current = head;
    while (current) {
        fwrite(&current->packet_id, sizeof(int), 1, file);
        fwrite(current->payload, strlen(current->payload) + 1, 1, file);
        fwrite(&current->timestamp, sizeof(time_t), 1, file);
        fwrite(&current->metadata, sizeof(void*), 1, file);
        current = current->next;
    }
}

// Function to deserialize the linked list from a file
DataPacket* deserialize_packet_list(FILE* file) {
    DataPacket* head = NULL;
    DataPacket* tail = NULL;

    int packet_id;
    char payload[256];
    time_t timestamp;
    void* metadata;

    while (fread(&packet_id, sizeof(int), 1, file)) {
        metadata = malloc(sizeof(void*));
        fread(metadata, sizeof(void*), 1, file);
        payload[0] = '\0';
        fseek(file, 0, SEEK_CUR);
        fgets(payload, 256, file);

        DataPacket* packet = create_packet(packet_id, payload, timestamp, metadata);
        if (head == NULL) {
            head = packet;
            tail = packet;
        } else {
            packet->next = NULL;
            tail->next = packet;
            tail = packet;
        }
    }

    return head;
}

// Function to integrate with an external logging library
void log_packet_operation(const char* operation, DataPacket* packet) {
    // Call the logging function here
}

// Function to periodically clean up unused or expired packets
void cleanup_packet_list(DataPacket** head, DataPacket* tail, time_t current_timestamp) {
    DataPacket* current = *head;
    while (current) {
        if (current->timestamp < current_timestamp - 3600) {
            remove_packet(head, current);
        } else {
            current = current->next;
        }
    }
}

// Function to handle concurrent access safely
void init_lock(pthread_mutex_t* lock) {
    pthread_mutex_init(lock, NULL);
}

void acquire_lock(pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);
}

void release_lock(pthread_mutex_t* lock) {
    pthread_mutex_unlock(lock);
}
