void addNfaPiEntry(int rnti, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&nfaPiMutex);

    if (nfaPiArray == NULL || nfaPiArraySize >= MAX_ENTRIES) {
        NFAPI_ARRAY_ENTRY* newArray = (NFAPI_ARRAY_ENTRY*)realloc(nfaPiArray, sizeof(NFAPI_ARRAY_ENTRY) * (nfaPiArraySize + 1));

