TrafficFlowStatistics** traffic_flow_array;
int traffic_flow_size = 0;

// Function to add new entries
TrafficFlowStatistics* add_statistics(TrafficFlowStatistics** array, int* size) {
    // Create a new TrafficFlowStatistics structure and increment the size
    *array = realloc(*array, (*size + 1) * sizeof(TrafficFlowStatistics));
    return &((*array)[*size++]);
