#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 10000
#define LOCK_MUTEX "list_lock"
#define CRC_INDICATION_REL8_TAG_MAX 10

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int validRX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int count;
};

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

int list_init(struct List* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    return 0;
}

int list_insert(struct List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = create_node(data);
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_remove(struct List* list, int RNTI) {
    Node* current = list->head;
    Node* previous = NULL;
    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (list->tail == current) {
                list->tail = previous;
            }
            free(current);
            list->count--;
        } else {
            previous = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_get_count(struct List* list) {
    pthread_mutex_lock(&list->lock);
    int count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

int list_get_active_crc_count(struct List* list) {
    int active_crc_count = 0;
    Node* current = list->head;
    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG) {
            active_crc_count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return active_crc_count;
}

void list_deinit(struct List* list) {
    Node* current = list->head;
    Node* next = NULL;
    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
