#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store traffic flow statistics
typedef struct {
    int flow_id;
    double traffic_volume;
    time_t last_update_time;
} TrafficFlowStatistics;

// Define the dynamic array of traffic flow statistics
typedef struct {
    TrafficFlowStatistics* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} TrafficFlowStatisticsArray;

// Function to initialize the dynamic array
TrafficFlowStatisticsArray* traffic_flow_statistics_array_init(size_t initial_capacity) {
    TrafficFlowStatisticsArray* array = (TrafficFlowStatisticsArray*)malloc(sizeof(TrafficFlowStatisticsArray));
    array->data = (TrafficFlowStatistics*)malloc(initial_capacity * sizeof(TrafficFlowStatistics));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to add a new traffic flow statistics entry
void traffic_flow_statistics_array_add(TrafficFlowStatisticsArray* array, int flow_id, double traffic_volume) {
    pthread_mutex_lock(&array->mutex);

    // Reallocate memory if the array is full
    if (array->size == array->capacity) {
        array->data = (TrafficFlowStatistics*)realloc(array->data, 2 * array->capacity * sizeof(TrafficFlowStatistics));
        array->capacity *= 2;
    }

    // Add the new entry to the end of the array
    TrafficFlowStatistics* new_entry = &array->data[array->size++];
    new_entry->flow_id = flow_id;
    new_entry->traffic_volume = traffic_volume;
    new_entry->last_update_time = time(NULL);

    pthread_mutex_unlock(&array->mutex);
}

// Function to update a specific traffic flow statistics entry
void traffic_flow_statistics_array_update(TrafficFlowStatisticsArray* array, int flow_id, double traffic_volume) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; i++) {
        if (array->data[i].flow_id == flow_id) {
            array->data[i].traffic_volume = traffic_volume;
            array->data[i].last_update_time = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Function to remove a specific traffic flow statistics entry
void traffic_flow_statistics_array_remove(TrafficFlowStatisticsArray* array, int flow_id) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; i++) {
        if (array->data[i].flow_id == flow_id) {
            // Shift elements down to fill the gap
            memmove(&array->data[i], &array->data[i+1], (array->size - i - 1) * sizeof(TrafficFlowStatistics));
            array->size--;
            break;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Function to list all active flows within a specified time window
void traffic_flow_statistics_array_list_active_flows(TrafficFlowStatisticsArray* array, int start_time, int end_time) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; i++) {
        if (array->data[i].last_update_time >= start_time && array->data[i].last_update_time <= end_time) {
            printf("Flow ID: %d, Traffic Volume: %.2f\n", array->data[i].flow_id, array->data[i].traffic_volume);
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Function to free the dynamic array
void traffic_flow_statistics_array_free(TrafficFlowStatisticsArray* array) {
    pthread_mutex_lock(&array->mutex);

    free(array->data);
    free(array);
    pthread_mutex_unlock(&array->mutex);
}
