int main() {
    // Example usage:
    int num_crc_indications = 100000;
    int batch_size = 1000;

    NFAPI_CRC_INDICATION_PDU_T** crc_indications = generate_crc_indications(num_crc_indications, batch_size);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T** generate_crc_indications(int num_crc_indications, int batch_size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T** crc_indications = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < num_crc_indications; i++) {
        pthread_mutex_lock(&mutex);

        NFAPI_CRC_INDICATION_PDU_T* current_crc_indication;

        if (i % batch_size == 0) {
            current_crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            current_crc_indication = crc_indications[i - i % batch_size];
        }

        for (int j = 0; j < batch_size; j++) {
            if (j >= num_crc_indications - i) break;

            current_crc_indication[j].rx_ue_info_tag = /* Generate valid RX_UE_INFORMATION_TAG */;
            current_crc_indication[j].rnti = rand() % 65536;
            current_crc_indication[j].crc_indication_rel8_tag = /* Generate valid CRC_INDICATION_REL8_TAG */;
            current_crc_indication[j].crcflag = (rand() % 2) == 1; // Randomly set CRCFLAG

            if (j >= num_crc_indications - i) {
                crc_indications[i + j % batch_size] = current_crc_indication;
            }
        }

        pthread_mutex_unlock(&mutex);
    }

    return crc_indications;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T** crc_indications, int num_crc_indications) {
    for (int i = 0; i < num_crc_indications; i++) {
        if (crc_indications[i] != NULL) {
            free(crc_indications[i]);
        }
    }

    free(crc_indications);
}
