#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int* nfapi_list = NULL;
int nfapi_list_size = 0;
int nfapi_list_capacity = 10; // initial capacity

void nfapi_init(int initial_capacity) {
    if (initial_capacity <= 0) return;

    nfapi_list = (int*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapi_list) {
        perror("Memory allocation failed");
        exit(1);
    }

    nfapi_list_size = 0;
    nfapi_list_capacity = initial_capacity;
}

void nfapi_add(NFAPI_CRC_INDICATION_PDU_T* new_element) {
    if (nfapi_list_size == nfapi_list_capacity) {
        // double capacity when full
        int new_capacity = nfapi_list_capacity * 2;
        void* temp = realloc(nfapi_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            perror("Memory allocation failed");
            exit(1);
        }

        nfapi_list = temp;
        nfapi_list_capacity = new_capacity;
    }

    // add element at end
    int idx = nfapi_list_size++;
    memmove(&nfapi_list[idx + 1], &nfapi_list[idx], (nfapi_list_size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(&nfapi_list[idx], new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void nfapi_remove(int idx) {
    if (idx >= nfapi_list_size || idx < 0) return;

    memmove(&nfapi_list[idx], &nfapi_list[idx + 1], (nfapi_list_size - idx - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // update size
    nfapi_list_size--;
}

void nfapi_reverse_iterate(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = nfapi_list_size - 1; i >= 0; i--) {
        callback(&nfapi_list[i]);
    }
}

// Example usage
int main() {
    nfapi_init(10); // initialize with initial capacity of 10

    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->RNTI = 1;
    new_element->CRCFLAG = 0x01;

    nfapi_add(new_element);

    // iterate in reverse order
    nfapi_reverse_iterate((void (*)(NFAPI_CRC_INDICATION_PDU_T*))print_element);

    return 0;
}
