void* allocate_array(size_t n) {
    pthread_mutex_lock(&lock);
    if (shared_data.size > 0) {
        pthread_mutex_unlock(&lock);
        return &shared_data;
    }

    void* ptr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ptr) {
        free(ptr);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    shared_data.array = ptr;
    shared_data.size = n;
    allocated++;
    pthread_mutex_unlock(&lock);
    return &shared_data;
}

void deallocate_array() {
    pthread_mutex_lock(&lock);
    if (shared_data.size == 0) {
        pthread_mutex_unlock(&lock);
        return;
    }

    free(shared_data.array);
    shared_data.array = NULL;
    shared_data.size = 0;
    allocated--;
    pthread_mutex_unlock(&lock);
