#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum allowed number of structures
#define MAX_STRUCTURES 1000

// Define the maximum allowed memory size in bytes
#define MAX_MEMORY_SIZE (MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T))

// Define the structure to hold the dynamically allocated array and its metadata
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
    int pdu_count;
    sem_t lock; // Read-write lock for concurrent access
} PDUArrayMetadata;

// Function to manage a dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
PDUArrayMetadata* pdu_array_init(int max_elements) {
    PDUArrayMetadata* metadata = (PDUArrayMetadata*)malloc(sizeof(PDUArrayMetadata));
    if (!metadata) return NULL; // Handle memory allocation failure

    metadata->pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!metadata->pdu_array) {
        free(metadata);
        return NULL; // Handle memory allocation failure
    }

    metadata->pdu_count = 0;
    sem_init(&metadata->lock, 0, 1); // Initialize read-write lock

    return metadata;
}

// Function to allocate a new structure and add it to the dynamically allocated array
void pdu_array_add(PDUArrayMetadata* metadata) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return; // Handle memory allocation failure

    pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Randomly set RX_UE_INFORMATION_TAG
    pdu->RNTI = rand() % 256; // Randomly set RNTI
    pdu->CRC_INDICATION_REL8_TAG = rand() % 255; // Randomly set CRC_INDICATION_REL8_TAG
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    sem_wait(&metadata->lock); // Acquire read-write lock for concurrent access
    metadata->pdu_array[metadata->pdu_count++] = *pdu;
    sem_post(&metadata->lock); // Release read-write lock
}

// Function to free the dynamically allocated array and its metadata
void pdu_array_free(PDUArrayMetadata* metadata) {
    sem_wait(&metadata->lock); // Acquire read-write lock for concurrent access

    for (int i = 0; i < metadata->pdu_count; i++) {
        free(metadata->pdu_array[i]);
    }

    free(metadata->pdu_array);
    free(metadata);

    sem_post(&metadata->lock); // Release read-write lock
}

// Function to periodically reclaim unused memory using a simple garbage collection strategy
void pdu_array_garbage_collect(PDUArrayMetadata* metadata) {
    for (int i = 0; i < metadata->pdu_count; i++) {
        if (!metadata->pdu_array[i]->RX_UE_INFORMATION_TAG) { // Check for corruption or invalid data
            free(metadata->pdu_array[i]);
            metadata->pdu_count--;
            i--; // Adjust index to skip the freed element
        }
    }

    // Reclaim unused memory periodically based on a predetermined threshold
    if (metadata->pdu_count > MAX_STRUCTURES / 2) {
        PDUArrayMetadata* new_metadata = pdu_array_init(MAX_STRUCTURES);
        for (int i = 0; i < metadata->pdu_count; i++) {
            if (new_metadata->pdu_array[i]) { // Check for valid data
                memcpy(&new_metadata->pdu_array[i], &metadata->pdu_array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }

        pdu_array_free(metadata);
        metadata = new_metadata;
    }
}

// Example usage:
int main() {
    PDUArrayMetadata* metadata = pdu_array_init(MAX_STRUCTURES);

    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, pdu_array_add, metadata);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    pdu_array_garbage_collect(metadata);

    pdu_array_free(metadata);

    return 0;
}
