int ProcessImageAndCRCIndication(const char* file_path, image_metadata_t* metadata, NFAPI_CRC_INDICATION_PDU_T** crc_list) {
    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        return -1; // File not found
    }

    TIFF* tiff = TIFFOpen(file_path, "r");
    if (tiff == NULL) {
        fclose(file);
        return -2; // Invalid file format
    }

    int bit_depth = 0;
    int sample_per_pixel = 0;
    int extra_samples = 0;

    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bit_depth) == 0) {
        fclose(file);
        return -3; // Unsupported bit depth
    }

    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &sample_per_pixel) == 0) {
        fclose(file);
        return -4; // Unknown error
    }

    if (TIFFGetField(tiff, TIFFTAG_EXTRA SAMPLES, &extra_samples) == 0) {
        fclose(file);
        return -5; // Unable to get extra samples
    }

    *metadata = (image_metadata_t){bit_depth, sample_per_pixel, extra_samples};

    NFAPI_CRC_INDICATION_PDU_T* crc_list_ptr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 100);
    for (int i = 0; i < 100; i++) {
        crc_list_ptr[i].rx_ue_information_tag = i;
        crc_list_ptr[i].rnti = i;
        crc_list_ptr[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }
    *crc_list = crc_list_ptr;

    fclose(file);
    TIFFClose(tiff);

    return 0;
}
