        sprintf(list[i].CRC_INDICATION_REL8_TAG, "%x", rand());
        list[i].CRCFLAG = rand() % 0x10000;

        // Validate CRC
        char* ref_val = get_CRC_Reference();
        if (validate_CRC(ref_val, &list[i])) {
            printf("Error: CRC validation failed for index %d\n", i);
            free(list);
            return NULL;
        }
    }

    return list;
}

char* get_CRC_Reference() {
    // Fetch CRC reference value from external data source
    return "REF_VAL";
}

int validate_CRC(char* ref_val, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validate CRC against reference value
    if (strcmp(pdu->CRC_INDICATION_REL8_TAG, ref_val)) {
        return 1;
    }
    return 0;
