void* allocateDynamicArray(size_t size) {
    return malloc(size);
}

void deallocateDynamicArray(void* ptr, size_t size) {
    free(ptr);
}

int findIndexInArray(LTE_EUTRAN_CELL_MEASUREMENT_TAG** array, int UE_INDEX) {
    for (int i = 0; *array[i].UE_INDEX != UE_INDEX && *array[i]; i++);
    return (*array)[i] ? i : -1;
}

void addMeasurementToDynamicArray(LTE_EUTRAN_CELL_MEASUREMENT_TAG** array, LTE_EUTRAN_CELL_MEASUREMENT_TAG* measurement) {
    int index = findIndexInArray(array, measurement->UE_INDEX);
    if (index == -1) {
        // Add new measurement to the end of the array
        (*array)[index] = measurement;
        *array = realloc(*array, (++size_t)(sizeof(LTE_EUTRAN_CELL_MEASUREMENT_TAG*) * size));
    } else {
        // Update existing measurement
        free((*array)[index]);
        (*array)[index] = measurement;
    }
}

void updateMeasurementsFromExternalSource(LTE_EUTRAN_CELL_MEASUREMENT_TAG** array, LTE_EUTRAN_CELL_MEASUREMENT_TAG* newMeasurements) {
    for (int i = 0; *newMeasurements[i]; i++) {
        addMeasurementToDynamicArray(array, &((*newMeasurements)[i]));
    }
}

