// Define the structure for a network event
typedef struct {
    time_t timestamp;
    char source_ip[16];
    int destination_port;
} Event;

// Function to add an event to the list
void add_event(Event** events, int* num_events) {
    // Dynamically allocate memory for new event
    *num_events += 1;
    events = (Event**) realloc(*events, (*num_events)*sizeof(Event*));

    // Prompt user for input
    printf("Enter timestamp: ");
    scanf("%lu", &((*events)[*num_events-1]->timestamp));
    printf("Enter source IP address: ");
    scanf("%15s", (*events)[*num_events-1]->source_ip);
    printf("Enter destination port number: ");
    scanf("%d", &((*events)[*num_events-1]->destination_port));
}

// Function to retrieve events by source IP
void get_events_by_source_ip(Event** events, int num_events, char target_ip[]) {
    for (int i = 0; i < num_events; i++) {
        if (strcmp((*events)[i]->source_ip, target_ip) == 0) {
            printf("Timestamp: %lu\nSource IP: %s\nDestination Port: %d\n", (*events)[i]->timestamp, (*events)[i]->source_ip, (*events)[i]->destination_port);
        }
    }
}

