    fprintf(file, "Timestamp,Source IP,Destination Port\n");

    for (int i = 0; i < num_events; i++) {
        fprintf(file, "%lu,%s,%d\n", (*events)[i]->timestamp, (*events)[i]->source_ip, (*events)[i]->destination_port);
    }

    fclose(file);
}

