        char action[5];
        scanf("%4s", action);

        if (strcmp(action, "add") == 0) {
            add_event(&events, &num_events);
        } else if (strcmp(action, "exit") == 0) {
            break;
        }
    }

    // Retrieve events by source IP
    printf("Enter the source IP to retrieve: ");
    char target_ip[16];
    scanf("%15s", target_ip);
    get_events_by_source_ip(&events, num_events, target_ip);

    // Export events to CSV file
