// Function to create and populate a linked list of NFAPI_CRC_INDATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n, int seed) {
    if (n <= 0) return NULL; // Validate input

    srand(seed); // Initialize pseudo-random number generator

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) return NULL; // Handle memory allocation failure

        new_node->RX_UE_INFORMATION_TAG = rand() % 1000;
        int rnti = rand() % (n - i);
        while (*tail && rnti == ((NFAPI_CRC_INDICATION_PDU_T*)*tail)->RNTI) {
            rnti = rand() % (n - i);
        }
        new_node->RNTI = rnti;
        for (int j = 0; j < 3; j++) {
            new_node->CRC_INDICATION_REL8_TAG[j] = 'X' + rand() % 10;
        }

        *tail = &new_node;

        if (!head) head = new_node;
    }

    return head;
}

// Function to transmit linked list of NFAPI_CRC_INDICATION_PDU_T structures
int transmit_linked_list(NFAPI_CRC_INDICATION_PDU_T* head, int threshold, int (*callback)(NFAPI_CRC_INDICATION_PDU_T*, int)) {
    if (!head) return -1; // Handle empty list

    int total_bytes = 0;
    NFAPI_CRC_INDICATION_PDU_T* current_node = head;

    while (current_node) {
        total_bytes += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current_node = ((NFAPI_CRC_INDICATION_PDU_T*)current_node)->next;
    }

    if (total_bytes > threshold) { // Check memory usage
        int bytes_to_free = total_bytes - threshold;
        NFAPI_CRC_INDICATION_PDU_T* previous_node = head;
        while (bytes_to_free > 0 && previous_node) {
            bytes_to_free -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            NFAPI_CRC_INDICATION_PDU_T* next_node = ((NFAPI_CRC_INDICATION_PDU_T*)previous_node)->next;
            free(previous_node);
            previous_node = next_node;
        }
    }

    if (head) {
        // Perform transmission
        int retries = 0;
        while (retries < 3 && callback(head, total_bytes)) {
            retries++;
        }
        if (!callback(head, total_bytes)) {
            printf("Transmission failed!\n");
        } else {
            printf("Transmission successful!\n");
        }
    }

    return 0;
}

// Function to handle transmission failure
int transmit_failure(NFAPI_CRC_INDICATION_PDU_T* head, int bytes_transmitted) {
    // Implement callback logic here
    printf("Transmission failed with %d bytes.\n", bytes_transmitted);
    return -1;
}
