#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define LOGGING_LEVEL_DEFAULT 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[9];
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* NFAPI_CRC_INDICATION_PDU_array[MAX_STRUCTURES];

int logging_level = LOGGING_LEVEL_DEFAULT;

void log_event(int level, const char* message) {
    if (level <= logging_level) {
        printf("%s\n", message);
    }
}

int get_random_crcflag() {
    return rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T* create_structure(int index) {
    NFAPI_CRC_INDICATION_PDU_T* structure = &NFAPI_CRC_INDICATION_PDU_array[index];
    structure->RX_UE_INFORMATION_TAG = index;
    strcpy(structure->RNTI, "RNTI_");
    structure->CRC_INDICATION_REL8_TAG = index * 2;
    structure->CRCFLAG = get_random_crcflag();
    return structure;
}

int validate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (structure->RX_UE_INFORMATION_TAG < 0 || structure->RX_UE_INFORMATION_TAG >= MAX_STRUCTURES) {
        log_event(1, "Invalid RX_UE_INFORMATION_TAG");
        return -1;
    }
    if (strlen(structure->RNTI) != 7) {
        log_event(1, "Invalid RNTI length");
        return -2;
    }
    if (structure->CRC_INDICATION_REL8_TAG < 0 || structure->CRC_INDICATION_REL8_TAG >= MAX_STRUCTURES * 2) {
        log_event(1, "Invalid CRC_INDICATION_REL8_TAG");
        return -3;
    }
    if (structure->CRCFLAG < 0 || structure->CRCFLAG > 1) {
        log_event(1, "Invalid CRCFLAG");
        return -4;
    }
    return 0;
}

int populate_structures(int start, int end) {
    for (int i = start; i <= end; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = create_structure(i);
        if (validate_structure(structure) < 0) {
            log_event(1, "Failed to validate structure");
            return -1;
        }
        log_event(logging_level, "Structure %d populated successfully", i);
    }
    return 0;
}

int get_statistics() {
    int success_count = 0;
    int fail_count = 0;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (validate_structure(&NFAPI_CRC_INDICATION_PDU_array[i]) >= 0) {
            success_count++;
        } else {
            fail_count++;
        }
    }
    log_event(logging_level, "Statistics: Successes %d, Failures %d", success_count, fail_count);
    return 0;
}

int main() {
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, &populate_structures, (void*) 0);
    if (ret) {
        log_event(1, "Failed to create thread");
        return -1;
    }
    pthread_join(thread, NULL);
    get_statistics();
    return 0;
}
