#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "logging_api.h"

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct Node* next;
} Node;

// Function to manage a dynamic linked list of NFAPI_CRC_INDICATION_PDU_T structures
void nfa_pi_crc_indication_pdu_list_manager(int num_pdu) {
    Node* head = NULL;
    Node* current = NULL;
    int allocated_count = 0;
    int freed_count = 0;

    // Allocate memory for the linked list nodes and PDU structures
    while (allocated_count < num_pdu) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            logging_api_log_error("Memory allocation failed");
            break;
        }
        allocated_count++;

        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            logging_api_log_error("Memory allocation failed");
            free(new_node);
            allocated_count--;
            break;
        }
        new_node->pdu = new_pdu;

        // Set CRCFLAG randomly
        new_pdu->crcflag = rand() % 2; // Randomly set to 0 or 1

        if (head == NULL) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    // Periodic cleanup of unused structures
    int i = 0;
    Node* temp = head;
    while (temp != NULL && i < num_pdu) {
        if (!temp->pdu->rx_ue_info || !temp->pdu->rnti || !temp->pdu->crc_ind_rel8_tag) {
            // Free the node and PDU structure
            free(temp);
            temp = head;
            freed_count++;
        } else {
            temp = temp->next;
        }
    }

    logging_api_log_info("Allocated %d nodes and PDUs", allocated_count - freed_count);
    logging_api_log_warning("Failed to allocate memory: %d nodes not created", freed_count);

    // Free any remaining structures
    while (head != NULL) {
        Node* next = head->next;
        free(head);
        head = next;
    }
}
