#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 50000
#define LOG_LEVEL 1 // 0 = error, 1 = warning, 2 = info

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    uint16_t source_port;
    uint16_t destination_port;
    size_t bytes_transferred;
} TCP_CONNECTION_INFO;

TCP_CONNECTION_INFO* connections;
size_t connection_count = 0;

void log_message(int level, const char* message) {
    if (level <= LOG_LEVEL) {
        printf("%s\n", message);
    }
}

int populate_connections() {
    for (size_t i = 0; i < MAX_CONNECTIONS; i++) {
        TCP_CONNECTION_INFO* connection = &connections[i];
        // Validate IP addresses and port numbers
        if (!validate_ip(connection->source_ip) || !validate_ip(connection->destination_ip) ||
            connection->source_port > 65535 || connection->destination_port > 65535) {
            log_message(0, "Invalid connection information");
            return -1;
        }
        // Record the connection in the logging framework
        log_message(LOG_LEVEL == 2 ? 2 : (LOG_LEVEL == 1 ? 1 : 0), "Connection added: source_ip=%s, destination_ip=%s, bytes_transferred=%zu",
                    connection->source_ip, connection->destination_ip, connection->bytes_transferred);
        connection_count++;
    }
    return 0;
}

int filter_connections(const char* ip_filter) {
    for (size_t i = 0; i < connection_count; i++) {
        TCP_CONNECTION_INFO* connection = &connections[i];
        if (ip_filter && (strcmp(connection->source_ip, ip_filter) == 0 || strcmp(connection->destination_ip, ip_filter) == 0)) {
            log_message(2, "Connection found: source_ip=%s, destination_ip=%s", connection->source_ip, connection->destination_ip);
            return i;
        }
    }
    return -1; // No matching connections
}

int get_connection_statistics() {
    printf("Total connections: %zu\n", connection_count);
    printf("Failed connections: %d\n", (connection_count - populate_connections()));
    return 0;
}

int main() {
    connections = calloc(MAX_CONNECTIONS, sizeof(TCP_CONNECTION_INFO));
    if (!connections) {
        log_message(0, "Memory allocation failed");
        return -1;
    }

    int result = populate_connections();
    if (result < 0) {
        log_message(0, "Connection population failed");
        return -1;
    }

    get_connection_statistics();

    // Example usage: Filter connections by destination IP
    const char* filter_ip = "192.168.1.100";
    size_t filtered_index = filter_connections(filter_ip);
    if (filtered_index >= 0) {
        log_message(2, "Filtered connection found at index %zu", filtered_index);
    } else {
        log_message(2, "No matching connections found");
    }

    free(connections);
    return 0;
}

int validate_ip(char* ip) {
    struct in_addr addr;
    if (inet_pton(AF_INET, ip, &addr)) {
        return 1; // Valid IP address
    }
    return 0; // Invalid IP address
}
