NFAPI_CRC_INDICATION_PDU_T* array = NULL;
size_t size = 0;
int allocations = 0;
int deallocations = 0;
int cache_size = 100000; // adjust according to your needs

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_array(size_t new_size) {
    if (new_size > MAX_ALLOCATIONS) return NULL;

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        allocations++;
        printf("Allocation failure: %ld\n", size);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    array = new_array;
    size = new_size;
    pthread_mutex_unlock(&lock);

    return array;
}

void deallocate_array() {
    if (array != NULL) {
        free(array);
        array = NULL;
        deallocations++;
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(int index) {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = &array[index % size];
    if (index >= size) {
        if (size < cache_size && allocations > deallocations * 5) {
            size *= 2;
            array = allocate_array(size);
        }
    }
    pthread_mutex_unlock(&lock);

    return pdu;
}

void set_pdu(int index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lock);
    array[index % size] = pdu;
    pthread_mutex_unlock(&lock);
}
