        if (N < 10) { // initial allocation for 10 elements
            array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
            if (array != NULL)
                break;
        }

        N *= 2; // double the size on each failed allocation
    }

    atomic_store(next_index, N); // store the current index

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = i; // populate unique values
        array[i].RNTI = i;
        array[i].CRC_INDICATION_REL8_TAG = i % 256; // limit CRCFLAG to 8 bits
        array[i].CRCFLAG = (i >> 8) & 0xFF; // limit CRCFLAG to 8 bits
    }

