// Function to validate a node
int validateNode(NFAPI_CRC_INDICATION_PDU_T* node) {
    // Check for valid structure data
    if (node->RX_UE_INFORMATION_TAG[0] == '\0' || node->RNTI < 0 || node->CRCFLAG < 0) {
        printf("Error: Invalid node detected. Skipping...\n");
        return 1;
    }
    return 0;
}

// Function to manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void manageNfaList(NFAPI_CRC_INDICATION_PDU_T** nfaList, int* nfaListSize) {
    // Check for invalid input parameters
    if (nfaList == NULL || *nfaListSize <= 0) return;

    NFAPI_CRC_INDICATION_PDU_T* newNfa = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNfa == NULL) {
        printf("Error: Unable to allocate memory.\n");
        return;
    }

    // Initialize node with random data
    srand(time(NULL));
    for (int i = 0; i < sizeof(newNfa->RX_UE_INFORMATION_TAG); i++) {
        newNfa->RX_UE_INFORMATION_TAG[i] = (char)(rand() % 256);
    }
    newNfa->RNTI = rand();
    for (int i = 0; i < sizeof(newNfa->CRC_INDICATION_REL8_TAG); i++) {
        newNfa->CRC_INDICATION_REL8_TAG[i] = (char)(rand() % 256);
    }
    newNfa->CRCFLAG = rand();

    // Validate the node
    if (validateNode(newNfa)) {
        free(newNfa);
        return;
    }

    // Add node to the list
    NFAPI_CRC_INDICATION_PDU_T** temp = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (*nfaListSize + 1));
    if (temp == NULL) {
        printf("Error: Unable to allocate memory.\n");
        free(newNfa);
        return;
    }
    for (int i = 0; i < *nfaListSize; i++) temp[i] = *(nfaList + i);
    temp[*nfaListSize] = newNfa;

    // Update the list size
    (*nfaListSize)++;

    // Clean up
    free(*(nfaList));
    *nfaList = temp;
}

// Function to free all allocated memory when the list is no longer needed
void freeNfaList(NFAPI_CRC_INDICATION_PDU_T** nfaList, int nfaListSize) {
    for (int i = 0; i < nfaListSize; i++) {
        if (*(nfaList + i)) free(*(nfaList + i));
    }
    free(nfaList);
}
