        return;
    }

    srand(seed);

    struct NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int list_size = 0;

    for (int i = 0; i < N; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            for (int j = 0; j < list_size; j++) {
                free(list + j);
            }
            free(list);
            return;
        }

        pdu->rx_ue_info_tag = 1;
        pdu->rnti = rand() % 1000;
        pdu->crc_ind_rel8_tag.crcflag = rand() & 1;

        if (list) {
            while (list_size > 0 && list[list_size - 1]->rnti == pdu->rnti) {
                --list_size;
            }

            for (int j = list_size; j < i; j++) {
                list[j] = list + j;
            }
        } else {
            list = pdu;
            list_size = 1;
        }

        if (i % 1000 == 0) {
            struct NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * (list_size + 1));

            if (!new_list) {
                for (int j = 0; j < list_size; j++) {
                    free(list + j);
                }
                free(list);
                return;
            }

            list = new_list;
        }
    }

    if (list) {
        free(list);
    }
}
