#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

// Define the structure for a TCP connection entry
typedef struct {
    int socket_fd;
    struct sockaddr_in peer_addr;
    enum { CLOSED, ESTABLISHED, FINISHED } state;
} Connection;

// Define the structure to manage the dynamic collection of connections
typedef struct {
    Connection *connections;
    size_t capacity;
    pthread_mutex_t lock;
    size_t count;
} ConnectionManager;

// Function prototypes
void init_manager(ConnectionManager *manager);
int add_connection(ConnectionManager *manager, int socket_fd, const struct sockaddr_in *peer_addr);
int update_connection_state(ConnectionManager *manager, int socket_fd, enum { CLOSED, ESTABLISHED, FINISHED } state);
Connection* get_connection(ConnectionManager *manager, int socket_fd);

// Implementation
ConnectionManager* connection_manager_init(size_t initial_capacity) {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    init_manager(manager);
    manager->capacity = initial_capacity;
    return manager;
}

void init_manager(ConnectionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->connections = calloc(manager->capacity, sizeof(Connection));
    manager->count = 0;
}

int add_connection(ConnectionManager *manager, int socket_fd, const struct sockaddr_in *peer_addr) {
    if (manager->count >= manager->capacity) {
        // Grow the capacity if necessary
        manager->capacity *= 2;
        Connection *new_connections = realloc(manager->connections, sizeof(Connection) * manager->capacity);
        manager->connections = new_connections;
    }

    Connection *connection = &manager->connections[manager->count++];
    connection->socket_fd = socket_fd;
    memcpy(&connection->peer_addr, peer_addr, sizeof(struct sockaddr_in));
    connection->state = ESTABLISHED;

    return 0;
}

int update_connection_state(ConnectionManager *manager, int socket_fd, enum { CLOSED, ESTABLISHED, FINISHED } state) {
    Connection *connection = get_connection(manager, socket_fd);
    if (connection != NULL) {
        connection->state = state;
        return 0;
    }
    return -1; // Connection not found
}

Connection* get_connection(ConnectionManager *manager, int socket_fd) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; i++) {
        if (manager->connections[i].socket_fd == socket_fd) {
            Connection *connection = &manager->connections[i];
            pthread_mutex_unlock(&manager->lock);
            return connection;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}
