void manage_list(int N, int seed) {
    if (N <= 0) return;

    srand(seed);

    TPC_COMMAND_PDU_T* list = NULL;
    for (int i = 0; i < N; i++) {
        TPC_COMMAND_PDU_T* p = malloc(sizeof(TPC_COMMAND_PDU_T));
        p->tx_power_control_target = rand() % 10000;
        if (!list) list = p;
        else {
            p->next = list;
            list = p;
        }
    }

    void free_list(TPC_COMMAND_PDU_T* head) {
        TPC_COMMAND_PDU_T* curr = head;
        while (curr) {
            TPC_COMMAND_PDU_T* next = curr->next;
            free(curr);
            curr = next;
        }
    }

    int batch_size = 1000;
    void process_batch(TPC_COMMAND_PDU_T* start, TPC_COMMAND_PDU_T* end) {
        // logic for processing a batch of structures
    }

    if (N % batch_size == 0) {
        TPC_COMMAND_PDU_T* batch_start = list;
        for (int i = 0; i < N; i += batch_size) {
            process_batch(batch_start, batch_start + batch_size - 1);
            batch_start += batch_size;
        }
    } else {
        int remainder = N % batch_size;
        TPC_COMMAND_PDU_T* start = list;
        for (int i = 0; i < remainder; i++) {
            process_batch(start, start + i);
            start += i + 1;
        }
        process_batch(start, start + batch_size - 1);
    }

    free_list(list);
}
