// Array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS];

// Mutex for thread synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to safely allocate and initialize an array element
NFAPI_CRC_INDICATION_PDU_T* add_element() {
    NFAPI_CRC_INDICATION_PDU_T* new_element;
    pthread_mutex_lock(&mutex);
    new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        // Handle out-of-memory condition
        printf("Error: Out of memory. Allocation failed.\n");
        return NULL; // Return failure
    }
    pthread_mutex_unlock(&mutex);

    // Initialize the structure with valid values and random CRC flag
    new_element->rx_ue_info = ...; // Set RX UE information tag
    new_element->rnti = ...; // Set RNTI value
    new_element->crc_ind_rel8_tag = ...; // Set CRC indication rel 8 tag
    new_element->crcflag = (rand() % 2) ? CRCFLAG_SET : CRCFLAG_NOT_SET;

    return new_element;
}

// Function to concurrently add an element to the array
void* add_to_array(void* arg) {
    int index = *(int*)arg; // Get the index from the argument

    pthread_mutex_lock(&mutex);
    array[index] = add_element();
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to concurrently retrieve an element from the array
void* get_from_array(void* arg) {
    int index = *(int*)arg; // Get the index from the argument

    pthread_mutex_lock(&mutex);
    if (array[index] != NULL) {
        // Process the retrieved element
        printf("Element at index %d: \n", index);
        printf("%ld, %ld, %ld, %s\n",
               array[index]->rx_ue_info,
               array[index]->rnti,
               array[index]->crc_ind_rel8_tag,
               (array[index]->crcflag == CRCFLAG_SET) ? "SET" : "NOT SET");
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to safely free all allocated resources when the list is no longer needed
void free_resources() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (array[i] != NULL) {
            free(array[i]);
            array[i] = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Example usage:
int main() {
    int num_elements = 5;

    // Initialize the array with indices
    for (int i = 0; i < num_elements; i++) {
        array[i] = NULL; // Initialize all elements to null
    }

    // Create threads to concurrently add and retrieve elements from the array
    pthread_t threads[num_elements];
    int* indices = (int*)malloc(num_elements * sizeof(int));
    for (int i = 0; i < num_elements; i++) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, add_to_array, &indices[i]);
    }

    // Wait for the threads to complete
    for (int i = 0; i < num_elements; i++) {
        pthread_join(threads[i], NULL);
    }

    free(indices);

    return 0;
}
