// Thread-safe dynamically sized array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} NFAPICRCIndicationArray;

// Initialize the thread-safe array with a specified initial capacity
NFAPICRCIndicationArray* nfapi_crc_indication_array_init(size_t initial_capacity) {
    NFAPICRCIndicationArray* array = (NFAPICRCIndicationArray*)malloc(sizeof(NFAPICRCIndicationArray));
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Add a new element to the array, dynamically resizing if necessary
void nfapi_crc_indication_array_add(NFAPICRCIndicationArray* array, NFAPI_CRC_INDICATION_PDU_T* new_element) {
    pthread_mutex_lock(&array->mutex);

    // Dynamically resize the array if it's full or almost full
    if (array->length >= array->capacity - 1) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            printf("Error: Out of memory\n");
            exit(1);
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    // Add the new element to the array
    array->array[array->length++] = *new_element;

    pthread_mutex_unlock(&array->mutex);
}

// Get the length of the array
size_t nfapi_crc_indication_array_length(NFAPICRCIndicationArray* array) {
    pthread_mutex_lock(&array->mutex);
    size_t length = array->length;
    pthread_mutex_unlock(&array->mutex);
    return length;
}

// Free the thread-safe array and its contents
void nfapi_crc_indication_array_free(NFAPICRCIndicationArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);

        // Release any allocated memory
        free(array->array);
        array->length = 0;
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}
