#include <forward_list>
#include <string>
#include <algorithm>
#include <random>

void populateAndInsertIndication(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& indicationList, const std::vector<std::string>& strings) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    for (const auto& string : strings) {
        bool found = false;
        auto it = indicationList.begin();
        while (it != indicationList.end()) {
            if (std::string(it->RX_UE_INFORMATION_TAG).compare(string) == 0) {
                found = true;
                break;
            }
            ++it;
        }

        if (!found) {
            it = indicationList.insert_after(it, NFAPI_CRC_INDICATION_PDU_T{});
            for (; it != indicationList.end(); ++it) {
                if (std::string(it->RX_UE_INFORMATION_TAG).compare(string) == 0) {
                    break;
                }
            }

            if (it != indicationList.begin()) {
                --it;
            }
        }

        for (; it != indicationList.end(); ++it) {
            (*it).CRCFLAG = dis(gen);
        }
    }
}
