#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define MEMORY_POOL_GROWTH_RATE 2
#define GC_INTERVAL 10 // seconds

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int memory_pool_size = 0;
int max_memory_allocation = MAX_SIZE;
int gc_count = 0;

void* my_calloc(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&lock);
    if (memory_pool_size + size <= max_memory_allocation) {
        ptr = malloc(size);
        memory_pool_size += size;
    } else {
        printf("Memory allocation failed. Reaching maximum limit.\n");
        ptr = NULL;
    }
    pthread_mutex_unlock(&lock);
    return ptr;
}

void my_free(void* ptr, size_t size) {
    pthread_mutex_lock(&lock);
    if (memory_pool_size >= size) {
        free(ptr);
        memory_pool_size -= size;
    } else {
        printf("Memory deallocation failed. Memory pool is empty.\n");
    }
    pthread_mutex_unlock(&lock);
}

void gc_callback() {
    static int count = 0;
    if ((++count % GC_INTERVAL == 0) && (memory_pool_size > 0)) {
        void* ptr = my_calloc(1); // dummy allocation to trigger deallocation
        my_free(ptr, 1);
    }
}

void print_memory_metrics() {
    printf("Memory pool size: %d bytes\n", memory_pool_size);
    printf("Free pool size: %d bytes\n", max_memory_allocation - memory_pool_size);
    printf("Peak allocation: %d bytes\n", memory_pool_size + (memory_pool_size / MEMORY_POOL_GROWTH_RATE));
}

NFAPI_CRC_INDICATION_PDU_T* allocate_array(int size) {
    NFAPI_CRC_INDICATION_PDU_T* array = my_calloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (array != NULL) {
        for (int i = 0; i < size; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 100;
            array[i].RNTI = rand() % 100;
            array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
            array[i].CRCFLAG = (rand() % 2) ? 1 : 0; // random CRC flag
        }
    } else {
        printf("Memory allocation failed. Maximum limit reached.\n");
        return NULL;
    }
    pthread_create(NULL, NULL, &gc_callback, NULL);
    print_memory_metrics();
    return array;
}
