typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    uint8_t crcflag;
} NFAPI_MESSAGE_T;

// Dynamic array structure
typedef struct {
    NFAPI_MESSAGE_T* messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFapiMessageArray;

NFapiMessageArray* nfapi_message_array_create(size_t initial_capacity) {
    NFapiMessageArray* arr = (NFapiMessageArray*)malloc(sizeof(NFapiMessageArray));
    arr->messages = (NFAPI_MESSAGE_T*)calloc(initial_capacity, sizeof(NFAPI_MESSAGE_T));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void nfapi_message_array_destroy(NFapiMessageArray* arr) {
    for (size_t i = 0; i < arr->size; i++) {
        free(arr->messages[i].rx_ue_info.tag);
        free(arr->messages[i].crc_indication_rel8.tag);
    }
    free(arr->messages);
    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

void nfapi_message_array_add(NFapiMessageArray* arr, NFAPI_MESSAGE_T* message) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        // Double the capacity when full
        size_t new_capacity = 2 * arr->capacity;
        NFAPI_MESSAGE_T* new_messages = (NFAPI_MESSAGE_T*)realloc(arr->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
        if (!new_messages) {
            printf("Memory allocation error\n");
            return;
        }
        arr->messages = new_messages;
        arr->capacity = new_capacity;
    }
    arr->messages[arr->size] = *message;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

void nfapi_message_array_remove(NFapiMessageArray* arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);
    if (index >= arr->size) {
        printf("Index out of bounds\n");
        return;
    }
    for (size_t i = index; i < arr->size - 1; i++) {
        arr->messages[i] = arr->messages[i + 1];
    }
    arr->size--;
    pthread_mutex_unlock(&arr->mutex);
}

void nfapi_message_array_iterate(NFapiMessageArray* arr, void (*callback)(NFAPI_MESSAGE_T*)) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; i++) {
        callback(arr->messages[i]);
    }
    pthread_mutex_unlock(&arr->mutex);
}
