#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_entry {
    NFAPI_CRC_INDICATION_PDU_T* entry;
    time_t last_accessed;
};

typedef struct {
    size_t capacity;
    size_t size;
    struct cache_entry* entries;
} cache_t;

void cache_init(cache_t* cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->entries = (struct cache_entry*)malloc(capacity * sizeof(struct cache_entry));
}

NFAPI_CRC_INDICATION_PDU_T* find_by_rnti(cache_t* cache, RNTI rnti) {
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->entries[i].entry->rnti == rnti) {
            return cache->entries[i].entry;
        }
    }
    return NULL;
}

void add_entry(cache_t* cache, NFAPI_CRC_INDICATION_PDU_T* entry) {
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->entries[i].entry->rnti == entry->rnti) {
            // Update existing entry
            cache->entries[i].entry = entry;
            return;
        }
    }
    // Insert new entry
    cache->entries[cache->size].entry = entry;
    cache->entries[cache->size].last_accessed = time(NULL);
    if (cache->size == cache->capacity) {
        // Reallocate memory and move existing entries
        size_t new_capacity = cache->capacity * 2;
        struct cache_entry* new_entries = (struct cache_entry*)realloc(cache->entries, new_capacity * sizeof(struct cache_entry));
        cache->capacity = new_capacity;
        cache->entries = new_entries;
    }
    cache->size++;
}

void remove_entry_by_rnti(cache_t* cache, RNTI rnti) {
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->entries[i].entry->rnti == rnti) {
            // Remove entry
            memmove(&cache->entries[i], &cache->entries[i + 1], (cache->size - i - 1) * sizeof(struct cache_entry));
            cache->size--;
            return;
        }
    }
}

void update_cache_entry(cache_t* cache, NFAPI_CRC_INDICATION_PDU_T* entry) {
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->entries[i].entry->rnti == entry->rnti) {
            // Update existing entry
            cache->entries[i].entry = entry;
            return;
        }
    }
}

int main() {
    // Initialize cache with a capacity of 1000 entries
    cache_t cache;
    cache_init(&cache, 1000);

    // Add some entries to the cache
    NFAPI_CRC_INDICATION_PDU_T* entry1 = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry1->rx_ue_info = ...;  // Initialize RX_UE_INFORMATION_TAG
    entry1->rnti = 123;
    entry1->crc_ind_rel8_tag = ...;  // Initialize CRC_INDICATION_REL8_TAG
    entry1->crcflag = rand() % 2;

    NFAPI_CRC_INDICATION_PDU_T* entry2 = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry2->rx_ue_info = ...;  // Initialize RX_UE_INFORMATION_TAG
    entry2->rnti = 456;
    entry2->crc_ind_rel8_tag = ...;  // Initialize CRC_INDICATION_REL8_TAG
    entry2->crcflag = rand() % 2;

    add_entry(&cache, entry1);
    add_entry(&cache, entry2);

    // Update an existing entry
    update_cache_entry(&cache, entry1);

    // Remove an entry by RNTI
    remove_entry_by_rnti(&cache, 123);

    return 0;
}

