#define MEMORY_LIMIT 1024 * 1024 // 1MB
#define MAX_ELEMENTS 1000
#define RAND_RANGE 10 // random payload length within this range

typedef struct {
    int RX_FRAME_TAG;
    int RX_FRAME_TYPE;
    unsigned char RX_FRAME_DATA[16]; // assuming fixed payload size of 16 bytes
} NFAPI_RX_FRAME_PDU_T;

NFAPI_RX_FRAME_PDU_T* allocateArray(int n) {
    if (n > MAX_ELEMENTS || n * sizeof(NFAPI_RX_FRAME_PDU_T) > MEMORY_LIMIT) {
        return NULL; // memory limit exceeded or too many elements
    }

    NFAPI_RX_FRAME_PDU_T* array = (NFAPI_RX_FRAME_PDU_T*)malloc(n * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!array) {
        return NULL; // allocation failed
    }

    for (int i = 0; i < n; i++) {
        array[i].RX_FRAME_TAG = i;
        array[i].RX_FRAME_TYPE = rand() % RAND_RANGE;
        int payloadLength = rand() % RAND_RANGE + 1;
        if (payloadLength > 16) // assuming fixed payload size of 16 bytes
            payloadLength = 16; // clamp to maximum allowed payload size
        memset(array[i].RX_FRAME_DATA, 0, payloadLength);
    }

    return array;
}

void deallocateArray(NFAPI_RX_FRAME_PDU_T* array) {
    free(array);
}

// Serialize access using a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_RX_FRAME_PDU_T* getArray() {
    pthread_mutex_lock(&mutex);
    NFAPI_RX_FRAME_PDU_T* array = allocateArray(MAX_ELEMENTS);
    pthread_mutex_unlock(&mutex);
    return array;
}

void putArray(NFAPI_RX_FRAME_PDU_T* array) {
    pthread_mutex_lock(&mutex);
    deallocateArray(array);
    pthread_mutex_unlock(&mutex);
}
