void manageNFAPIArray(int N, int* array) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for the dynamic array of structures
    NFAPI_CRC_INDICATION_PDU_T** nfapiArray = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!nfapiArray) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize array with random RNTI values
    for (int i = 0; i < N; i++) {
        nfapiArray[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!nfapiArray[i]) {
            printf("Memory allocation failed.\n");
            return;
        }

        nfapiArray[i]->RX_UE_INFORMATION_TAG = i;
        nfapiArray[i]->RNTI = rand() % 1000; // Random RNTI value
        nfapiArray[i]->CRC_INDICATION_REL8_TAG = i;
        nfapiArray[i]->CRCFLAG = 0;
    }

    // Check for duplicate RNTI values and update CRCFLAG if necessary
    int uniqueRNTIs = 1; // Assume all RNTIs are unique initially
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (nfapiArray[i]->RNTI == nfapiArray[j]->RNTI) {
                // Duplicate RNTI found, update CRCFLAG
                uniqueRNTIs = 0;
                break;
            }
        }
    }

    if (!uniqueRNTIs) {
        for (int i = 0; i < N; i++) {
            nfapiArray[i]->CRCFLAG = 1;
        }
    } else {
        // No duplicate RNTI values found, update CRCFLAG accordingly
        for (int i = 0; i < N; i++) {
            if (nfapiArray[i]->RNTI % 2 == 0) {
                nfapiArray[i]->CRCFLAG = 1;
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < N; i++) {
        free(nfapiArray[i]);
    }
    free(nfapiArray);
}
