void* pdch_array_manager(void* arg) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // ensure thread safety

    // dynamic allocation strategy: fixed-size blocks with a maximum capacity
    const int BLOCK_SIZE = 16;
    const int MAX_CAPACITY = 1000;  // adjust according to system requirements

    MAC_PDU** pdch_array = (MAC_PDU**)malloc(BLOCK_SIZE * sizeof(MAC_PDU*));
    int array_index = 0, block_index = 0;

    while (1) {
        pthread_mutex_lock(&lock);

        if (array_index >= MAX_CAPACITY) {  // handle out-of-memory situations
            printf("Out of memory: unable to allocate new block.\n");
            break;
        }

        MAC_PDU* pdch_entry = (MAC_PDU*)malloc(sizeof(MAC_PDU));

        if (!pdch_entry) {
            printf("Error allocating PDCH entry.\n");
            free(pdch_array);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // initialize PDCH entry with default values or external data source
        pdch_entry->seq_num = 0;  // adjust according to system requirements
        strcpy(pdch_entry->pdch_data, "");  // consider alternative data structures for large PDCH_DATA

        pdch_array[array_index++] = pdch_entry;

        pthread_mutex_unlock(&lock);

        if (array_index >= BLOCK_SIZE) {
            block_index++;
            pdch_array = (MAC_PDU**)realloc(pdch_array, (block_index + 1) * BLOCK_SIZE * sizeof(MAC_PDU*));
        }
    }

    // iterate over the array to update PDCH_DATA based on specific conditions
    for (int i = 0; i < array_index; i++) {
        MAC_PDU* pdch_entry = pdch_array[i];

        if (retransmission_request || data_corruption_indicator) {  // adjust according to system requirements
            // update PDCH_DATA based on retransmission or corruption indicators
            printf("Updating PDCH entry %d.\n", i);
        }
    }

    // ensure thread safety while iterating over the array
    pthread_mutex_unlock(&lock);

    for (int i = 0; i < array_index; i++) {
        free(pdch_array[i]);
    }

    free(pdch_array);
    return NULL;
}
