#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <unistd.h>

#define MAX_ARRAY_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *dynamic_array[MAX_ARRAY_SIZE];
int array_size = 0;
int max_size = MAX_ARRAY_SIZE;

void initialize_array() {
    for (int i = 0; i < max_size; i++) {
        dynamic_array[i] = NULL;
    }
}

int add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&lock);

    if (array_size >= max_size) {
        // Handle memory pressure
        max_size *= 2;
        // Reallocate the array
        NFAPI_CRC_INDICATION_PDU_T **new_array = 
            (NFAPI_CRC_INDICATION_PDU_T **) realloc(
                dynamic_array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * max_size);
        if (!new_array) {
            pthread_mutex_unlock(&lock);
            return -1; // Memory allocation failed
        }
        dynamic_array = new_array;
    }

    int idx = array_size++;
    dynamic_array[idx] = element;

    pthread_mutex_unlock(&lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *remove_element(int RNTI) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        if (dynamic_array[i]->RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T *element = dynamic_array[i];
            memmove(dynamic_array + i, dynamic_array + i + 1, 
                    sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (array_size - i - 1));
            array_size--;
            pthread_mutex_unlock(&lock);
            return element;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL; // Element not found
}

int update_element(int RNTI, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        if (dynamic_array[i]->RNTI == RNTI) {
            // Update the element
            dynamic_array[i] = new_element;
            pthread_mutex_unlock(&lock);
            return 0; // Element updated successfully
        }
    }

    pthread_mutex_unlock(&lock);
    return -1; // Element not found
}

void print_array() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, "
               "CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", 
               dynamic_array[i]->RX_UE_INFORMATION_TAG, 
               dynamic_array[i]->RNTI, 
               dynamic_array[i]->CRC_INDICATION_REL8_TAG, 
               dynamic_array[i]->CRCFLAG);
    }

    pthread_mutex_unlock(&lock);
}

void *thread_function(void *arg) {
    // Thread-specific operations
    printf("Thread %p: Hello, world!\n", arg);
    return NULL;
}

int main() {
    initialize_array();

    NFAPI_CRC_INDICATION_PDU_T element1 = 
        (NFAPI_CRC_INDICATION_PDU_T) {1234, 5, 6789, 0};
    add_element(&element1);

    NFAPI_CRC_INDICATION_PDU_T element2 = 
        (NFAPI_CRC_INDICATION_PDU_T) {5678, 7, 9012, 1};
    add_element(&element2);

    print_array();

    // Remove an element
    NFAPI_CRC_INDICATION_PDU_T *removed_element = remove_element(5);
    if (removed_element) {
        printf("Removed element: ");
        print_array(); // Print the updated array
    }

    pthread_t thread;
    pthread_create(&thread, NULL, thread_function, NULL);

    return 0;
}
