typedef struct {
    uint32_t imsi;
    uint16_t rnti;
    void* ue_context;
} UE_Status_Report;

struct hash_table {
    int size;
    int num_entries;
    int peak_memory_usage;
    int total_allocations;
    pthread_mutex_t lock;
    UE_Status_Report** entries;
};

UE_Status_Report* ue_status_report_init() {
    UE_Status_Report* report = (UE_Status_Report*)malloc(sizeof(UE_Status_Report));
    if (!report) return NULL;

    // Initialize random values for last_reported_rsrp, last_reported_rssi, and last_reported_sinr
    // in ue_context

    return report;
}

int hash_table_init(struct hash_table* table, int size) {
    table->size = size;
    table->num_entries = 0;
    table->peak_memory_usage = 0;
    table->total_allocations = 0;

    pthread_mutex_init(&table->lock, NULL);

    table->entries = (UE_Status_Report**)calloc(size, sizeof(UE_Status_Report*));

    return 0;
}

void hash_table_insert(struct hash_table* table, UE_Status_Report* report) {
    int hash_value = report->imsi % table->size;

    pthread_mutex_lock(&table->lock);

    if (!table->entries[hash_value]) {
        // Successful allocation
        table->entries[hash_value] = report;
        table->num_entries++;
        table->total_allocations++;

        // Update peak memory usage if necessary
        size_t current_memory_usage = sizeof(UE_Status_Report) + (report->ue_context ? report->ue_context->size : 0);
        if (current_memory_usage > table->peak_memory_usage)
            table->peak_memory_usage = current_memory_usage;
    }

    pthread_mutex_unlock(&table->lock);
}

void hash_table_update(struct hash_table* table, UE_Status_Report* old_report) {
    // Find the corresponding entry in the hash table
    int hash_value = old_report->imsi % table->size;

    pthread_mutex_lock(&table->lock);

    if (table->entries[hash_value] == old_report) {
        // Update existing entry
        table->entries[hash_value] = ue_status_report_init();
        table->num_entries++;

        // Update peak memory usage if necessary
        size_t current_memory_usage = sizeof(UE_Status_Report) + (table->entries[hash_value]->ue_context ? table->entries[hash_value]->ue_context->size : 0);
        if (current_memory_usage > table->peak_memory_usage)
            table->peak_memory_usage = current_memory_usage;
    }

    pthread_mutex_unlock(&table->lock);

    // Release memory for the old report
    free(old_report->ue_context);
    free(old_report);
}

void hash_table_delete(struct hash_table* table, UE_Status_Report* report) {
    int hash_value = report->imsi % table->size;

    pthread_mutex_lock(&table->lock);

    if (table->entries[hash_value] == report) {
        // Deallocate the entry
        table->entries[hash_value] = NULL;
        table->num_entries--;

        // Release memory for the report
        free(report->ue_context);
        free(report);
    }

    pthread_mutex_unlock(&table->lock);
}

void hash_table_free(struct hash_table* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i]) {
            UE_Status_Report* report = table->entries[i];
            // Deallocate the entry and its context
            free(report->ue_context);
            free(report);
        }
    }

    free(table->entries);

    pthread_mutex_destroy(&table->lock);
}
