int load_resource_bundle(char* file_path, void** bundle_ptr, size_t* num_items) {
    // Load resource bundle from file
    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        return -1;  // File not found or inaccessible
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    *bundle_ptr = malloc(file_size + sizeof(void*));
    fread(*bundle_ptr, 1, file_size, file);

    fclose(file);

    // Fetch number of items in the bundle
    FILE* config_file = fopen("config.txt", "rb");
    if (config_file == NULL) {
        return -2;  // Configuration file not found or inaccessible
    }

    fseek(config_file, 0, SEEK_END);
    long config_size = ftell(config_file);
    rewind(config_file);

    char* buffer = malloc(config_size + 1);
    fread(buffer, 1, config_size, config_file);
    buffer[config_size] = '\0';

    *num_items = atoi(strtok(buffer, "\n"));
    free(buffer);
    fclose(config_file);

    // Dynamically construct and populate NFAPI_CRC_INDICATION_PDU_T structures
    int i;
    NFAPI_CRC_INDICATION_PDU_T* nfa_pds = (NFAPI_CRC_INDICATION_PDU_TAG*)malloc(*num_items * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (i = 0; i < *num_items; i++) {
        nfa_pds[i].rnti = rand() % 10000;
        sprintf(nfa_pds[i].rx_ue_info_tag, "RX_UE_INFO_TAG_%d", i);
        int crcflag = rand() % 2;
        (nfa_pds[i].crc_indication_rel8_tag).crcflag = crcflag;
    }

    free(*bundle_ptr);
    *bundle_ptr = nfa_pds;

    return 0;  // Successful bundle load
}
