void* thread_func(void* arg);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list[10000];
int capacity = 10000, head = 0, tail = 0, size = 0;

void lru_insert(NFAPI_CRC_INDICATION_PDU_T* p) {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        NFAPI_CRC_INDICATION_PDU_T* temp;
        temp = list[head];
        head = (head + 1) % capacity;
        size--;
        free(temp);
    }
    list[tail] = p;
    tail = (tail + 1) % capacity;
    if (size < capacity)
        size++;
    pthread_mutex_unlock(&lock);
}

void lru_remove() {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* temp;
    temp = list[head];
    head = (head + 1) % capacity;
    size--;
    free(temp);
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* lru_lookup(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* p;
    int i, j, k;
    pthread_mutex_lock(&lock);
    for (k = 0; k < size; k++) {
        i = head + k % capacity;
        if (list[i]->rnti == rnti) {
            p = list[i];
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return p;
}

void* thread_func(void* arg) {
    int num = (int)arg;
    for (int i = 0; i < num; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        p->rnti = rand();
        p->crcflag = rand() % 2;
        lru_insert(p);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, (void*)i);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
