void ProcessImageAndManageCRCIndications(int M, const unsigned char* input_string) {
    // Initialize the list of structures
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int size = 0;

    // Initialize the random seed
    srand(time(NULL));

    while (1) {
        // Check if the list has reached its capacity limit
        if (size >= M) {
            // Remove the oldest element from the list to make room for new ones
            free(list);
            list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            size = 0;
        }

        // Create a new structure with random values and add it to the list
        NFAPI_CRC_INDICATION_PDU_T* p = &list[size++];
        p->RX_UE_INFORMATION_TAG = rand() % 10000;
        memcpy(p->RNTI, "Random", 7);
        p->CRC_INDICATION_REL8_TAG = (uint16_t)rand();

        // Update the random seed
        srand(time(NULL) + size);

        // Check if the file is a valid TIFF image
        FILE* file = fopen("image.tiff", "rb");
        if (!file) {
            printf("Error: Unable to open the file.\n");
            exit(1);
        }

        // Read the TIFF metadata
        uint16_t bit_depth;
        int32_t num_samples_per_pixel;
        int32_t extra_samples;

        fread(&bit_depth, 2, 1, file);
        if (bit_depth != 8) {
            printf("Warning: Unrecognized bit depth.\n");
        }
        fread(&num_samples_per_pixel, 4, 1, file);
        fread(&extra_samples, 4, 1, file);

        // Compute the MD5 hash of the input string
        unsigned char* output = (unsigned char*)malloc(16);
        MD5(input_string, strlen((const char*)input_string), output);
        char checksum[33];
        for (int i = 0; i < 16; i++) {
            sprintf(checksum + i * 2, "%02x", output[i]);
        }
        free(output);

        // Close the file
        fclose(file);
    }

    // Free the list of structures
    free(list);

    return;
}

int main() {
    ProcessImageAndManageCRCIndications(10, (const unsigned char*)"Input string");
    return 0;
}
