typedef struct {
    time_t timestamp;
    char eventType[16];
    char description[256];
} NetworkEventLogEntry;

typedef struct {
    int capacity;
    int size;
    NetworkEventLogEntry** entries;
} LogArray;

void log_array_init(LogArray* array, int capacity) {
    array->capacity = capacity;
    array->size = 0;
    array->entries = (NetworkEventLogEntry**)malloc(capacity * sizeof(NetworkEventLogEntry*));
}

int log_array_insert(LogArray* array, NetworkEventLogEntry* entry) {
    if (array->size == array->capacity) {
        // Double the capacity when full
        array->capacity *= 2;
        array->entries = (NetworkEventLogEntry**)realloc(array->entries, array->capacity * sizeof(NetworkEventLogEntry*));
    }
    array->entries[array->size] = entry;
    array->size++;
    return 0;
}

int log_array_delete(LogArray* array, int index) {
    if (index < 0 || index >= array->size) {
        return -1; // Index out of bounds
    }
    for (int i = index; i < array->size - 1; i++) {
        array->entries[i] = array->entries[i + 1];
    }
    array->size--;
    return 0;
}

void log_array_log_entries(LogArray* array) {
    FILE* file = fopen("eventlog.txt", "w");
    for (int i = 0; i < array->size; i++) {
        fprintf(file, "%ld %s %s\n", array->entries[i]->timestamp, array->entries[i]->eventType, array->entries[i]->description);
    }
    fclose(file);
}

void log_array_free(LogArray* array) {
    for (int i = 0; i < array->size; i++) {
        free(array->entries[i]);
    }
    free(array->entries);
}
