// Function to generate and populate linked list of NFAPI_CRC_INDICATION_PDU structures
NFAPI_CRC_INDICATION_PDU* generateCRCIndicationList(int N, int minRnti, int maxRnti) {
    srand(time(NULL)); // seed random number generator

    // Initialize head and tail pointers for the linked list
    NFAPI_CRC_INDICATION_PDU* head = NULL;
    NFAPI_CRC_INDICATION_PDU* tail = NULL;

    // Generate and add N nodes to the list, ensuring unique RNTI values within range
    for (int i = 0; i < N; i++) {
        int rnti = rand() % ((maxRnti - minRnti) + 1) + minRnti;
        // Ensure uniqueness by checking for existing nodes with same RNTI value
        while (findNodeByRNTI(head, rnti) != NULL) {
            rnti = rand() % ((maxRnti - minRnti) + 1) + minRnti;
        }

        NFAPI_CRC_INDICATION_PDU* newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (newNode == NULL) {
            printf("Memory allocation failed.\n");
            return head; // handle memory allocation failure
        }
        newNode->RX_UE_INFORMATION_TAG = 0; // initialize with default value
        newNode->RNTI = rnti;
        newNode->CRC_INDICATION_REL8_TAG = rand() % 100 + 1; // random CRCFLAG value
        newNode->CRCFLAG = (rand() % 2) ? 1 : 0; // random CRCFLAG value

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    // Sort the linked list by RNTI in ascending order
    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU* next = current->next;
        while (next != NULL) {
            if (current->RNTI > next->RNTI) {
                int temp = current->RNTI;
                current->RNTI = next->RNTI;
                next->RNTI = temp;
                // swap other fields as needed
            }
            next = next->next;
        }
        current = current->next;
    }

    return head; // head of the sorted linked list
}

// Helper function to find a node in the linked list by RNTI value
NFAPI_CRC_INDICATION_PDU* findNodeByRNTI(NFAPI_CRC_INDICATION_PDU* head, int rnti) {
    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL; // node not found
}
