// Define a Java method for processing large integer arrays using Union-Find data structure
public static void processLargeIntegerArray(int[] arr) {
    int n = arr.length;
    int parent[] = new int[n];
    int rank[] = new int[n];

    // Initialize the Union-Find data structure
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    for (int i = 0; i < n; i++) {
        // Find the representative of each element
        int root = find(parent, arr[i]);
        // Union the elements with the same representative
        union(parent, rank, arr[i], root);
    }
}

// Function to find the representative of an element using the Union-Find data structure
public static int find(int[] parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

// Function to union two elements with the same representative using the Union-Find data structure
public static void union(int[] parent, int[] rank, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rootX != rootY) {
        // Merge the trees with the same representative
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

