    uint16_t rnti;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *nfapdu_list[MAX_NFAPDU];
int nfapdu_count = 0;
int seed_value = 42; // default value
int min_crcflag = MIN_CRCFLAG;
int max_crcflag = MAX_CRCFLAG;

void* generate_nfapdu_list(int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *nfapdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapdu) {
            LOG_ERROR("Memory allocation failure");
            continue;
        }

        nfapdu->rx_ue_information_tag = 0x01; // default value
        nfapdu->rnti = rand_r(&seed_value) % 65536;
        int crcflag = (rand_r(&seed_value) % (max_crcflag - min_crcflag)) + min_crcflag;
        if (crcflag < MIN_CRCFLAG || crcflag > MAX_CRCFLAG) {
            LOG_ERROR("Invalid CRC flag value");
            free(nfapdu);
            continue;
        }

        pthread_mutex_lock(&lock);
        nfapdu_list[nfapdu_count++] = nfapdu;
        pthread_mutex_unlock(&lock);
    }
}

int get_nfapdu_count() {
    int count = 0;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_NFAPDU; i++) {
        if (nfapdu_list[i]) {
            count++;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return count;
}
