void initFrameHeaders(int maxEntries, int* timestampArray, int* sequenceNumberArray, int* packetLengthArray) {
    // Initialize the doubly linked list with a dummy node
    Node* head = (Node*)malloc(sizeof(Node));
    head->prev = NULL;
    head->next = NULL;

    // Iterate over the arrays to populate the FrameHeaders and the linked list
    for (int i = 0; i < maxEntries; i++) {
        FrameHeader frameHeader = {timestampArray[i], sequenceNumberArray[i], packetLengthArray[i]};

        // Create a new node for the linked list
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->frameHeader = frameHeader;
        newNode->prev = head;
        newNode->next = head->next;

        // Update the head of the linked list if necessary
        if (head->next != NULL) {
            head->next->prev = newNode;
        } else {
            head->next = newNode;
        }

        head->next = newNode;
    }
}

