#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct FrameHeader {
    int Timestamp;
    int SequenceNumber;
    int PacketLength;
} FrameHeader;

typedef struct FrameList {
    FrameHeader* frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} FrameList;

FrameList* frameListInit(size_t initialCapacity) {
    FrameList* list = (FrameList*)malloc(sizeof(FrameList));
    list->frames = (FrameHeader*)calloc(initialCapacity, sizeof(FrameHeader));
    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void frameListAdd(FrameList* list, FrameHeader frame) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        FrameHeader* newFrames = (FrameHeader*)realloc(list->frames, newCapacity * sizeof(FrameHeader));
        list->frames = newFrames;
        list->capacity = newCapacity;
    }

    list->frames[list->size] = frame;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

void frameListDelete(FrameList* list) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; i++) {
        free(&list->frames[i]);
    }

    free(list->frames);
    list->capacity = 0;
    list->size = 0;

    pthread_mutex_unlock(&list->mutex);
}

void frameListLog(FrameList* list) {
    pthread_mutex_lock(&list->mutex);

    printf("Frame List: Size - %zu, Capacity - %zu\n", list->size, list->capacity);

    pthread_mutex_unlock(&list->mutex);
}
