        indications[i].RNTI = rand();

        char* hostname = "example.com";
        u_char ip[16];
        int result = resolveHostname(hostname, ip);

        if (result != 0) {
            // Handle DNS resolution error
            free(indications);
            return NULL;
        }

        indications[i].CRC_INDICATION_REL8_TAG = rand();
    }

    return indications;
}

int resolveHostname(char* hostname, u_char* ip) {
    struct sockaddr_in addr;
    int sockfd;
    socklen_t addrlen = sizeof(addr);

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        // Handle socket creation error
        return -1;
    }

    if (getaddrinfo(hostname, NULL, (void*)&addr, &addrlen, NULL) != 0) {
        // Handle DNS resolution error
        close(sockfd);
        freeaddrinfo((void*)gai_strerror(0));
        return -2;
    }

    inet_ntop(AF_INET, &(addr.sin_addr), ip, sizeof(u_char) * 16);
    close(sockfd);

    return 0;
}

