void* dynamic_array_allocation(size_t n, size_t threshold, int max_alloc_at_once, int log_level) {
    void *ptr = NULL;
    size_t total_allocated = 0;
    size_t allocated_this_cycle = 0;

    while (total_allocated + sizeof(NFAPI_CRC_INDICATION_PDU_T) <= threshold && allocated_this_cycle < max_alloc_at_once) {
        ptr = realloc(ptr, (allocated_this_cycle + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ptr) {
            printf("Memory allocation failed at cycle %d\n", allocated_this_cycle);
            return NULL;
        }
        allocated_this_cycle++;
