// Define the NET_EVENT_RECORD structure
typedef struct {
    int event_type;
    int timestamp;
    // Other relevant event data
} NET_EVENT_RECORD;

// Define the NETWORK_METRICS_REPORT structure
typedef struct {
    int packet_loss_rate;
    double throughput_avg;
    double latency_avg;
} NETWORK_METRICS_REPORT;

int processAndAggregateNetworkMetrics(NET_EVENT_RECORD* events, int num_events) {
    NETWORK_METRICS_REPORT report = {0};
    int failed_logging_attempts = 0;

    // Aggregate metrics
    for (int i = 0; i < num_events; i++) {
        switch (events[i].event_type) {
            case 1: // Packet loss event
                report.packet_loss_rate++;
                break;
            case 2: // Throughput event
                report.throughput_avg += events[i].timestamp / 1000.0;
                break;
            case 3: // Latency event
                report.latency_avg += events[i].timestamp / 1000.0;
                break;
        }
    }

    // Log metrics to multiple external data sinks
    if (log_to_file(report, "network_metrics.log")) {
        printf("Logged metrics to file successfully.\n");
    } else {
        failed_logging_attempts++;
    }

    if (log_to_db(report, "network_metrics_table")) {
        printf("Logged metrics to database successfully.\n");
    } else {
        failed_logging_attempts++;
    }

    // Handle failures and provide detailed logs
    if (failed_logging_attempts > 0) {
        printf("Failed to log %d times. Review logs for errors.\n", failed_logging_attempts);
        return -1;
    }

    return 0;
}

int log_to_file(NETWORK_METRICS_REPORT report, char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Failed to open file for logging: %s\n", filename);
        return -1;
    }

    // Log metrics in human-readable format
    fprintf(file, "Packet Loss Rate: %d\nThroughput Avg: %.2f Mbps\nLatency Avg: %.2f ms\n", 
            report.packet_loss_rate, report.throughput_avg / 1000.0, report.latency_avg);

    fclose(file);
    return 1;
}

int log_to_db(NETWORK_METRICS_REPORT report) {
    // Assume a database library with API to insert data
    db_insert("network_metrics_table", "packet_loss_rate", report.packet_loss_rate,
              "throughput_avg", report.throughput_avg, "latency_avg", report.latency_avg);

    return 1;
}

