public class UpdatePageElementService
{
    private readonly IUpdateService _updateService;
    private readonly IHtmlSanitizer _htmlSanitizer;
    private readonly ILogger _logger;

    public UpdatePageElementService(IUpdateService updateService, IHtmlSanitizer htmlSanitizer, ILogger logger)
    {
        _updateService = updateService;
        _htmlSanitizer = htmlSanitizer;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> HandleUpdateRequest([FromBody] UpdatePageElementRequest request)
    {
        if (!ValidateRequest(request))
            return BadRequest("Invalid request");

        try
        {
            var sanitizedHtml = _htmlSanitizer.Sanitize(request.HtmlContent);
            await _updateService.UpdateElementAsync(request.PageSectionId, request.ElementId, sanitizedHtml);

            return Ok("Update successful. Please refresh the page to see the changes.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating page element");
            return StatusCode(500, "Server error");
        }
    }

    private bool ValidateRequest(UpdatePageElementRequest request)
    {
        if (!request.PageSectionId.IsValid())
            return false;

        if (!request.ElementId.IsValid())
            return false;

        // Additional validation logic here...
        return true;
    }
}

public class UpdatePageElementRequest
{
    public Guid PageSectionId { get; set; }
    public Guid ElementId { get; set; }
    public string HtmlContent { get; set; }
