NFAPI_CRC_INDICATION_PDU_T* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *new_node = data;
    return new_node;
}

void insert_at_tail(struct node** head, struct node** tail, NFAPI_CRC_INDICATION_PDU_T data) {
    struct node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
        *tail = new_node;
    } else {
        (*tail)->next = new_node;
        *tail = new_node;
    }
}

int check_duplicate_rnti(struct node* head, RNTI rnti) {
    struct node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void handle_duplicate_rnti_error() {
    printf("Error: Duplicate RNTI value found. Aborting operation.\n");
    exit(1);
}

NFAPI_CRC_INDICATION_PDU_T* find_node_by_rnti(struct node* head, RNTI rnti) {
    struct node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

