#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Configurable parameters
int max_size = 10000;
int threshold = (max_size * 90) / 100;

// Function to manage the linked list and track unique RNTI values
void* nfa_pi_crc_indication_pdu_list(int* total_unique_rnti, int* current_size, int* warning_threshold_reached) {
    time_t timestamp;
    struct tm* tinfo;

    // Initialize data structures
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;
    int unique_rnti_count = 0;
    int list_size = 0;

    // Function to add a new structure to the linked list and update statistics
    void add_to_list(NFAPI_CRC_INDATION_PDU_T* pdu) {
        if (list_size >= max_size || (!pdu->RNTI && unique_rnti_count < threshold)) {
            printf("Warning: List size exceeds %d%% of max_size.\n", 90);
            *warning_threshold_reached = 1;
        }

        // Allocate memory for the new structure
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Copy the pdu structure
        *new_pdu = *pdu;

        // Update statistics and linked list
        new_pdu->timestamp = time(NULL);
        list = realloc(list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!list) {
            printf("Memory allocation failed.\n");
            free(new_pdu);
            return;
        }
        list[list_size++] = &new_pdu;

        // Check for unique RNTI values
        int found = 0;
        for (int i = 0; i < list_size; i++) {
            if (list[i]->RNTI == pdu->RNTI) {
                found = 1;
                break;
            }
        }

        if (!found) {
            unique_rnti_count++;
        }

        free(pdu);
    }

    // Function to validate the linked list
    void validate_list() {
        for (int i = 0; i < list_size - 1; i++) {
            if (list[i]->timestamp > list[i + 1]->timestamp) {
                printf("Timestamp inconsistency detected.\n");
            }
        }
    }

    // Function to log performance metrics
