int addUeToStatistic(NetworkStatistic* stat, int ueID) {
    if (stat->ueCount >= stat->ueIDs) {
        // Reallocate memory and update UE count
        stat->ueIDs = (int*)realloc(stat->ueIDs, (stat->ueCount + 1) * sizeof(int));
        if (!stat->ueIDs) {
            return -1; // Handle memory allocation failure
        }
    }

    if (ueID < 0 || ueID >= 10000) { // Validate UE identifier range [0-9999]
        return -2; // Invalid UE identifier
    }

    stat->ueIDs[stat->ueCount++] = ueID;
    stat->timestamp = time(NULL); // Update timestamp

    return 1; // Successful addition of UE
}

