MemoryPoolAllocator* create_memory_pool_allocator(int block_size) {
    MemoryPoolAllocator* allocator = (MemoryPoolAllocator*)malloc(sizeof(MemoryPoolAllocator));
    allocator->blocks = (void**)malloc(block_size * sizeof(void*));
    allocator->num_blocks = 0;
    allocator->block_size = block_size;
    return allocator;
}

void* allocate_memory(MemoryPoolAllocator* allocator) {
    if (allocator->num_blocks == 0) {
        return NULL;
    }
    void* result = allocator->blocks[0];
    for (int i = 0; i < allocator->num_blocks - 1; i++) {
        allocator->blocks[i] = allocator->blocks[i + 1];
    }
    allocator->num_blocks--;
    return result;
}

void free_memory(MemoryPoolAllocator* allocator, void* block) {
    for (int i = 0; i < allocator->num_blocks; i++) {
        if (allocator->blocks[i] == block) {
            memmove(&allocator->blocks[i], &allocator->blocks[i + 1], (allocator->num_blocks - i - 1) * sizeof(void*));
            allocator->num_blocks--;
            return;
        }
    }
}

