pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
FILE* error_log_file = fopen(ERROR_LOG_FILE, "w");

void* nfa_pi_crc_indication_pdu_allocate() {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (!new_pdu) {
        fprintf(error_log_file, "Memory allocation failed!\n");
        exit(1);
    }
    return new_pdu;
}

void nfa_pi_crc_indication_pdu_free(void* pdu) {
