    return 0;
}

int nfa_pi_crc_indication_pdu_initialize(int pool_size) {
    int i;
    for (i = 0; i < pool_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)nfa_pi_crc_indication_pdu_allocate();
        if (!pdu) {
            return -1;
        }
        nfa_pi_crc_indication_pdu_populate(pdu);
    }
    return 0;
}

void nfa_pi_crc_indication_pdu_shutdown() {
    // deallocate and free pool
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        void* pdu = &nfa_pi_crc_indication_pdu_pool[i];
        if (pdu) {
            nfa_pi_crc_indication_pdu_free(pdu);
        }
    }
}

void* nfa_pi_crc_indication_pdu_get() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &nfa_pi_crc_indication_pdu_pool[i];
        if (!pdu->ue_info) { // check if the structure is valid
            pthread_mutex_unlock(&pool_lock);
            return pdu;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void nfa_pi_crc_indication_pdu_put(void* pdu) {
    pthread_mutex_lock(&pool_lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)pdu;
    if (!pdu->ue_info) { // check if the structure is valid
        pthread_mutex_unlock(&pool_lock);
    } else {
        pthread_mutex_unlock(&pool_lock);
    }
}

