// Function to dynamically allocate and initialize a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int n) {
    srand(time(NULL));  // Initialize random number generator

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDATION_PDU_T* current = NULL;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

