        // Initialize RX_UE_INFORMATION_TAG and RNTI values from an external data source
        new_node->tag_value = 0; // Replace with actual data retrieval
        new_node->rnti_value = 1; // Replace with actual data retrieval

        // Randomly set CRCFLAG for each node
        if (rand() % 2) {
            new_node->crcflag = CRCFLAG_ENABLED;
        } else {
            new_node->crcflag = CRCFLAG_DISABLED;
        }

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

// Function to free allocated memory and clean up the linked list
void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}
