#include <stdlib.h>
#include <pthread.h>

#define MAX_INITIALIZED_STRUCTURES 10
#define MIN_INCREMENT 5

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[CRC_INDICATION_PDU_T_SIZE];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initializeStructures(int numStructures, pthread_mutex_t* mutex) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) return NULL;

    for (int i = 0; i < numStructures; i++) {
        pthread_mutex_lock(mutex);
        structures[i].RX_UE_INFORMATION_TAG = i;
        structures[i].RNTI = rand() % RAND_MAX;
        structures[i].CRCFLAG = rand() % 2;
        pthread_mutex_unlock(mutex);
    }

    return structures;
}

void* resizeStructures(void* ptr, int newSize, pthread_mutex_t* mutex) {
    NFAPI_CRC_INDICATION_PDU_T** structures = (NFAPI_CRC_INDICATION_PDU_T**)ptr;

    if (!structures || !*structures) return NULL;

    void* reallocate = realloc(*structures, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!reallocate) {
        free(*structures);
        return NULL;
    }

    *structures = (NFAPI_CRC_INDICATION_PDU_T*)reallocate;
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize structures
    NFAPI_CRC_INDICATION_PDU_T* structures = initializeStructures(MAX_INITIALIZED_STRUCTURES, &mutex);

    // Dynamically resize if needed
    if (structures && structures->RX_UE_INFORMATION_TAG >= MAX_INITIALIZED_STRUCTURES) {
        pthread_mutex_lock(&mutex);
        int newCapacity = MAX_INITIALIZED_STRUCTURES + MIN_INCREMENT;
        void* reallocate = resizeStructures(&structures, newCapacity, &mutex);
        if (!reallocate) {
            free(structures);
            return 1; // error
        }
    }

    return 0;
}
