#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct TCP_CONNECTION_RECORD {
    int CONNECTION_ID;
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int STATUS;
} TCP_CONNECTION_RECORD;

// Function to create a new TCP connection record
TCP_CONNECTION_RECORD* create_TCP_connection_record(int id, const char* src_ip, const char* dst_ip) {
    TCP_CONNECTION_RECORD* new_conn = (TCP_CONNECTION_RECORD*)malloc(sizeof(TCP_CONNECTION_RECORD));
    new_conn->CONNECTION_ID = id;
    strcpy(new_conn->SOURCE_IP, src_ip);
    strcpy(new_conn->DESTINATION_IP, dst_ip);
    new_conn->STATUS = 0; // Initialize status as 0 (new connection)
    return new_conn;
}

// Function to add a new TCP connection record to the list
void add_TCP_connection(TCP_CONNECTION_RECORD** head, TCP_CONNECTION_RECORD* new_conn) {
    if (*head == NULL || (*head)->CONNECTION_ID > new_conn->CONNECTION_ID) {
        // If the list is empty or the new connection has a lower ID, insert at the beginning
        new_conn->next = *head;
        *head = new_conn;
    } else {
        TCP_CONNECTION_RECORD* temp = *head;
        while (temp->next != NULL && temp->next->CONNECTION_ID <= new_conn->CONNECTION_ID) {
            temp = temp->next;
        }
        new_conn->next = temp->next;
        temp->next = new_conn;
    }
}

// Function to find a TCP connection record by ID
TCP_CONNECTION_RECORD* find_TCP_connection(TCP_CONNECTION_RECORD** head, int id) {
    TCP_CONNECTION_RECORD* current = *head;
    while (current != NULL && current->CONNECTION_ID < id) {
        current = current->next;
    }
    if (current == NULL || current->CONNECTION_ID > id) {
        return NULL; // Connection not found
    }
    return current;
}

// Function to remove a TCP connection record from the list
void remove_TCP_connection(TCP_CONNECTION_RECORD** head, TCP_CONNECTION_RECORD* conn) {
    if (*head == conn) {
        *head = conn->next;
    } else {
        TCP_CONNECTION_RECORD* temp = *head;
        while (temp->next != NULL && temp->next != conn) {
            temp = temp->next;
        }
        if (temp->next != NULL) {
            temp->next = conn->next;
        } else {
            // Remove the last element
            temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = NULL;
        }
    }
}

// Function to free memory for a TCP connection record
void free_TCP_connection(TCP_CONNECTION_RECORD* conn) {
    if (conn == NULL) return; // Nothing to do
    free(conn);
}

// Function to traverse the list and print connection records
void print_TCP_connections(TCP_CONNECTION_RECORD* head) {
    while (head != NULL) {
        printf("Connection ID: %d, Source IP: %s, Destination IP: %s, Status: %d\n", 
               head->CONNECTION_ID, head->SOURCE_IP, head->DESTINATION_IP, head->STATUS);
        head = head->next;
    }
}
