typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    pthread_mutex_t mutex;
} NFAPI_List;

NFAPI_List list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_list() {
    list.data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list.size = 0;
}

int is_unique_rnti(RNTI rnti) {
    for(int i = 0; i < list.size; i++) {
        if(list.data[i].rnti == rnti) return 0;
    }
    return 1;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* element) {
