    if(list.size >= MAX_LIST_SIZE) {
        printf("List size exceeded!\n");
        return;
    }

    for(int i = 0; i < list.size; i++) {
        if(is_unique_rnti(element->rnti)) break;
        else {
            pthread_mutex_unlock(&list.mutex);
            sleep(DELAY_TIME / 1000); // retry after a delay
            pthread_mutex_lock(&list.mutex);
            i = 0;
        }
    }

    list.data[list.size++] = *element;

    pthread_mutex_unlock(&list.mutex);
}

void update_statistics() {
    int total_elements = list.size;
    int sum_crcflag = 0;

    for(int i = 0; i < total_elements; i++) {
        sum_crcflag += list.data[i].crcflag;
    }

    printf("Statistics: Total elements - %d, Average CRCFLAG - %d\n", total_elements, sum_crcflag / total_elements);
}

void* retrieve_statistics(void* ptr) {
    update_statistics();
    return NULL;
}

int main() {
    initialize_list();

    pthread_t statistics_thread;

    pthread_create(&statistics_thread, NULL, retrieve_statistics, NULL);

    // Add elements to the list
    add_to_list(...); // fill in your data

    // Update statistics every 10 seconds
    while(1) {
        sleep(STATISTICS_UPDATE_INTERVAL);
        update_statistics();
    }

    return 0;
}
