int file_processor(const char* key, const char* input_file_path, int mode, const char* output_file_path) {
    // Check for NULL inputs and invalid modes
    if (!key || !input_file_path || !output_file_path || (mode != 0 && mode != 1)) {
        return -1; // Invalid parameters
    }

    // Initialize OpenSSL
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    AES_KEY* aes_key;
    unsigned char iv[AES_BLOCK_SIZE];

    if (!ctx) {
        ERR_error_fp(stderr, "Failed to initialize context");
        return -2; // Initialization failed
    }

    // Generate a random IV for encryption and decryption
    RAND_bytes(iv, sizeof(iv));
    EVP_CIPHER_CTX_set_iv(ctx, iv, AES_BLOCK_SIZE);

    // Set up the key and cipher mode
    if (mode == 0) { // Encryption
        aes_key = (AES_KEY*)malloc(sizeof(AES_KEY));
        if (!aes_key) {
            ERR_error_fp(stderr, "Failed to allocate AES key");
            EVP_CIPHER_CTX_free(ctx);
            return -3; // Memory allocation failed
        }
        AES_make_key(aes_key, key, strlen(key), 128); // Generate a 128-bit key from the input string
    } else { // Decryption
        aes_key = (AES_KEY*)malloc(sizeof(AES_KEY));
        if (!aes_key) {
            ERR_error_fp(stderr, "Failed to allocate AES key");
            EVP_CIPHER_CTX_free(ctx);
            return -3; // Memory allocation failed
        }
        AES_make_key(aes_key, key, strlen(key), 128); // Generate a 128-bit key from the input string
    }

    // Open files and process data
    FILE* input_file = fopen(input_file_path, "rb");
    if (!input_file) {
        ERR_error_fp(stderr, "Failed to open input file");
        EVP_CIPHER_CTX_free(ctx);
        free(aes_key);
        return -4; // File not found or permission denied
    }

    FILE* output_file = fopen(output_file_path, "wb");
    if (!output_file) {
        ERR_error_fp(stderr, "Failed to open output file");
        fclose(input_file);
        EVP_CIPHER_CTX_free(ctx);
        free(aes_key);
        return -5; // File not found or permission denied
    }

    unsigned char buffer[AES_BLOCK_SIZE];
    while (fread(buffer, 1, AES_BLOCK_SIZE, input_file) == AES_BLOCK_SIZE) {
        int out_len = 0;
        if (mode == 0) { // Encryption
            AES_encrypt(aes_key, ctx, buffer, AES_BLOCK_SIZE, buffer, &out_len);
        } else { // Decryption
            AES_decrypt(aes_key, ctx, buffer, AES_BLOCK_SIZE, buffer, &out_len);
        }
        fwrite(buffer, 1, out_len, output_file);
    }

    fclose(input_file);
    fclose(output_file);

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    free(aes_key);

    return 0; // Success
}
