#define MAX_PDU 100000
#define BUFFER_SIZE 1024
#define RANDOM_SEED 42

typedef struct {
    uint16_t dst_addr;
    uint16_t src_addr;
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    char data[BUFFER_SIZE];
} MAC_PDU;

pthread_mutex_t pdus_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *state_file = NULL;

int pdus_count = 0;
MAC_PDU *pdus[MAX_PDU];

void init_pdu(MAC_PDU *pdu) {
    pthread_mutex_lock(&pdus_lock);
    pdu->header.dst_addr = (uint16_t)(rand() % 65535);
    pdu->header.src_addr = (uint16_t)(rand() % 65535);
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        pdu->data[i] = (char)(rand() % 256);
    }
    pthread_mutex_unlock(&pdus_lock);
}

void add_pdu(MAC_PDU *pdu) {
    pthread_mutex_lock(&pdus_lock);
    pdus[pdus_count++] = pdu;
    pthread_mutex_unlock(&pdus_lock);
}

void save_state(void) {
    pthread_mutex_lock(&pdus_lock);
    state_file = fopen("state.bin", "wb");
    if (state_file != NULL) {
        for (int i = 0; i < pdus_count; ++i) {
            fwrite(&pdus[i]->header, sizeof(MAC_HEADER), 1, state_file);
            fwrite(pdus[i]->data, BUFFER_SIZE, 1, state_file);
        }
    }
    pthread_mutex_unlock(&pdus_lock);
}

void* thread_function(void* arg) {
    // Simulate transmission
    for (int i = 0; i < pdus_count; ++i) {
        add_pdu(pdus[i]);
        // Simulate transmission delay
        usleep(rand() % 10000 + 1);
    }
    return NULL;
}

int main(void) {
    srand(RANDOM_SEED);

    pthread_t threads[MAX_PDU];
    for (int i = 0; i < MAX_PDU; ++i) {
        pdus[i] = malloc(sizeof(MAC_PDU));
        init_pdu(pdus[i]);
    }

    // Create and start threads
    for (int i = 0; i < MAX_PDU; ++i) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }
    for (int i = 0; i < MAX_PDU; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Save state
    save_state();

    return 0;
}
