#include <pthread.h>

typedef struct {
    int CONNECTION_ID;
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int STATUS;
    int CRC_INDICATION_REL8_TAG;
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD* head;
    pthread_mutex_t lock;
} TCP_CONNECTION_LIST;

TCP_CONNECTION_LIST* tcp_connection_list_init() {
    TCP_CONNECTION_LIST* list = (TCP_CONNECTION_LIST*)malloc(sizeof(TCP_CONNECTION_LIST));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void tcp_connection_list_insert(TCP_CONNECTION_LIST* list, TCP_CONNECTION_RECORD* record) {
    pthread_mutex_lock(&list->lock);
    record->CRCFLAG = rand();
    record->next = list->head;
    list->head = record;
    pthread_mutex_unlock(&list->lock);
}

TCP_CONNECTION_RECORD* tcp_connection_list_remove(TCP_CONNECTION_LIST* list, int CONNECTION_ID) {
    TCP_CONNECTION_RECORD* current = list->head;
    TCP_CONNECTION_RECORD* previous = NULL;
    pthread_mutex_lock(&list->lock);
    while (current && current->CONNECTION_ID != CONNECTION_ID) {
        previous = current;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    if (previous)
        previous->next = current->next;
    else
        list->head = current->next;
    free(current);
    pthread_mutex_unlock(&list->lock);
    return current;
}

void tcp_connection_list_free(TCP_CONNECTION_LIST* list) {
    TCP_CONNECTION_RECORD* current = list->head;
    TCP_CONNECTION_RECORD* next = NULL;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void tcp_connection_list_garbage_collect(TCP_CONNECTION_LIST* list, int min_idle_time) {
    TCP_CONNECTION_RECORD* current = list->head;
    TCP_CONNECTION_RECORD* previous = NULL;
    while (current) {
        if (current->STATUS == 0 && time(NULL) - current->LAST_ACTIVITY > min_idle_time) {
            pthread_mutex_lock(&list->lock);
            previous = current;
            current = current->next;
            free(previous);
            pthread_mutex_unlock(&list->lock);
        } else {
            previous = current;
            current = current->next;
        }
    }
}
