typedef struct {
    int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_array(int n, int seed) {
    void *ptr = NULL;
    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;
    if (posix_memalign(&ptr, 16, size) != 0) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize CRCFLAG
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = ptr + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pdu->RNTI = rand_r(&seed) % 100;
        pdu->CRC_INDICATION_REL8_TAG = (uint32_t)rand_r(&seed);
    }

    return ptr;
}

int validate_array(void* ptr, int n) {
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = ptr + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (pdu->RNTI < 0 || pdu->CRC_INDICATION_REL8_TAG > 1000000) {
            printf("Corrupted data detected at index %d\n", i);
            return -1;
        }
    }

    return 0;
}

void deallocate_array(void* ptr, int n) {
    free(ptr);
}

int main() {
    // Simulate network partitioning
    srand(time(NULL));
    int n = 10000; // initial allocation size

    void *ptr = allocate_array(n, time(NULL));

    for (int i = 0; i < 10; i++) { // simulate network partitions
        int new_n = n + (rand() % 100);
        void *new_ptr = allocate_array(new_n, rand());
        if (new_ptr != ptr) {
            printf("Network partition detected at index %d\n", i);
            deallocate_array(ptr, n);
            ptr = new_ptr;
            n = new_n;
        }
    }

    // Validate array periodically
    for (int i = 0; i < 100; i++) {
        int result = validate_array(ptr, n);
        if (result == -1) {
            printf("Corrupted data detected\n");
            break;
        }
    }

    deallocate_array(ptr, n);

    return 0;
}
