    char ip_address[16];
    char subnet_mask[16];
} NIC_CONFIG_T;

// Define a structure for NIC instance
typedef struct {
    int id;
    NIC_CONFIG_T config;
    pthread_mutex_t lock; // For thread safety
} NIC_INSTANCE_T;

// Array to hold 16 instances of NIC configuration
NIC_INSTANCE_T nic_instances[16];

void initialize_network_interfaces() {
    // Initialize instances with valid default values
    for (int i = 0; i < 16; i++) {
        strcpy(nic_instances[i].config.mac_address, "00:11:22:33:44:55");
        strcpy(nic_instances[i].config.ip_address, "192.168.1.");
        strcat(nic_instances[i].config.ip_address, itoa(i));
        strcpy(nic_instances[i].config.subnet_mask, "255.255.255.0");
    }

    // Initialize mutex for each instance
    for (int i = 0; i < 16; i++) {
        pthread_mutex_init(&nic_instances[i].lock, NULL);
    }
}

// Function to update NIC configuration
void update_nic_config(int id, char* mac_address, char* ip_address, char* subnet_mask) {
    // Lock the instance to prevent concurrent updates
    pthread_mutex_lock(&nic_instances[id].lock);

    // Update the NIC configuration
    strcpy(nic_instances[id].config.mac_address, mac_address);
    strcpy(nic_instances[id].config.ip_address, ip_address);
    strcpy(nic_instances[id].config.subnet_mask, subnet_mask);

    // Unlock the instance to allow other updates
    pthread_mutex_unlock(&nic_instances[id].lock);
}

// Function to log configuration changes and errors
void log_config_change(int id, const char* message) {
    // Log the change or error using a centralized logging service
    printf("NIC %d: %s\n", id, message);
}
