    int len = strlen((char *)plaintext);
    AES_KEY aes_key;
    AES_set_encrypt_key("secretkey", 13, &aes_key);
    AES_cbc_encrypt(plaintext, ciphertext, len, &aes_key, AES_ENCRYPT);

    // Camellia encryption and decryption
    unsigned char camellia_plaintext[] = "Hello, World!";
    unsigned char camellia_ciphertext[16];
    int camellia_len = strlen((char *)camellia_plaintext);
    CAMELLIA_KEY camellia_key;
    CAMELLIA_set_encrypt_key("secretkey", 13, &camellia_key);
    CAMELLIA_cbc_encrypt(camellia_plaintext, camellia_ciphertext, camellia_len, &camellia_key, CAMELLIA_ENCRYPT);

    // MD5 and SHA-256 hashing
    unsigned char message[] = "Hello, World!";
    unsigned char md5_digest[16];
    unsigned char sha256_digest[32];
    MD5_CTX md5_ctx;
    SHA256_CTX sha256_ctx;
    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, message, strlen((char *)message));
    MD5_Final(md5_digest, &md5_ctx);

    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, message, strlen((char *)message));
    SHA256_Final(sha256_digest, &sha256_ctx);

    // RSA encryption and decryption
    unsigned char rsa_plaintext[] = "Hello, World!";
    unsigned char rsa_ciphertext[128];
    int rsa_len = strlen((char *)rsa_plaintext);
    RSA *rsa_key;
    BIGNUM *rsa_e;
    BIGNUM *rsa_n;
    rsa_key = RSA_new();
    rsa_e = BN_new();
    rsa_n = BN_new();

    // Initialize and load the RSA key
    BN_set_word(rsa_e, 65537);
    BN_set_word(rsa_n, 0x10001);
    RSA_generate_key_ex(rsa_key, 1024, rsa_e, rsa_n, NULL);

    // Encrypt using RSA
    unsigned char *rsa_plaintext_p = (unsigned char *)rsa_plaintext;
    int rsa_ciphertext_len = 128;
    rsa_ciphertext = malloc(rsa_ciphertext_len);
    int rsa_ciphertext_len_alloc = 0;

    while (rsa_ciphertext_len <= 127) {
        for (int i = 0; i < rsa_len; i++) {
            rsa_ciphertext[rsa_ciphertext_len_alloc++] = rsa_plaintext[i];
        }
        rsa_ciphertext_len += rsa_len;
    }

    RSA_public_encrypt(rsa_ciphertext_len, rsa_ciphertext, rsa_key, 0);

    // Free memory
    free(rsa_ciphertext);
    BN_free(rsa_e);
    BN_free(rsa_n);
    RSA_free(rsa_key);
}
