#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_FRAME_SIZE 1024
#define MAX_LOGGED_FRAMES 1000

typedef struct {
    RX_FRAME_INFO info;
    PHY_RX_FRAME_PDU payload;
    PHY_RX_CHANNEL_STATE state;
} LTE_PHY_RX_FRAME_PDU;

typedef struct {
    int size;
    LTE_PHY_RX_FRAME_PDU* frames;
    pthread_mutex_t mutex;
    FILE* log_file;
} DynamicFrameList;

void initialize_frame_list(DynamicFrameList* frame_list) {
    frame_list->size = 0;
    frame_list->frames = NULL;
    pthread_mutex_init(&frame_list->mutex, NULL);
    frame_list->log_file = fopen("frame_processing.log", "a");
}

int frame_list_insert(DynamicFrameList* frame_list, LTE_PHY_RX_FRAME_PDU frame) {
    if (frame_list->size == MAX_LOGGED_FRAMES) {
        // Handle overflow
        return -1;
    }

    pthread_mutex_lock(&frame_list->mutex);
    frame_list->frames = realloc(frame_list->frames, (frame_list->size + 1) * sizeof(LTE_PHY_RX_FRAME_PDU));
    frame_list->frames[frame_list->size] = frame;
    frame_list->size++;
    pthread_mutex_unlock(&frame_list->mutex);

    // Log the insertion
    fprintf(frame_list->log_file, "Frame inserted: size=%d\n", frame_list->size);
    fflush(frame_list->log_file);

    return 0;
}

int frame_list_remove(DynamicFrameList* frame_list) {
    if (frame_list->size == 0) {
        // Handle underflow
        return -1;
    }

    pthread_mutex_lock(&frame_list->mutex);
    frame_list->frames = realloc(frame_list->frames, --frame_list->size * sizeof(LTE_PHY_RX_FRAME_PDU));
    pthread_mutex_unlock(&frame_list->mutex);

    // Log the removal
    fprintf(frame_list->log_file, "Frame removed: size=%d\n", frame_list->size);
    fflush(frame_list->log_file);

    return 0;
}

void finalize_frame_list(DynamicFrameList* frame_list) {
    pthread_mutex_unlock(&frame_list->mutex);
    fclose(frame_list->log_file);
}
