NFAPI_UL_CCCH_INDICATION_PDU **nfaPiUlCcchIndicationPduArray = NULL;
size_t nfaPiUlCcchIndicationPduArraySize = 0;
size_t nfaPiUlCcchIndicationPduArrayCapacity = 0;

// Thread-safe locking mechanism
pthread_mutex_t nfaPiUlCcchIndicationPduMutex = PTHREAD_MUTEX_INITIALIZER;

void initNfaPiUlCcchIndicationPduArray(size_t initialCapacity) {
    pthread_mutex_lock(&nfaPiUlCcchIndicationPduMutex);

    if (nfaPiUlCcchIndicationPduArray != NULL) {
        pthread_mutex_unlock(&nfaPiUlCcchIndicationPduMutex);
        return;
    }

    nfaPiUlCcchIndicationPduArray = (NFAPI_UL_CCCH_INDICATION_PDU **)malloc(initialCapacity * sizeof(NFAPI_UL_CCCH_INDICATION_PDU *));
    nfaPiUlCcchIndicationPduArraySize = 0;
    nfaPiUlCcchIndicationPduArrayCapacity = initialCapacity;

    pthread_mutex_unlock(&nfaPiUlCcchIndicationPduMutex);
}

void* reallocNfaPiUlCcchIndicationPduArray(size_t newSize) {
    void *newArray = NULL;

    pthread_mutex_lock(&nfaPiUlCcchIndicationPduMutex);

    if (newSize > nfaPiUlCcchIndicationPduArrayCapacity) {
        newArray = realloc(nfaPiUlCcchIndicationPduArray, newSize * sizeof(NFAPI_UL_CCCH_INDICATION_PDU *));

        if (newArray == NULL) {
            pthread_mutex_unlock(&nfaPiUlCcchIndicationPduMutex);
            return NULL;
        }
    } else {
        newArray = nfaPiUlCcchIndicationPduArray;
    }

    free(nfaPiUlCcchIndicationPduArray);
    nfaPiUlCcchIndicationPduArray = (NFAPI_UL_CCCH_INDICATION_PDU **)newArray;
    nfaPiUlCcchIndicationPduArraySize = newSize;
    nfaPiUlCcchIndicationPduArrayCapacity = newSize;

    pthread_mutex_unlock(&nfaPiUlCcchIndicationPduMutex);

    return newArray;
}

void pruneUnusedElements() {
    size_t i = 0;

    pthread_mutex_lock(&nfaPiUlCcchIndicationPduMutex);

    for (i = 0; i < nfaPiUlCcchIndicationPduArraySize; i++) {
        if ((rand() % 2) == 1) { // Randomly set CRCFLAG to 1
            NFAPI_UL_CCCH_INDICATION_PDU *pdu = nfaPiUlCcchIndicationPduArray[i];

            pdu->CRCFLAG = (pdu->RX_UE_INFORMATION_TAG + pdu->RNTI + pdu->CRC_INDICATION_REL8_TAG) % 2;
        }
    }

    size_t newSize = 0;

    for (i = 0; i < nfaPiUlCcchIndicationPduArraySize; i++) {
        if (nfaPiUlCcchIndicationPduArray[i]->CRCFLAG == 1) { // Only keep elements with CRCFLAG set to 1
            newSize++;
        } else {
            free(nfaPiUlCcchIndicationPduArray[i]);
        }
    }

    nfaPiUlCcchIndicationPduArray = reallocNfaPiUlCcchIndicationPduArray(newSize);
    nfaPiUlCcchIndicationPduArraySize = newSize;

    pthread_mutex_unlock(&nfaPiUlCcchIndicationPduMutex);
}

int main() {
    initNfaPiUlCcchIndicationPduArray(16);

    pruneUnusedElements();

    return 0;
}
