        }

        for (int j = 0; j < payload_len; j++) {
            ((char *)messages[i].payload)[j] = rand() % 256;
        }

        messages[i].flag = rand() % 2;
    }

    return messages;
}

void free_messages(Message *messages, int num_messages) {
