        for (int j = 0; j < 1024; j++) {
            ((char *)packets[i]->payload)[j] = (char)rand();
        }
        packets[i]->timestamp = time(NULL);
    }
    return packets;
}

// Function to handle concurrent access and processing of packets
void *process_packets(void *arg) {
    Packet **packets = (Packet **)arg;
    // Process each packet concurrently
    for (int i = 0; i < num_packets; i++) {
        // Perform any necessary operations on the packet, such as parsing or filtering
        printf("Processing packet %d: Source IP - %s, Destination IP - %s, Port - %d, Timestamp - %ld\n", i, packets[i]->src_ip, packets[i]->dst_ip, packets[i]->port, packets[i]->timestamp);
    }
    return NULL;
}

int main() {
    int num_packets = 100; // adjust the number of packets as needed
    Packet **packets = init_packets(num_packets);

    pthread_t threads[num_packets];
    for (int i = 0; i < num_packets; i++) {
        pthread_create(&threads[i], NULL, process_packets, (void *)packets);
    }

    for (int i = 0; i < num_packets; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (int i = 0; i < num_packets; i++) {
        free(packets[i]->payload);
        free(packets[i]);
    }
    free(packets);

    return 0;
}
