// Define the dynamic array of TransactionLogEntries
TransactionLogEntry **log_entries = NULL;

// Initialize the log entries array
void init_log_entries(int size) {
    log_entries = (TransactionLogEntry **)malloc(size * sizeof(TransactionLogEntry *));
    for (int i = 0; i < size; i++) {
        log_entries[i] = (TransactionLogEntry *)malloc(sizeof(TransactionLogEntry));
    }
}

// Insert a new TransactionLogEntry
void insert_log_entry(int transaction_id, time_t timestamp, double transaction_amount, char *transaction_description) {
    // Find the next available slot in the array
    int i = 0;
    while (log_entries[i] != NULL) {
        i++;
    }

    // Add the new log entry to the array
    log_entries[i] = (TransactionLogEntry *)malloc(sizeof(TransactionLogEntry));
    log_entries[i]->transaction_id = transaction_id;
    log_entries[i]->timestamp = timestamp;
    log_entries[i]->transaction_amount = transaction_amount;
    log_entries[i]->transaction_description = transaction_description;

    // Update the array size
    int new_size = i + 1;
    TransactionLogEntry **new_log_entries = (TransactionLogEntry **)malloc(new_size * sizeof(TransactionLogEntry *));
    for (int j = 0; j < i; j++) {
        new_log_entries[j] = log_entries[j];
    }
    free(log_entries);
    log_entries = new_log_entries;
}

// Delete a TransactionLogEntry
void delete_log_entry(int transaction_id) {
    // Find the log entry with the matching transaction ID
    int i = 0;
    while (log_entries[i]->transaction_id != transaction_id) {
        i++;
    }

    // Remove the log entry from the array and free its memory
    TransactionLogEntry *entry = log_entries[i];
    for (int j = i; j < size - 1; j++) {
        log_entries[j] = log_entries[j + 1];
    }
    free(entry);
}

// Retrieve a TransactionLogEntry by transaction ID
TransactionLogEntry *get_log_entry(int transaction_id) {
    // Find the log entry with the matching transaction ID
    int i = 0;
    while (log_entries[i]->transaction_id != transaction_id) {
        i++;
    }

    return log_entries[i];
}

// Create and populate a list of NFAPI_RX_PDU_T structures
void create_nfapi_rx_pdu_t_list(int size, NFAPIT *nfapi_rx_pdu_ts) {
    for (int i = 0; i < size; i++) {
        nfapi_rx_pdu_ts[i].ue_context_tag = rand();
        nfapi_rx_pdu_ts[i].rnti = rand();
        nfapi_rx_pdu_ts[i].dl_frame_tag.crcflag = rand();
    }
}

// Process a large integer array using Union-Find
int process_array(int *array, int size) {
    // Initialize the parent array
    int *parent = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        parent[i] = i;
    }

    // Find and count disjoint sets
    int count = 0;
    for (int i = 0; i < size; i++) {
        int root = find(parent, array[i]);
        if (root == -1) {
            count++;
        }
    }

    free(parent);
    return count;
}

// Find the root of a node in the Union-Find forest
int find(int *parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}
