struct LinkedListNode {
    NFAPI_CRC_INDATION_PDU_T data;
    struct LinkedListNode* next;
};

NFAPI_CRC_INDICATION_PDU_T* createLinkedListNode() {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    return node;
}

void addNodeToList(struct LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T* newNode) {
    if(*head == NULL || (*head)->data.crcflag < newNode->data.crcflag) {
        newNode->next = *head;
        *head = newNode;
    } else {
        struct LinkedListNode* current = *head;
        while(current->next && current->next->data.crcflag >= newNode->data.crcflag) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

void serializeLinkedList(struct LinkedListNode* head, FILE* file) {
