        fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        head = head->next;
    }
}

struct LinkedListNode* deserializeLinkedList(FILE* file) {
    struct LinkedListNode* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T temp;
    while(fread(&temp, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        struct LinkedListNode* newNode = createLinkedListNode();
        if(newNode == NULL) {
            return NULL; // Handle memory allocation failure
        }
        newNode->data = temp;
        addNodeToList(&head, &newNode->data);
    }
    return head;
}

void freeLinkedList(struct LinkedListNode* head) {
    struct LinkedListNode* current = head;
    while(current) {
        struct LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
}
