        if (!queue.includes(fieldId)) {
            queue.push(fieldId);
        }
    }

    function dequeueRefresh() {
        return queue.shift();
    }

    function isFieldBeingRefreshed(fieldId) {
        // Implement caching mechanism to track refresh states
        // For demonstration purposes, assume a simple in-memory cache
        const cachedRefreshStates = {};
        return !!cachedRefreshStates[fieldId];
    }

    function handleNetworkError(error) {
        setTimeout(() => {
            // Retry failed refresh attempts after a short delay
            refreshDialogFields(resourceId, url);
        }, retryDelay);
    }

    function logRefreshAttempt(fieldId, success) {
        fetch(`${loggingServiceUrl}/refresh-attempt`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ fieldId, resourceId, success }),
