public class DisjointPairCounter {
    public static int countDisjointPairs(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);

        for (int num : arr) {
            int root = uf.find(num);
            uf.union(root, num);
        }

        int disjointCount = 0;
        for (int i = 0; i < arr.length; i++) {
            if (!uf.isSameSet(i, arr[i])) {
                disjointCount++;
            }
        }

        return disjointCount / 2;
    }
}

class UnionFind {
    private int[] parent;
    private int[] size;

    public UnionFind(int n) {
        parent = new int[n];
        size = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }

    public boolean isSameSet(int x, int y) {
        return find(x) == find(y);
    }
}
