#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int state;
    int next_state;
} Transition;

// Define a node in the linked list of states
typedef struct {
    int state;
    struct State* next;
    int ref_count;
} State;

// Function to dynamically manage a linked list of states
State* manage_states(int* initial_states, int num_initial_states, Transition* fsa, int last_state) {
    // Initialize the first node with the initial states
    State* head = (State*)malloc(sizeof(State));
    if (!head) return NULL;  // Handle memory allocation error

    head->state = initial_states[0];
    head->next = NULL;
    head->ref_count = 1;

    State* current = head;
    for (int i = 1; i < num_initial_states; i++) {
        State* new_node = (State*)malloc(sizeof(State));
        if (!new_node) return NULL;  // Handle memory allocation error

        new_node->state = initial_states[i];
        new_node->next = NULL;
        new_node->ref_count = 1;

        current->next = new_node;
        current = new_node;
    }

    // Process the FSA transitions
    for (int i = 0; i < last_state; i++) {
        if (fsa[i].state == head->state) {
            head->next->state = fsa[i].next_state;
            head->next->ref_count++;
        }
    }

    // Update the reference count of the last state
    head->next->ref_count++;

    return head;
}

// Function to deallocate memory for a linked list of states
void free_states(State* head) {
    State* current = head;
    while (current) {
        State* next = current->next;
        if (--current->ref_count == 0) {
            free(current);
            current = next;
        } else {
            current = next;
        }
    }
}

int main() {
    // Example usage:
    int initial_states[] = {1, 2};
    int num_initial_states = sizeof(initial_states) / sizeof(initial_states[0]);
    Transition fsa[] = {{1, 2}, {2, 3}};
    int last_state = sizeof(fsa) / sizeof(fsa[0]);

    State* states = manage_states(initial_states, num_initial_states, fsa, last_state);
    if (states) {
        // Process the linked list of states...
        free_states(states);
    }

    return 0;
}

