typedef struct {
    uint8_t RX_FRAME_TAG;
    uint16_t RX_FRAME_TYPE;
    void* RX_FRAME_DATA; // payload length determined by a random size within a given range
} NFAPI_RX_FRAME_PDU_T;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate memory for an array of NFAPI_RX_FRAME_PDU_T structures
NFAPI_RX_FRAME_PDU_T** allocate_rx_frame_pdu(int N, int max_size) {
    if (N <= 0 || max_size < sizeof(NFAPI_RX_FRAME_PDU_T)) {
        return NULL; // handle edge cases where the user might input invalid or extremely large numbers for the list size
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_RX_FRAME_PDU_T** rx_frame_pdu = (NFAPI_RX_FRAME_PDU_T**)malloc(N * sizeof(NFAPI_RX_FRAME_PDU_T*));
    if (!rx_frame_pdu) {
        return NULL; // handle allocation failures
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        rx_frame_pdu[i] = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!rx_frame_pdu[i]) {
            // handle allocation failures
            free(rx_frame_pdu);
            return NULL;
        }
        pthread_mutex_unlock(&lock);

        // initialize the structures with default values before validation
