struct dynamic_list {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t max_size;
    pthread_mutex_t mutex;
};

void dynamic_list_init(struct dynamic_list* list, size_t initial_max_size) {
    list->size = 0;
    list->max_size = initial_max_size;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
}

void dynamic_list_insert(struct dynamic_list* list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->max_size) {
        // Reallocate memory for growth
        size_t new_max_size = list->max_size * 2;
        list->elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->max_size = new_max_size;
    }
    // Check for uniqueness based on RX_UE_INFORMATION_TAG and RNTI
    int found = 0;
    for (size_t i = 0; i < list->size; ++i) {
