             memcmp(list->elements[i].RNTI, new_element.RNTI, sizeof(new_element.RNTI))) == 0) {
            found = 1;
            break;
        }
    }
    if (!found) {
        list->elements[list->size++] = new_element;
    }
    pthread_mutex_unlock(&list->mutex);
}

