pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTURES];
int current_allocations = 0;

void* allocate_structure() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (!structures[i]) {
            NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
            structures[i] = new_struct;
            current_allocations++;
            pthread_mutex_unlock(&lock);
            return (void*)new_struct;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int validate_structure(void* structure) {
    if (!structure) {
        return -1; // invalid pointer
    }

    NFAPI_CRC_INDICATION_PDU_T* struct_ptr = structure;
    if (struct_ptr->RX_UE_INFORMATION_TAG < 0 || 
       struct_ptr->RNTI < 0 || 
       struct_ptr->CRC_INDICATION_REL8_TAG < 0) {
        return -2; // invalid values
    }
    return 1; // valid structure
}

void deallocate_structure(void* structure) {
    if (!structure) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* struct_ptr = structure;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (&structures[i] == &struct_ptr) {
            free(struct_ptr);
            structures[i] = NULL;
            current_allocations--;
            return;
        }
    }
}

void log_allocation(void* structure, int status) {
    pthread_mutex_lock(&lock);
    if (status == 1) {
        printf(LOG_FORMAT "success\n");
    } else {
        printf(LOG_FORMAT "failure\n");
    }
    pthread_mutex_unlock(&lock);
}
