        indications[i].RNTI = rand() % 1024;

        // Set CRC_INDICATION_REL8_TAG
        indications[i].CRC_INDICATION_REL8_TAG = i % 128;

        // Randomly set CRCFLAG
        indications[i].CRCFLAG = rand() % 2 ? 1 : 0;
    }

    // Process data in batches
    for (int i = 0; i < numInstances; i += batchSize) {
        int batchSizeRemaining = batchSize;

        if (i + batchSize > numInstances) {
            batchSizeRemaining = numInstances - i;
        }

        // Handle batch processing and potential memory allocation failures
        NFAPI_CRC_INDICATION_PDU_T* batch = &indications[i];
        for (int j = 0; j < batchSizeRemaining; j++) {
            if (!batch[j].RX_UE_INFORMATION_TAG || !batch[j].RNTI || !batch[j].CRC_INDICATION_REL8_TAG) {
                printf("Error: Invalid data in batch.\n");
                return;
            }
        }
    }

    // Handle potential memory deallocation failures
    free(indications);
}
