struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

NFAPI_CRC_INDICATION_PDU_T* create_node() {
    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int populate_list(struct node** head, int N) {
    *head = NULL;
    for (int i = 0; i < N; i++) {
        struct node* new_node = create_node();
        pthread_mutex_lock(&mutex);
        while (true) {
            new_node->data.rnti = rand() % 1000000; // Generate random RNTI
            if (!find_duplicate(new_node->data.rnti, *head)) break;
            if (i < 99) continue; // Try generating a new RNTI up to 100 times
            else {
                printf("Failed to generate unique RNTI\n");
                return -1;
            }
        }
        pthread_mutex_unlock(&mutex);
        new_node->data.ue_info = ...; // Initialize UE information tag
        new_node->data.crc_tag = ...; // Initialize CRC indication tag
        new_node->data.crcflag = rand() % 2; // Set random CRC flag
        if (*head == NULL || compare_rnti(new_node->data.rnti, (*head)->data.rnti) > 0)
            *head = new_node;
        else {
            struct node* current = *head;
            while (current->next && compare_rnti(new_node->data.rnti, current->next->data.rnti) > 0)
                current = current->next;
            new_node->next = current->next;
            current->next = new_node;
        }
    }
}

int find_duplicate(int rnti, struct node* head) {
    while (head != NULL && head->data.rnti != rnti)
        head = head->next;
    return head != NULL;
}

int compare_rnti(int a, int b) {
    if (a < b) return -1;
    else if (a > b) return 1;
    else return 0;
}
