// Thread-safe dynamic list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T* nfaapi_crc_indication_list_create(int initial_capacity) {
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->entries = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void nfaapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T* list) {
    free(list->entries);
    free(list);
}

int nfaapi_crc_indication_list_add_entry(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->entries = realloc(list->entries, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    list->entries[list->size++] = entry;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int nfaapi_crc_indication_list_update_entry(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI == RNTI) {
            list->entries[i] = new_entry;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int nfaapi_crc_indication_list_remove_entry(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI == RNTI) {
            memmove(list->entries + i, list->entries + i + 1, (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

// Serialize NFAPI_CRC_INDICATION_LIST_T to binary file
void nfaapi_crc_indication_list_serialize(NFAPI_CRC_INDICATION_LIST_T* list, FILE* file) {
    fwrite(&list->size, sizeof(int), 1, file);
    for (int i = 0; i < list->size; i++) {
        fwrite(&list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

// Deserialize NFAPI_CRC_INDICATION_LIST_T from binary file
NFAPI_CRC_INDICATION_LIST_T* nfaapi_crc_indication_list_deserialize(FILE* file) {
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    fread(&list->size, sizeof(int), 1, file);
    list->entries = malloc(list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < list->size; i++) {
        fread(&list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    return list;
}

