void init_nfa_pi_crc_list() {
    nfa_pi_crc_list.list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1000);
    nfa_pi_crc_list.size = 0;
    nfa_pi_crc_list.capacity = 1000;
    pthread_mutex_init(&nfa_pi_crc_list.lock, NULL);
}

void add_nfa_pi_crc_entry(int rnti, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    if (nfa_pi_crc_list.size >= nfa_pi_crc_list.capacity) {
        // reallocate memory when the list is full
        nfa_pi_crc_list.list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfa_pi_crc_list.list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfa_pi_crc_list.capacity + 1000));
        nfa_pi_crc_list.capacity += 1000;
    }
    // insert the entry at the end of the list
    nfa_pi_crc_list.list[nfa_pi_crc_list.size] = *entry;
    nfa_pi_crc_list.size++;
    pthread_mutex_unlock(&nfa_pi_crc_list.lock);
}

void update_nfa_pi_crc_entry(int rnti, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    for (int i = 0; i < nfa_pi_crc_list.size; i++) {
        if (nfa_pi_crc_list.list[i].rnti == rnti) {
            // update the entry
            memcpy(&nfa_pi_crc_list.list[i], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
    }
    pthread_mutex_unlock(&nfa_pi_crc_list.lock);
}

void remove_nfa_pi_crc_entry(int rnti) {
    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    for (int i = 0; i < nfa_pi_crc_list.size; i++) {
        if (nfa_pi_crc_list.list[i].rnti == rnti) {
            // remove the entry
            memmove(&nfa_pi_crc_list.list[i], &nfa_pi_crc_list.list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfa_pi_crc_list.size - i - 1));
            nfa_pi_crc_list.size--;
            break;
        }
    }
    pthread_mutex_unlock(&nfa_pi_crc_list.lock);
}

void serialize_nfa_pi_crc_list(char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return;
    }
    fwrite(&nfa_pi_crc_list.size, sizeof(int), 1, file);
    for (int i = 0; i < nfa_pi_crc_list.size; i++) {
        fwrite(&nfa_pi_crc_list.list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void deserialize_nfa_pi_crc_list(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return;
    }
    fread(&nfa_pi_crc_list.size, sizeof(int), 1, file);
    nfa_pi_crc_list.list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * nfa_pi_crc_list.size);
    for (int i = 0; i < nfa_pi_crc_list.size; i++) {
        fread(&nfa_pi_crc_list.list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void verify_deserialized_data() {
    // verify the integrity of the deserialized data
    for (int i = 0; i < nfa_pi_crc_list.size; i++) {
        if (!validate_crc(nfa_pi_crc_list.list[i].crc_indication_rel8)) {
