        // process the entries in the batch
        process_entry(nfa_pi_crc_list.list[i].rx_ue_info, nfa_pi_crc_list.list[i].rnti, nfa_pi_crc_list.list[i].crc_indication_rel8);
    }
}

void cache_entries(int cache_size) {
    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    for (int i = 0; i < cache_size; i++) {
        // add the entries to the cache
        cache.add(nfa_pi_crc_list.list[i].rx_ue_info, nfa_pi_crc_list.list[i].rnti);
    }
    pthread_mutex_unlock(&nfa_pi_crc_list.lock);
}

void purge_cache_entries(int age_threshold) {
    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    for (int i = cache.size - 1; i >= 0; i--) {
        if (cache.get(i).age > age_threshold) {
            // remove the entry from the cache
            cache.remove(i);
        }
    }
    pthread_mutex_unlock(&nfa_pi_crc_list.lock);
}

void track_crc_error_rate() {
    int total_crc_errors = 0;
