        if ((*list)[i]->TEID == teid) {
            GTPv2_C_PDU **new_list = (GTPv2_C_PDU**)malloc((*size - 1) * sizeof(GTPv2_C_PDU*));
            int j = 0;
            for (int k = 0; k < *size; k++) {
                if ((*list)[k]->TEID != teid) {
                    new_list[j] = (*list)[k];
