#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint8_t tag;
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t rel8_tag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int n, uint16_t (*checksum)(uint8_t*, int), unsigned char** buffer) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (int i = 0; i < n; i++) {
        list[i].rx_ue_info.tag = i % 256;
        list[i].rx_ue_info.rnti = i;

        CRC_INDICATION_REL8_TAG crc_ind_rel8;
        crc_ind_rel8.rel8_tag = i * (1 << 15);

        // Validate against checksum function
        if (!checksum((unsigned char*)&crc_ind_rel8, sizeof(CRC_INDICATION_REL8_TAG))) {
            free(list);
            return NULL; // CRC validation failed
        }

        list[i].timestamp = time(NULL); // Set timestamp

        // Serialize structure to buffer
        *buffer += (char*)&list[i];
    }

    for (int i = 1; i < n; i++) {
        if (list[i].rx_ue_info.rnti == list[0].rx_ue_info.rnti) {
            free(list);
            return NULL; // Duplicate RNTI detected
        }
    }

    return list;
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int n, unsigned char** buffer) {
    for (int i = 0; i < n; i++) {
        *buffer += (char*)&list[i];
    }
}
