```c
#include <pthread.h>
#include <semaphore.h>

void processNetworkTraffic(PriorityQueue* queue) {
    pthread_t thread;
    sem_t semaphore;
    pthread_create(&thread, NULL, &processEvents, queue);
    sem_init(&semaphore, 0, 1);
    while (1) {
        sem_wait(&semaphore);
        if (queue->count > 0) {
            NetworkTrafficEvent* event = &queue->events[queue->count - 1];
            // process the event
            printf("Processing event: %lld, type: %s, size: %d\n", 
                   event->timestamp, event->eventType, event->payloadSize);
        }
        sem_post(&semaphore);
    }
}

void* processEvents(void* arg) {
    PriorityQueue* queue = (PriorityQueue*)arg;
    while (1) {
        // dequeue an event and process it
        if (queue->count > 0) {
            NetworkTrafficEvent* event = &queue->events[queue->count - 1];
            printf("Processing event: %lld, type: %s, size: %d\n", 
                   event->timestamp, event->eventType, event->payloadSize);
        }
    }
}
