    ue_status_report->measurement_results[ue_status_report->num_measurement_results++] = *measurement_result;
}

// Function to remove a MeasurementResult from the list within a specific UEStatusReport
void remove_measurement_result(UEStatusReport* ue_status_report, uint32_t timestamp) {
    int i, j;

    // Find and remove the MeasurementResult with the given timestamp
    for (i = 0; i < ue_status_report->num_measurement_results; ++i) {
        if (ue_status_report->measurement_results[i].timestamp == timestamp) {
            break;
        }
    }

    // Reallocate memory to avoid gaps in the list
    measurement_results = realloc(ue_status_report->measurement_results, 
                                  (ue_status_report->num_measurement_results - 1) * sizeof(MeasurementResult));

    // Shift elements after the removed MeasurementResult
    for (j = i; j < ue_status_report->num_measurement_results - 1; ++j) {
        measurement_results[j] = measurement_results[j + 1];
    }

    ue_status_report->num_measurement_results--;
}

// Function to retrieve a MeasurementResult from the list within a specific UEStatusReport
MeasurementResult* get_measurement_result(UEStatusReport* ue_status_report, uint32_t timestamp) {
    int i;

    // Find and return the MeasurementResult with the given timestamp
    for (i = 0; i < ue_status_report->num_measurement_results; ++i) {
        if (ue_status_report->measurement_results[i].timestamp == timestamp) {
            return &ue_status_report->measurement_results[i];
        }
    }

    // Return NULL if the MeasurementResult is not found
    return NULL;
}

// Function to print UEStatusReport details
void print_ue_status_report(UEStatusReport* ue_status_report) {
    printf("UE Identifier: %s\n", ue_status_report->ue_identifier);
    printf("Number of MeasurementResults: %d\n", ue_status_report->num_measurement_results);

    for (int i = 0; i < ue_status_report->num_measurement_results; ++i) {
        printf("Timestamp: %u, Value1: %.2f, Value2: %.2f\n",
               ue_status_report->measurement_results[i].timestamp,
               ue_status_report->measurement_results[i].value1,
               ue_status_report->measurement_results[i].value2);
    }
}

int main() {
    // Create and initialize an empty UEStatusReport
    UEStatusReport ue_status_report;
    strcpy(ue_status_report.ue_identifier, "IMEI123456");
    ue_status_report.num_measurement_results = 0;

    // Add MeasurementResults to the report
    add_measurement_result(&ue_status_report, (MeasurementResult*)malloc(sizeof(MeasurementResult)));
    ue_status_report.measurement_results[0].timestamp = 1;
    ue_status_report.measurement_results[0].value1 = 2.5f;
    ue_status_report.measurement_results[0].value2 = 3.7f;

    add_measurement_result(&ue_status_report, (MeasurementResult*)malloc(sizeof(MeasurementResult)));
    ue_status_report.measurement_results[1].timestamp = 2;
    ue_status_report.measurement_results[1].value1 = 4.8f;
    ue_status_report.measurement_results[1].value2 = 6.3f;

    // Remove a MeasurementResult from the report
    remove_measurement_result(&ue_status_report, 1);

    // Retrieve and print a MeasurementResult
    MeasurementResult* retrieved_measurement_result = get_measurement_result(&ue_status_report, 2);
    if (retrieved_measurement_result) {
        printf("Retrieved MeasurementResult: Timestamp: %u, Value1: %.2f, Value2: %.2f\n",
               retrieved_measurement_result->timestamp,
               retrieved_measurement_result->value1,
               retrieved_measurement_result->value2);
    } else {
        printf("MeasurementResult not found!\n");
    }

    // Print UEStatusReport details
    print_ue_status_report(&ue_status_report);

    return 0;
}

