    *list = NULL;
    *size = 0;
}

bool isRntiUnique(NFAPI_CRC_INDICATION_PDU_T** list, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            if (*((list)[i]->rnti) == *((list)[j]->rnti)) return false;
        }
