}

void nfaPI_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_T** list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (*list == NULL) {
        *list = (NFAPI_CRC_INDICATION_PDU_T*)nfaPI_crc_indication_pdu_list_allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*list)[0] = *pdu;
        ++(*size);
    } else {
        NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)nfaPI_crc_indication_pdu_list_allocate((size_t)size + 2);
        new_list[0] = *list;
        new_list[1] = pdu;
        for (size_t i = 0; i < size; ++i) {
            new_list[i + 2] = (*list)[i];
        }
        nfaPI_crc_indication_pdu_list_free(*list);
        *list = new_list;
        ++(*size);
    }
}

void nfaPI_crc_indication_pdu_list_remove_consecutive_duplicates(NFAPI_CRC_INDICATION_PDU_T** list, size_t* size) {
    if (*size < 2) return;

    for (size_t i = 0; i < *size - 1; ++i) {
        if (*((list)[i]->rnti) == *((list)[i + 1]->rnti)) {
            NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)nfaPI_crc_indication_pdu_list_allocate((size_t)size - 1);
            for (size_t j = 0; j < i; ++j) {
                new_list[j] = (*list)[j];
            }
            if (i < *size - 1) {
                for (size_t j = i + 1; j < *size; ++j) {
                    new_list[j - 1] = (*list)[j];
                }
            }
            nfaPI_crc_indication_pdu_list_free(*list);
            *list = new_list;
            --*size;
            i -= 1;
        }
    }
}

void nfaPI_crc_indication_pdu_list_shutdown(NFAPI_CRC_INDICATION_PDU_T** list, size_t* size) {
    if (*list != NULL) {
        for (size_t i = 0; i < *size; ++i) {
            nfaPI_crc_indication_pdu_list_free(&((*list)[i]));
        }
        free(*list);
    }
}

