typedef struct {
    uint8_t rx_ue_information_tag;
    int32_t rnti;
    float snr_info_tag;
} NFAPI_RX_INDICATION_PDU_T;

// Thread-safe list manager for handling NFAPI_RX_INDICATION_PDU_T structures
struct List {
    NFAPI_RX_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
};

List* list_init(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->elements = (NFAPI_RX_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_RX_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void list_free(List* list) {
    free(list->elements);
    free(list);
}

int list_add(List* list, NFAPI_RX_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_RX_INDICATION_PDU_T* new_elements = (NFAPI_RX_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_RX_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->capacity = new_capacity;
        list->elements = new_elements;
    }

    for (size_t i = 0; i < list->size; i++) {
        if (list->elements[i].rnti == new_element.rnti) {
            pthread_mutex_unlock(&list->lock);
            return -1; // RNTI already exists
        }
    }

    list->elements[list->size++] = new_element;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void list_remove(List* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; i++) {
        if (list->elements[i].rnti == rnti) {
            memmove(&list->elements[i], &list->elements[i + 1], sizeof(NFAPI_RX_INDICATION_PDU_T) * (list->size - i - 1));
            list->size--;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void list_foreach(List* list, void (*callback)(NFAPI_RX_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; i++) {
        callback(list->elements[i]);
    }

    pthread_mutex_unlock(&list->lock);
}
