} NFAPI_SRB_MESSAGE_T;

typedef struct node {
    NFAPI_SRB_MESSAGE_T message;
    struct node* prev;
    struct node* next;
} Node;

typedef struct list {
    Node* head;
    Node* tail;
    size_t max_size;
    size_t curr_size;
    pthread_mutex_t lock;
} List;

List* nfapi_srb_message_list_create(size_t max_memory_usage) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->max_size = max_memory_usage;
    list->curr_size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void nfapi_srb_message_list_insert(List* list, NFAPI_SRB_MESSAGE_T message) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return; // Handle memory allocation failure

    node->message = message;
    node->prev = NULL;
    node->next = list->head;

    pthread_mutex_lock(&list->lock);
    if (list->head) {
        list->head->prev = &node->next;
    } else {
        list->tail = &node->next;
    }
    list->head = node;

    list->curr_size++;

    if (list->curr_size >= list->max_size * 0.8) { // Implement dynamic resizing strategy
        Node* old_head = list->head;
        list->head = list->head->next;
        free(old_head);
        list->tail->prev = NULL; // Adjust tail pointer accordingly
    }

    pthread_mutex_unlock(&list->lock);
}

void nfapi_srb_message_list_remove(List* list, Node* node) {
    if (!node) return; // Handle invalid or null node

    if (node == list->head) {
        list->head = node->next;
    } else if (node == list->tail) {
        list->tail = node->prev;
    }

    node->prev->next = node->next;
    node->next->prev = node->prev;

    free(node);
    list->curr_size--;
}

void nfapi_srb_message_list_destroy(List* list) {
    Node* node = list->head;
    while (node) {
        Node* next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
