#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically manage a list of NFAPI_CRC_INDICATION_PDU_T structures
void* nfapi_crc_indication_pdu_list(int max_memory_budget, int* statistics) {
    // Initialize list and statistics
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;
    int list_size = 0;
    *statistics = (int*)malloc(sizeof(int) * 3);
    (*statistics)[0] = 0; // Unique RNTI values
    (*statistics)[1] = 0; // Average CRCFLAG value
    (*statistics)[2] = 0; // Total size of allocated memory

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    void* result = NULL;

    // Function to dynamically allocate and deallocate memory for the list
    int* get_memory(int size) {
        int* temp = (int*)malloc(size * sizeof(int));
        if (!temp) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        return temp;
    }

    // Function to dynamically allocate and deallocate memory for the list
    void free_memory(void* ptr, int size) {
        free(ptr);
    }

    while (1) {
        pthread_mutex_lock(&lock);

        if (list_size > 0 && list[list_size - 1]->RNTI == list[list_size - 2]->RNTI) {
            // Handle duplicate RNTI value and resize the list
            printf("Duplicate RNTI value detected. Resizing the list...\n");
            NFAPI_CRC_INDICATION_PDU_T** temp = get_memory(list_size + 1);
            for (int i = 0; i < list_size; i++) {
                temp[i] = list[i];
            }
            free_memory(list, list_size);
            list = temp;
            list_size++;
        }

        // Dynamically allocate and deallocate memory based on the size of the list
        if (list_size >= max_memory_budget) {
            printf("Memory budget exceeded. Notifying caller...\n");
            result = malloc(sizeof(int));
            *(int*)result = 1; // Additional memory allocation required
            pthread_mutex_unlock(&lock);
            return result;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_element) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        // Initialize the CRC flag randomly
        new_element->CRCFLAG = rand() % 2;
        new_element->RNTI = (rand() % 1000000); // Randomly set RNTI value

        // Check if the newly allocated element has a duplicate RNTI value
        for (int i = 0; i < list_size; i++) {
            if (new_element->RNTI == list[i]->RNTI) {
                printf("Duplicate RNTI value detected. Freeing memory...\n");
                free(new_element);
                pthread_mutex_unlock(&lock);
                return result;
            }
        }

        // Add the new element to the list and update statistics
        if (list_size < max_memory_budget) {
            NFAPI_CRC_INDICATION_PDU_T** temp = get_memory(list_size + 2);
            for (int i = 0; i < list_size; i++) {
                temp[i] = list[i];
            }
            free_memory(list, list_size);
            list = temp;
            list_size++;
        }

        (*statistics)[0]++;
        (*statistics)[1] += new_element->CRCFLAG;
        (*statistics)[2] += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        pthread_mutex_unlock(&lock);
    }
}
