// Define a MAC_PDU structure
typedef struct {
    // Define MAC_HEADER type (assuming it's an int)
    int mac_header;
    // Define SCHEDULED_TTI type (assuming it's an int)
    int scheduled_tti;
    // Define PDU_TYPE type (assuming it's an enum or int)
    int pdu_type;
    // Add a PDUCOUNT field with random value
    int pdccount;
} MAC_PDU;

// Define the linked list node structure
typedef struct {
    MAC_PDU *pdu;
    struct list_node* next;
} LIST_NODE;

// Function to add a new MAC_PDU structure without reallocating the entire array
void add_MAC_PDU(struct list_node** head, int max_size) {
    // Create a new node and set its pdu pointer to a dynamically allocated MAC_PDU instance
    LIST_NODE* new_node = (LIST_NODE*)malloc(sizeof(LIST_NODE));
    new_node->pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    new_node->pdu->mac_header = rand();
    new_node->pdu->scheduled_tti = rand();
    new_node->pdu->pdu_type = rand() % 2;
    // Set the pdccount to a random value between 0 and max_size
    new_node->pdu->pdccount = rand() % (max_size + 1);

    if (*head == NULL) {
        *head = new_node;
    } else {
        LIST_NODE* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to serialize the MAC_PDU structures into a binary format
void serialize_MAC_PDU(MAC_PDU* pdu, FILE* file) {
    fwrite(&pdu->mac_header, sizeof(int), 1, file);
    fwrite(&pdu->scheduled_tti, sizeof(int), 1, file);
    fwrite(&pdu->pdu_type, sizeof(int), 1, file);
    fwrite(&pdu->pdccount, sizeof(int), 1, file);
}

// Function to deserialize the MAC_PDU structures from a binary format
MAC_PDU* deserialize_MAC_PDU(FILE* file) {
    MAC_PDU* pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    fread(&pdu->mac_header, sizeof(int), 1, file);
    fread(&pdu->scheduled_tti, sizeof(int), 1, file);
    fread(&pdu->pdu_type, sizeof(int), 1, file);
    fread(&pdu->pdccount, sizeof(int), 1, file);
    return pdu;
}

int main() {
    // Initialize a linked list with an initial size of 1000
    struct list_node* head = NULL;

    for (int i = 0; i < 10; ++i) {
        add_MAC_PDU(&head, 10000);
    }

    // Serialize the linked list into a binary file
    FILE* file = fopen("mac_pdu.bin", "wb");
    LIST_NODE* current = head;
    while (current != NULL) {
        serialize_MAC_PDU(current->pdu, file);
        current = current->next;
    }
    fclose(file);

    return 0;
}
