typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return -1;

    if (*head == NULL || !check_rnti(*head, &data)) {
        new_node->next = *head;
        *head = new_node;
        return 0;
    }

    Node* current = *head;
    while (current->next && check_rnti(current->next, &data)) {
        current = current->next;
    }
    new_node->next = current->next;
    current->next = new_node;

    return 0;
}

int check_rnti(Node* node, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (node && node->data.rnti == data->rnti)
        return -1; // duplicate RNTI found
    return 0; // no duplicate RNTI found
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
