#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

void createCRCList(int max_size, int* list) {
    // Initialize the linked list
    struct Node* head = NULL;
    struct Node* current = NULL;

    for (int i = 0; i < max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T tempData;
        tempData.RNTI = rand() % 1000 + 1; // Assign a random RNTI
        tempData.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (head == NULL) {
            head = (struct Node*) malloc(sizeof(struct Node));
            current = head;
        } else {
            struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
            current->next = newNode;
            current = newNode;
        }

        // Error handling for RNTI uniqueness
        if (!isUniqueRNTI(tempData.RNTI, list)) {
            printf("Error: No unique RNTI available.\n");
            free(head);
            return;
        }

        list[i] = tempData;
    }
}

int isUniqueRNTI(int rnti, int* list) {
    for (int i = 0; i < max_size; i++) {
        if (list[i].RNTI == rnti) {
            return 0; // RNTI not unique
        }
    }
    return 1; // RNTI is unique
}

void updateCRCList(NFAPI_CRC_INDICATION_PDU_T* newPDU, struct Node** head_ref) {
    struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
    newNode->data = *newPDU;

    if (*head_ref == NULL) {
        *head_ref = newNode;
    } else {
        struct Node* current = *head_ref;
        while (current->next != NULL)
            current = current->next;
        current->next = newNode;
    }
}

void prioritizeUpdates(struct Node* head, int threshold) {
    // Priority update mechanism based on urgency score
    struct Node* current = head;
    while (current != NULL && current->data.urgencyScore <= threshold) {
        current = current->next;
    }

    if (current == NULL)
        return; // No critical updates

    struct Node* temp = current->next;
    current->next = NULL;
    while (temp != NULL) {
        temp->prev = NULL;
        struct Node* next = temp->next;
        temp->next = current;
        current = temp;
        temp = next;
    }

    head = current; // Update the head reference
}

void cleanUpUnusedEntries(struct Node** head_ref, int max_size) {
    if (*head_ref == NULL)
        return;

    struct Node* slow = *head_ref;
    struct Node* fast = *head_ref;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }

    free(fast);
    *head_ref = slow; // Update the head reference
}

void logError(int error_code, char* message) {
    // Logging mechanism based on configurable logging levels
    printf("Error: %d - %s\n", error_code, message);
}
