// Define CUSTOMER_ORDER_INFO structure
typedef struct {
    int ORDER_ID;
    int CUSTOMER_ID;
    char** PRODUCT_LIST;
} CUSTOMER_ORDER_INFO;

// Define Hash Table Node structure
typedef struct {
    CUSTOMER_ORDER_INFO* customer_order_info;
    struct node* next;
} HASH_TABLE_NODE;

// Define Hash Table structure
typedef struct {
    int size;
    int max_size;
    HASH_TABLE_NODE** buckets;
} HASH_TABLE;

void hash_table_init(HASH_TABLE* table, int max_size) {
    table->size = 0;
    table->max_size = max_size;
    table->buckets = (HASH_TABLE_NODE**)malloc(max_size * sizeof(HASH_TABLE_NODE*));
    for (int i = 0; i < max_size; i++) {
        table->buckets[i] = NULL;
    }
}

void hash_table_insert(HASH_TABLE* table, CUSTOMER_ORDER_INFO* customer_order_info) {
    int index = customer_order_info->CUSTOMER_ID % table->max_size;
    HASH_TABLE_NODE* node = (HASH_TABLE_NODE*)malloc(sizeof(HASH_TABLE_NODE));
    node->customer_order_info = customer_order_info;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->size++;
}

void hash_table_remove(HASH_TABLE* table, int customer_id) {
    int index = customer_id % table->max_size;
    HASH_TABLE_NODE* current = table->buckets[index];
    HASH_TABLE_NODE* previous = NULL;
    while (current != NULL) {
        if (current->customer_order_info->CUSTOMER_ID == customer_id) {
            if (previous == NULL) {
                table->buckets[index] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            table->size--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

int main() {
    HASH_TABLE* table = (HASH_TABLE*)malloc(sizeof(HASH_TABLE));
    hash_table_init(table, 16);

    CUSTOMER_ORDER_INFO* customer_order_info1 = (CUSTOMER_ORDER_INFO*)malloc(sizeof(CUSTOMER_ORDER_INFO));
    customer_order_info1->ORDER_ID = 1;
    customer_order_info1->CUSTOMER_ID = 10;
    char** product_list1[] = { "Product A", "Product B" };
    customer_order_info1->PRODUCT_LIST = product_list1;

    CUSTOMER_ORDER_INFO* customer_order_info2 = (CUSTOMER_ORDER_INFO*)malloc(sizeof(CUSTOMER_ORDER_INFO));
    customer_order_info2->ORDER_ID = 2;
    customer_order_info2->CUSTOMER_ID = 20;
    char** product_list2[] = { "Product C", "Product D" };
    customer_order_info2->PRODUCT_LIST = product_list2;

    hash_table_insert(table, customer_order_info1);
    hash_table_insert(table, customer_order_info2);

    // Remove a customer order
    int customer_id_to_remove = 10;
    hash_table_remove(table, customer_id_to_remove);

    return 0;
}
