        printf("Error: Requested allocation exceeds maximum limit.\n");
        return NULL;
    }

    void** temp = realloc(nfapi_crc_indication_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (count + 1));
