        printf("Error: Requested allocation exceeds maximum limit or is not aligned.\n");
        return NULL;
    }

    void** temp = realloc(nfapi_crc_indication_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (count + 1));
    if (!temp) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }
    nfapi_crc_indication_pdu_list = temp;
    for (int i = count; i > 0; --i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Error: Memory allocation failed.\n");
            for (int j = 0; j < i - 1; ++j) {
                free(nfapi_crc_indication_pdu_list[j]);
