        if (validate_entry(pdu)) {
            list[i] = pdu;
        } else {
            free(pdu); // release memory for invalid entries
        }
    }

    qsort(list, num_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*), cmpfunc);

    return list;
}

int cmpfunc(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu1 = *(NFAPI_CRC_INDICATION_PDU_T**)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu2 = *(NFAPI_CRC_INDICATION_PDU_T**)b;

    return (pdu1->RNTI - pdu2->RNTI);
}

void release_allocated_memory(NFAPI_CRC_INDICATION_PDU_T** list, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(list[i]);
    }
    free(list);
}
