void manage_CRC_indication_list(int max_collisions) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int num_items = 0;
    int collisions = 0;
    int max_allowed_collisions = max_collisions;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* new_item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_item) {
            printf("Error allocating memory\n");
            return;
        }

        // Generate random CRCFLAG
        new_item->CRCFLAG = rand() % 256;

        // Validate RNTI for uniqueness
        int found = 0;
        for (int i = 0; i < num_items; i++) {
            if (!strcmp(new_item->RX_UE_INFORMATION_TAG, list[i]->RX_UE_INFORMATION_TAG) &&
                new_item->RNTI == list[i]->RNTI) {
                found = 1;
                break;
            }
        }

        if (found) {
            collisions++;

            // Check for maximum allowed collisions
            if (collisions > max_allowed_collisions) {
                printf("Maximum allowed collisions exceeded\n");
                free(new_item);
                while (list) {
                    NFAPI_CRC_INDICATION_PDU_T* next = list;
                    list = list->next;
                    free(next);
                }
                return;
            } else {
                // Allocate memory for collision information
                int* coll_info = malloc(sizeof(int));
                if (!coll_info) {
                    printf("Error allocating memory\n");
                    return;
                }
                *coll_info = collisions;

                // Update list and num_items
                NFAPI_CRC_INDICATION_PDU_T* prev = NULL;
                for (int i = 0; i < num_items; i++) {
                    if (!strcmp(new_item->RX_UE_INFORMATION_TAG, list[i]->RX_UE_INFORMATION_TAG) &&
                        new_item->RNTI == list[i]->RNTI) {
                        free(list[i]);
                        free(coll_info);
                        return;
                    }
                }

                // Insert new item into the list
                if (prev) {
                    prev->next = new_item;
                } else {
                    new_item->next = list;
                    list = new_item;
                }
                num_items++;
            }
        } else {
            // Validate CRC_INDICATION_REL8_TAG against reference value
            // ...

            // Insert new item into the list
            if (num_items) {
                list[num_items-1]->next = new_item;
            } else {
                list = new_item;
            }
            num_items++;
        }
    }
}
