        stats[i].timestamp = time(NULL);

        int j = 0;
        while (j < MAX_UE_PER_CELL) {
            int rnti = rand() % (MAX_RNTI - MIN_RNTI) + MIN_RNTI;
            if (rnti != -1 && !contains_ue(stats[i].ues, j, rnti)) {
                stats[i].ues[j] = rnti;
                j++;
            }
        }
    }

    return stats;
}

int contains_ue(int* ues, int i, int rnti) {
    for (int j = 0; j < i; j++) {
        if (ues[j] == rnti) {
            return 1;
        }
    }
    return 0;
}

