// Structure to represent a linked list node
typedef struct Node {
    nfa_pi_crc_indication_pdu_t data;
    struct Node* next;
} Node;

// Initialize the head of the linked list
Node* head = NULL;

// Lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add an element to the end of the linked list
void insert(nfa_pi_crc_indication_pdu_t data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to remove an element from the linked list
void remove(nfa_pi_crc_indication_pdu_t data) {
    if (head == NULL) return;

    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data.RNTI != data.RNTI) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

