        return NULL;
    }
    memset(pHead->payload, 0, 1024);
    pHead->timestamp = time(NULL);
    pHead->next = NULL;

    // Initialize a pointer to keep track of the current node
    DataPacket* pCurrent = pHead;

    // Dynamically allocate memory for the remaining linked list nodes
    for (int i = 1; i < N; i++) {
        DataPacket* newNode = (DataPacket*)malloc(sizeof(DataPacket));
        if (!newNode) {
            fprintf(logFile, "Memory allocation failed for new node.\n");
