        newNode->payload = malloc(1024);  // Initialize payload with a fixed size
        if (!newNode->payload) {
            fprintf(logFile, "Memory allocation failed for new payload.\n");
            // Return the partially allocated linked list
            return NULL;
        }
        memset(newNode->payload, 0, 1024);
        newNode->timestamp = time(NULL);
        newNode->next = NULL;

        // Link the new node to the current node
        pCurrent->next = newNode;
        pCurrent = newNode;
    }

    // Close the log file
    fclose(logFile);

    return pHead;
}

// Function to deallocate memory for an array of structures and a linked list of data packets
void DeallocateMemory(NFAPI_CRC_INDICATION_PDU_T** pStructures, DataPacket* pHead) {
