        if (pStructures[i]) {
            free(pStructures[i]);
        }
    }
    free(pStructures);

    // Deallocate memory for the linked list nodes
    DataPacket* pCurrent = pHead;
    while (pCurrent) {
        DataPacket* nextNode = pCurrent->next;
        free(pCurrent->payload);
        free(pCurrent);
        pCurrent = nextNode;
    }
}
