#define MAX_ENTRIES 10000

typedef struct {
    int valid_rx_ue_info_tag;
    int rnti;
    char crc_indication_rel8_tag[16];
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int count = 0;

void initialize_list() {
    head = NULL;
    count = 0;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = *data;
    newNode->next = head;
    head = newNode;
    count++;
}

int find_max_rnti() {
    Node* current = head;
    int max_rnti = 0;
    while (current != NULL) {
        if (current->data.rnti > max_rnti)
            max_rnti = current->data.rnti;
        current = current->next;
    }
    return max_rnti;
}

void remove_from_list(int rnti) {
    Node* prev = NULL;
    Node* current = head;
    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }
    if (current != NULL) {
        if (prev == NULL)
            head = current->next;
        else
            prev->next = current->next;
        free(current);
        count--;
    }
}

void free_list() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    count = 0;
}

int main() {
    srand(time(NULL));

    // Initialize the list
    initialize_list();

    // Add up to MAX_ENTRIES structures to the list
    for (int i = 0; i < MAX_ENTRIES; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.valid_rx_ue_info_tag = rand() % 100;
        data.rnti = rand() % 10000;
        sprintf(data.crc_indication_rel8_tag, "CRCFLAG_%d", rand() % 10);
        add_to_list(&data);
    }

    // Find the structure with the largest RNTI value
    int max_rnti = find_max_rnti();
    printf("Structure with the largest RNTI: %d\n", max_rnti);

    // Remove a structure from the list by its RNTI
    remove_from_list(5000);

    // Free the list
    free_list();

    return 0;
}

