    for (i = 0; i < size; i++) {
        if (!array[i]) {
            free(array[i]);
            array[i] = NULL;
        }
    }

    for (i = 0; i < list_size; i++) {
        if (!list[i]) {
            free(list[i]);
            list[i] = NULL;
        }
    }
}

int main() {
    int n = 10;
    void* array = initialize_and_populate(n);
    void* list = manage_crc_indication_pdu_list(n);

    // Periodic cleanup to optimize memory usage
    pthread_t thread_id = pthread_self();
    pthread_create(&thread_id, NULL, periodic_cleanup, (void*)array, n);
    pthread_join(thread_id, NULL);

    return 0;
}
