void validateStringAndAppend(char *str, char **result) {
    size_t newSize = strlen(str);
    if (newSize > MAX_STRING_LENGTH) {
        while (newSize > MAX_STRING_LENGTH && str[newSize - 1]) {
            newSize--;
        }
        if (newSize <= MAX_STRING_LENGTH) {
            *result = strdup(str + newSize);
        } else {
            *result = NULL;
        }
    } else {
        char hash[33];
        sprintf(hash, "%x", time(NULL));
        char *uniqueId = strcat(strdup(str), hash);
        *result = uniqueId;
    }
}

