// Dynamic list of traffic flow stats
typedef struct {
    size_t size;
    TrafficFlowStats** entries;
} TrafficFlowStatsList;

TrafficFlowStatsList* traffic_flow_stats_list_create() {
    TrafficFlowStatsList* list = (TrafficFlowStatsList*)malloc(sizeof(TrafficFlowStatsList));
    list->size = 0;
    list->entries = NULL;
    return list;
}

void traffic_flow_stats_list_add_entry(TrafficFlowStatsList* list, TrafficFlowStats* entry) {
    if (!list->entries) {
        list->entries = (TrafficFlowStats**)malloc(sizeof(TrafficFlowStats*) * 2);
        list->size = 1;
    } else if (list->size == 1 && list->entries[0]) {
        size_t new_size = list->size * 2 + 1;
        TrafficFlowStats** new_entries = (TrafficFlowStats**)malloc(sizeof(TrafficFlowStats*) * new_size);
        memcpy(new_entries, list->entries, sizeof(TrafficFlowStats*) * list->size);
        free(list->entries);
        list->entries = new_entries;
        list->size = new_size;
    }
    list->entries[list->size++] = entry;
}

TrafficFlowStats* traffic_flow_stats_list_get_entry_by_imsi(TrafficFlowStatsList* list, const char* imsi) {
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->entries[i]->imsi, imsi) == 0) {
            return list->entries[i];
        }
    }
    return NULL;
}

TrafficFlowStats* traffic_flow_stats_list_get_entry_by_ue_id(TrafficFlowStatsList* list, int ueId) {
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->ueId == ueId) {
            return list->entries[i];
        }
    }
    return NULL;
}

void traffic_flow_stats_list_update_entry(TrafficFlowStatsList* list, const char* imsi, int packetCount, float packetLossRate) {
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->entries[i]->imsi, imsi) == 0) {
            list->entries[i]->packetCount = packetCount;
            if (packetLossRate != 0.0f) {
                list->entries[i]->packetLossRate = packetLossRate;
            }
            return;
        }
    }
}

void traffic_flow_stats_list_free(TrafficFlowStatsList* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->entries[i]);
    }
    free(list->entries);
    free(list);
}
