#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define CONNECTION_METADATA_SIZE sizeof(struct connection_metadata)

typedef struct {
    uint32_t src_ip;
    uint16_t src_port;
    uint32_t dst_ip;
    uint16_t dst_port;
    int state; // 0: closed, 1: established
    time_t last_activity;
} struct connection_metadata;

struct connection_metadata* connections[MAX_CONNECTIONS];
pthread_mutex_t connection_lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file;

void init_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i] = NULL;
    }
}

void free_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i]) {
            free(connections[i]);
            connections[i] = NULL;
        }
    }
}

void process_network_event(struct sockaddr_in* src_addr, struct sockaddr_in* dst_addr) {
    pthread_mutex_lock(&connection_lock);

    // Find an available connection slot or allocate new memory
    int idx = -1;
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (!connections[i]) {
            idx = i;
            break;
        }
    }
    if (idx == -1) {
        // No available slots, allocate new memory
        connections[idx] = malloc(CONNECTION_METADATA_SIZE);
        if (!connections[idx]) {
            pthread_mutex_unlock(&connection_lock);
            return; // Memory allocation failed
        }
    }

    struct connection_metadata* conn = connections[idx];
    conn->src_ip = src_addr->sin_family;
    conn->src_port = htons(src_addr->sin_port);
    conn->dst_ip = dst_addr->sin_family;
    conn->dst_port = htons(dst_addr->sin_port);
    conn->state = 1; // Assume established
    time(&conn->last_activity);

    pthread_mutex_unlock(&connection_lock);

    // Log the connection event
    fprintf(log_file, "New connection: src=%s:%u, dst=%s:%u\n",
        inet_ntoa(src_addr->sin_addr), ntohs(src_addr->sin_port),
        inet_ntoa(dst_addr->sin_addr), ntohs(dst_addr->sin_port));
}

void close_connection(int idx) {
    pthread_mutex_lock(&connection_lock);

    if (idx < 0 || idx >= MAX_CONNECTIONS || !connections[idx]) {
        pthread_mutex_unlock(&connection_lock);
        return; // Invalid connection index
    }

    connections[idx]->state = 0;
    time(&connections[idx]->last_activity);

    pthread_mutex_unlock(&connection_lock);
}

void main() {
    init_connections();
    log_file = fopen("log.txt", "w");

    while (1) {
        // Process network events
        process_network_event(...); // Fill in your code here

        // Monitor and handle connections
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            if (connections[i] && connections[i]->state == 0) {
                close_connection(i);
            }
        }
    }

    free_connections();
    fclose(log_file);
}
