// Function to manage a dynamically sized pool of NFAPI_RRC_PDU_T structures
void* rrc_pdu_pool_manager(void** ppduPool, pthread_mutex_t* mutex) {
    // Initialize the pool size
    int poolSize = 10;

    // Allocate the initial memory for the pool
    *ppduPool = malloc(poolSize * sizeof(NFAPI_RRC_PDU_T));

    if (!(*ppduPool)) {
        // Handle allocation failure
    }
}

// Function to create a new NFAPI_RRC_PDU_T structure and add it to the pool
NFAPI_RRC_PDU_T* rrc_pdu_create(pthread_mutex_t* mutex, void** ppduPool) {
    NFAPI_RRC_PDU_T* pdu;

    // Lock the mutex for thread safety
    pthread_mutex_lock(mutex);

    // Check if the pool is full and needs to be resized
    if (/* check if the pool is full */) {
        // Resize the pool
        void* temp = realloc(*ppduPool, ((*ppduPool) + poolSize) * sizeof(NFAPI_RRC_PDU_T));

        if (!temp) {
            // Handle allocation failure
        }

        *ppduPool = temp;
    }

    // Create a new pdu and add it to the pool
    pdu = &((*ppduPool)[(*ppduPool)->size]);

    // Unlock the mutex for thread safety
    pthread_mutex_unlock(mutex);

    return pdu;
}

// Function to free the memory used by the NFAPI_RRC_PDU_T structure
void rrc_pdu_free(NFAPI_RRC_PDU_T* pdu) {
    free(pdu);
