void process_files(int argc, char **argv) {
    int i;
    for (i = 0; i < argc; i++) {
        char *file_path = argv[i];
        // Parse command-line options
        int operation_type = 0;
        if (strcmp(argv[1], "-encrypt") == 0) {
            operation_type = SSL_FILETYPE_ENCRYPT;
        } else if (strcmp(argv[1], "-decrypt") == 0) {
            operation_type = SSL_FILETYPE_DECRYPT;
        } else {
            printf("Invalid command-line option: %s\n", argv[1]);
            return;
        }

        // Initialize OpenSSL library
        SSL_library_init();

        // Load cipher object based on command-line options
        EVP_CIPHER_CTX *cipher_ctx = NULL;
        if (operation_type == SSL_FILETYPE_ENCRYPT) {
            cipher_ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(cipher_ctx, NULL, NULL);
        } else if (operation_type == SSL_FILETYPE_DECRYPT) {
            cipher_ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(cipher_ctx, NULL, NULL);
        }

        // Perform cryptographic operation
        FILE *file = fopen(file_path, "rb+");
        if (file != NULL) {
            int bytes_read;
            unsigned char buffer[1024];
            while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
                if (operation_type == SSL_FILETYPE_ENCRYPT) {
                    int bytes_written = EVP_EncryptUpdate(cipher_ctx, buffer, bytes_read);
                    fwrite(buffer, 1, bytes_written, file);
                } else if (operation_type == SSL_FILETYPE_DECRYPT) {
                    int bytes_written = EVP_DecryptUpdate(cipher_ctx, buffer, bytes_read);
                    fwrite(buffer, 1, bytes_written, file);
                }
            }
            fclose(file);
        }

        // Clean up
        EVP_CIPHER_CTX_free(cipher_ctx);
    }
}
