// Function to manage the array of structures
void* nfa_pi_crc_indication_pdu_mgmt(void* data) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T** arr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_STRUCTURES);
    int size = 0;

    // Function to validate integrity of structures
    void (*validate_struct)(NFAPI_CRC_INDICATION_PDU_T*);

    pthread_t threads[MAX_STRUCTURES];
    int num_threads = 4; // Number of concurrent threads

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* struc = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!struc) {
            perror("Memory allocation failed");
            exit(1);
        }

        // Allocate memory for structure
        pthread_create(&threads[size], NULL, validate_struct, struc);

        pthread_mutex_lock(&lock);
        arr[size] = struc;
        size++;
        pthread_mutex_unlock(&lock);

        if (size >= MAX_STRUCTURES) {
