            NFAPI_CRC_INDICATION_PDU_T** new_arr = realloc(arr, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * 2 * MAX_STRUCTURES);
            arr = new_arr;
        }
    }

    // Function to log processed structures
    void (*log_processed)(int);

    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_processed, size);

    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }
