        (*pdu_list)[i].RNTI = rand() % 1000;
        (*pdu_list)[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        (*pdu_list)[i].CRCFLAG = (rand() % 2);
    }

    return 0;
}

int resolve_hostname_to_ip(char *hostname, struct in_addr **ip) {
    int sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) return -1;

    struct addrinfo hints = {0};
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    struct addrinfo *result = NULL;
    getaddrinfo(hostname, NULL, &hints, &result);
    if (result == NULL) {
        close(sock_fd);
        return -1;
    }

    *ip = (struct in_addr *)malloc(sizeof(struct in_addr));
    if (*ip == NULL) {
        freeaddrinfo(result);
        close(sock_fd);
        return -1;
    }

    inet_ntop(AF_INET, &result->ai_addr->ai_addr, (*ip).s_addr);

    freeaddrinfo(result);
    close(sock_fd);

    return 0;
}

int main(int argc, char **argv) {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    create_crc_indication_pdu_list(n, &pdu_list);
    if (n < 1) return -1;

    char hostname[] = "example.com";
    struct in_addr *ip;
    resolve_hostname_to_ip(hostname, &ip);
    if (ip == NULL) {
        free(pdu_list);
        return -1;
    }

    // Log metrics and error messages

    return 0;
}
