typedef struct {
    char client_id[16];
    char ip_addr[32];
    int port_num;
} NetworkRecord;

void init_network_records(NetworkRecord **records, size_t *count) {
    // Initialize the list with a default capacity
    *count = 10;
    *records = (NetworkRecord *)malloc(*count * sizeof(NetworkRecord));
    for (size_t i = 0; i < *count; i++) {
        strcpy((*records)[i].client_id, "");
        strcpy((*records)[i].ip_addr, "");
        (*records)[i].port_num = -1;
    }
}

int add_network_record(NetworkRecord **records, size_t *count, char client_id[16], char ip_addr[32], int port_num) {
    if (strlen(client_id) == 0 || strlen(ip_addr) == 0 || port_num < 0 || port_num > 65535) {
        return -1; // Invalid record
    }

    for (size_t i = 0; i < *count; i++) {
        if (!strcmp((*records)[i].client_id, client_id)) {
            return -2; // Duplicate client ID
        }
    }

    if (*count == sizeof(NetworkRecord) * 1024 / sizeof(NetworkRecord[1])) { // Dynamic scaling limit
        size_t new_count = *count + *count / 2;
        NetworkRecord *new_records = (NetworkRecord *)realloc(*records, new_count * sizeof(NetworkRecord));
        *records = new_records;
    }

    (*records)[*count].client_id[15] = '\0'; // Null-terminate the client ID
    strcpy((*records)[*count].ip_addr, ip_addr);
    (*records)[*count].port_num = port_num;
    (*count)++;

    return 0; // Successful addition
}

void print_network_records(NetworkRecord *records, size_t count) {
    for (size_t i = 0; i < count; i++) {
        printf("Client ID: %s, IP Address: %s, Port Number: %d\n", records[i].client_id, records[i].ip_addr, records[i].port_num);
    }
}

void free_network_records(NetworkRecord **records, size_t *count) {
    if (*count > 0) {
        free(*records);
        *count = 0;
    }
}
