typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[16];
    int CRC_INDICATION_REL8_TAG;
    int PHY_RX_FRAME_INFO_TAG;
} NFAPI_MESSAGE_T;

void *nfapi_message_queue(void *);

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, nfapi_message_queue, NULL);
    return 0;
}

void *nfapi_message_queue(void *) {
    int i = 0;
    while (1) {
        // Receive message
        NFAPI_MESSAGE_T message;
        // Implement receive logic here

        // Validate message
        if (validate_message(&message)) {
            printf("Received valid message: %d, %s, %d, %d\n", 
                   message.RX_UE_INFORMATION_TAG, message.RNTI,
                   message.CRC_INDICATION_REL8_TAG, message.PHY_RX_FRAME_INFO_TAG);
            // Process and dispatch the validated message
        } else {
            printf("Received invalid message: Aborting processing.\n");
        }
    }
    return NULL;
}

int validate_message(NFAPI_MESSAGE_T *message) {
    if (message->RX_UE_INFORMATION_TAG > 255 || message->RX_UE_INFORMATION_TAG < 0) {
        return 0; // Invalid tag
    }

    for (int i = 0; i < strlen(message->RNTI); i++) {
        if (!isalnum((unsigned char) message->RNTI[i])) {
            return 0; // Invalid RNTI format
        }
    }

    if (message->CRC_INDICATION_REL8_TAG > 255 || message->CRC_INDICATION_REL8_TAG < 0) {
        return 0; // Invalid CRC indication
    }

    if (message->PHY_RX_FRAME_INFO_TAG > 255 || message->PHY_RX_FRAME_INFO_TAG < 0) {
        return 0; // Invalid PHY RX frame info tag
    }

    return 1; // Valid message
}
