pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;
int max_pdu_count = MAX_PDU;
int current_pdu_count = 0;
NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;

void create_pdu_list(int count) {
    if (count > max_pdu_count) {
        printf("Error: Maximum PDU limit exceeded.\n");
        return;
    }
    pdu_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    for (int i = 0; i < count; i++) {
        pdu_list[i].ue_info = rand() % CRCFLAG_MAX + CRCFLAG_MIN;
        pdu_list[i].rnti = rand();
        pdu_list[i].crc_indication = rand();
        pthread_mutex_lock(&pdu_list_mutex);
        current_pdu_count++;
        pthread_mutex_unlock(&pdu_list_mutex);
    }
}

void serialize_pdu_list(char *buffer, int count) {
    pthread_mutex_lock(&pdu_list_mutex);
    for (int i = 0; i < count; i++) {
        memcpy(buffer + sizeof(NFAPI_CRC_INDICATION_PDU_T) * i,
               &pdu_list[i],
               sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&pdu_list_mutex);
}

void deserialize_pdu_list(char *buffer, int count) {
    pthread_mutex_lock(&pdu_list_mutex);
    for (int i = 0; i < count; i++) {
        memcpy(&pdu_list[i],
               buffer + sizeof(NFAPI_CRC_INDICATION_PDU_T) * i,
               sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&pdu_list_mutex);
}

int get_current_pdu_count() {
    return current_pdu_count;
}

int get_total_pdu_size() {
    return sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_pdu_count;
}

void set_max_pdu_count(int new_count) {
    if (new_count < 1) {
        printf("Error: Maximum PDU count must be greater than zero.\n");
        return;
    }
    max_pdu_count = new_count;
}
