        for (int j = 0; j < sizeof(arr[count].CRC_INDICATION_REL8_TAG) / sizeof(arr[count].CRC_INDICATION_REL8_TAG[0]); j++) {
            arr[count].CRC_INDICATION_REL8_TAG[j] = (uint8_t)(rand() % 256); // set CRCFLAG randomly
        }
        count++;
    }

    return count;
}
