// List node structure
typedef struct Node {
    UDP_Header* header;
    struct Node* next;
} Node;

// Function to create a new list node and allocate memory for the header
Node* newNode(UDP_Header* header) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->header = header;
    node->next = NULL;
    return node;
}

void insertNode(Node** head, UDP_Header* header) {
    Node* new_node = newNode(header);
    if (*head == NULL || strcmp((*head)->header->dst_ip, new_node->header->dst_ip) > 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && strcmp(current->next->header->dst_ip, new_node->header->dst_ip) < 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void removeNode(Node** head, UDP_Header* header) {
    if (*head == NULL || (*head)->header != header)
        return;

    Node* temp = *head;
    *head = (*head)->next;
    free(temp);
}

int main(int argc, char* argv[]) {
    int M = atoi(argv[1]);
    if (M < 1 || M > 5000) {
        printf("Invalid value for M. Please enter a number between 1 and 5000.\n");
        return -1;
    }

    Node* head = NULL;
    for (int i = 0; i < M; i++) {
        UDP_Header header;
