#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_CONNECTIONS 10000
#define INACTIVE_TIMEOUT 5 * 60 // 5 minutes in seconds
#define LOG_LEVEL printf

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    int status; // 0: idle, 1: active
} TCP_CONNECTION_PDU_T;

pthread_mutex_t connection_list_mutex = PTHREAD_MUTEX_INITIALIZER;
TCP_CONNECTION_PDU_T *connection_list = NULL;
int connection_list_len = 0;
int max_connections_reached = 0;

void initialize_network_interface() {
    connection_list = (TCP_CONNECTION_PDU_T *)malloc(MAX_CONCURRENT_CONNECTIONS * sizeof(TCP_CONNECTION_PDU_T));
}

int add_connection(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port, uint16_t dst_port) {
    pthread_mutex_lock(&connection_list_mutex);

    if (max_connections_reached >= MAX_CONCURRENT_CONNECTIONS) {
        LOG_LEVEL("Error: Maximum concurrent connections reached.\n");
        return -1;
    }

    TCP_CONNECTION_PDU_T *new_connection = &connection_list[connection_list_len++];
    new_connection->src_ip = src_ip;
    new_connection->dst_ip = dst_ip;
    new_connection->src_port = src_port;
    new_connection->dst_port = dst_port;
    new_connection->status = 0; // idle

    pthread_mutex_unlock(&connection_list_mutex);

    return connection_list_len - 1; // index of the newly added connection
}

void cleanup_inactive_connections() {
    time_t current_time = time(NULL);
    for (int i = 0; i < connection_list_len; i++) {
        TCP_CONNECTION_PDU_T *conn = &connection_list[i];
        if (current_time - conn->timestamp > INACTIVE_TIMEOUT) {
            // mark as idle
            conn->status = 0;
        }
    }
}

void log_connection_event(int conn_index, int event_type) {
    LOG_LEVEL("Connection %d: ", conn_index);
    if (event_type == 1) {
        LOG_LEVEL("established\n");
    } else {
        LOG_LEVEL("closed due to inactivity\n");
    }
}

void *connection_monitor_thread(void *arg) {
    while (1) {
        // monitor connections and log events
        for (int i = 0; i < connection_list_len; i++) {
            TCP_CONNECTION_PDU_T *conn = &connection_list[i];
            if (conn->status == 1) { // active
                // check for inactivity and cleanup inactive connections
                if (...) {
                    cleanup_inactive_connections();
                }
            }
        }

        // log active connections every second
        sleep(1);
    }
}

int main() {
    initialize_network_interface();

    pthread_t connection_monitor;
    pthread_create(&connection_monitor, NULL, &connection_monitor_thread, NULL);

    int conn_index = 0;
    while (1) {
        // handle new connections
        int new_conn_index = add_connection(1, 2, 3, 4);
        if (new_conn_index != -1) {
            LOG_LEVEL("New connection established: %d\n", new_conn_index);
        } else {
            LOG_LEVEL("Error: Connection limit reached.\n");
        }

        // monitor connections and log events
        // ...
    }
}
