#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

#define MAX_ACTIVE_CONNECTIONS 1000

typedef struct {
    uint16_t RNTI;
    uint32_t RX_UE_INFORMATION_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* generateCRCList(int numEntries) {
    // Initialize list and allocate memory
    NFAPI_CRC_INDICATION_PDU_T* crcList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Generate random CRCFLAG values
    for (int i = 0; i < numEntries; i++) {
        crcList[i].RNTI = rand();
        crcList[i].RX_UE_INFORMATION_TAG = rand();
        crcList[i].CRCFLAG = (uint8_t)rand() % 256;
    }

    return crcList;
}

int configureNetworkInterface() {
    // Initialize socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Failed to create socket\n");
        return -1; // Error creating socket
    }

    // Set up network interface configuration
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080); // Replace with desired port number

    if (bind(sockfd, (struct sockaddr*) &serv_addr, sizeof(serv_addr)) < 0) {
        printf("Failed to bind socket\n");
        return -1; // Error binding
    }

    listen(sockfd, MAX_ACTIVE_CONNECTIONS);

    // Start accepting connections in a new thread
    pthread_t acceptThread;
    if (pthread_create(&acceptThread, NULL, acceptConnections, (void*) &sockfd) < 0) {
        printf("Failed to create accept thread\n");
        return -1; // Error creating thread
    }

    return 0; // Success
}

void* acceptConnections(void* sockfd) {
    int connSock = *((int*) sockfd);
    while (true) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int newsockfd = accept(connSock, (struct sockaddr*) &client_addr, &client_len);

        if (newsockfd < 0) {
            printf("Failed to accept connection\n");
            continue; // Try again
        }

        // Handle accepted connection in a separate thread
        pthread_t handleThread;
        pthread_create(&handleThread, NULL, handleConnection, (void*) &newsockfd);
    }
}

void* handleConnection(void* sockfd) {
    int connSock = *((int*) sockfd);

    // Read and write data to/from the connected client

    close(connSock); // Close connection
}

int main() {
    srand(time(NULL)); // Initialize random seed

    int numCRCEntries = 100; // Replace with desired number of CRC entries
    void* crcList = generateCRCList(numCRCEntries);

    configureNetworkInterface();

    return 0;
}
