void cache_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if(cache_index >= CACHE_SIZE){
        NFAPI_CRC_INDICATION_PDU_T* evicted_pdu = &cache[0];
        // Priority-based eviction policy: evict the least recently used or least frequently used
        cache_index--;
        // Update pointers and indices
        for(int i=0; i<cache_index; i++){
            &cache[i+1] = &cache[i];
        }
    } else {
        cache[cache_index] = *pdu;
        cache_index++;
    }
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
