typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = rand() % 1000; // random CRCFLAG
    return new_node;
}

void* serialize_list(struct node* head) {
    FILE* file = fopen("serialized_list.bin", "wb");
    if (!file) return NULL;

    struct node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    return "serialized_list.bin";
}

int cleanup_unused_entries(struct node** head) {
    struct node* current = *head;
    struct node* previous = NULL;

    while (current != NULL) {
        if (/* logic to determine whether the entry is unused */) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            current = (*head);
        } else {
            previous = current;
            current = current->next;
        }
    }

    return 0;
}

struct node* manage_crc_indication_pdu_list(int N) {
    struct node* head = NULL;
    int i;

    for (i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(i, i);
        if (!new_node) return NULL;

        // logic to handle unique CRCFLAG
        new_node->CRCFLAG = (int)(time(NULL) % 1000); // random CRCFLAG

        struct node* current = head;
        while (current != NULL && current->data.RNTI < i) {
            current = current->next;
        }

        if (current == NULL || current->data.RNTI != i) {
            new_node->next = current;
            if (current == NULL) {
                head = new_node;
            } else {
                struct node* previous = find_previous_node(head, i);
                new_node->next = current;
                previous->next = new_node;
            }
        } else {
            // duplicate RNTI found
            free(new_node);
        }
    }

    return head;
}

int main() {
    int N = 100; // number of NFAPI_CRC_INDICATION_PDU_T structures to create
    struct node* head = manage_crc_indication_pdu_list(N);

    if (head) {
        void* serialized_data = serialize_list(head);
        printf("Serialized data: %s\n", serialized_data ? "Success" : "Failed");
        cleanup_unused_entries(&head);
    }

    return 0;
}

