    // Create a pool of threads for processing incoming data streams
    pthread_t threadPool[numThreads];
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threadPool[i], NULL, manageNfaList, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threadPool[i], NULL);
    }

    return 0;
}
