typedef struct {
    uint32_t ueid;
    time_t timestamp;
    char *buffer;
    size_t buffer_len;
} NFAPI_RX_PDU_T;

// Dynamic array structure to store PDUs
typedef struct {
    NFAPI_RX_PDU_T *pdus;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex; // Concurrency control using a mutex
} PDU_Array;

PDU_Array* pdu_array_init(size_t initial_capacity) {
    PDU_Array* array = (PDU_Array*)malloc(sizeof(PDU_Array));
    if (!array) return NULL;

    array->pdus = (NFAPI_RX_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_RX_PDU_T));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL); // Initialize the mutex

    return array;
}

void pdu_array_add(PDU_Array* array, NFAPI_RX_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);

    if (array->length >= array->capacity) {
        size_t new_capacity = array->capacity * 2; // Double the capacity
        NFAPI_RX_PDU_T* new_pdus = (NFAPI_RX_PDU_T*)realloc(array->pdus, sizeof(NFAPI_RX_PDU_T) * new_capacity);
        if (!new_pdus) {
            pthread_mutex_unlock(&array->mutex);
            return; // Error allocating memory
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }

    array->pdus[array->length] = pdu;
    array->length++;

    pthread_mutex_unlock(&array->mutex);
}

NFAPI_RX_PDU_T* pdu_array_get(PDU_Array* array, size_t index) {
    pthread_mutex_lock(&array->mutex);

    if (index >= array->length) {
        pthread_mutex_unlock(&array->mutex);
        return NULL; // Invalid index
    }

    NFAPI_RX_PDU_T* pdu = &array->pdus[index];
    pthread_mutex_unlock(&array->mutex);

    return pdu;
}

void pdu_array_remove(PDU_Array* array, size_t index) {
    pthread_mutex_lock(&array->mutex);

    if (index >= array->length) {
        pthread_mutex_unlock(&array->mutex);
        return; // Invalid index
    }

    for (size_t i = index; i < array->length - 1; i++) {
        array->pdus[i] = array->pdus[i + 1];
    }
    array->length--;

    pthread_mutex_unlock(&array->mutex);
}

size_t pdu_array_size(PDU_Array* array) {
    return array->length;
}
