#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initializeStruct(int tag, int rnti, int indication) {
    NFAPI_CRC_INDICATION_PDU_T* structPtr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    structPtr->RX_UE_INFORMATION_TAG = tag;
    structPtr->RNTI = rnti;
    structPtr->CRC_INDICATION_REL8_TAG = indication;
    srand(time(NULL));
    structPtr->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return structPtr;
}

int cacheStruct(NFAPI_CRC_INDICATION_PDU_T* structPtr, int cacheSize) {
    static NFAPI_CRC_INDICATION_PDU_T* cache[10]; // Fixed-size buffer for caching recently used structures
    int i;

    for (i = 0; i < cacheSize - 1 && cache[i] != NULL; i++) {
        if (cache[i] == structPtr) {
            // Cache hit, move the rest of the cache down to make room
            memmove(&cache[i], &cache[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (cacheSize - i - 1));
            break;
        }
    }

    // If the cache is full and the requested structure is not found, evict the least recently used structure
    if (i == cacheSize - 1) {
        free(cache[0]);
        memmove(&cache[0], &cache[1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * cacheSize);
        i = 0;
    }

    // Add the requested structure to the cache
    cache[i] = structPtr;

    return i;
}

int main() {
    int N, cacheSize;
    FILE* configFile;
    char buffer[1024];

    printf("Enter number of structures: ");
    scanf("%d", &N);

    printf("Enter cache size: ");
    scanf("%d", &cacheSize);

    // Initialize configuration file
    configFile = fopen("config.txt", "r");
    if (configFile == NULL) {
        return -1; // Error reading config file
    }

    // Read configuration file and validate correctness
    fgets(buffer, 1024, configFile);
    fclose(configFile);

    // Dynamically allocate memory for array of structures based on user input N
    NFAPI_CRC_INDICATION_PDU_T* structArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int totalProcessed = 0;

    for (int i = 0; i < N; i++) {
        // Initialize structure with current system time
        NFAPI_CRC_INDICATION_PDU_T* structPtr = initializeStruct(i, i, i);

        // Cache the structure based on user input cacheSize
        int cacheIndex = cacheStruct(structPtr, cacheSize);

        if (structArray[i] != NULL) {
            free(structArray[i]);
        }
        structArray[i] = structPtr;

        totalProcessed++;
    }

    printf("Total number of CRC indications processed: %d\n", totalProcessed);

    // Release all allocated resources
    for (int i = 0; i < N; i++) {
        if (structArray[i] != NULL) {
            free(structArray[i]);
        }
    }
    free(structArray);

    return 0;
}
