#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[32];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

// Forward declaration
void insert(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_node);
void deleteNode(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI);

// Hash table for rapid RNTI checks
typedef struct {
    int RNTI;
    NFAPI_CRC_INDICATION_PDU_T* node;
} HashTableEntry;

HashTableEntry* hashTable = NULL;
int hashTableSize = 0;

void initHashTable(int size) {
    hashTable = (HashTableEntry*)malloc(size * sizeof(HashTableEntry));
    for (int i = 0; i < size; i++) {
        hashTable[i].RNTI = -1;
        hashTable[i].node = NULL;
    }
    hashTableSize = size;
}

// Function to manage the dynamically resizable linked list
NFAPI_CRC_INDICATION_PDU_T** createList() {
    // Initialize head and tail of the list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    return &head;
}

void insert(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    if (hashTable == NULL) initHashTable(1000);

    int index = new_node->RNTI % hashTableSize;
    if (hashTable[index].RNTI != -1 && strcmp(hashTable[index].node->RX_UE_INFORMATION_TAG, new_node->RX_UE_INFORMATION_TAG) == 0) {
        printf("Error: Attempted to insert a node with an existing RNTI and RX_UE_INFORMATION_TAG.\n");
        return;
    }

    if (*head == NULL || hashTable[index].RNTI == -1) {
        *head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    hashTable[index].node = new_node;
    hashTable[index].RNTI = new_node->RNTI;

    return;
}

void deleteNode(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    NFAPI_CRC_INDICATION_PDU_T* previous = NULL;

    while (current != NULL && current->RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    // Update the hash table
    int index = RNTI % hashTableSize;
    hashTable[index].RNTI = -1;
    hashTable[index].node = NULL;

    return;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize the node structure
    for (int i = 0; i < sizeof(new_node->RX_UE_INFORMATION_TAG); i++) {
        new_node->RX_UE_INFORMATION_TAG[i] = 'A' + rand() % 26;
    }
    new_node->RNTI = rand() % 10000;
    for (int i = 0; i < sizeof(new_node->CRC_INDICATION_REL8_TAG); i++) {
        new_node->CRC_INDICATION_REL8_TAG[i] = 'B' + rand() % 26;
    }
    new_node->CRCFLAG = rand() % 2;

    NFAPI_CRC_INDICATION_PDU_T** head = createList();
    insert(head, new_node);

    // Perform deletion
    deleteNode(head, new_node->RNTI);

    return 0;
}

