    for (i = 0; i < crc_indication_handler.size; i++) {
        if (crc_indication_handler.elements[i].rnti == rnti) {
            break;
        }
    }

    if (i == crc_indication_handler.size) {
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_indication_handler.elements, sizeof(NFAPI_CRC_INDATION_PDU_T) * (crc_indication_handler.size + 1));
        if (!new_elements) {
            pthread_mutex_unlock(&crc_indication_handler.lock);
            return -1;
        }
        crc_indication_handler.elements = new_elements;
        crc_indication_handler.size++;
    }

    crc_indication_handler.elements[i] = *p;

    pthread_mutex_unlock(&crc_indication_handler.lock);

    return 0;
}

int crc_indication_handler_remove(RNTI rnti) {
    pthread_mutex_lock(&crc_indication_handler.lock);

    int i, j;
    for (i = 0; i < crc_indication_handler.size; i++) {
        if (crc_indication_handler.elements[i].rnti == rnti) {
            break;
        }
    }

    if (i == crc_indication_handler.size) {
        pthread_mutex_unlock(&crc_indication_handler.lock);
        return -1;
    }

    for (j = i; j < crc_indication_handler.size - 1; j++) {
        crc_indication_handler.elements[j] = crc_indication_handler.elements[j + 1];
    }
    crc_indication_handler.size--;

    pthread_mutex_unlock(&crc_indication_handler.lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* crc_indication_handler_query(RNTI rnti) {
    pthread_mutex_lock(&crc_indication_handler.lock);

    int i;
    for (i = 0; i < crc_indication_handler.size; i++) {
        if (crc_indication_handler.elements[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* p = malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
            *p = crc_indication_handler.elements[i];
            pthread_mutex_unlock(&crc_indication_handler.lock);
            return p;
        }
    }

    pthread_mutex_unlock(&crc_indication_handler.lock);

    return NULL;
}

void crc_indication_handler_merge_with_remote_data(NFAPI_CRC_INDICATION_PDU_T* remote_pdu) {
    pthread_mutex_lock(&crc_indication_handler.lock);

    int i, j;
    for (i = 0; i < crc_indication_handler.size; i++) {
        bool found = false;
        for (j = 0; j < array_length(remote_pdu); j++) {
            if (remote_pdu[j].rnti == crc_indication_handler.elements[i].rnti) {
                found = true;
                break;
            }
        }

        if (!found) {
            // remove the element
            for (; i < crc_indication_handler.size - 1; i++) {
                crc_indication_handler.elements[i] = crc_indication_handler.elements[i + 1];
            }
            crc_indication_handler.size--;
        }
    }

    pthread_mutex_unlock(&crc_indication_handler.lock);
}

void crc_indication_handler_receive_remote_data(NFAPI_CRC_INDICATION_PDU_T* remote_pdu) {
    // receive the data and merge it with the local collection
    crc_indication_handler_merge_with_remote_data(remote_pdu);
}
