#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a structure to hold CRC indications
typedef struct {
    int RNTI;
    NFAPI_CRC_INDICATION_PDU_T data;
} NFAPI_CRC_INDICATION;

// Define the function to manage the collection of NFAPI_CRC_INDICATION structures
void *nfaPi_crc_indication_collection_init(size_t capacity) {
    // Allocate memory for the collection and its elements
    void *collection = malloc(sizeof(void *) * (capacity + 1));
    void **elements = (void **)(((char *)collection) + sizeof(void *));

    return collection;
}

// Add an element to the collection
int nfaPi_crc_indication_collection_add(void *collection, int RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    // Find the next available slot in the collection
    size_t i = 0;
    while (((NFAPI_CRC_INDICATION *)elements)[i].RNTI != 0) {
        i++;
    }

    if (i < capacity) {
        // Add the new element to the collection
        ((NFAPI_CRC_INDICATION *)elements)[i].RNTI = RNTI;
        ((NFAPI_CRC_INDICATION *)elements)[i].data = data;

        return 0; // Success
    } else {
        return -1; // Collection is full
    }
}

// Remove an element from the collection by its RNTI
int nfaPi_crc_indication_collection_remove(void *collection, int RNTI) {
    size_t i = 0;
    while (((NFAPI_CRC_INDICATION *)elements)[i].RNTI != RNTI) {
        i++;
    }

    if (i < capacity) {
        // Remove the element from the collection
        ((NFAPI_CRC_INDICATION *)elements)[i].RNTI = 0;

        return 0; // Success
    } else {
        return -1; // Element not found
    }
}

// Retrieve an element by its RNTI
int nfaPi_crc_indication_collection_get(void *collection, int RNTI, NFAPI_CRC_INDICATION_PDU_T *data) {
    size_t i = 0;
    while (((NFAPI_CRC_INDICATION *)elements)[i].RNTI != RNTI) {
        i++;
    }

    if (i < capacity) {
        // Retrieve the element from the collection
        *data = ((NFAPI_CRC_INDICATION *)elements)[i].data;

        return 0; // Success
    } else {
        return -1; // Element not found
    }
}

// Merge incoming data with the local collection
void nfaPi_crc_indication_collection_merge(void *collection, NFAPI_CRC_INDICATION_PDU_T *incoming_data) {
    size_t i = 0;
    while (i < capacity) {
        if (((NFAPI_CRC_INDICATION *)elements)[i].RNTI == 0) {
            // Add the incoming data to the collection
            ((NFAPI_CRC_INDICATION *)elements)[i].data = *incoming_data;

            return; // Done merging
        } else {
            i++;
        }
    }
}

// Release resources allocated by the function
void nfaPi_crc_indication_collection_free(void *collection) {
    free(collection);
}
