```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ARRAY_SIZE 1000
#define MEMORY_THRESHOLD_1 8000000
#define MEMORY_THRESHOLD_2 12000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfa_array = NULL;
int array_size = 0;
int array_capacity = MAX_ARRAY_SIZE;
int memory_usage = 0;

// Initialize the array
void init_nfa_array(int size) {
    if (size > array_capacity) {
        // Resize the array if necessary
        array_capacity = size * 2 + 1;
        nfa_array = realloc(nfa_array, array_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfa_array) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            return;
        }
    }

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* nfa = &((NFAPI_CRC_INDICATION_PDU_T*)nfa_array)[i];
        nfa->RX_UE_INFORMATION_TAG = rand();
        nfa->RNTI = rand();
        nfa->CRC_INDICATION_REL8_TAG = rand();
        // Set CRCFLAG based on a condition
        int sum_rnti = 0;
        for (int j = 0; j < i; j++) {
            sum_rnti += ((NFAPI_CRC_INDICATION_PDU_T*)nfa_array)[j].RNTI;
        }
        if (sum_rnti > MEMORY_THRESHOLD_1) {
            nfa->CRCFLAG |= 0x01;
        } else if (sum_rnti > MEMORY_THRESHOLD_2) {
            nfa->CRCFLAG |= 0x02;
        }
    }

    array_size = size;
}

// Validate unique RX_UE_INFORMATION_TAG values
void validate_nfa_array() {
    int* rx_tags = malloc(array_size * sizeof(int));
    if (!rx_tags) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < array_size; i++) {
        rx_tags[i] = ((NFAPI_CRC_INDICATION_PDU_T*)nfa_array)[i].RX_UE_INFORMATION_TAG;
    }

    // Create a hash table to store unique RX_UE_INFORMATION_TAG values
    int* hash_table = malloc(array_size * sizeof(int));
    if (!hash_table) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        free(rx_tags);
        return;
    }

    for (int i = 0; i < array_size; i++) {
        int tag = rx_tags[i];
        int j = 0;
        while (j < i) {
            if (hash_table[j] == tag) {
                // Duplicate found, reallocate the array and retry
                init_nfa_array(0);
                return;
            }
            j++;
        }
        hash_table[i] = tag;
    }

    free(rx_tags);
    free(hash_table);
}

int main() {
    // Initialize the array with at least N elements
    init_nfa_array(100);

    // Validate unique RX_UE_INFORMATION_TAG values
    validate_nfa_array();

    return 0;
}
