AesContext* init_cipher(const char* password) {
    // Derive the encryption key from the password using SHA-1 hash function
    unsigned char* key = (unsigned char*)malloc(32);
    SHA_CTX sha_ctx;
    SHA_Init(&sha_ctx);
    SHA_Update(&sha_ctx, password, strlen(password));
