int filter_frames(MAC_RX_FRAME_T **frames, int num_frames, int threshold) {
    int count = 0;
    for (int i = 0; i < num_frames; i++) {
        if ((*frames)[i]->sequence_number > threshold) {
            count++;
        }
    }
    return count;
}

void print_frame(MAC_RX_FRAME_T *frame) {
    printf("Sequence Number: %d\n", frame->sequence_number);
    printf("Payload Data: ");
    for (int i = 0; i < sizeof(frame->data); i++) {
        printf("%c", frame->data[i]);
    }
    printf("\n");
}

int main() {
    srand(time(NULL));
    int num_frames = 100;
    MAC_RX_FRAME_T **frames = (MAC_RX_FRAME_T **)malloc(num_frames * sizeof(MAC_RX_FRAME_T *));

    for (int i = 0; i < num_frames; i++) {
        frames[i] = (MAC_RX_FRAME_T *)malloc(sizeof(MAC_RX_FRAME_T));

        frames[i]->sequence_number = rand() % 10000;
        for (int j = 0; j < sizeof(frames[i]->data); j++) {
            frames[i]->data[j] = (char)(rand() % 256);
        }
    }

    int threshold = 5000;
    int filtered_count = filter_frames(frames, num_frames, threshold);

    printf("Filtered Frames: %d\n", filtered_count);

    for (int i = 0; i < num_frames; i++) {
        if ((*frames)[i]->sequence_number > threshold) {
            print_frame((*frames)[i]);
        }
    }

    for (int i = 0; i < num_frames; i++) {
        free(frames[i]);
    }
    free(frames);

    return 0;
}
