#define NR_PDU 1000
#define BUFFER_SIZE 1024

typedef struct {
    // SRS_UL_DCI and PUSCH_DCI instances
} NR_PDU;

NR_PDU* pool = NULL;
int pool_size = 0;
int pool_capacity = NR_PDU;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int error_code = 0;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        error_code = ENOMEM;
        return NULL;
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

NR_PDU* create_pdu() {
    NR_PDU* pdu = allocate_memory(sizeof(NR_PDU));
    if (!pdu) {
        return NULL;
    }
    // Initialize SRS_UL_DCI and PUSCH_DCI instances
    // ...
    return pdu;
}

void destroy_pdu(NR_PDU* pdu) {
    free(pdu);
}

int get_pdu_index(NR_PDU* pdu) {
    pthread_mutex_lock(&lock);
    int index = pool_size - 1;
    for (int i = 0; i < pool_size; i++) {
        if (pool[i] == pdu) {
            index = i;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return index;
}

void* allocate_pdu() {
    NR_PDU* pdu = create_pdu();
    if (!pdu) {
        error_code = ENOMEM;
        return NULL;
    }
    pthread_mutex_lock(&lock);
    if (pool_size >= pool_capacity) {
        // Reallocate the buffer
        void* buffer = allocate_memory(BUFFER_SIZE);
        if (!buffer) {
            error_code = ENOMEM;
            free(pdu);
            return NULL;
        }
        for (int i = 0; i < pool_size; i++) {
            buffer[i] = pdu[i];
        }
        destroy_pdu(pool);
        pool = buffer;
    }
    pthread_mutex_unlock(&lock);
    return pdu;
}

void deallocate_pdu(NR_PDU* pdu) {
    int index = get_pdu_index(pdu);
    if (index >= 0) {
        destroy_pdu(pool[index]);
        memmove(&pool[index], &pool[index + 1], pool_size - index - 1);
        pool_size--;
    }
}

void print_pool_info() {
    pthread_mutex_lock(&lock);
    printf("Pool size: %d, Capacity: %d\n", pool_size, pool_capacity);
    pthread_mutex_unlock(&lock);
}
