// Function to manage dynamic array of structures
int manage_crc_indication_pdu_array(int max_size, pthread_mutex_t* mutex, NFAPI_CRC_INDICATION_PDU_T** arr) {
    int size = 0;
    *arr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (*arr == NULL)
        return -1; // Memory allocation failed

    pthread_mutex_init(mutex, NULL);

    while (size < max_size) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL)
            return -1; // Memory allocation failed

        int rnti = rand() % INT_MAX;
        // Initialize other fields of the structure
        pdu->RX_UE_INFORMATION_TAG = ...;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = ...;
        pdu->CRCFLAG = (rand() % 2 == 0);

        if (pthread_mutex_lock(mutex) != 0)
            return -1; // Locking failed

        for (int i = 0; i < size; i++) {
            if ((*arr)[i]->RNTI == rnti) {
                free(pdu);
                pthread_mutex_unlock(mutex);
                return -2; // Duplicate RNTI detected
            }
        }

        (*arr)[size++] = pdu;

        pthread_mutex_unlock(mutex);
    }

    return 0;
}

int validate_rnti uniqueness(NFAPI_CRC_INDICATION_PDU_T** arr, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
