    struct NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return NULL;
    }

    for (i = 0; i < num_elements && i < MAX_LIST_SIZE; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            fprintf(log_file, "Error allocating memory for PDU.\n");
            break;
        }

        int rnti = rand() % 0x10000; // Generate a random RNTI
        pdu->RX_UE_INFORMATION_TAG = rand() % 0x100000; // Generate a random RX UE information tag
        pdu->RNTI = rnti;

        // Set CRCFLAG randomly
        int crcflag = rand() % 2;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        if (list == NULL) {
            list = pdu;
        } else {
            struct NFAPI_CRC_INDICATION_PDU_T* current_pdu = list;
            while (current_pdu != NULL && current_pdu->RNTI != rnti) {
                current_pdu = current_pdu->next;
            }

            if (current_pdu == NULL || current_pdu->next == NULL) {
                current_pdu->next = pdu;
            } else {
                // RNTI already exists in the list, return an error
                fprintf(log_file, "Error: Duplicate RNTI value.\n");
                free(pdu);
                break;
            }
        }
    }

    fclose(log_file);
    return list;
