} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_list(int N) {
    if (N < MIN_N || N > MAX_N) {
        printf("Invalid input parameter: N must be between %d and %d.\n", MIN_N, MAX_N);
        return;
    }

    srand(time(NULL)); // seed the random number generator

    // allocate memory dynamically for the list of structures
    NFAPI_CRC_INDATION_PDU_T* nfa_pds = (NFAPI_CRC_INDATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDATION_PDU_T));

    if (!nfa_pds) {
        printf("Memory allocation failed.\n");
        return;
    }

    // add elements to the list with thread-safe operations
    int i;
    for (i = 0; i < N; i++) {
        nfa_pds[i].RX_UE_INFORMATION_TAG = rand() % MAX_N;
        nfa_pds[i].RNTI = rand() % MAX_N;
        nfa_pds[i].CRC_INDICATION_REL8_TAG = rand() % MAX_N;
        nfa_pds[i].CRCFLAG = rand() % 2; // set CRCFLAG randomly

        printf("Element added: RX_UE_INFORMATION_TAG=%d, RNTI=%u, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
