#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define AGE_THRESHOLD 30 // in seconds
#define NODE_SIZE sizeof(struct NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

struct {
    pthread_mutex_t lock;
    struct node* head;
    struct node* tail;
    size_t count;
    size_t max_size;
    unsigned int age_threshold;
} nfa_pi_crc_list;

void init_list() {
    nfa_pi_crc_list.head = NULL;
    nfa_pi_crc_list.tail = NULL;
    nfa_pi_crc_list.count = 0;
    nfa_pi_crc_list.max_size = MAX_ELEMENTS;
    pthread_mutex_init(&nfa_pi_crc_list.lock, NULL);
}

int crc_indication_pdu_insert(NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* new_node;
    if ((new_node = malloc(NODE_SIZE)) == NULL)
        return -1;

    memcpy(&new_node->data, data, NODE_SIZE);

    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    if (nfa_pi_crc_list.head == NULL) {
        nfa_pi_crc_list.head = new_node;
        nfa_pi_crc_list.tail = new_node;
    } else {
        nfa_pi_crc_list.tail->next = new_node;
        nfa_pi_crc_list.tail = new_node;
    }
    nfa_pi_crc_list.count++;

    pthread_mutex_unlock(&nfa_pi_crc_list.lock);

    return 0;
}

int crc_indication_pdu_remove() {
    struct node* current;

    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    if (nfa_pi_crc_list.head == NULL) {
        pthread_mutex_unlock(&nfa_pi_crc_list.lock);
        return -1; // empty list
    }

    current = nfa_pi_crc_list.head;
    nfa_pi_crc_list.head = current->next;

    if (nfa_pi_crc_list.head == NULL)
        nfa_pi_crc_list.tail = NULL;

    free(current);

    nfa_pi_crc_list.count--;

    pthread_mutex_unlock(&nfa_pi_crc_list.lock);
}

int crc_indication_pdu_gc() {
    struct node* current;
    int removed_count = 0;

    pthread_mutex_lock(&nfa_pi_crc_list.lock);
    for (current = nfa_pi_crc_list.head; current != NULL;) {
        if ((current->data.age > AGE_THRESHOLD) && 
            (removed_count < nfa_pi_crc_list.count / 2)) { // age threshold exceeded
            struct node* prev = nfa_pi_crc_list.head;
            current = current->next;
            prev->next = current;
            free(prev);
            removed_count++;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&nfa_pi_crc_list.lock);

    return 0;
}

void* crc_indication_pdu_pool_allocator(size_t size) {
    // Memory pool allocator implementation
}
