typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createNfalistAndStateList(yaml_parser_t* yaml, int* statesCount) {
    NFAPI_CRC_INDICATION_PDU_T** nfalist = NULL;
    size_t nfalistSize = 0;
    size_t lastStateIndex = 0;

    // Initialize state list
    int* states = (int*)malloc(sizeof(int) * (*statesCount));
    if (!states) {
        return NULL;
    }

    yaml_event_t event;
    while (yaml_parser_parse(yaml, &event)) {
        if (event.type == YAML_SCALAR_NODE) {
            int state;
            yaml_scalar_node_t* scalar = &event.data.scalar;
            if (yamlevent_get_string(&scalar->value) && sscanf(scalar->value, "%d", &state) == 1) {
                states[lastStateIndex++] = state;
            }
        }

        yaml_event_delete(&event);
    }

    // Initialize NFA list
    size_t nfalistCount = 0;

    yaml_node_t* node;
    yaml_parser_get_current_event(yaml, &event);
    while (event.type == YAML_SEQUENCE_NODE) {
        node = yaml_sequence_begin(event.data.sequence);
        for (; node; yaml_sequence_next(&node)) {
            if (node->type == YAML_MAPPING_NODE) {
                NFAPI_CRC_INDICATION_PDU_T* nfa = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!nfa) {
                    free(states);
                    return NULL;
                }

                yaml_mapping_node_t* mapping = node->data.mapping;
                for (yaml_mapping_pair_t* pair = yaml_mapping_begin(mapping); pair; yaml_mapping_next(&pair)) {
                    if (strcmp(pair->key, "RX_UE_INFORMATION_TAG") == 0) {
                        nfa->RX_UE_INFORMATION_TAG = atoi(yamlevent_get_string(&pair->value));
                    }
                    else if (strcmp(pair->key, "RNTI") == 0) {
                        nfa->RNTI = atoi(yamlevent_get_string(&pair->value));
                    }
                    else if (strcmp(pair->key, "CRC_INDICATION_REL8_TAG") == 0) {
                        nfa->CRC_INDICATION_REL8_TAG = atoi(yamlevent_get_string(&pair->value));
                        nfa->CRCFLAG = rand() % 2;
                    }
                }

                nfalist[nfalistCount++] = nfa;
            }
        }

        yaml_event_delete(&event);
    }

    // Update state list and return NFA list
    for (size_t i = 0; i < nfalistCount; ++i) {
        if (!nfalist[i]) {
            free(states);
            for (size_t j = i + 1; j < nfalistSize; ++j) {
                free(nfalists[j]);
            }
            return NULL;
        }
    }

    int totalProcessedCRCs = 0;

    // Process NFA list
    for (size_t i = 0; i < nfalistCount; ++i) {
        // Initialize CRC indication data
        NFAPI_CRC_INDICATION_PDU_T* nfa = nfalist[i];
        // ... process nfa ...
        totalProcessedCRCs++;
    }

    yaml_parser_delete(yaml);
    free(states);

    return nfalist;
}']

