    double lte_phy_measurement2;
} LTE_PHY_MEASUREMENT;

struct {
    LTE_PHY_MEASUREMENT* measurements;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Measurements = {0};

void* custom_allocator(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && posix_memalign(&ptr, 16, size) != 0) {
        return NULL;
    }
    return ptr;
}

LTE_PHY_MEASUREMENT* initialize_measurements() {
    Measurements.measurements = custom_allocator(sizeof(LTE_PHY_MEASUREMENT));
    Measurements.capacity = 10;
    Measurements.count = 0;
    pthread_mutex_init(&Measurements.mutex, NULL);
    return Measurements.measurements;
}

void add_measurement(LTE_PHY_MEASUREMENT measurement) {
    pthread_mutex_lock(&Measurements.mutex);
    if (Measurements.count >= Measurements.capacity) {
        Measurements.capacity *= 2;
        Measurements.measurements = custom_allocator(sizeof(LTE_PHY_MEASUREMENT) * Measurements.capacity);
        memcpy(Measurements.measurements, Measurements.measurements, sizeof(LTE_PHY_MEASUREMENT) * Measures.count);
        free(Measurements.measurements - (Measurements.capacity / 2));
    }
    Measurements.measurements[Measurements.count++] = measurement;
    pthread_mutex_unlock(&Measurements.mutex);
}

int get_measurement_count() {
    pthread_mutex_lock(&Measurements.mutex);
    int count = Measurements.count;
    pthread_mutex_unlock(&Measurements.mutex);
    return count;
}

LTE_PHY_MEASUREMENT* filter_measurements(time_t start, time_t end) {
    LTE_PHY_MEASUREMENT* filtered_measurements = custom_allocator(sizeof(LTE_PHY_MEASUREMENT));
    size_t i, j = 0;
    pthread_mutex_lock(&Measurements.mutex);
    for (i = 0; i < Measurements.count; i++) {
        if (Measurements.measurements[i].timestamp >= start && Measurements.measurements[i].timestamp <= end) {
            filtered_measurements[j++] = Measurements.measurements[i];
        }
    }
    free(Measurements.measurements - (Measurements.capacity / 2));
    pthread_mutex_unlock(&Measurements.mutex);
    return filtered_measurements;
}

void clear_measurements() {
    pthread_mutex_lock(&Measurements.mutex);
    if (Measurements.count > 0) {
        Measurements.count = 0;
        free(Measurements.measurements - (Measurements.capacity / 2));
        pthread_mutex_unlock(&Measurements.mutex);
        pthread_mutex_destroy(&Measurements.mutex);
    }
}
