```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Structure to represent network connection status
typedef struct {
    int connectionID;
    time_t statusTime;
    float connectionQuality;
} NetworkConnectionStatus;

// Node structure for linked list of connection statuses
typedef struct node {
    NetworkConnectionStatus status;
    struct node* next;
} Node;

// Function to initialize and populate the array of connection statuses
void initNetworkConnectionStatusArray(int numConnections, pthread_mutex_t* mutex) {
    // Initialize the array with a default size
    int initialCapacity = 1000;
    NetworkConnectionStatus** connectionStatuses = (NetworkConnectionStatus**)malloc(initialCapacity * sizeof(NetworkConnectionStatus*));

    for (int i = 0; i < initialCapacity; i++) {
        connectionStatuses[i] = NULL;
    }

    // Initialize a mutex to ensure thread safety
    pthread_mutex_init(mutex, NULL);

    // Function to validate and populate the array of connection statuses
    void* validateAndPopulate(void* arg) {
        int* numConnectionsPtr = (int*)arg;

        for (int i = 0; i < *numConnectionsPtr; i++) {
            NetworkConnectionStatus* status = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));

            // Validate the connection ID, status time, and connection quality
            if (status != NULL) {
                // Initialize the connection status with random values
                status->connectionID = rand();
                status->statusTime = time(NULL);
                status->connectionQuality = 0.5f;

                // Ensure that the status time is within a valid range and the connection quality meets a minimum threshold for reliability
                if (status->statusTime >= 1 && status->statusTime <= 300 && status->connectionQuality >= 0.9) {
                    // Dynamically resize the array as needed to accommodate more connections
                    int newSize = (*numConnectionsPtr + 1) * 2;
                    NetworkConnectionStatus** newConnectionStatuses = (NetworkConnectionStatus**)realloc(connectionStatuses, newSize * sizeof(NetworkConnectionStatus*));

                    if (newConnectionStatuses != NULL) {
                        for (int j = *numConnectionsPtr; j < newSize; j++) {
                            newConnectionStatuses[j] = NULL;
                        }

                        // Insert the new connection status into the linked list
                        Node* newNode = (Node*)malloc(sizeof(Node));
                        newNode->status = *status;
                        newNode->next = NULL;

                        if (*numConnectionsPtr > 0) {
                            Node* current = connectionStatuses[*numConnectionsPtr - 1];
                            while (current != NULL && current->next != NULL) {
                                current = current->next;
                            }

                            current->next = newNode;
                        } else {
                            newConnectionStatuses[0] = &newNode->status;
                        }

                        *numConnectionsPtr += newSize - (*numConnectionsPtr + 1);
                    }
                }
            }

            free(status);
        }
    }

    // Create a thread pool to populate the array of connection statuses concurrently
    pthread_t* threads = (pthread_t*)malloc(initialCapacity * sizeof(pthread_t));
    for (int i = 0; i < initialCapacity; i++) {
        pthread_create(&threads[i], NULL, validateAndPopulate, &numConnections);
    }

    // Wait for the threads to finish
    for (int i = 0; i < initialCapacity; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);

    // Iterate over the linked list of connection statuses and retrieve specific connection details
    void printConnectionStatus(Node* node) {
        printf("Connection ID: %d\n", node->status.connectionID);
        printf("Status Time: %ld\n", (long int)node->status.statusTime);
        printf("Connection Quality: %.2f\n", node->status.connectionQuality);

        // Free the node
        free(node);
    }

    Node* current = connectionStatuses[0];
    while (current != NULL) {
        printConnectionStatus(current);
        current = current->next;
    }
}
```

The `initNetworkConnectionStatusArray` function initializes and populates an array of `NetworkConnectionStatus` structures, each containing a unique `connectionID`, a `statusTime`, and a `connectionQuality` metric. The function validates the input parameters for each connection status entry, ensuring that the `statusTime` is within a specified valid range and the `connectionQuality` meets a minimum threshold for reliability.

The function also dynamically resizes the array to accommodate up to 50,000 active connections, with a goal of minimizing memory overhead and maximizing speed. Each connection status entry is stored in a linked list structure to allow for efficient insertion and removal of entries during runtime.

The `validateAndPopulate` function is used by a thread pool to concurrently populate the array of connection statuses. The `printConnectionStatus` function iterates over the linked list of connection statuses and retrieves specific connection details.']

