using System;
using System.Security.Cryptography;
using System.Text;

public class MultiPartMessageProcessor
{
    private readonly string _key;
    private readonly byte[] _iv;

    public MultiPartMessageProcessor(string key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public void ProcessMessages(string message, Action<string> processMessageCallback, Func<string, bool> validateMessageCallback)
    {
        string[] parts = message.Split(new char[] { '|' }, StringSplitOptions.RemoveEmptyEntries);

        foreach (string part in parts)
        {
            try
            {
                byte[] encryptedData = Convert.FromBase64String(part);
                byte[] decryptedData = Decrypt(encryptedData);
                string plainText = Encoding.UTF8.GetString(decryptedData);

                if (!validateMessageCallback(plainText))
                {
                    continue;
                }

                processMessageCallback(plainText);
            }
            catch (Exception ex)
            {
                RecordFailure(ex.Message, part);
            }
        }
    }

    private byte[] Decrypt(byte[] encryptedData)
    {
        using (TripleDESCryptoServiceProvider cryptoProvider = new TripleDESCryptoServiceProvider())
        {
            cryptoProvider.Key = Convert.FromBase64String(_key);
            cryptoProvider.IV = _iv;

            using (MemoryStream ms = new MemoryStream(encryptedData))
            {
                using (CryptoStream cs = new CryptoStream(ms, cryptoProvider.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    byte[] buffer = new byte[cs.Length];
                    cs.Read(buffer, 0, buffer.Length);
                    return buffer;
                }
            }
        }
    }

    private void RecordFailure(string message, string part)
    {
        // Integrate with external logging service here
    }
}
