    }
    queue->metadata[queue->size] = metadata;
    memcpy(queue->buffer + queue->size * sizeof(VideoFrameMetadata), &metadata, sizeof(VideoFrameMetadata));
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

