} Event;

// Function to initialize and manage the dynamic list of events
EventList* initEventList() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    list->size = 0;
    list->capacity = 8; // Initial capacity for better memory usage
    list->events = (Event**)malloc(list->capacity * sizeof(Event*));
    return list;
}

// Function to add a new event to the list
void addEvent(EventList* list, Event* event) {
    if (list->size >= list->capacity) { // Check if list needs resizing
        list->capacity *= 2; // Double the capacity for better memory usage
        list->events = (Event*)realloc(list->events, list->capacity * sizeof(Event));
    }
    list->events[list->size] = event;
    list->size++;
}

// Function to update an existing event in the list
void updateEvent(EventList* list, int index, Event* updatedEvent) {
    if (index >= 0 && index < list->size) { // Check for valid index
        list->events[index]->timestamp = updatedEvent->timestamp;
        list->events[index]->type = updatedEvent->type;
        strcpy(list->events[index]->id, updatedEvent->id);
    } else {
        printf("Invalid index for updating event.\n");
    }
}

// Function to remove an event from the list
void removeEvent(EventList* list, int index) {
    if (index >= 0 && index < list->size) { // Check for valid index
        memmove(&list->events[index], &list->events[index + 1], (list->size - index - 1) * sizeof(Event));
        list->size--;
    } else {
        printf("Invalid index for removing event.\n");
    }
}

// Function to serialize the event list to disk
void serializeEventList(EventList* list, FILE* file) {
    int i;
    fwrite(&list->size, sizeof(int), 1, file); // Write the size of the event list
    for (i = 0; i < list->size; i++) { // Serialize each event in the list
        Event event = *(list->events[i]);
        fwrite(&event.timestamp, sizeof(time_t), 1, file);
        fwrite(&event.type, sizeof(int), 1, file);
        fwrite(event.id, strlen(event.id) + 1, 1, file); // Write the length of the ID and then the ID
    }
}

// Function to deserialize the event list from disk
EventList* deserializeEventList(FILE* file) {
    EventList* list = initEventList();
    int size;
    fread(&size, sizeof(int), 1, file); // Read the size of the event list
    for (int i = 0; i < size; i++) { // Deserialize each event in the list
        Event event;
        fread(&event.timestamp, sizeof(time_t), 1, file);
        fread(&event.type, sizeof(int), 1, file);
        int idLength;
        fread(&idLength, sizeof(int), 1, file); // Read the length of the ID
        event.id = (char*)malloc(idLength + 1);
        fread(event.id, idLength + 1, 1, file); // Read the ID and store it in a dynamically allocated buffer
        addEvent(list, &event); // Add the deserialized event to the list
    }
    return list;
}

// Function to query events within a specific time range
void queryEvents(EventList* list, int startTimestamp, int endTimestamp) {
    for (int i = 0; i < list->size; i++) { // Iterate through each event in the list
        Event event = *(list->events[i]);
        if (event.timestamp >= startTimestamp && event.timestamp <= endTimestamp) { // Check if the event falls within the specified time range
            printf("Event %s at timestamp %ld is of type %d.\n", event.id, event.timestamp, event.type);
        }
    }
}

// Function to handle concurrency issues when multiple threads access the list simultaneously
void handleConcurrency(EventList* list) {
    pthread_mutex_lock(&list->mutex); // Lock the mutex for thread safety
    // Perform operations on the event list that require thread safety
    pthread_mutex_unlock(&list->mutex); // Unlock the mutex after completing the operations
}

