// Function to create and populate a doubly-linked list of NFAPI_CRC_INDICATION_PDU_T structures
void* populate_list(int n, unsigned int* bitstream, pthread_mutex_t* mutex) {
    // Initialize the head and tail pointers for the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    // Iterate through the given bitstream array to create the linked list
    for (int i = 0; i < n; i++) {
