        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) return NULL;

        new_node->rx_ue_info.tag = rand() % 256;
        new_node->rnti = rand() % 65536;
        new_node->crc_ind_rel_tag.tag = rand() % 256;
        new_node->crcflag = (bitstream[i] & 1) ? 1 : 0;

        // Add the new node to the linked list with thread-safe operations
        pthread_mutex_lock(mutex);
        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
        pthread_mutex_unlock(mutex);
    }

    return (void*)tail; // Return the last node in the linked list
}

// Serialize the linked list to a binary file
int serialize_list(NFAPI_CRC_INDICATION_PDU_T* head, FILE* file) {
    // Write the number of nodes in the linked list
    fwrite(&head->next, sizeof(int), 1, file);

    // Iterate through the linked list and write each node's data to the file
    while (head) {
