        fwrite(&head->rnti, sizeof(uint16_t), 1, file);
        fwrite(&head->crc_ind_rel_tag.tag, sizeof(uint8_t), 1, file);
        fwrite(&head->crcflag, sizeof(int), 1, file);

        head = head->next;
    }

    return 0; // Successful serialization
}

// Deserialize the linked list from a binary file
NFAPI_CRC_INDICATION_PDU_T* deserialize_list(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

