        fread(&new_node->crc_ind_rel_tag.tag, sizeof(uint8_t), 1, file);
        fread(&new_node->crcflag, sizeof(int), 1, file);

        // Add the new node to the linked list with thread-safe operations
        pthread_mutex_lock(mutex); // Assuming a global mutex for this example
