    list->frames = realloc(list->frames, (list->frame_count + 1) * sizeof(LTE_PHY_RX_FRAME*));
    if (!list->frames) {
        pthread_mutex_unlock(&list->lock);
        for (size_t i = 0; i < list->frame_count; ++i)
            free(list->frames[i]->LTE_PHY_SRB1_BUFFER);
        for (size_t i = 0; i <= list->frame_count; ++i)
            free(list->frames[i]);
        free(list->frames);
        return;
    }

    list->frames[list->frame_count++] = new_frame;
    pthread_mutex_unlock(&list->lock);
}

