    if (!list) return;

    for (size_t i = 0; i < list->frame_count; ++i) {
        if (list->frames[i]->LTE_RX_TX_ID == LTE_RX_TX_ID) {
            free(list->frames[i]->LTE_PHY_SRB1_BUFFER);
