    time_t timestamp;
    int referenceCount;
} NFAPI_CRC_INDICATION_PDU_T;

// Define structure to represent a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Function to create a new node with given data and timestamp
Node* createNode(NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the beginning of the linked list
void insertAtBeginning(Node **head, NFAPI_CRC_INDICATION_PDU_T *newData) {
    Node *newNode = createNode(newData);
    if (*head != NULL) {
        newNode->next = *head;
        *head = newNode;
    } else {
        *head = newNode;
    }
}

// Function to delete a node from the linked list
void deleteNode(Node **head, NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *current = *head;
    Node *previous = NULL;

    while (current != NULL && current->data != data) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Not found

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Function to sort the linked list based on timestamp in ascending order
void sortList(Node **head) {
    Node *current = *head;
    Node *previous = NULL;

    while (current != NULL) {
        previous = current;
        current = current->next;
        previous->data->timestamp;
    }
}

// Function to destroy the linked list and free all allocated memory
void destroyList(Node **head) {
    Node *current = *head;
    Node *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

// Function to increment the reference count of a node
void incReferenceCount(Node **head, NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *current = *head;

    while (current != NULL && current->data != data) {
        current = current->next;
    }

    if (current == NULL) return; // Not found

    current->data->referenceCount++;
}

// Function to decrement the reference count of a node
void decReferenceCount(Node **head, NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *current = *head;

    while (current != NULL && current->data != data) {
        current = current->next;
    }

    if (current == NULL) return; // Not found

    if (--current->data->referenceCount <= 0) {
        deleteNode(head, current->data);
    }
}

// Function to add a new node with given data and timestamp
void addNode(Node **head, NFAPI_CRC_INDICATION_PDU_T *newData) {
    insertAtBeginning(head, newData);
    incReferenceCount(head, newData);
}

// Function to remove the first occurrence of a node with given data
void removeNode(Node **head, NFAPI_CRC_INDICATION_PDU_T *data) {
    deleteNode(head, data);
    decReferenceCount(head, data);
}

int main() {
    // Example usage:
    Node *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *newData1 = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newData1->RX_UE_INFORMATION_TAG = 0x1234;
    newData1->RNTI = 5678;
    strcpy(newData1->CRC_INDICATION_REL8_TAG, "Random CRC");
    newData1->CRCFLAG = 0x09;
    newData1->timestamp = time(NULL);
    newData1->referenceCount = 0;

    NFAPI_CRC_INDICATION_PDU_T *newData2 = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newData2->RX_UE_INFORMATION_TAG = 0x5678;
    newData2->RNTI = 9012;
    strcpy(newData2->CRC_INDICATION_REL8_TAG, "Random CRC");
    newData2->CRCFLAG = 0x04;
    newData2->timestamp = time(NULL);
    newData2->referenceCount = 0;

    addNode(&head, newData1);
    addNode(&head, newData2);

    // Sort the linked list
    sortList(&head);

    // Print the sorted list
    Node *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: 0x%x, RNTI: %d, CRC_INDICATION_REL8_TAG: %s, timestamp: %ld, referenceCount: %d\n",
               current->data->RX_UE_INFORMATION_TAG,
               current->data->RNTI,
               current->data->CRC_INDICATION_REL8_TAG,
               current->data->timestamp,
               current->data->referenceCount);
        current = current->next;
    }

    // Remove the first occurrence of a node with given data
    removeNode(&head, newData1);

    // Destroy the linked list and free all allocated memory
    destroyList(&head);

    return 0;
}
