    }
}

void freeTNL_RX_PACKET(TNL_RX_PACKET *packet) {
    free(packet->ip_header);
    free(packet->pdu);

    for (int i = 0; i < packet->frame.num_ipsdus; i++) {
        free(packet->ipsdus[i]);
    }

    free(packet->ipsdus);
}

void tnl_rx_config(TNL_RX_PACKET *packet, bool enable_checksum_validation) {
    // Initialize IP header and PDU
    packet->ip_header = init_ip_header();
    packet->pdu = init_pdu();

    // Reassemble IPSDUs from fragments
    for (int i = 0; i < packet->frame.num_ipsdus; i++) {
        packet->ipsdus[i] = reassemble_ip_pdu_fragments(packet->ipsdus[i]);
    }
}

void tnl_rx_process(TNL_RX_PACKET *packet) {
    // Process packet
    process_packet(packet);

    // Validate checksum if enabled
    if (enable_checksum_validation) {
        validate_checksum(packet);
    }
}

