#define MAX_BUFFER_SIZE (1 << 20) // 1MB

struct MAC_PDU_HEADER {
    uint16_t sourceMAC;
    uint16_t destinationMAC;
};

struct L2_PDU {
    // Custom structure for L2 PDU
};

struct TNL_RX_FRAME {
    struct MAC_PDU_HEADER header;
    struct L2_PDU l2PDU;
    void* macSDU; // Dynamically allocated array of MAC SDUs
    int buffer_size;
};

void initTNL_RX_FRAME(struct TNL_RX_FRAME** frames, int numFrames) {
    for (int i = 0; i < numFrames; i++) {
        struct TNL_RX_FRAME* frame = malloc(sizeof(struct TNL_RX_FRAME));
        if (!frame) {
            // Handle memory allocation failure
            continue;
        }
        frame->header.sourceMAC = 0;
        frame->header.destinationMAC = 0;
        frame->l2PDU = (struct L2_PDU)malloc(sizeof(struct L2_PDU));
        if (!frame->l2PDU) {
            // Handle memory allocation failure
            free(frame);
            continue;
        }
        int buffer_size = 1 << 10; // Default to 1024 bytes
        while (buffer_size <= MAX_BUFFER_SIZE && !is_power_of_two(buffer_size)) {
            buffer_size *= 2;
        }
        frame->macSDU = malloc(buffer_size * sizeof(void*));
        if (!frame->macSDU) {
            // Handle memory allocation failure
            free(frame);
            free(frame->l2PDU);
            continue;
        }
        frame->buffer_size = buffer_size;
        *frames = i < 0 ? NULL : frame;
    }
}

int is_power_of_two(int n) {
    return (n & (n - 1)) == 0;
}
