typedef struct {
    int port;
    CLIENT_INFO* client_info;
    void* data;
    size_t data_size;
} TCP_CONNECTION;

typedef struct {
    TCP_CONNECTION* connections;
    size_t num_connections;
} CONNECTIONS_LIST;

CONNECTIONS_LIST* init_connections_list() {
    CONNECTIONS_LIST* list = (CONNECTIONS_LIST*)malloc(sizeof(CONNECTIONS_LIST));
    list->connections = NULL;
    list->num_connections = 0;
    return list;
}

void add_connection(CONNECTIONS_LIST* list, TCP_CONNECTION* conn) {
    if (!list->connections) {
        list->connections = (TCP_CONNECTION*)malloc(sizeof(TCP_CONNECTION));
        *list->connections = *conn;
        list->num_connections = 1;
    } else {
        TCP_CONNECTION** new_connections = (TCP_CONNECTION**)realloc(list->connections, (list->num_connections + 1) * sizeof(TCP_CONNECTION*));
        if (!new_connections) {
            printf("Memory allocation failed\n");
            return;
        }
        new_connections[list->num_connections++] = conn;
    }
}

void update_connection(CONNECTIONS_LIST* list, TCP_CONNECTION* old_conn, TCP_CONNECTION* new_conn) {
    for (size_t i = 0; i < list->num_connections; i++) {
        if (*list->connections[i] == *old_conn) {
            *list->connections[i] = *new_conn;
            return;
        }
    }
}

void free_connections_list(CONNECTIONS_LIST* list) {
    for (size_t i = 0; i < list->num_connections; i++) {
        free(list->connections[i]->client_info);
        free(list->connections[i]->data);
    }
    free(list->connections);
    free(list);
}
