typedef struct {
    int UE_ID;
    int MEASUREMENT_TYPE;
    double MEASUREMENT_VALUE;
} NFAPI_RRC_UE_MEASUREMENTS_PDU_T;

void init_measurements_list(int* measurements_count, NFAPI_RRC_UE_MEASUREMENTS_PDU_T*** measurements_list) {
    *measurements_count = 0;
    *measurements_list = (NFAPI_RRC_UE_MEASUREMENTS_PDU_T**)malloc(1 * sizeof(NFAPI_RRC_UE_MEASUREMENTS_PDU_T*));
}

void add_measurement(int* measurements_count, NFAPI_RRC_UE_MEASUREMENTS_PDU_T*** measurements_list, double mean, double std_dev) {
    if (*measurements_count >= 1000) {
        // Handle overflow
        printf("Measurements list is full.\n");
        return;
    }

    NFAPI_RRC_UE_MEASUREMENTS_PDU_T* measurement = (NFAPI_RRC_UE_MEASUREMENTS_PDU_T*)malloc(sizeof(NFAPI_RRC_UE_MEASUREMENTS_PDU_T));
    if (!measurement) {
        printf("Memory allocation failed.\n");
        return;
    }

    measurement->UE_ID = *measurements_count;
    measurement->MEASUREMENT_TYPE = rand() % 3; // Randomly generate MEASUREMENT_TYPE
    measurement->MEASUREMENT_VALUE = exp(-((mean - (rand() % 100)) / (std_dev))) + mean;

    (*measurements_list) = realloc(*measurements_list, (*measurements_count + 1) * sizeof(NFAPI_RRC_UE_MEASUREMENTS_PDU_T*));
    if (!(*measurements_list)) {
        printf("Memory allocation failed.\n");
        free(measurement);
        return;
    }

    (*measurements_list)[*measurements_count] = measurement;
    (*measurements_count)++;
}

void serialize_measurements(NFAPI_RRC_UE_MEASUREMENTS_PDU_T** measurements_list, int measurements_count) {
    FILE* file = fopen("measurements.bin", "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return;
    }

    fwrite(&measurements_count, sizeof(int), 1, file);
    for (int i = 0; i < measurements_count; i++) {
        fwrite(&measurements_list[i]->UE_ID, sizeof(int), 1, file);
        fwrite(&measurements_list[i]->MEASUREMENT_TYPE, sizeof(int), 1, file);
        fwrite(&measurements_list[i]->MEASUREMENT_VALUE, sizeof(double), 1, file);
    }

    fclose(file);
}

int main() {
    int measurements_count = 0;
    NFAPI_RRC_UE_MEASUREMENTS_PDU_T** measurements_list;

    init_measurements_list(&measurements_count, &measurements_list);

    add_measurement(&measurements_count, &measurements_list, 10.5, 2.1);
    add_measurement(&measurements_count, &measurements_list, 10.5, 2.1);
    add_measurement(&measurements_count, &measurements_list, 8.7, 3.4);

    serialize_measurements(measurements_list, measurements_count);

    return 0;
}
