typedef struct {
    char* RX_UE_INFORMATION_TAG;
    int RNTI;
    char* CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateArray(int n) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        array[i].RX_UE_INFORMATION_TAG = (char*)malloc(32 * sizeof(char));
        array[i].RNTI = rand() % 100;
        array[i].CRC_INDICATION_REL8_TAG = (char*)malloc(32 * sizeof(char));

        sprintf(array[i].RX_UE_INFORMATION_TAG, "RX_%08X", i);
        sprintf(array[i].CRC_INDICATION_REL8_TAG, "CRC_%02x", rand() % 256);

        char* crcflag = (rand() % 2 ? "R" : "N");
        strcat(strcat(strcpy(array[i].RX_UE_INFORMATION_TAG, "RX_"), array[i].RX_UE_INFORMATION_TAG), crcflag);
    }

    return array;
}

unsigned char* getMD5Hash(const char* input) {
    unsigned char* output = (unsigned char*)malloc(16 * sizeof(unsigned char));
    int len = strlen(input);

    if(len > 0x10000) {
        // handle very long inputs
        for(int i=0; i<len; i+=1024) {
            MD5_CTX mdContext;
            const unsigned char* part = &input[i];
            size_t partLen = (i+1024 <= len) ? 1024 : len - i;

            MD5Init(&mdContext);
            MD5Update(&mdContext, part, partLen);
            MD5Final(output + i/1024 * 16, &mdContext);

            if(i+1024 >= len)
                break;
        }
    } else {
        MD5_CTX mdContext;
        MD5Update(&mdContext, (const unsigned char*)input, len);
        MD5Final(output, &mdContext);
    }

    return output;
}
