    // Scale array dynamically based on load factor and available memory
    NFAPI_CRC_INDICATION_PDU_T** scaled_configs = (NFAPI_CRC_INDICATION_PDU_T**)realloc(configs, (int)(load_factor * num_configs) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

