void* mem_alloc(MemAllocator* allocator, size_t size) {
    if (allocator->used_size + size > allocator->total_size) {
        // Reallocate memory if necessary
        MemAllocator new_allocator = create_allocator(2 * allocator->total_size);
        memcpy(new_allocator.mem_start, allocator->mem_start, allocator->used_size);
        free(allocator->mem_start);
        allocator = &new_allocator;
    }
    void* result = allocator->mem_start + allocator->used_size;
    allocator->used_size += size;
    return result;
}

void mem_free(MemAllocator* allocator, void* ptr) {
    if (ptr < allocator->mem_start || ptr > allocator->mem_start + allocator->total_size - 1)
