    if (nfapi_crc_list == NULL || size > MAX_LIST_SIZE) {
        free(nfapi_crc_list);
        nfapi_crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
