```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag; // randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool allocator
void* my_malloc(size_t size) {
    static void* memory_pool = NULL;
    static size_t total_size = 0, used_size = 0;

    if (!memory_pool) {
        memory_pool = malloc(4096); // initial block size is 4KB
        total_size += 4096;
        used_size = 0;
    }

    if (used_size + size > total_size) {
        // allocate a new block when the current one is full
        void* new_memory = realloc(memory_pool, total_size + 4096);
        memory_pool = new_memory;
        total_size += 4096;
    }

    void* ptr = memory_pool + used_size;
    used_size += size;

    return ptr;
}

void my_free(void* ptr) {
    static void* last_allocated = NULL;

    if (last_allocated != ptr) {
        // adjust the next available pointer
        last_allocated = ptr;
    }
}

// Linked list node structure with custom allocator
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node, *PNode;

// Initialize linked list
void init_list(PNode* head) {
    *head = NULL;
}

// Add new connection to the list
void add_connection(PNode* head, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    PNode new_node = (PNode)my_malloc(sizeof(Node));
    new_node->data = *new_data;
    new_node->next = *head;
    *head = new_node;
}

// Retrieve the count of successfully initialized connections
int get_connection_count(PNode head) {
    int count = 0;
    PNode curr = head;

