typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int validateRNTI(NFAPI_CRC_INDICATION_PDU_T** array, int size) {
    int* rntiSet = (int*)malloc(sizeof(int)*size);
    for (int i = 0; i < size; i++) {
        if (rntiSet[i] == 0) {
            rntiSet[i] = (*array)[i].RNTI;
        } else if (rntiSet[i] != (*array)[i].RNTI) {
            free(rntiSet);
            return -1; // duplicate RNTI found
        }
    }
    free(rntiSet);
    return 0; // all RNTI values are unique
}

int populateArray(NFAPI_CRC_INDICATION_PDU_T** array, int* size, int max) {
    for (int i = 0; i < *size && i < max; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand();
        (*array)[i].RNTI = rand() % 100;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand();
        (*array)[i].CRCFLAG = (rand() & 1);
    }
}

void printArray(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", 
               array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG, array[i].CRCFLAG);
    }
}

int main() {
    int max = 1024 / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* array;
    int attempts = 0;
    clock_t start = clock();

    while (1) {
        if (!(array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*max))) {
            printf("Memory allocation failed!\n");
            break; // exit on allocation failure
        }
        for (int i = 0; i < max; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand();
            array[i].RNTI = rand() % 100;
            array[i].CRC_INDICATION_REL8_TAG = rand();
            array[i].CRCFLAG = (rand() & 1);
        }
        if (validateRNTI(&array, max) >= 0) {
            printArray(array, max);
            free(array);
            break; // exit on successful population
        } else {
            attempts++;
            printf("Failed to populate array! Attempt %d\n", attempts);
            free(array);
        }
    }

    clock_t end = clock();
    double time_taken = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Population took %.2f seconds.\n", time_taken);

    return 0;
}
