void init_ue_ctx(lte_ue_context** pool, int capacity) {
    *pool = (lte_ue_context*)malloc(sizeof(lte_ue_context) * capacity);
    for(int i=0; i<capacity; i++) {
        (*pool)[i].rnti = -1;
        (*pool)[i].num_rbs = 0;
        (*pool)[i].rb_pool = NULL;
    }
}

int ue_ctx_add(lte_ue_context** pool, int capacity) {
    for(int i=0; i<capacity; i++) {
        if((*pool)[i].rnti == -1) {
            return i;
        }
    }
    return -1;
}

void ue_ctx_remove(lte_ue_context** pool, int idx, int capacity) {
    free((*pool)[idx].rb_pool);
    for(int i=idx; i<capacity-1; i++) {
        (*pool)[i] = (*pool)[i+1];
    }
    (*pool)[capacity-1].rnti = -1;
}

void ue_ctx_update(lte_ue_context* ctx, int num_rbs) {
    if(ctx->num_rbs != num_rbs) {
        free(ctx->rb_pool);
        ctx->rb_pool = (char**)malloc(sizeof(char*) * num_rbs);
        ctx->num_rbs = num_rbs;
    }
}

