    int Mcs;
    int Cqi;
    void* UCI;  // dynamically allocated buffer for uplink control information (UCI)
} UeStats;

int populate_ue_stats(int num_entries, int max_memory_usage) {
    int successful_allocations = 0;
    UeStats* ue_stats_array = NULL;
    size_t total_memory_usage = 0;
    size_t uci_buffer_size = 0; // variable buffer size for uplink control information (UCI)

    srand(time(NULL)); // seed random number generator

    while (successful_allocations < num_entries && total_memory_usage <= max_memory_usage) {
        UeStats* ue_stats;

        if (!(ue_stats = (UeStats*)malloc(sizeof(UeStats)))) {
            printf("Memory allocation failed!\n");
            break;  // fail gracefully and stop allocating
        }

        ue_stats->Rnti = rand() % 1000;  // random value for RNTI
        ue_stats->Mcs = rand() % 10;  // random value for MCS
        ue_stats->Cqi = rand() % 20 + 1;  // random value for CQI

        uci_buffer_size = sizeof(int) * (rand() % 50 + 5);  // allocate a buffer for UCI with random size between 5 and 55 integers
        if (!(ue_stats->UCI = malloc(uci_buffer_size))) {
            printf("Memory allocation failed! Total memory usage: %zu\n", total_memory_usage);
            free(ue_stats);  // deallocate partially initialized UE stats structure
            break;  // fail gracefully and stop allocating
        }

        for (int i = 0; i < uci_buffer_size / sizeof(int); i++) {
            ((int*)ue_stats->UCI)[i] = rand();  // initialize UCI buffer with random values
        }

        ue_stats_array = realloc(ue_stats_array, (successful_allocations + 1) * sizeof(UeStats));
        memcpy(&ue_stats_array[successful_allocations], &ue_stats, sizeof(UeStats));

        free(ue_stats);  // deallocate UE stats structure

        successful_allocations++;
        total_memory_usage += sizeof(UeStats) + uci_buffer_size;
    }

    if (total_memory_usage > max_memory_usage || ue_stats_array == NULL) {
        printf("Total memory usage exceeded! No entries allocated.\n");
    } else {
        printf("Successfully allocated %d UE stats structures within the given memory constraints!\n", successful_allocations);
    }

    free(ue_stats_array);  // deallocate dynamically allocated UE stats array

    return successful_allocations;
}
