#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PDU 1000
#define MIN_RNTI 1
#define MAX_RNTI 256
#define CRCFLAG_PROB 0.5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_pdu_list(int num_pdu, float crc_flag_prob, FILE* log_file) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    int rnti_range = MAX_RNTI - MIN_RNTI + 1;
    int i, j, k;

    // Initialize the random number generator
    srand(time(NULL));

    // Allocate memory for the PDU list (MINIMUM required)
    int min_required_pdu = num_pdu;
    if (min_required_pdu > MAX_PDU) {
        min_required_pdu = MAX_PDU;
    }
    pdu_list = malloc(min_required_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        // Fallback mechanism for memory allocation failure
        printf("Error allocating memory. Continuing with reduced performance.\n");
        return -1;
    }

    // Initialize the RNTI counter
    int current_rnti = MIN_RNTI;

    for (i = 0; i < num_pdu; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i % rnti_range;
        pdu_list[i].RNTI = current_rnti++;

        // Randomly set CRCFLAG
        double rand_num = (double)rand() / RAND_MAX;
        if (rand_num < crc_flag_prob) {
            pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 1;  // Set to true with given probability
        } else {
            pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;  // Set to false with complementary probability
        }

        // Log information about the PDU generation process
        fprintf(log_file, "Generated PDU %d: RNTI = %d, CRCFLAG = %s\n", i + 1, pdu_list[i].RNTI,
                (pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG ? "TRUE" : "FALSE"));
    }

    // Validate generated PDUs against a predefined schema
    for (i = 0; i < num_pdu; i++) {
        if (!validate_pdu(pdu_list + i)) {
            printf("Error: Invalid PDU %d.\n", i);
            return -1;
        }
    }

    // Reclaim unused memory blocks to optimize performance
    int reused_pdu = 0;
    for (i = num_pdu; i > 0; i--) {
        if (!validate_pdu(pdu_list + i - 1)) {
            // Free the PDU structure and move back one step
            free(pdu_list + i - 1);
            reused_pdu++;
            i--;
        } else {
            break;
        }
    }

    // Print statistics about the PDU generation process
    printf("PDU generation complete. Success rate: %f%%, Failed allocations: %d, Reused PDUs: %d\n",
           (num_pdu - reused_pdu) * 100.0 / num_pdu,
           reused_pdu,
           reused_pdu);

    // Log statistics about the PDU generation process
    fprintf(log_file, "PDU generation complete. Success rate: %.2f%%, Failed allocations: %d, Reused PDUs: %d\n",
            (num_pdu - reused_pdu) * 100.0 / num_pdu,
            reused_pdu,
            reused_pdu);

    return 0;
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validate the PDU structure against a predefined schema
    if (pdu->RX_UE_INFORMATION_TAG < MIN_RNTI || pdu->RX_UE_INFORMATION_TAG > MAX_RNTI) {
        return 0;  // Invalid RNTI value
    }

    if ((pdu->RNTI < MIN_RNTI || pdu->RNTI > MAX_RNTI) &&
        (pdu->RX_UE_INFORMATION_TAG < MIN_RNTI || pdu->RX_UE_INFORMATION_TAG > MAX_RNTI)) {
        return 0;  // Invalid RNTI value
    }

    if ((pdu->CRC_INDICATION_REL8_TAG.CRCFLAG != 1) && (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG != 0)) {
        return 0;  // CRC FLAG is not set to either true or false
    }

    return 1;  // Valid PDU structure
}

int main() {
    FILE* log_file = fopen("pdu_generation_log.txt", "w");
    if (!log_file) {
        printf("Error opening log file.\n");
        return -1;
    }

    int num_pdu = generate_pdu_list(100, 0.5, log_file);
    fclose(log_file);

    return num_pdu;
}
