    // Generate PDUs based on configuration
    for (int i = 0; i < cfg->num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rand() % 0x10000;
        pdu->RNTI = rand() % (cfg->rnti_range_start + cfg->rnti_range_end) + cfg->rnti_range_start;
        bool set_crc = rand() < (double)cfg->crc_prob;
        pdu->CRCFLAG = set_crc;

        // Ensure uniqueness of RNTI
        for (int j = 0; j < i; j++) {
            if (pdu->RNTI == list[j]->RNTI) {
                free(pdu);
                i--;
                break;
            }
        }

        *list = realloc(*list, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        (*list)[i] = pdu;
    }
}
