void* pool_alloc(size_t size) {
    static void* pool = NULL;
    static int remaining = 0;
    if (remaining == 0) {
        pool = malloc(size);
        remaining = (int)size / sizeof(void*);
    }
    return (void*) (((char*)pool) + (remaining--) * sizeof(void*));
}

void pool_free(void* ptr, size_t size) {
    static void* pool = NULL;
    int idx = (char*)ptr - ((char*)pool);
    pool = realloc(pool, (idx / sizeof(void*) + 1) * sizeof(void*));
    remaining += idx % sizeof(void*) > 0 ? 1 : -1;
}

