#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the structure to be stored in the linked list
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate and manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_manage_linked_list(int N, int M, int min_RNTI, int max_RNTI) {
    // Initialize the head of the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    for (int i = 0; i < M && i <= N; i++) {
        // Allocate memory for a new node
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (node) {
            // Generate random values for RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG and CRCFLAG
            node->RX_UE_INFORMATION_TAG = rand();
            node->CRC_INDICATION_REL8_TAG = rand();
            node->CRCFLAG = rand() % 2;

            // Ensure the RNTI value is within the specified valid range and does not repeat with previous nodes
            int rnti = rand() % (max_RNTI - min_RNTI + 1) + min_RNTI;
            while ((head && head->RNTI == rnti) || (i > 0 && node->RNTI == (node - 1)->RNTI)) {
                rnti = rand() % (max_RNTI - min_RNTI + 1) + min_RNTI;
            }
            node->RNTI = rnti;

            // Add the new node to the linked list
            if (!head) {
                head = node;
            } else {
                NFAPI_CRC_INDICATION_PDU_T* current = head;
                while (current -> next) {
                    current = current -> next;
                }
                current -> next = node;
            }
        }
    }

    // Sort the linked list based on RNTI in ascending order
    qsort(head, N, sizeof(NFAPI_CRC_INDICATION_PDU_T*), compare_rnti);

    return head;
}

// Function to compare two nodes based on their RNTI values for sorting purposes
int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* node_a = *(NFAPI_CRC_INDICATION_PDU_T**) a;
    NFAPI_CRC_INDICATION_PDU_T* node_b = *(NFAPI_CRC_INDICATION_PDU_T**) b;

    if (node_a -> RNTI < node_b -> RNTI) {
        return -1;
    } else if (node_a -> RNTI > node_b -> RNTI) {
        return 1;
    }

    return 0;
}
