            nfaPiCrcIndicationPduList = newList;
            maxNfaPiCrcIndicationPduListSize = newMaxSize;
        }
    }

    // Copy the structure to prevent aliasing
    NFAPI_CRC_INDICATION_PDU_T* newNfaPiCrcIndicationPdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(newNfaPiCrcIndicationPdu->RX_UE_INFORMATION_TAG, nfaPiCrcIndicationPdu->RX_UE_INFORMATION_TAG);
