    if (nfaPiCrcIndicationPduListSize > 0) {
        NFAPI_CRC_INDICATION_PDU_T* prevNfaPiCrcIndicationPdu = &nfaPiCrcIndicationPduList[nfaPiCrcIndicationPduListSize - 1];
