        prevNfaPiCrcIndicationPdu->RNTI++;
    }

    nfaPiCrcIndicationPduList = realloc(nfaPiCrcIndicationPduList, (nfaPiCrcIndicationPduListSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfaPiCrcIndicationPduList[nfaPiCrcIndicationPduListSize++] = newNfaPiCrcIndicationPdu;
