typedef struct LTE_Uplink_RRC_Notify_Tag {
    uint32_t ue_id;
    int num_channels;
    double *transmission_powers;
} LTE_Uplink_RRC_Notify_Tag;

// Custom memory pool with configurable block sizes
typedef struct MemoryPool {
    void **blocks;
    size_t block_size;
    size_t allocated_size;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->allocated_size = 0;
    pool->total_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void *allocate_memory_block(MemoryPool *pool) {
    void *ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated_size == 0) {
        ptr = malloc(pool->block_size);
        pool->blocks = &ptr;
        pool->allocated_size = pool->block_size;
    } else {
        ptr = *(void **)pool->blocks;
        pool->blocks++;
        *pool->blocks = NULL;
        pool->allocated_size -= pool->block_size;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Dynamic array of LTE_Uplink_RRC_Notify_Tag structures
typedef struct UplinkNotifyArray {
    MemoryPool *memory_pool;
    size_t capacity;
    LTE_Uplink_RRC_Notify_Tag **array;
} UplinkNotifyArray;

UplinkNotifyArray *create_uplink_notify_array(size_t initial_capacity) {
    UplinkNotifyArray *array = (UplinkNotifyArray *)malloc(sizeof(UplinkNotifyArray));
    array->memory_pool = create_memory_pool(initial_capacity);
    array->capacity = initial_capacity;
    array->array = (LTE_Uplink_RRC_Notify_Tag **)malloc(array->capacity * sizeof(LTE_Uplink_RRC_Notify_Tag *));
    return array;
}

int add_entry(UplinkNotifyArray *array, uint32_t ue_id, int num_channels, double *transmission_powers) {
    LTE_Uplink_RRC_Notify_Tag *entry = (LTE_Uplink_RRC_Notify_Tag *)allocate_memory_block(array->memory_pool);
    entry->ue_id = ue_id;
    entry->num_channels = num_channels;
    entry->transmission_powers = transmission_powers;
    array->array[ array->capacity++ % array->capacity ] = entry;
    return 0;
}

LTE_Uplink_RRC_Notify_Tag *get_entry(UplinkNotifyArray *array, uint32_t ue_id) {
    for (size_t i = 0; i < array->capacity; i++) {
        if (array->array[i]->ue_id == ue_id) {
            return array->array[i];
        }
    }
    return NULL;
}

void free_uplink_notify_array(UplinkNotifyArray *array) {
    for (size_t i = 0; i < array->capacity; i++) {
        free(array->array[i]);
    }
    free(array->memory_pool);
    free(array);
}
