}

int nfapi_crc_indication_pdu_validate(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->valid_RX_UE_INFORMATION_TAG < 1 || pdu->RNTI < 0) {
        perror("Invalid UE information");
        return -1;
    }
    return 0;
}

void nfapi_crc_indication_pdu_list_add(int seed, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&nfapi_crc_indication_pdu_lock);
    for (int i = 0; i < nfapi_crc_indication_pdu_list_size; i++) {
        if (nfapi_crc_indication_pdu_list[i].RNTI == pdu->RNTI) {
            perror("Duplicate RNTI");
            pthread_mutex_unlock(&nfapi_crc_indication_pdu_lock);
            return;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = nfapi_crc_indication_pdu_allocate(seed);
    if (!new_pdu) {
        pthread_mutex_unlock(&nfapi_crc_indication_pdu_lock);
        return;
    }
    for (int i = 0; i < BATCH_SIZE && i + nfapi_crc_indication_pdu_list_size < MAX_LIST_SIZE; i++) {
        new_pdu->RNTI += i;
        if (nfapi_crc_indication_pdu_validate(new_pdu) == -1) {
            pthread_mutex_unlock(&nfapi_crc_indication_pdu_lock);
            return;
        }
    }
    nfapi_crc_indication_pdu_list = realloc(nfapi_crc_indication_pdu_list, (nfapi_crc_indication_pdu_list_size + BATCH_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    if (!nfapi_crc_indication_pdu_list) {
        pthread_mutex_unlock(&nfapi_crc_indication_pdu_lock);
        return;
    }
    memcpy(nfapi_crc_indication_pdu_list + nfapi_crc_indication_pdu_list_size, new_pdu, BATCH_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapi_crc_indication_pdu_list_size += BATCH_SIZE;
    pthread_mutex_unlock(&nfapi_crc_indication_pdu_lock);
}

int nfapi_crc_indication_pdu_list_export(char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("File open failure");
        return -1;
    }
    for (int i = 0; i < nfapi_crc_indication_pdu_list_size; i++) {
        fwrite(&nfapi_crc_indication_pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
    fclose(fp);
    return 0;
}

int nfapi_crc_indication_pdu_list_restore(char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("File open failure");
        return -1;
    }
    rewind(fp);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        if (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp) != 1) {
            break;
        }
        nfapi_crc_indication_pdu_list = realloc(nfapi_crc_indication_pdu_list, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapi_crc_indication_pdu_list) {
            fclose(fp);
            return -1;
        }
        memcpy(nfapi_crc_indication_pdu_list + i, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    nfapi_crc_indication_pdu_list_size = i;
    fclose(fp);
    return 0;
}
