#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_LIST_SIZE 100
#define MEMORY_THRESHOLD 1024*1024 // 1MB
#define ALERT_THRESHOLD 0.8 // 80% of memory threshold

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* head = NULL;
int num_elements = 0;
int total_memory_allocated = 0;
double memory_usage = 0.0;
pthread_t resource_manager_thread;
pthread_cond_t alert_condition = PTHREAD_COND_INITIALIZER;

void* resource_manager(void* arg) {
    while (1) {
        pthread_mutex_lock(&list_lock);
        if (memory_usage >= ALERT_THRESHOLD * MEMORY_THRESHOLD) {
            printf("Memory usage threshold reached: %f%%\n", memory_usage / MEMORY_THRESHOLD * 100);
            pthread_cond_signal(&alert_condition);
        }
        pthread_mutex_unlock(&list_lock);

        usleep(100000); // adjust to desired monitoring interval
    }

    return NULL;
}

void add_element(NFAPI_CRC_INDICATION_PDU_T* new_element) {
    pthread_mutex_lock(&list_lock);

    if (num_elements >= MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* old_head = head;
        head = new_element->next;
        free(old_head);
        num_elements--;
    } else {
        new_element->next = head;
        head = new_element;
    }

    if (++num_elements > MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* old_head = head;
        head = new_element->next;
        free(old_head);
        num_elements--;
    }

    total_memory_allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    memory_usage = (double)total_memory_allocated / MEMORY_THRESHOLD;

    pthread_mutex_unlock(&list_lock);

    return;
}

void remove_old_element() {
    pthread_mutex_lock(&list_lock);

    if (num_elements > 0) {
        NFAPI_CRC_INDICATION_PDU_T* old_head = head;
        head = head->next;
        free(old_head);
        num_elements--;
    }

    pthread_mutex_unlock(&list_thread);

    return;
}

void configure(int m, int x) {
    MAX_LIST_SIZE = m;
    MEMORY_THRESHOLD = x;

    // Initialize and start the resource manager thread
    pthread_create(&resource_manager_thread, NULL, &resource_manager, NULL);
}
