typedef struct VideoFrameQueue {
    int size;
    int front;
    int rear;
    struct NFAPI_CRC_INDICATION_PDU_T** frames;
} VideoFrameQueue;

void initializeQueue(VideoFrameQueue* queue, int max_size) {
    queue->size = 0;
    queue->front = 0;
    queue->rear = 0;
    queue->frames = (struct NFAPI_CRC_INDICATION_PDU_T**)malloc(max_size * sizeof(struct NFAPI_CRC_INDICATION_PDU_T*));
}

void enqueue(VideoFrameQueue* queue, struct NFAPI_CRC_INDICATION_PDU_T* frame) {
    if (queue->size == queue->rear - queue->front + 1) {
        // Queue full, handle overflow
        queue->frames = realloc(queue->frames, (queue->size * 2 + 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T*));
        queue->rear = queue->size;
    }
    queue->frames[queue->rear] = frame;
    queue->rear = (queue->rear + 1) % queue->size;
    queue->size++;
}

struct NFAPI_CRC_INDICATION_PDU_T* dequeue(VideoFrameQueue* queue) {
    if (queue->size == 0) {
        // Queue empty, handle underflow
        return NULL;
    }
    struct NFAPI_CRC_INDICATION_PDU_T* frame = queue->frames[queue->front];
    queue->front = (queue->front + 1) % queue->size;
    queue->size--;
    return frame;
}

void freeQueue(VideoFrameQueue* queue) {
    free(queue->frames);
}
