// Function to initialize and manage the pipeline
void* manage_pipeline(void* arg) {
    // Allocate memory for the pipeline structures
    RTCP_Packet* current_packet = (RTCP_Packet*)malloc(sizeof(RTCP_Packet));
    RTCP_Packet** packet_list = (RTCP_Packet**)malloc(sizeof(RTCP_Packet*) * 10); // initial buffer size of 10 packets

    pthread_mutex_t mutex;
    pthread_cond_t cond;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    while (1) {
        // Wait for new packet arrival
        pthread_mutex_lock(&mutex);
        pthread_cond_wait(&cond, &mutex);

        // Process the newly arrived packet
        process_packet(current_packet); // custom function to handle packet processing

        // Store the processed packet in the buffer
        packet_list[packet_list_size] = current_packet;
        packet_list_size++;

        if (packet_list_size >= 10) { // resizing the buffer
            RTCP_Packet** new_buffer = (RTCP_Packet**)realloc(packet_list, sizeof(RTCP_Packet*) * 20);
            memcpy(new_buffer, packet_list, sizeof(RTCP_Packet*) * 10);
            free(packet_list);
            packet_list = new_buffer;
        }

        pthread_mutex_unlock(&mutex);
    }
}

// Function to process the newly arrived RTCP packet
void process_packet(RTCP_Packet* packet) {
    // Demultiplex and validate the audio stream
    demux_audio_stream(packet->audio_samples);

    // Update the timestamp, sequence number, and SSRC metadata
    update_metadata(packet);
}

int main() {
    pthread_t thread;

    pthread_create(&thread, NULL, manage_pipeline, NULL);

    return 0;
}
