typedef struct VideoFrameQueue {
    int timestamp;
    int sequenceNumber;
    int payloadType;
    void* frameData;
} VideoFrameQueue;

void initializeQueue(VideoFrameQueue** queue, int capacity) {
    *queue = (VideoFrameQueue*)malloc(sizeof(VideoFrameQueue) * capacity);
}

int enqueue(VideoFrameQueue* queue, int capacity, void* frameData) {
    for(int i=0; i<capacity; i++) {
        if(queue[i].frameData == NULL) {
            queue[i].frameData = frameData;
            return 1;
        }
    }
    return -1;
}

void dequeue(VideoFrameQueue** queue, int capacity) {
    for(int i=0; i<capacity; i++) {
        if(queue[i].frameData != NULL) {
            queue[i].frameData = NULL;
            break;
        }
    }
}

int main() {
    VideoFrameQueue* queue = NULL;
    initializeQueue(&queue, 10);

    for(int i=0; i<5; i++) {
        enqueue(queue, 10, (void*)i);
    }

    for(int i=0; i<5; i++) {
        dequeue(&queue, 10);
    }

    return 0;
}
