#include <string.h>
#include <time.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(pdu_array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    for(int i = 0; i < n; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG[15] = 'X';
        pdu_array[i].RNTI = rand() % 1000000;

        // Generate random CRC flag
        uint16_t crcflag = (uint16_t)rand();
        pdu_array[i].CRC_INDICATION_REL8_TAG.crcflag = crcflag;
    }

    return pdu_array;
}

int main() {
    int n = 10000; // Number of elements to create
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_crc_indication_pdu(n);

    if(pdu_array == NULL) {
        printf("Memory allocation failed.\n");
    } else {
        printf("Array created successfully with %d elements.\n", n);

        // Verify CRC flags
        for(int i = 0; i < n; i++) {
            uint16_t computed_crc = compute_crc(&pdu_array[i]);

            if(computed_crc != pdu_array[i].CRC_INDICATION_REL8_TAG.crcflag) {
                printf("Error: CRC flag mismatch at index %d.\n", i);
            }
        }

        // Free allocated memory
        free(pdu_array);
    }

    return 0;
}

uint16_t compute_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    uint16_t crc = 0;

    crc = (crc >> 1) | (crc & 1);
    crc ^= (uint16_t)pdu->RX_UE_INFORMATION_TAG[0];
    crc ^= (uint16_t)pdu->RNTI;

    return crc;
}
