void manageTrafficEvents(TrafficEvent** trafficEvents, int* capacity, int* size) {
    // Allocate memory for a new event if necessary
    if (*size >= *capacity && *size < 2 * *capacity) {
        *capacity *= 2;
        *trafficEvents = (TrafficEvent**)realloc(*trafficEvents, sizeof(TrafficEvent*) * *capacity);
    }

    // Clear outdated events periodically
    int i;
    for (i = *size - 1; i >= 0; i--) {
        if (trafficEvents[i]->timestamp < (int)time(NULL) - 3600) { // remove events older than 1 hour
            memmove(&trafficEvents[i], &trafficEvents[i + 1], sizeof(TrafficEvent*) * (*size - i - 1));
            (*size)--;
        } else {
            break;
        }
    }

    // Resize the array when necessary
    if (*size < *capacity / 2) {
        *capacity /= 2;
        *trafficEvents = (TrafficEvent**)realloc(*trafficEvents, sizeof(TrafficEvent*) * *capacity);
    }
}

