    if (!list) return NULL;

    for (int i = 0; i < size; i++) {
        strcpy(list[i].src_ip, "0.0.0.0");
        strcpy(list[i].dst_ip, "0.0.0.0");
        list[i].src_port = -1;
        list[i].dst_port = -1;
        list[i].checksum = 0;
    }

    return list;
}

void free_packet_header_list(packet_header_t* list) {
    if (!list) return;

    free(list);
}

int validate_packet_header(packet_header_t* header) {
    // Validate IP formats
    if (strlen(header->src_ip) != 15 || strlen(header->dst_ip) != 15) {
        // Log error and return error code
        return -1;
    }

    // Validate port numbers
    if (header->src_port < 0 || header->src_port > 65535 ||
        header->dst_port < 0 || header->dst_port > 65535) {
        // Log error and return error code
        return -2;
    }

    // Validate checksum
    if (header->checksum != 0xFFFFFFFF) {
        // Log error and return error code
        return -3;
    }

    return 0;
}

void update_packet_header(packet_header_t* header, int src_port, int dst_port, unsigned int checksum) {
    // Update packet header fields
    header->src_port = src_port;
    header->dst_port = dst_port;
    header->checksum = checksum;
