    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateArray(int n) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    for (int i = 0; i < 3 && i < n; ++i) {
        int size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        array = realloc(array, (i + 1) * size);

        if (array == NULL) {
            printf("Memory allocation failed. Exiting.\n");
            return NULL;
        }

        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = i;
        array[i].CRC_INDICATION_REL8_TAG = i;
        array[i].CRCFLAG = rand() % 2;
    }

    for (int i = n - 1; i >= 0; --i) {
        free(&array[i]);
    }

    free(array);

    return NULL;
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    NFAPI_CRC_INDICATION_PDU_T* array = allocateArray(n);

    if (array != NULL) {
        for (int i = 0; i < n; ++i) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG, array[i].CRCFLAG);
        }
    } else {
        printf("Error occurred during memory allocation.\n");
    }

