    for (int i = 0; i < capacity; i++) {
        if (!frame_info_array[i]) {
            frame_info_array[i] = frame_info;
            return;
        }
    }
}

// Function to update an existing frame information entry
void lte_frame_info_update(LTE_DL_FRAMEINFO** frame_info_array, int capacity, LTE_DL_FRAMEINFO* frame_info) {
    for (int i = 0; i < capacity; i++) {
        if (frame_info_array[i] == frame_info) {
            // Update the existing entry here
            return;
        }
    }
}

// Function to safely iterate over the array without causing race conditions
void lte_frame_info_iterate(LTE_DL_FRAMEINFO** frame_info_array, int capacity, void (*callback)(LTE_DL_FRAMEINFO*)) {
    for (int i = 0; i < capacity; i++) {
        if (frame_info_array[i]) {
            callback(frame_info_array[i]);
        }
    }
}

// Function to periodically clean up unused entries
void lte_frame_info_cleanup(LTE_DL_FRAMEINFO** frame_info_array, int capacity) {
    // Implement your cleanup logic here
}

// Function to free the dynamic array and its contents
void lte_frame_info_free(LTE_DL_FRAMEINFO** frame_info_array, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (frame_info_array[i]) {
            free(frame_info_array[i]);
        }
