void add_ue_context(UE_Context* ue);
void remove_ue_context(int index);
int validate_ue_context(UE_Context* ue);

// Function to initialize and manage the dynamic list of LTE UE Contexts
void manage_ue_context_list() {
    int num_ue = 0;
    UE_Context **ue_list = NULL;

    init_ue_context_list();

    while (1) {
        printf("Enter 'add' to add a new UE context, 'remove' to remove an existing one, or 'quit' to exit:\n");
        char choice[6];
        scanf("%s", choice);

        if (strcmp(choice, "add") == 0) {
            UE_Context* ue = (UE_Context*)malloc(sizeof(UE_Context));
            add_ue_context(ue);
            num_ue++;
        } else if (strcmp(choice, "remove") == 0) {
            int index;
            printf("Enter the index of the UE context to remove:\n");
            scanf("%d", &index);
            remove_ue_context(index);
            num_ue--;
        } else if (strcmp(choice, "quit") == 0) {
            break;
        }
    }

    for (int i = 0; i < num_ue; i++) {
        free(ue_list[i]->mac_ce);
        free(ue_list[i]->rrc_message);
        free(ue_list[i]);
    }
    free(ue_list);

    printf("UE context list has been managed.\n");
}

void init_ue_context_list() {
    // Initialize the UE context list with a certain size
    int num_ue = 10;
    UE_Context **ue_list = (UE_Context**)malloc(num_ue * sizeof(UE_Context*));

    for (int i = 0; i < num_ue; i++) {
        ue_list[i] = NULL;
    }
}

void add_ue_context(UE_Context* ue) {
    // Add the new UE context to the list
    int index = num_ue++;
    ue_list[index] = ue;
}

void remove_ue_context(int index) {
    // Remove the UE context at the given index from the list
    if (index < 0 || index >= num_ue) {
        printf("Invalid index.\n");
        return;
    }

    free(ue_list[index]->mac_ce);
    free(ue_list[index]->rrc_message);
    free(ue_list[index]);
    ue_list[index] = NULL;

    // Shift the remaining UE contexts to fill the gap
