typedef struct {
    pthread_mutex_t lock;
    UE_Context *contexts;
    int count;
    int cache_size;
    int cache_count;
    UE_Context **cache;
} LTE_UeContexts;

void lte_ue_context_init(LTE_UeContexts *ue_ctxs, int cache_size) {
    ue_ctxs->count = 0;
    ue_ctxs->cache_size = cache_size;
    ue_ctxs->cache_count = 0;
    ue_ctxs->cache = (UE_Context **)malloc(sizeof(UE_Context *) * cache_size);
    for (int i = 0; i < cache_size; i++) {
        ue_ctxs->cache[i] = NULL;
    }
}

void lte_ue_context_insert(LTE_UeContexts *ue_ctxs, UE_Context *ctx) {
    pthread_mutex_lock(&ue_ctxs->lock);
    if (ue_ctxs->count >= 50000) {
        printf("Error: Maximum number of UE contexts reached.\n");
        return;
    }

    // Dynamic memory allocation for new context
    ctx = (UE_Context *)malloc(sizeof(UE_Context));
    strcpy(ctx->mac_ce, ue_ctxs->contexts[ue_ctxs->count].mac_ce);
    strcpy(ctx->rrc_message, ue_ctxs->contexts[ue_ctxs->count].rrc_message);
    ue_ctxs->count++;

    // Cache management
    if (ue_ctxs->cache_count < ue_ctxs->cache_size) {
        for (int i = 0; i < ue_ctxs->cache_size; i++) {
            if (ue_ctxs->cache[i] == NULL) {
                ue_ctxs->cache[i] = ctx;
                break;
            }
        }
        ue_ctxs->cache_count++;
    } else {
        // Replace the least recently used cache entry
        int min_index = 0, min_time = -1;
        for (int i = 0; i < ue_ctxs->cache_size; i++) {
            if (ue_ctxs->cache[i] != NULL && ue_ctxs->cache[i]->time_used < min_time) {
                min_index = i;
                min_time = ue_ctxs->cache[i]->time_used;
            }
        }
        ue_ctxs->cache[min_index] = ctx;
    }

    pthread_mutex_unlock(&ue_ctxs->lock);
}

void lte_ue_context_update(LTE_UeContexts *ue_ctxs, char mac_ce[], char rrc_message[]) {
