#include <condition_variable>

class NetworkEvent {
public:
    // Event details (e.g., timestamp, source, data)
    std::string timestamp;
    std::string source;
    std::string data;

    NetworkEvent(const std::string& ts, const std::string& src, const std::string& d)
        : timestamp(ts), source(src), data(d) {}
};

class NetworkEventManager {
public:
    NetworkEventManager() : eventList(), cleanupInterval(1000), maxEvents(10000),
        isCleaningUp(false), lock(), cv() {}

    void addEvent(const NetworkEvent& event) {
        std::unique_lock<std::mutex> ul(lock);
        eventList.push_back(event);
        if (eventList.size() > maxEvents)
            resizeIfNeeded();
        cv.notify_one(); // Notify waiting threads
    }

    void updateEvent(size_t index, const NetworkEvent& newEvent) {
        std::unique_lock<std::mutex> ul(lock);
        if (index < eventList.size()) {
            auto it = eventList.begin() + index;
            *it = newEvent; // Update in place
        }
    }

    void removeExpiredEvents() {
        std::unique_lock<std::mutex> ul(lock);
        while (!isCleaningUp) { // Wait until cleanup is allowed
            cv.wait(ul, [this] { return !isCleaningUp; });
        }
        for (auto it = eventList.begin(); it != eventList.end();) {
            if (it->timestamp.empty() || it->timestamp.size() > 1024) { // Remove expired events
                it = eventList.erase(it);
            } else
                ++it;
        }
        isCleaningUp = false; // Cleanup completed
    }

    size_t getActiveEventCount() {
        std::unique_lock<std::mutex> ul(lock);
        return eventList.size();
    }

    std::list<NetworkEvent> getEventsBySource(const std::string& source) {
        std::unique_lock<std::mutex> ul(lock);
        std::list<NetworkEvent> result;
        for (auto it = eventList.begin(); it != eventList.end(); ++it) {
            if (it->source == source)
                result.push_back(*it);
        }
        return result;
    }

private:
    void resizeIfNeeded() {
        // Implement dynamic resizing logic
    }

    std::list<NetworkEvent> eventList;
    size_t cleanupInterval; // milliseconds
    bool isCleaningUp;
    std::mutex lock;
    std::condition_variable cv;
};
