#include <stdlib.h>
#include <string.h>

typedef struct {
    // MAC_Header structure
    uint8_t mac_header[16];

    // TransportBlock structure
    uint32_t transport_block;

    // TransmissionTimingAdvance field
    int transmission_timing_advance;
} LTE_TransportChannel;

// Function to initialize and populate a dynamically allocated array of LTE_TransportChannel structures
void initialize_transport_channels(struct LTE_TransportChannel **channels, size_t *num_channels) {
    *num_channels = 0; // Initialize the number of channels

    size_t initial_capacity = 10000;
    struct LTE_TransportChannel *initial_channels = (struct LTE_TransportChannel *)malloc(initial_capacity * sizeof(LTE_TransportChannel));

    for (size_t i = 0; i < initial_capacity; i++) {
        initial_channels[i].mac_header[0] = 1; // Initialize MAC Header
        initial_channels[i].transport_block = 2; // Initialize Transport Block
        initial_channels[i].transmission_timing_advance = 3; // Initialize Transmission Timing Advance

        (*num_channels)++;
    }

    struct LTE_TransportChannel **channels_array = (struct LTE_TransportChannel **)malloc(initial_capacity * sizeof(struct LTE_TransportChannel *));
    for (size_t i = 0; i < initial_capacity; i++) {
        channels_array[i] = &initial_channels[i];
    }

    // Dynamically resize the array to accommodate additional channels
    size_t capacity = initial_capacity;
    while (*num_channels >= capacity) {
        capacity *= 2; // Double the capacity

        struct LTE_TransportChannel *new_channels = (struct LTE_TransportChannel *)realloc(initial_channels, capacity * sizeof(LTE_TransportChannel));
        if (!new_channels) {
            free(channels_array);
            free(initial_channels);
            *num_channels = 0;
            return;
        }

        initial_channels = new_channels;

        struct LTE_TransportChannel **new_channels_array = (struct LTE_TransportChannel **)realloc(channels_array, capacity * sizeof(struct LTE_TransportChannel *));
        if (!new_channels_array) {
            free(channels_array);
            free(initial_channels);
            *num_channels = 0;
            return;
        }

        channels_array = new_channels_array;

        for (size_t i = capacity / 2; i < capacity; i++) {
            initial_channels[i].mac_header[0] = 1; // Initialize MAC Header
            initial_channels[i].transport_block = 2; // Initialize Transport Block
            initial_channels[i].transmission_timing_advance = 3; // Initialize Transmission Timing Advance

            (*num_channels)++;
        }
    }

    *channels = channels_array;
}

// Function to return the total number of successfully initialized channels, including those resized during initialization
size_t get_total_channels(const struct LTE_TransportChannel **channels) {
    return channels ? *channels : 0;
}
