#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    char* ip;
    int port;
    void* buffer;
} tcp_context;

typedef struct {
    tcp_context* contexts;
    int context_count;
    pthread_mutex_t lock;
} connection_manager;

connection_manager* create_connection_manager() {
    connection_manager* manager = (connection_manager*)malloc(sizeof(connection_manager));
    manager->contexts = NULL;
    manager->context_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_context(connection_manager* manager, char* ip, int port) {
    tcp_context* context = (tcp_context*)malloc(sizeof(tcp_context));
    context->ip = strdup(ip);
    context->port = port;
    context->buffer = malloc(1024); // assume 1KB buffer
    pthread_mutex_lock(&manager->lock);
    manager->contexts = realloc(manager->contexts, sizeof(tcp_context) * (manager->context_count + 1));
    manager->contexts[manager->context_count] = context;
    manager->context_count++;
    pthread_mutex_unlock(&manager->lock);
}

void remove_context(connection_manager* manager, int index) {
    if(index < 0 || index >= manager->context_count)
        return; // handle invalid index
    pthread_mutex_lock(&manager->lock);
    free(manager->contexts[index]->ip);
    free(manager->contexts[index]->buffer);
    free(manager->contexts[index]);
    for(int i = index; i < manager->context_count - 1; i++) {
        manager->contexts[i] = manager->contexts[i+1];
    }
    manager->context_count--;
    pthread_mutex_unlock(&manager->lock);
}

tcp_context* get_context(connection_manager* manager, int index) {
