        if (new_node->crc_indication.crcflag < 0 || new_node->crc_indication.crcflag > 7) {
            free(new_node);
            printf("Invalid CRCFLAG value.\n");
            return;
        }

        if (*head == NULL) {
            *head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }
}

int find_duplicate_rnti(NFAPI_CRC_INDICATION_PDU_T* head, int rnti_value) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        if (current->rnti == rnti_value) {
            return 1;
        }
        current = current->next;
    }
