// Function to manage dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_pdu_list(int K, int max_crc_indications, MemoryAllocator* allocator) {
    // Initialize the list and its size indicator
    NFAPI_CRC_INDICATION_PDU_T** crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    int crc_indication_count = 0;

    // Loop until the list is full or the specified limit is reached
    while (crc_indication_count < K) {
        NFAPI_CRC_INDICATION_PDU_T* new_crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_crc_indication) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            break;
        }

        // Get the RNTI and validate uniqueness
        int rnti = new_crc_indication->RNTI;
        bool is_rnti_unique = true;
        for (int i = 0; i < crc_indication_count; i++) {
            if (crc_indication_list[i]->RNTI == rnti) {
                is_rnti_unique = false;
                break;
            }
        }

        // Insert the new CRC indication only if RNTI is unique
        if (is_rnti_unique) {
            crc_indication_list[crc_indication_count++] = new_crc_indication;
        } else {
            free(new_crc_indication);
        }
    }

    // Purge older entries from the list to make space for new ones
    for (int i = 0; i < K - max_crc_indications; i++) {
        free(crc_indication_list[i]);
    }

    // Deallocate memory and reset the size indicator
    for (int i = 0; i < crc_indication_count; i++) {
        free(crc_indication_list[i]);
    }
    free(crc_indication_list);
}
