#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_elements 1000000
#define RNTI_RANGE_MIN 1
#define RNTI_RANGE_MAX 255

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int unique_RNTIs[MAX_elements];
int total_unique_RNTIs = 0;

void* create_NFAPI_CRC_INDICATION_PDU_T(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    int rnti = rand() % (RNTI_RANGE_MAX - RNTI_RANGE_MIN + 1) + RNTI_RANGE_MIN;
    while (unique_RNTIs[rnti] || find_NFAPI_CRC_INDICATION_PDU_T(rnti)) {
        rnti = rand() % (RNTI_RANGE_MAX - RNTI_RANGE_MIN + 1) + RNTI_RANGE_MIN;
    }

    pdu->RX_UE_INFORMATION_TAG = (int)arg;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand();
    pdu->CRCFLAG = rand();

    unique_RNTIs[pdu->RNTI] = 1;

    total_unique_RNTIs++;

    clock_t start, end;
    start = clock();
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open the log file.\n");
        return NULL;
    }
    fprintf(log_file, "Created NFAPI_CRC_INDICATION_PDU_T with RX_UE_INFORMATION_TAG: %d and RNTI: %d in %.5f seconds.\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, (double)(clock() - start) / CLOCKS_PER_SEC);
    fclose(log_file);

    return pdu;
}

int find_NFAPI_CRC_INDICATION_PDU_T(int rnti) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_elements; i++) {
        if (unique_RNTIs[i] && unique_RNTIs[i] == rnti) {
            pthread_mutex_unlock(&lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&lock);

    return 0;
}

void release_NFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    free(pdu);
}
