typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void crc_indications_serialize(NFAPI_CRC_INDICATION_PDU_T* indications, int n) {
    FILE *file = fopen("crc_indications.bin", "wb");

    if (file == NULL) {
        // handle error
    }

    for (int i = 0; i < n; i++) {
        fwrite(&indications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* crc_indications_deserialize(int* n) {
    FILE *file = fopen("crc_indications.bin", "rb");

    if (file == NULL) {
        // handle error
    }

    fseek(file, 0, SEEK_END);
    int size = ftell(file);
    rewind(file);

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(size / sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < *n; i++) {
        fread(&indications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);

    return indications;
}

NFAPI_CRC_INDICATION_PDU_T* crc_indications_allocate(int n) {
    if (n < 0 || n > 10000) { // predefined maximum value
        return NULL; // or handle error
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        indications[i].RX_UE_INFORMATION_TAG = rand() % 100;
        indications[i].RNTI = rand() % 100;
        indications[i].CRCFLAG = rand() % 2; // random CRC flag
    }

    return indications;
}

int main() {
    int N = 10; // variable input size
    NFAPI_CRC_INDICATION_PDU_T* indications = crc_indications_allocate(N);

    if (indications == NULL) {
        // handle error
    }

    crc_indications_serialize(indications, N);

    free(indications);

    return 0;
}

