#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NETWORK_CONTEXTS 1000
#define MAX_PDCP_PDUS 10
#define CRC_INDICATION_REL8_TAG_SIZE 32
#define RX_UE_INFORMATION_TAG_SIZE 64
#define RNTI_SIZE 16

typedef struct {
    uint64_t ue_id;
    int rrc_state;
    struct {
        uint8_t* pdu_segment;
        size_t pdu_segment_len;
    } pdcp_pdu[MAX_PDCP_PDUS];
} lte_ue_context;

typedef struct {
    uint8_t rx_ue_information_tag[RX_UE_INFORMATION_TAG_SIZE];
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag[CRC_INDICATION_REL8_TAG_SIZE];
    uint8_t crcflag;
} nfapi_crc_indication_pdu_t;

void initializeNetworkContextsAndCRCIndications(int max_network_contexts, int timeout) {
    pthread_mutexattr_t mutexattr;
    pthread_mutexattr_init(&mutexattr);
    pthread_mutexattr_settype(&mutexattr, PTHREAD_MUTEX_NORMAL);

    lte_ue_context* network_contexts = (lte_ue_context*)malloc(max_network_contexts * sizeof(lte_ue_context));
    nfapi_crc_indication_pdu_t* crc_indications = (nfapi_crc_indication_pdu_t*)malloc(MAX_NETWORK_CONTEXTS * sizeof(nfapi_crc_indication_pdu_t));

    pthread_mutex_t semaphore;
    pthread_mutex_init(&semaphore, &mutexattr);
    pthread_mutex_setmutex(&semaphore);

    int i;
    for (i = 0; i < max_network_contexts; i++) {
        network_contexts[i].ue_id = i + 1;
        network_contexts[i].rrc_state = 0;

        // Initialize PDCP PDUs
        size_t pdu_segment_len = sizeof(uint8_t) * MAX_PDCP_PDUS;
        network_contexts[i].pdcp_pdu[0].pdu_segment = (uint8_t*)malloc(pdu_segment_len);
        network_contexts[i].pdcp_pdu[0].pdu_segment_len = pdu_segment_len;

        // Initialize NFAPI CRC indications
        for (int j = 0; j < MAX_NETWORK_CONTEXTS; j++) {
            crc_indications[j].rx_ue_information_tag[0] = 'R';
            crc_indications[j].rnti = i + 1;
            srand(time(NULL));
            for (int k = 0; k < CRC_INDICATION_REL8_TAG_SIZE; k++) {
                crc_indications[j].crc_indication_rel8_tag[k] = (uint8_t)(rand() & 0xFF);
            }
            crc_indications[j].crcflag = 1;
        }

        // Periodically check and validate the integrity of CRC INDICATION REL8 TAG
        pthread_mutex_lock(&semaphore);
        for (int j = 0; j < MAX_NETWORK_CONTEXTS; j++) {
            if (!validate_crc_indication_rel8_tag(crc_indications[j].crc_indication_rel8_tag, CRC_INDICATION_REL8_TAG_SIZE)) {
                // Handle error
            }
        }
        pthread_mutex_unlock(&semaphore);
    }

    // Free memory and delete semaphore
    free(network_contexts);
    free(crc_indications);
    pthread_mutex_destroy(&semaphore);
}
