void populate_NFAPICRCINDICATIONPDU(int n, struct NFAPI_CRC_INDATION_PDU_T** NFAPICRCINDICATIONPDUArray) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 255);

    for (int i = 0; i < n; ++i) {
        struct NFAPI_CRC_INDATION_PDU_T* NFAPICRCINDICATIONPDU = (struct NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDATION_PDU_T));

        if (!NFAPICRCINDICATIONPDU) {
            printf("Memory allocation failed.\n");
            return;
        }

        NFAPICRCINDICATIONPDU->RX_UE_INFORMATION_TAG = i;
        NFAPICRCINDICATIONPDU->RNTI = dis(gen);
        NFAPICRCINDICATIONPDU->timestamp = time(NULL);

        NFAPICRCINDICATIONPDU->CRCFLAG = (dis(gen) % 256); // Ensure CRCFLAG is within the valid range [0,255]

        (*NFAPICRCINDICATIONPDUArray)[i] = NFAPICRCINDICATIONPDU;
    }
}

void free_NFAPICRCINDICATIONPDU(struct NFAPI_CRC_INDATION_PDU_T** NFAPICRCINDICATIONPDUArray, int n) {
    for (int i = 0; i < n; ++i) {
        if ((*NFAPICRCINDICATIONPDUArray)[i]) {
            free((*NFAPICRCINDICATIONPDUArray)[i]);
