NFAPI_CRC_INDICATION_PDU_T** generateNFAPIList(int numStructures) {
    // Initialize the list with NULL pointers
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < numStructures; i++) {
        // Dynamically allocate memory for each structure
        NFAPI_CRC_INDICATION_PDU_T* structPtr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!structPtr) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        // Initialize the structure's fields
        structPtr->RX_UE_INFORMATION_TAG = rand() % 1000; // Randomly set RX_UE_INFORMATION_TAG
        structPtr->RNTI = rand() % 10000; // Randomly set RNTI
        sprintf(structPtr->CRC_INDICATION_REL8_TAG, "%d", time(NULL)); // Set timestamped CRC_INDICATION_REL8_TAG
        structPtr->CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG

        // Validate and wrap CRCFLAG within the specified range
        if (structPtr->CRCFLAG > 1 || structPtr->CRCFLAG < 0) {
            structPtr->CRCFLAG %= 2;
        }

        list[i] = structPtr;
    }

    return list;
}

// Function to filter structures based on RNTI values
