    NFAPI_CRC_INDICATION_PDU_T** filteredList = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < numStructures; i++) {
        if (list[i]->RNTI == rntiFilter) {
            filteredList[filteredList] = list[i];
        }
    }

    return filteredList;
