#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    pthread_mutex_t lock;
} nfa_crc_list;

void crc_list_init(nfa_crc_list *list) {
    list->size = 0;
    list->data = (NFAPI_CRC_INDATION_PDU_T *)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
}

int crc_list_insert(nfa_crc_list *list, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    if (list->size >= MAX_LIST_SIZE) {
        return -1; // List is full
    }

    pthread_mutex_lock(&list->lock);
    list->data[list->size] = *new_data;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void crc_list_serialize(const nfa_crc_list *list, const char* filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        printf("Failed to open file for writing\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    fwrite(&list->size, sizeof(int), 1, fp); // Serialize size
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, fp);
    pthread_mutex_unlock(&list->lock);

    fclose(fp);
}

void crc_list_deserialize(nfa_crc_list *list, const char* filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        printf("Failed to open file for reading\n");
        return;
    }

    int size;
    fread(&size, sizeof(int), 1, fp); // Deserialize size
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, fp);
    list->size = size;

    fclose(fp);
}

int main() {
    nfa_crc_list list;
    crc_list_init(&list);

    // Insert some data
    NFAPI_CRC_INDICATION_PDU_T* new_data1 = ...; // Initialize the structure
    crc_list_insert(&list, new_data1);
    NFAPI_CRC_INDICATION_PDU_T* new_data2 = ...; // Initialize the structure
    crc_list_insert(&list, new_data2);

    // Serialize the list to a file
    crc_list_serialize(&list, "data.bin");

    // Deserialize the list from the file
    crc_list_deserialize(&list, "data.bin");

    return 0;
}
