#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE_Ngap_Message_T
typedef struct {
    NAS_Message nas;
    NR_RRC_Capability_Information rrc;
} LTE_Ngap_Message_T;

// Define the structure for TrafficFlowStatistics
typedef struct {
    uint32_t flow_id;
    uint64_t traffic_volume;
    time_t last_update_time;
} TrafficFlowStatistics;

// Define the new message type UE_Location_Update
typedef struct {
    double latitude;
    double longitude;
    time_t timestamp;
} UE_Location_Update;

// Define the structure for the dynamic array of messages
typedef struct {
    LTE_Ngap_Message_T* lte_msg;
    TrafficFlowStatistics* traffic_flow_stats;
    UE_Location_Update* ue_location_update;
    int size; // Current size of the dynamic array
    int capacity; // Maximum capacity of the dynamic array (5000)
} MessageArray;

// Function to initialize the dynamic array of messages
MessageArray* init_message_array() {
    MessageArray* msg_arr = (MessageArray*)malloc(sizeof(MessageArray));
    if (!msg_arr) {
        return NULL;
    }
    msg_arr->size = 0;
    msg_arr->capacity = 5000;
    msg_arr->lte_msg = (LTE_Ngap_Message_T*)calloc(msg_arr->capacity, sizeof(LTE_Ngap_Message_T));
    if (!msg_arr->lte_msg) {
        free(msg_arr);
        return NULL;
    }
    msg_arr->traffic_flow_stats = (TrafficFlowStatistics*)calloc(msg_arr->capacity, sizeof(TrafficFlowStatistics));
    if (!msg_arr->traffic_flow_stats) {
        free(msg_arr->lte_msg);
        free(msg_arr);
        return NULL;
    }
    msg_arr->ue_location_update = (UE_Location_Update*)calloc(msg_arr->capacity, sizeof(UE_Location_Update));
    if (!msg_arr->ue_location_update) {
        free(msg_arr->traffic_flow_stats);
        free(msg_arr->lte_msg);
        free(msg_arr);
        return NULL;
    }
    return msg_arr;
}

// Function to add a message to the dynamic array
void add_message(MessageArray* msg_arr, int msg_type) {
    if (msg_arr->size >= msg_arr->capacity) {
        // Resize the dynamic array if it's full
        msg_arr->capacity *= 2; // Double the capacity
        msg_arr->lte_msg = (LTE_Ngap_Message_T*)realloc(msg_arr->lte_msg, msg_arr->capacity * sizeof(LTE_Ngap_Message_T));
        msg_arr->traffic_flow_stats = (TrafficFlowStatistics*)realloc(msg_arr->traffic_flow_stats, msg_arr->capacity * sizeof(TrafficFlowStatistics));
        msg_arr->ue_location_update = (UE_Location_Update*)realloc(msg_arr->ue_location_update, msg_arr->capacity * sizeof(UE_Location_Update));
    }
    // Add the message to the dynamic array
    if (msg_type == 0) { // LTE_Ngap_Message_T
        msg_arr->lte_msg[msg_arr->size] = (LTE_Ngap_Message_T){};
        msg_arr->traffic_flow_stats[msg_arr->size].flow_id = rand();
        msg_arr->traffic_flow_stats[msg_arr->size].traffic_volume = rand();
        msg_arr->traffic_flow_stats[msg_arr->size].last_update_time = time(NULL);
    } else if (msg_type == 1) { // TrafficFlowStatistics
        msg_arr->traffic_flow_stats[msg_arr->size] = (TrafficFlowStatistics){};
        msg_arr->lte_msg[msg_arr->size].nas.nas_message_id = rand();
        msg_arr->lte_msg[msg_arr->size].rrc.nr_rrc_capability_information = rand();
    } else if (msg_type == 2) { // UE_Location_Update
        msg_arr->ue_location_update[msg_arr->size] = (UE_Location_Update){};
        msg_arr->ue_location_update[msg_arr->size].latitude = rand() / (double)RAND_MAX;
        msg_arr->ue_location_update[msg_arr->size].longitude = rand() / (double)RAND_MAX;
        msg_arr->ue_location_update[msg_arr->size].timestamp = time(NULL);
    }
    msg_arr->size++;
}

// Function to archive old flow statistics or unused messages
void archive_messages(MessageArray* msg_arr, int num_entries_to_archive) {
    if (num_entries_to_archive > 0 && msg_arr->size >= num_entries_to_archive) {
        // Archive the oldest entries
        for (int i = 0; i < num_entries_to_archive; i++) {
            // Move the last entry to the first position and shift all other entries down
            if (msg_arr->lte_msg[i]) {
                msg_arr->lte_msg[0] = msg_arr->lte_msg[msg_arr->size - 1];
                msg_arr->traffic_flow_stats[0] = msg_arr->traffic_flow_stats[msg_arr->size - 1];
                msg_arr->ue_location_update[0] = msg_arr->ue_location_update[msg_arr->size - 1];
            }
        }
        // Remove the archived entries
        for (int i = num_entries_to_archive; i < msg_arr->size; i++) {
            if (msg_arr->lte_msg[i]) {
                free(msg_arr->lte_msg[i]);
                free(msg_arr->traffic_flow_stats[i]);
                free(msg_arr->ue_location_update[i]);
            }
        }
    }
}

// Function to monitor memory usage
void print_memory_usage(MessageArray* msg_arr) {
    printf("Memory usage: %lu bytes\n", (unsigned long)msg_arr->size * sizeof(LTE_Ngap_Message_T) + (unsigned long)(msg_arr->traffic_flow_stats) * sizeof(TrafficFlowStatistics) + (unsigned long)(msg_arr->ue_location_update) * sizeof(UE_Location_Update));
}

int main() {
    MessageArray* msg_arr = init_message_array();
    for (int i = 0; i < 5000; i++) {
        add_message(msg_arr, rand() % 3);
    }
    archive_messages(msg_arr, 1000);
    print_memory_usage(msg_arr);
    return 0;
}
