typedef struct {
    int phy_channel_state;
    uint32_t cell_id;
    float sinr_threshold;
} PHY_STATS_T;

void manage_phy_stats_array(int m) {
    if (m <= 0) return; // Handle edge case

    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for the array of structures
    PHY_STATS_T* phy_stats = (PHY_STATS_T*) malloc(m * sizeof(PHY_STATS_T));
    if (!phy_stats) {
        printf("Memory allocation failed\n");
        return;
    }

    // Populate each structure with data
    int i;
    for (i = 0; i < m; i++) {
        phy_stats[i].phy_channel_state = i + 1; // Unique channel state

        // Generate a unique cell ID, minimizing collisions
        uint32_t cell_id = rand() % ((1 << 31) - i * 1000000);
        while (cell_id > 0 && !is_prime(cell_id)) {
            cell_id = rand() % ((1 << 31) - i * 1000000);
        }
        phy_stats[i].cell_id = cell_id;

        // Set SINR_THRESHOLD based on Fibonacci condition
        if (is_fibonacci(i))
            phy_stats[i].sinr_threshold = (float)i / 10;
        else
            phy_stats[i].sinr_threshold = (float)(m - i) / 10;
    }

    // Validate that each channel state is unique and no two structures have the same cell ID
    for (i = 0; i < m; i++) {
        bool unique_channel_state = true;
        bool unique_cell_id = true;
        for (int j = 0; j < m; j++) {
            if (j != i && phy_stats[i].phy_channel_state == phy_stats[j].phy_channel_state) {
                unique_channel_state = false;
                break;
            }
            if (j != i && phy_stats[i].cell_id == phy_stats[j].cell_id) {
                unique_cell_id = false;
                break;
            }
        }

        if (!unique_channel_state || !unique_cell_id) {
            printf("Error: Unique channel state and cell ID validation failed\n");
            free(phy_stats);
            return;
        }
    }

    // Free allocated memory
    free(phy_stats);
}

// Helper functions to validate Fibonacci numbers and prime numbers

bool is_fibonacci(int n) {
    int a = 0, b = 1;
    while (b < n) {
        a = b;
        b += a + 1;
    }
    return b == n;
}

bool is_prime(uint32_t num) {
    if (num <= 1) return false;
    for (uint32_t i = 2; i * i <= num; i++) {
        if (num % i == 0)
            return false;
    }
    return true;
}
