#define BUFFER_SIZE 1024
#define MAX_INT 2147483647

void *readBuffer;
int largestInt = INT_MIN;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *processStream(int fd) {
    int bytesRead, err;
    unsigned char buffer[BUFFER_SIZE];
    while ((bytesRead = read(fd, buffer, BUFFER_SIZE)) > 0) {
        for (int i = 0; i < bytesRead; i++) {
            int num = buffer[i] << 24 | buffer[i + 1] << 16 | buffer[i + 2] << 8 | buffer[i + 3];
            if (num > largestInt) {
                largestInt = num;
                pthread_mutex_lock(&mutex);
                printf("Largest integer: %d\n", largestInt);
                pthread_mutex_unlock(&mutex);
            }
        }
    }
    return NULL;
}

int main() {
    int fd = open("/path/to/file", O_RDONLY);
    readBuffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    pthread_t thread;
    pthread_create(&thread, NULL, processStream, (void *)fd);
    pthread_join(thread, NULL);
    munmap(readBuffer, BUFFER_SIZE);
    return 0;
}

