    char crc_indication_rel8_tag[CRC_INDICATION_REL8_TAG_MAX_SIZE];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *list = NULL;
int list_size = 0;
int total_crc_flags = 0;
int avg_crc_flag = 0;

void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&lock);
    if (list == NULL) {
        list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
    }
    if (list_size >= MAX_ELEMENTS) {
        printf("List is full, cannot add more elements.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    list[list_size] = *element;
    total_crc_flags += element->crc_indication_rel8_tag[0];
    avg_crc_flag = total_crc_flags / (list_size + 1);
    list_size++;
    pthread_mutex_unlock(&lock);
}

void remove_element(int index) {
    pthread_mutex_lock(&lock);
    if (index >= list_size || index < 0) {
        printf("Index out of bounds.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    for (int i = index; i < list_size - 1; i++) {
        list[i] = list[i + 1];
    }
    free(&list[list_size - 1]);
    list_size--;
    total_crc_flags -= list[list_size].crc_indication_rel8_tag[0];
    avg_crc_flag = total_crc_flags / (list_size);
    pthread_mutex_unlock(&lock);
}

void print_statistics() {
    printf("Total elements: %d\n", list_size);
    printf("Average CRC flag: %d\n", avg_crc_flag);
}

int main() {
    // Initialize the list
    add_element((NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)));

    // Add more elements to the list
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        add_element((NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    }

    // Remove some elements from the list
    for (int i = 0; i < list_size / 2; i++) {
        remove_element(i);
    }

    // Print statistics
    print_statistics();

    return 0;
}
