void* read_ints_from_file(int fd, int *size) {
    int i;
    int ints[MAX_INTS];
    size_t bytes_read = 0;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    volatile int updated_size = 0;

    while (bytes_read < *size) {
        pthread_mutex_lock(&lock);
        if (*size - bytes_read > MAX_INTS - ints) {
            // Read a chunk of ints
            size_t to_read = MIN(*size - bytes_read, MAX_INTS);
            read(fd, ints, to_read * sizeof(int));
            bytes_read += to_read;
        } else {
            // No more data available
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&lock);
            break;
        }
    }

    pthread_mutex_lock(&lock);
    *size = bytes_read;
    pthread_mutex_unlock(&lock);

