            // Read a chunk of indications
            size_t to_read = MIN(*updated_size - bytes_read, MAX_INTS / NFAPI_CRC_INDICATION_PDU_T_SIZE);
            read(fd, &indications[bytes_read], to_read * NFAPI_CRC_INDICATION_PDU_T_SIZE);
            bytes_read += to_read;
        } else {
            // No more data available
            pthread_cond_signal(lock);
            pthread_mutex_unlock(lock);
            break;
        }
    }

    return indications;
