// Function to create and manage a list of NFAPI_CRC_INDATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** createNFAPIData(int* N, json_object* config) {
    // Initialize the dynamic dataset
    NFAPI_CRC_INDICATION_PDU_T** data = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_NFAPI * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Set the initial number of structures to 0
    int count = 0;

    // Initialize a counter for logging operations
    int logCount = 0;

    // Loop through each entry in the configuration file
    json_object_iter* iter;
    json_object_iter_init(config, NULL);
    while ((iter = json_object_iter(json_object_get(config), NULL)) != NULL) {
        char* key = iter->key;
        if (strcmp(key, "THRESHOLD") == 0) {
            // Set the threshold value from the configuration file
            int threshold = json_object_get_int(iter->value);
            // Allocate memory for each structure based on the threshold
            while (count < *N && count < threshold) {
                data[count] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (data[count] == NULL) {
                    printf("Error allocating memory for NFAPI structure at index %d.\n", count);
                    logCount++;
                } else {
                    // Set the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values
                    sprintf(data[count]->RX_UE_INFORMATION_TAG, "RX UE INFORMATION TAG %d", count);
                    data[count]->RNTI = rand() % 100;
                    data[count]->CRCFLAG = rand() & 0xFF;

                    // Increment the count for logging operations
                    logCount++;
                }
                count++;
            }
        } else if (strcmp(key, "CRCFLAG_MAX") == 0) {
            int crcFlagMax = json_object_get_int(iter->value);
            // Set a flag to indicate when the CRCFLAG value exceeds the maximum limit
            bool crcFlagOverflow = false;

            // Loop through each allocated structure and set its CRCFLAG value
            for (int i = 0; i < count; i++) {
                if (data[i]->CRCFLAG > crcFlagMax) {
                    data[i]->CRCFLAG = crcFlagMax;
                    crcFlagOverflow = true;
                }
            }

            // Log an error message if the CRCFLAG overflowed
            if (crcFlagOverflow) {
                printf("Warning: CRCFLAG value exceeded the maximum limit.\n");
                logCount++;
            }
        }
    }

    // Free any remaining memory for unallocated structures
    for (int i = count; i < MAX_NFAPI; i++) {
        free(data[i]);
    }
    free(data);

    return &data[0];
}
