int frame_header_array_add(MAC_FRAME_HEADER_T*** frames, size_t capacity, MAC_FRAME_HEADER_T* frame) {
    if (capacity == 0) {
        // Double the capacity when the array is full
        *frames = (MAC_FRAME_HEADER_T**)realloc(*frames, (*capacity + 1) * sizeof(MAC_FRAME_HEADER_T*));
        capacity *= 2;
    }

    // Check for duplicate CID
    int i;
    for (i = 0; i < capacity; i++) {
        if ((*frames)[i]->CID == frame->CID) {
            return -1; // Duplicate CID detected
        }
    }

    (*frames)[capacity-1] = frame;
    return 0;
}

