#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char mac_id[17]; // 16 characters for MAC ID + null terminator
    int phy_params; // configurable parameters (bandwidth and modulation settings)
    int channel_mapping;
} LTE_ENB_FR1_TAG;

// Function to add a new node to the list
void add_node(LTE_ENB_FR1_TAG **head, char* mac_id, int phy_params, int channel_mapping) {
    LTE_ENB_FR1_TAG *new_node = (LTE_ENB_FR1_TAG *)malloc(sizeof(LTE_ENB_FR1_TAG));

    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }

    strcpy(new_node->mac_id, mac_id);
    new_node->phy_params = phy_params;
    new_node->channel_mapping = channel_mapping;

    // Check for duplicate MAC IDs
    LTE_ENB_FR1_TAG *current = *head;
    while (current) {
        if (!strcmp(current->mac_id, mac_id)) {
            free(new_node);
            printf("Duplicate MAC ID found.\n");
            return;
        }
        current = current->next;
    }

    new_node->prev = NULL;
    new_node->next = *head;

    if (*head) {
        (*head)->prev = &new_node->next;
    } else {
        new_node->prev = NULL;
    }

    *head = new_node;
}

// Function to remove a node from the list
void remove_node(LTE_ENB_FR1_TAG **head, char* mac_id) {
    LTE_ENB_FR1_TAG *current = *head;
    while (current) {
        if (!strcmp(current->mac_id, mac_id)) {
            if (current->prev)
                current->prev->next = current->next;
            else
                *head = current->next;

            if (current->next)
                current->next->prev = current->prev;

            free(current);
            return;
        }
        current = current->next;
    }
}

// Function to serialize the list to a binary file
void serialize_list(LTE_ENB_FR1_TAG *head, FILE *file) {
    fwrite(&head, sizeof(LTE_ENB_FR1_TAG), 1, file);
}

// Function to deserialize the list from a binary file
LTE_ENB_FR1_TAG *deserialize_list(FILE *file) {
    LTE_ENB_FR1_TAG *head = (LTE_ENB_FR1_TAG *)malloc(sizeof(LTE_ENB_FR1_TAG));
    fread(&head, sizeof(LTE_ENB_FR1_TAG), 1, file);
    return head;
}

// Function to manage the doubly linked list
void manage_list(LTE_ENB_FR1_TAG **head) {
    // Add nodes to the list
    add_node(head, "MAC_ID_1", 12345, 67890);
    add_node(head, "MAC_ID_2", 54321, 98765);

    // Remove a node from the list
    remove_node(head, "MAC_ID_2");
}

int main() {
    LTE_ENB_FR1_TAG *head = NULL;

    // Add nodes to the list
    add_node(&head, "MAC_ID_1", 12345, 67890);
    add_node(&head, "MAC_ID_2", 54321, 98765);

    // Serialize the list to a binary file
    FILE *file = fopen("list.bin", "wb");
    serialize_list(head, file);
    fclose(file);

    // Deserialize the list from the binary file
    file = fopen("list.bin", "rb");
    head = deserialize_list(file);
    fclose(file);

    // Manage the doubly linked list
    manage_list(&head);

    return 0;
}
