typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_create(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void nfapi_crc_indication_list_destroy(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list) return;
    for (size_t i = 0; i < list->size; i++) {
        free(list->data + i);
    }
    free(list->data);
    free(list);
}

void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->capacity = new_capacity;
        list->data = new_data;
    }
    element->CRCFLAG ^= 1; // Ensure uniqueness
    list->data[list->size++] = *element;
    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_indication_list_validate_rnti(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size - 1; i++) {
        if (list->data[i].RNTI == list->data[i + 1].RNTI) {
            nfapi_crc_indication_list_destroy(list);
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T* list = nfapi_crc_indication_list_create(10);
    // Add elements...
    nfapi_crc_indication_list_validate_rnti(list);
    // Reset the list...
    return 0;
}
