// Custom memory pool structure
typedef struct {
    void* data;
    size_t capacity;
    size_t used;
} MemoryPool;

// Function to initialize and allocate memory pool
MemoryPool* init_memory_pool(size_t initial_capacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->data = malloc(initial_capacity * sizeof(void*));
    mp->capacity = initial_capacity;
    mp->used = 0;
    return mp;
}

// Function to add an element to the linked list
int add_element_to_list(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T* new_element) {
    if (mp->used >= mp->capacity) {
        // Dynamically resize the memory pool when necessary
        mp->data = realloc(mp->data, (mp->capacity * 2) * sizeof(void*));
        mp->capacity *= 2;
    }

    // Ensure no two consecutive elements share the same CRCFLAG value
    while (new_element->CRC_INDICATION_REL8_TAG.CRCFLAG == mp->data[mp->used]->CRC_INDICATION_REL8_TAG.CRCFLAG) {
        new_element->CRC_INDICATION_REL8_TAG.CRCFLAG++;
    }

    // Ensure all RNTI values remain unique throughout the list's lifecycle
    for (size_t i = 0; i < mp->used; ++i) {
        if (new_element->RNTI == ((NFAPI_CRC_INDICATION_PDU_T*)mp->data[i])->RNTI) {
            // Release all allocated memory and return an error status upon detecting any duplicate RNTI
            free(mp->data);
            mp->data = NULL;
            mp->used = 0;
            mp->capacity = 0;
            return -1;
        }
    }

    // Periodic revalidation feature to check for duplicate RNTI values every 1000 elements added
    if (mp->used % 1000 == 0) {
        // Perform periodic revalidation cycle when the threshold is reached
        for (size_t i = 0; i < mp->used - 1; ++i) {
            for (size_t j = i + 1; j < mp->used; ++j) {
                if (((NFAPI_CRC_INDICATION_PDU_T*)mp->data[i])->RNTI == ((NFAPI_CRC_INDICATION_PDU_T*)mp->data[j])->RNTI) {
                    free(mp->data);
                    mp->data = NULL;
                    mp->used = 0;
                    mp->capacity = 0;
                    return -1;
                }
            }
        }
    }

    // Log the addition of each element
    printf("Added element with RNTI: %u and CRCFLAG: %u\n", new_element->RNTI, new_element->CRC_INDICATION_REL8_TAG.CRCFLAG);

    // Add the new element to the linked list
    mp->data[mp->used] = new_element;
    mp->used++;

    return 0;
}

// Function to handle memory allocation failures gracefully and reset the list to its initial state when needed
void* safe_malloc(size_t size) {
    void* p = malloc(size);
    if (p == NULL) {
        // Reset the list to its initial state upon memory allocation failure
        free(mp->data);
        mp->data = NULL;
        mp->used = 0;
        mp->capacity = 0;
        return NULL;
    }
    else
        return p;
}

// Function to handle thread safety and ensure concurrent access from multiple threads without compromising data integrity or performance
void* safe_free(void* p) {
    if (pthread_mutex_lock(&mutex) != 0)
        return NULL;

    free(p);

    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    // Initialize and allocate memory pool
    MemoryPool* mp = init_memory_pool(10);

    // Add elements to the linked list
    for (size_t i = 0; i < 50000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Initialize and add the new element
        if (new_element != NULL) {
            new_element->RX_UE_INFORMATION_TAG = 0;
            new_element->RNTI = i;
            new_element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;

            if (add_element_to_list(mp, new_element) == -1) {
                // Reset the list to its initial state upon detecting any duplicate RNTI
                free(mp->data);
                mp->data = NULL;
                mp->used = 0;
                mp->capacity = 0;

                return -1;
            }
        }
    }

    // Free all allocated memory upon completion
    for (size_t i = 0; i < mp->used; ++i) {
        safe_free(mp->data[i]);
    }

    free(mp->data);

    return 0;
}

