    double sinr;
    int channel_quality_indicator;
} PHY_FRAME_INFO;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int phy_frame_info_list_init(PHY_FRAME_INFO **list) {
    *list = (PHY_FRAME_INFO *)malloc(sizeof(PHY_FRAME_INFO));
    return 0;
}

void phy_frame_info_list_free(PHY_FRAME_INFO **list) {
    free(*list);
    *list = NULL;
}

int phy_frame_info_list_append(PHY_FRAME_INFO **list, PHY_FRAME_INFO *frame_info) {
    if (pthread_mutex_lock(&lock) != 0) {
        return -1; // Error locking the mutex
    }

    int i = 0;
    while ((*list)[i].frame_type == frame_info->frame_type && i < MAX_SIZE) {
        i++;
    }

    if (i >= MAX_SIZE) {
        phy_frame_info_list_free(list);
        return -1; // Error: too many consecutive elements with the same type
    }

    *list = realloc(*list, sizeof(PHY_FRAME_INFO) * (i + 2));
    (*list)[i] = *frame_info;
    i++;

    while (i < MAX_SIZE) {
        if ((*list)[i-1].sinr == (*list)[i].sinr) {
            phy_frame_info_list_free(list);
            return -1; // Error: duplicate SINR value
        }
        i++;
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

void phy_frame_info_list_reset(PHY_FRAME_INFO **list) {
    free(*list);
    *list = (PHY_FRAME_INFO *)malloc(sizeof(PHY_FRAME_INFO));
}
