    pthread_mutex_lock(&lock);

    FrameStruct* old_array = frames;
    frames = new_array;
    int num_frames_to_copy = (num_frames > new_capacity ? new_capacity : num_frames);
    for (int i = 0; i < num_frames_to_copy; i++) {
        new_array[i] = old_array[i];
    }

    pthread_mutex_unlock(&lock);

    frame_array_destroy(old_array, num_frames_to_copy);
}

void add_frame(FrameStruct* frame) {
    pthread_mutex_lock(&lock);

    if (num_frames == capacity) {
        int new_capacity = capacity * 2;
        frame_array_resize(new_capacity);
        capacity = new_capacity;
    }

    frames[num_frames] = *frame;
    num_frames++;

    pthread_mutex_unlock(&lock);
}

void remove_frame(int index) {
    pthread_mutex_lock(&lock);

    if (index >= 0 && index < num_frames) {
        for (int i = index; i < num_frames - 1; i++) {
            frames[i] = frames[i + 1];
        }
        num_frames--;
    }

    pthread_mutex_unlock(&lock);
}

FrameStruct* get_frame(int index) {
    pthread_mutex_lock(&lock);

    if (index >= 0 && index < num_frames) {
        return &frames[index];
    } else {
        pthread_mutex_unlock(&lock);
        return NULL;
