    *frames = (FrameConfig*)malloc(sizeof(FrameConfig));
    *size = 1;
}

int addFrameToBatch(FrameConfig** frames, int* size, FrameConfig frame, int priority) {
    if (*size == 0) {
        return -1; // Batch is empty
    }

    if (priority > 2 || priority < 0) {
        return -2; // Invalid priority level
    }

    if (frame.frame.pdschSymbolsTag == NULL || frame.cqI < 0 || frame.harqFeedback < 0) {
        return -3; // Frame contains invalid or null values
    }

    *size += (*size <= growthFactor) ? 1 : growthFactor;
    *frames = realloc(*frames, sizeof(FrameConfig) * (*size));
    (*frames)[*size - 1] = frame;

    return 0; // Success
}

int serializeFramesToFile(const FrameConfig** frames, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -4; // Error opening file
    }

    fwrite(frames, sizeof(FrameConfig), size, file);
    fclose(file);

    return 0; // Success
}

int deserializeFramesFromFile(const char* filename, FrameConfig** frames, int* size) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -5; // Error opening file
    }

    *size = fread(frames, sizeof(FrameConfig), 1, file);
    fclose(file);

    return 0; // Success
}

