// Define custom allocator structure
typedef struct {
    void* base;
    size_t size;
    int ref_count;
} custom_allocator;

// Initialize custom allocator with memory pool of 5MB
custom_allocator init_allocator(size_t pool_size) {
    custom_allocator alloc;
    alloc.base = malloc(pool_size);
    alloc.size = pool_size;
    alloc.ref_count = 0;
    return alloc;
}

// Allocate memory using custom allocator
void* custom_malloc(custom_allocator* alloc, size_t size) {
    if (alloc->ref_count > 0) {
        // If ref_count is greater than 0, it means the memory pool has been partially freed, so we need to reallocate
        free(alloc->base);
        alloc->base = malloc(size + sizeof(custom_allocator));
        alloc->size = size;
        alloc->ref_count = 1;
    }
    return alloc->base;
}

// Free memory using custom allocator
void custom_free(custom_allocator* alloc, void* ptr) {
    if (alloc->ref_count > 0) {
        free(ptr);
        alloc->ref_count--;
    }
}

