#define MAX_SESSIONS 10000
#define MAX_MEMORY_PER_SESSION 5000000 // 50 MB

typedef struct {
    int RNTI;
    unsigned int CRCFLAG;
    char RX_UE_INFORMATION_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* array;
} MAC_Entity_Context;

void initialize_MAC_Entity_Context(MAC_Entity_Context* context) {
    context->size = 0;
    context->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_MEMORY_PER_SESSION * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void add_MAC_Entity_Context(MAC_Entity_Context* context, NFAPI_CRC_INDICATION_PDU_T* entity) {
    pthread_mutex_lock(&context->lock);
    context->array[context->size] = *entity;
    context->size++;
    pthread_mutex_unlock(&context->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_MAC_Entity_Context(MAC_Entity_Context* context, int index) {
    pthread_mutex_lock(&context->lock);
    if (index >= 0 && index < context->size) {
        return &context->array[index];
    }
    pthread_mutex_unlock(&context->lock);
    return NULL;
}

void update_MAC_Entity_Context(MAC_Entity_Context* context, NFAPI_CRC_INDICATION_PDU_T* entity) {
    pthread_mutex_lock(&context->lock);
    for (int i = 0; i < context->size; i++) {
        if (entity->RNTI == context->array[i].RNTI) {
            // update existing entity
            memcpy(&context->array[i], entity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
    }
    pthread_mutex_unlock(&context->lock);
}

void free_MAC_Entity_Context(MAC_Entity_Context* context) {
    free(context->array);
}

int main() {
    // Initialize a MAC entity context
    MAC_Entity_Context context;
    initialize_MAC_Entity_Context(&context);

    // Add some entities to the context
    NFAPI_CRC_INDICATION_PDU_T entity1 = {"Entity 1", 0, "RX_UE_INFORMATION_TAG"};
    add_MAC_Entity_Context(&context, &entity1);
    NFAPI_CRC_INDICATION_PDU_T entity2 = {"Entity 2", 1, "RX_UE_INFORMATION_TAG"};
    add_MAC_Entity_Context(&context, &entity2);

    // Get an entity from the context
