#define NFAPI_CRC_INDICATION_PDU_T_MAX 100

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU_T(int count) {
    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < count; i++) {
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);

        char RX_UE_INFORMATION_TAG[16];
        sprintf(RX_UE_INFORMATION_TAG, "RX_%02x", ltm->tm_sec % 256);

        int RNTI = (int)rand() % 1000;
        char CRC_INDICATION_REL8_TAG[16];
        sprintf(CRC_INDICATION_REL8_TAG, "CRC_%d", ltm->tm_min % 60);

        int CRCFLAG = rand() % 2;

        result[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        result[i].RNTI = RNTI;
        result[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        result[i].CRCFLAG = CRCFLAG;
    }

    return result;
}

void free_NFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* array, int count) {
    for (int i = 0; i < count; i++) {
        free(array[i].RX_UE_INFORMATION_TAG);
        free(array[i].CRC_INDICATION_REL8_TAG);
    }
    free(array);
}
