#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    double signal_strength;
} FrameStatistics;

typedef struct node {
    FrameStatistics stats;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    pthread_mutex_init(&lock, NULL);
}

void add_to_list(Node** head_ref, FrameStatistics stats) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->stats = stats;
    new_node->next = *head_ref;
    *head_ref = new_node;
    pthread_mutex_unlock(&lock);
}

FrameStatistics* get_last_stats() {
    Node* current = head;
    FrameStatistics* last_stats = NULL;

    while (current) {
        last_stats = &current->stats;
        current = current->next;
    }

    return last_stats;
}

void filter_measurements(Node** head_ref, double signal_strength_threshold) {
    Node* current = *head_ref;
    Node* prev = NULL;

    while (current) {
        if (current->stats.signal_strength < signal_strength_threshold) {
            if (!prev) {
                *head_ref = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
        } else {
            prev = current;
        }
        current = current->next;
    }
}

void* thread_func(void* arg) {
    // Handle data from external source
    while (/* condition */) {
        FrameStatistics stats;
        // Read data and fill stats struct
        pthread_mutex_lock(&lock);
        add_to_list(&head, stats);
        pthread_mutex_unlock(&lock);

        sleep(/* interval */);  // Ensure consistent sampling
    }
    return NULL;
}

int main() {
    init_list();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    while (/* condition */) {
        FrameStatistics* last_stats = get_last_stats();
        if (last_stats) {
            // Process and filter measurements
            double signal_strength_threshold = /* dynamic threshold */;
            filter_measurements(&head, signal_strength_threshold);

            free(last_stats);  // Manage memory efficiently
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

