// Hash table to store and manage connections
typedef struct {
    size_t capacity;
    ConnectionMetadata** connections;
} ConnectionHashTable;

// Function to initialize the hash table
ConnectionHashTable* initHashTable(size_t capacity) {
    ConnectionHashTable* hashTable = (ConnectionHashTable*)malloc(sizeof(ConnectionHashTable));
    hashTable->capacity = capacity;
    hashTable->connections = (ConnectionMetadata**)calloc(capacity, sizeof(ConnectionMetadata*));
    return hashTable;
}

// Function to add a connection to the hash table
void addConnection(ConnectionHashTable* hashTable, int clientId, const char* serverAddress) {
    size_t index = clientId % hashTable->capacity;
    ConnectionMetadata* connection = (ConnectionMetadata*)malloc(sizeof(ConnectionMetadata));
    connection->clientId = clientId;
    strcpy(connection->serverAddress, serverAddress);
    connection->connectionStatus = 0; // Initially disconnected

    if (!hashTable->connections[index]) {
        hashTable->connections[index] = connection;
    } else {
        // Handle duplicate entry (client ID and server address combination)
        // For demonstration purposes, simply update the existing connection
        free(hashTable->connections[index]);
        hashTable->connections[index] = connection;
    }
}

// Function to remove a connection from the hash table
void removeConnection(ConnectionHashTable* hashTable, int clientId) {
    size_t index = clientId % hashTable->capacity;
    if (hashTable->connections[index]) {
        free(hashTable->connections[index]);
        hashTable->connections[index] = NULL;
    }
}

// Function to update a connection's status
void updateConnectionStatus(ConnectionHashTable* hashTable, int clientId, int newStatus) {
    size_t index = clientId % hashTable->capacity;
    if (hashTable->connections[index]) {
        ConnectionMetadata* connection = hashTable->connections[index];
        connection->connectionStatus = newStatus;
    }
}

