#define MAX_N 1024
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random pseudo-random number based on a seed value
int get_random(int seed) {
    // Using a simple linear congruential generator (LCG)
    return ((seed * 1103515245 + 12345) % (2^31)) & 0x7fffffff;
}

// Function to generate NFAPI_CRC_INDICATION_PDU_T structures based on the provided configuration
int create_crc_indication_pdu_list(int N, int* crcflags[], FILE* log_file) {
    if (N <= 0) {
        printf("Invalid number of elements. Returning error code.\n");
        return -1;
    }

    // Initialize list and CRC flags
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed. Returning error code.\n");
        return -2;
    }
    int* crc_flags = (int*)malloc(N * sizeof(int));
    if (!crc_flags) {
        // If CRC flags allocation fails, free the previously allocated list
        free(list);
        printf("Memory allocation failed. Returning error code.\n");
        return -3;
    }

    for (int i = 0; i < N; i++) {
        int seed = i * 12345;
        list[i].RX_UE_INFORMATION_TAG = get_random(seed) % 2^16;
        list[i].RNTI = get_random(seed) % 2^10;
        list[i].CRC_INDICATION_REL8_TAG = get_random(seed) % 2^12;

        if (list[i].RNTI < 0 || list[i].RNTI > 511) {
            fprintf(log_file, "RNTI value out of range: %d\n", list[i].RNTI);
        }

        crc_flags[i] = get_random(seed) % 2;
    }

    // Implement synchronization mechanism to handle concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    return N;
}

// Function to add more elements to the list at runtime without affecting existing data
int add_crc_indication_pdu(int* crcflags[], int start_index, int new_elements) {
    if (start_index < 0 || new_elements <= 0) {
        printf("Invalid parameters. Returning error code.\n");
        return -1;
    }

    // Allocate memory for the new elements and update the list
    NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) {
        printf("Memory allocation failed. Returning error code.\n");
        return -2;
    }

    for (int i = 0; i < new_elements; i++) {
        int seed = i * 12345;
        new_list[i].RX_UE_INFORMATION_TAG = get_random(seed) % 2^16;
        new_list[i].RNTI = get_random(seed) % 2^10;
        new_list[i].CRC_INDICATION_REL8_TAG = get_random(seed) % 2^12;

        if (new_list[i].RNTI < 0 || new_list[i].RNTI > 511) {
            fprintf(log_file, "RNTI value out of range: %d\n", new_list[i].RNTI);
        }

        crc_flags[start_index + i] = get_random(seed) % 2;
    }

    // Update the original list
    pthread_mutex_lock(&mutex);
    memcpy(list + start_index, new_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_elements);
    free(new_list);
    pthread_mutex_unlock(&mutex);

    return start_index + new_elements;
}

// Function to handle edge cases and gracefully exit
int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Invalid number of command-line arguments. Exiting.\n");
        return -1;
    }

    int N = atoi(argv[1]);

    // Initialize the list and CRC flags
    NFAPI_CRC_INDICATION_PDU_T* crc_list = create_crc_indication_pdu_list(N, &crc_flags, log_file);

    if (crc_list == NULL) {
        printf("Failed to create the list. Exiting.\n");
        return -2;
    }

    // Demonstrate adding more elements at runtime
    int new_elements = 10;
    start_index = 5;  // Add elements starting from index 5

    // Call add_crc_indication_pdu function and handle its return value
    int updated_start_index = add_crc_indication_pdu(&crc_flags, start_index, new_elements);

    if (updated_start_index < 0) {
        printf("Failed to add the new elements. Exiting.\n");
        return -3;
    }

    // Perform any necessary cleanup or logging before exiting
    free(crc_list);
    fclose(log_file);

    return 0;
}
