#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_STRUCTURES 10000
#define LOGGING_ENABLED 1
#define DATA_PROCESSING_PIPELINE 1

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *populateNFAPICRCIndications(int max_structures) {
    int i, j;
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    int pdu_count = 0;

    // Determine the maximum number of structures based on available memory resources
    int max_memory = (int)sysconf(_SC_PHYS_PAGES) * (int)sysconf(_SC_PAGE_SIZE);
    int max_structures_calculated = min(max_structures, max_memory / sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Create the list of structures
    pdu_list = malloc(max_structures_calculated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        // Handle memory allocation failure
        fprintf(stderr, "Error: Memory allocation failed for %d structures. Available system memory: %d bytes.\n", max_structures_calculated, max_memory);
        return NULL;
    }

    // Populate the list of structures
    for (i = 0; i < max_structures_calculated; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        strcpy(pdu.RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_");
        pdu.RNTI = rand() % 1000;
        sprintf(pdu.CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG_%d", i);
        pdu.CRCFLAG = rand() & 1;

        // Ensure uniqueness of CRC_INDICATION_REL8_TAG
        for (j = 0; j < i; j++) {
            if (strcmp(pdu_list[j].CRC_INDICATION_REL8_TAG, pdu.CRC_INDICATION_REL8_TAG) == 0) {
                do {
                    sprintf(pdu.CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG_%d", i);
                    pdu.CRCFLAG = rand() & 1;
                } while (j < i && strcmp(pdu_list[j].CRC_INDICATION_REL8_TAG, pdu.CRC_INDICATION_REL8_TAG) == 0);
            }
        }

        // Add the structure to the list
        memcpy(&pdu_list[pdu_count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu_count++;

        if (LOGGING_ENABLED)
            printf("Populated structure %d: RNTI=%d, CRC_INDICATION_REL8_TAG=\"%s\", CRCFLAG=%d\n", i, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG, pdu.CRCFLAG);

    }

    // Sort the structures in ascending order of RNTI
    qsort(pdu_list, pdu_count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);

    return pdu_list;
}

