#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNFAPICRCIndications(int* n, NFAPI_CRC_INDICATION_PDU_T** result) {
    int max = (int)(1024 * 1024 * 2); // adjust this value based on system load and data throughput
    int* uniqueCRCFlags = (int*)malloc(max * sizeof(int));
    int* rntiList = (int*)malloc(max * sizeof(int));

    for (int i = 0; i < max; i++) {
        NFAPI_CRC_INDICATION_PDU_T* indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        indication->RX_UE_INFORMATION_TAG = rand() % 100;
        indication->RNTI = rand() % 2000 + 1; // ensure uniqueness
        int crcFlag = rand();
        while (findCRCFlags(uniqueCRCFlags, i, crcFlag)) {
            crcFlag = rand();
        }
        indication->CRCFLAG = crcFlag;
        rntiList[i] = indication->RNTI;

        if (!*result) *result = &indication;
        else (*result)[i] = indication;
    }

    qsort(*result, max, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareIndications);

    free(uniqueCRCFlags);
    free(rntiList);
}

int findCRCFlags(int* crcFlags, int n, int flag) {
    for (int i = 0; i < n; i++) {
        if (crcFlags[i] == flag) return 1;
    }
    return 0;
}

int compareIndications(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* indicationA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* indicationB = (NFAPI_CRC_INDICATION_PDU_T*)b;

    return (indicationA->RNTI - indicationB->RNTI);
}
