#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct NetworkConnectionStatus {
    int connectionID;
    time_t statusTime;
    float connectionQuality;
} NetworkConnectionStatus;

// Linked list node structure
typedef struct Node {
    NetworkConnectionStatus data;
    struct Node* next;
} Node;

// Function to initialize the linked list
Node* initList(Node* head) {
    // Initialize the head of the list and return it
    head = (Node*)malloc(sizeof(Node));
    head->next = NULL;
    return head;
}

// Function to insert a new node at the end of the list
void insertNode(Node** head_ref, NetworkConnectionStatus newData) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    Node* last = *head_ref;

    // If list is empty, then new node is the first node
    if (*head_ref == NULL) {
        *head_ref = (Node*)malloc(sizeof(Node));
        (*head_ref)->data = newData;
        (*head_ref)->next = NULL;
        return;
    }

    while (last->next != NULL)
        last = last->next;

    // Set link of previous node as new node
    newNode->data = newData;
    newNode->next = NULL;
    last->next = newNode;
}

// Function to delete a node with the given connectionID
void deleteNode(Node** head_ref, int connectionID) {
    Node* prev = NULL;
    Node* current = *head_ref;

    while (current != NULL && current->data.connectionID != connectionID) {
        prev = current;
        current = current->next;
    }

    if (current == NULL)
        return;

    if (prev == NULL) {
        *head_ref = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
}

// Function to print the linked list
void printList(Node* head) {
    Node* temp = head;
    while (temp != NULL) {
        printf("Connection ID: %d, Status Time: %lu, Connection Quality: %.2f\n", 
               temp->data.connectionID, temp->data.statusTime, temp->data.connectionQuality);
        temp = temp->next;
    }
}

int main() {
    Node* head = NULL;

    // Initialize the linked list
    initList(&head);

    // Insert some nodes into the list
    insertNode(&head, (NetworkConnectionStatus){1, 1643723400, 0.9});
    insertNode(&head, (NetworkConnectionStatus){2, 1643723410, 0.8});
    insertNode(&head, (NetworkConnectionStatus){3, 1643723420, 0.7});

    // Print the linked list
    printList(head);

    // Delete a node with connection ID 2
    deleteNode(&head, 2);

    // Print the updated linked list
    printList(head);

    return 0;
}
