#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONNECTIONS 10000
#define MAX_QUEUE_SIZE 1000
#define REQUEST_TIMEOUT 10

typedef struct connection_request {
    char client_ip[16];
    int port;
    time_t timestamp;
} connection_request;

sem_t semaphore;
connection_request *connections = NULL;
int connections_count = 0;
int max_connections = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *process_connection(void *arg) {
    connection_request *request = (connection_request *)arg;
    // Process the connection request here
    printf("Processing connection from %s:%d\n", request->client_ip, request->port);
    return NULL;
}

int manage_connections(int sock) {
    int client_socket = accept(sock, NULL, NULL);
    if (client_socket < 0) {
        perror("Error accepting socket");
        return -1;
    }

    connection_request *request = (connection_request *)malloc(sizeof(connection_request));
    inet_ntop(AF_INET, &request->client_ip, sizeof(request->client_ip), 16);
    request->port = ntohs(getpeername(client_socket, AF_INET, &request->client_ip));
    request->timestamp = time(NULL);

    pthread_mutex_lock(&mutex);
    if (connections_count >= MAX_CONNECTIONS) {
        sem_post(&semaphore);
        // Handle connection limit exceeded
    }

    connections[connections_count] = *request;
    connections_count++;

    pthread_mutex_unlock(&mutex);

    pthread_t thread;
    pthread_create(&thread, NULL, process_connection, request);
    pthread_join(thread, NULL);

    close(client_socket);
    return 0;
}

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        return -1;
    }

    listen(sock, MAX_QUEUE_SIZE);

    sem_init(&semaphore, 0, 0);

    while (1) {
        int client_socket = accept(sock, NULL, NULL);
        if (client_socket < 0) {
            perror("Error accepting socket");
            continue;
        }

        // Handle the connection here
        manage_connections(client_socket);
    }

    return 0;
}
