DynList* dyn_list_create(size_t initial_capacity) {
    DynList* dl = malloc(sizeof(DynList));
    if (!dl) return NULL;

    dl->capacity = initial_capacity;
    dl->count = 0;
    dl->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dl->data) {
        free(dl);
        return NULL;
    }

    return dl;
}

bool dyn_list_insert(DynList* dl, NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (dl->count >= dl->capacity) {
        size_t new_capacity = dl->capacity * 2;
        void* new_data = realloc(dl->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return false;

        dl->data = new_data;
        dl->capacity = new_capacity;
    }

    dl->data[dl->count] = *elem;
    dl->count++;
    return true;
}

void dyn_list_free(DynList* dl) {
    free(dl->data);
    free(dl);
}

