#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[2];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure to hold the list of NFAPI_CRC_INDICATION_PDU_T and its limits
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list;
    int max_list_size;
    int max_entries_per_rnti;
    pthread_mutex_t lock;
} NFAPICRCList;

// Function to create a new NFAPICRCList with given limits
NFAPICRCList* nfapi_crc_create(int max_list_size, int max_entries_per_rnti) {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    list->list = NULL;
    list->max_list_size = max_list_size;
    list->max_entries_per_rnti = max_entries_per_rnti;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new entry to the NFAPICRCList
int nfapi_crc_add(NFAPICRCList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    // Acquire lock for thread-safety
    pthread_mutex_lock(&list->lock);

    // Check if RNTI already exists in the list
    int found = 0;
    NFAPI_CRC_INDICATION_PDU_T* rnti_list = list->list;
    while (rnti_list && !found) {
        if (rnti_list->RNTI == RNTI) {
            // If found, append a unique identifier to the existing entry
            int new_rnti = RNTI * 1000 + rand();
            rnti_list->RX_UE_INFORMATION_TAG += new_rnti;
            found = 1;
        } else if (rnti_list->RNTI > RNTI) {
            break; // Exit the loop since we've reached a higher RNTI
        }
        rnti_list++;
    }

    // If not found, create a new entry and add it to the list
    if (!found && list->list == NULL) {
        list->list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->list->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        list->list->RNTI = RNTI;
        int crcflag = rand() % 2; // Randomly set CRCFLAG
        list->list->CRC_INDICATION_REL8_TAG[0] = crcflag;
        list->list->CRC_INDICATION_REL8_TAG[1] = crcflag;

        // Update the count and check for maximum limits
        if (list->max_entries_per_rnti > 0) {
            int rnti_count = 0;
            NFAPI_CRC_INDICATION_PDU_T* temp_list = list->list;
            while (temp_list) {
                if (temp_list->RNTI == RNTI) {
                    rnti_count++;
                    temp_list++;
                } else {
                    break; // Exit the loop since we've reached a higher RNTI
                }
            }
            if (rnti_count >= list->max_entries_per_rnti) {
                printf("Error: Maximum entries per RNTI exceeded for RNTI %d.\n", RNTI);
                return 1;
            }
        }

        // Check for maximum list size
        int count = 0;
        temp_list = list->list;
        while (temp_list) {
            count++;
            temp_list++;
        }
        if (count >= list->max_list_size) {
            printf("Error: Maximum list size exceeded.\n");
            return 1;
        }

    } else {
        // If entry found and it's not the first one, check for validity
        if (!found && rnti_list) {
            int ci = RX_UE_INFORMATION_TAG & 0xFF; // Get CI from RX_UE_INFORMATION_TAG
            int valid_ci = rnti_list->RX_UE_INFORMATION_TAG & 0xFF;
            if (ci != valid_ci) {
                printf("Error: Invalid cell identity (CI) combination for RNTI %d.\n", RNTI);
                return 1;
            }
        }

    }

    // Release lock
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to free the NFAPICRCList and its contents
void nfapi_crc_free(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* temp_list = list->list;
    while (temp_list) {
        NFAPI_CRC_INDICATION_PDU_T* next_temp_list = temp_list->next;
        free(temp_list);
        temp_list = next_temp_list;
    }
    free(list->list);
    pthread_mutex_unlock(&list->lock);
}

// Function to interface with an external logging framework
void log_error(const char* message) {
    // Implement your logging logic here
    printf("Error: %s\n", message);
}

int main() {
    NFAPICRCList* list = nfapi_crc_create(10, 5); // Create a new NFAPICRCList with limits

    int RX_UE_INFORMATION_TAG1 = 0x1234;
    int RNTI1 = 100;
    int ret_val = nfapi_crc_add(list, RX_UE_INFORMATION_TAG1, RNTI1);
    if (ret_val) {
        log_error("Error adding entry to the list");
    }

    // ... Add more entries and handle errors as needed ...

    // Free the NFAPICRCList
    nfapi_crc_free(list);

    return 0;
}

