    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addElement(Node** head, NFAPI_CRC_INDICATION_PDU_T* element) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Memory allocation failed");
        return;
    }
    newNode->data = *element;
    newNode->next = (*head);
    (*head) = newNode;
}

void removeElement(Node** head, int RNTI) {
    Node* current = (*head);
    Node* previous = NULL;
    while (current && current->data.RNTI != RNTI)
        previous = current, current = current->next;

    if (!current) return; // Element not found

    if (previous) previous->next = current->next;
    else *head = current->next;

    free(current);
}

void updateElement(Node** head, int RNTI, NFAPI_CRC_INDICATION_PDU_T* updatedElement) {
    Node* current = (*head);
    while (current && current->data.RNTI != RNTI)
        current = current->next;

    if (!current) return; // Element not found

    current->data = *updatedElement;
}

void* threadSafeCRCHandle(void* arg) {
    pthread_mutex_lock(&lock);

    // Perform operations on the list
    // ...

    pthread_mutex_unlock(&lock);
    return NULL;
}

