void createNfalock(int numNFALocks, int* maxListSize, sem_t* semaphore) {
    // Check input parameters
    if (numNFALocks < 1 || *maxListSize > MAX_NFALOCKS) {
        printf("Invalid configuration. Aborting.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfalockList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*maxListSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_init(semaphore, 0, 1); // Initialize semaphore with initial value 1

    for (int i = 0; i < numNFALocks; i++) {
        NFAPI_CRC_INDICATION_PDU_T nfalock;

        do {
            nfalock.ci = rand() % 100; // Generate random cell identity
            nfalock.rnti = rand() % 500; // Generate random RNTI
            nfalock.crc_indication_rel8_tag = (uint8_t)rand(); // Generate random CRC indication REL8 tag
            nfalock.crcflag = (uint8_t)rand(); // Generate random CRC flag

            if (nfalockList != NULL && findNFALock(nfalockList, *maxListSize, &nfalock)) {
                printf("Duplicate RNTI found. Skipping...\n");
                continue;
            }
        } while (findInvalidCI(nfalock.ci)); // Ensure cell identity is valid

        sem_wait(semaphore); // Acquire semaphore
        nfalockList[i] = nfalock; // Add NFALock to the list
        sem_post(semaphore); // Release semaphore

        if (i >= *maxListSize) {
            printf("Maximum number of NFALocks reached.\n");
            break;
        }
    }

    free(nfalockList);
    sem_destroy(semaphore); // Destroy semaphore
}

int findNFALock(NFAPI_CRC_INDICATION_PDU_T* list, int size, NFAPI_CRC_INDICATION_PDU_T* nfalock) {
    for (int i = 0; i < size; i++) {
        if ((list[i].ci == nfalock->ci && list[i].rnti == nfalock->rnti)) {
            return 1; // Duplicate found
        }
    }
    return 0; // No duplicate found
}

