    for (int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Failed to allocate memory.\n");
            return pdus;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        pdu->RNTI = rand() % 65536;
        strcpy(pdu->CRC_INDICATION_REL8_TAG, "0000");
        pdu->CRCFLAG = rand() % 2;

        if (i == 0) {
            pdus = pdu;
        } else {
            pdus = realloc(pdus, (num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*)));
            pdus[i - 1] = pdu - 1;
        }
    }

    return pdus;
}

void free_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T** pdus) {
    for (int i = 0; i < *pdus; i++) {
        free((*pdus)[i]);
    }
    free(*pdus);
}
