int nfapi_crc_indication_pdu_list_resize(NFAPI_CRC_INDICATION_PDU_LIST* list, size_t new_size) {
    if (new_size < list->used) {
        return -1; // cannot shrink the list
    }
    NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) {
        return -1; // memory allocation failed
    }
    list->allocated = new_size;
    list->elements = new_elements;
    return 0;
}

