} LTE_PHY_RX_PDU_T;

// Dynamic collection of LTE_PHY_RX_PDU_T structures
typedef struct {
    LTE_PHY_RX_PDU_T* elements;
    int size;
    int capacity;
} LTE_PHY_RX_PDU_COLLECTION;

// Initialize the dynamic collection with an initial capacity
LTE_PHY_RX_PDU_COLLECTION* lte_phy_rx_pdu_collection_init(int initial_capacity) {
    LTE_PHY_RX_PDU_COLLECTION* collection = (LTE_PHY_RX_PDU_COLLECTION*)malloc(sizeof(LTE_PHY_RX_PDU_COLLECTION));
    collection->elements = (LTE_PHY_PHY_RX_PDU_T*)calloc(initial_capacity, sizeof(LTE_PHY_PHY_RX_PDU_T));
    collection->size = 0;
    collection->capacity = initial_capacity;
    return collection;
}

// Add a new LTE_PHY_RX_PDU_T to the dynamic collection
void lte_phy_rx_pdu_collection_add(LTE_PHY_RX_PDU_COLLECTION* collection, LTE_PHY_RX_PDU_T new_element) {
    if (collection->size == collection->capacity) {
        // Double the capacity and reallocate elements array
        int new_capacity = collection->capacity * 2;
        LTE_PHY_PHY_RX_PDU_T* new_elements = (LTE_PHY_PHY_RX_PDU_T*)realloc(collection->elements, new_capacity * sizeof(LTE_PHY_PHY_RX_PDU_T));
        collection->elements = new_elements;
        collection->capacity = new_capacity;
    }
    collection->elements[collection->size] = new_element;
    collection->size++;
}

// Iterate over the dynamic collection to process each sub-packet
void lte_phy_rx_pdu_collection_process_sub_packets(LTE_PHY_RX_PDU_COLLECTION* collection, void (*process_sub_packet)(DL_CCCH_PDU_T*)) {
    for (int i = 0; i < collection->size; i++) {
        LTE_PHY_RX_PDU_T* current_element = &collection->elements[i];
        // Validate sub-packets before processing
        for (int j = 0; j < current_element->num_sub_packets; j++) {
            process_sub_packet(&current_element->sub_packets[j]);
        }
    }
}

// Free the dynamic collection and its elements
void lte_phy_rx_pdu_collection_free(LTE_PHY_RX_PDU_COLLECTION* collection) {
    for (int i = 0; i < collection->size; i++) {
        free(collection->elements[i].sub_packets);
    }
    free(collection->elements);
    free(collection);
}

// Example usage:
int main() {
    LTE_PHY_RX_PDU_COLLECTION* collection = lte_phy_rx_pdu_collection_init(4);

    // Add elements to the collection
    LTE_PHY_RX_PDU_T element1 = {PHICH_TAG_A, (DL_CCCH_PDU_T*)malloc(sizeof(DL_CCCH_PDU_T)), 2};
    LTE_PHY_RX_PDU_T element2 = {PHICH_TAG_B, (DL_CCCH_PDU_T*)malloc(sizeof(DL_CCCH_PDU_T)), 3};
    lte_phy_rx_pdu_collection_add(collection, element1);
    lte_phy_rx_pdu_collection_add(collection, element2);

