    if (!msg) return NULL;

    msg->message_id = message_id;
    msg->num_contexts = 0;
    msg->contexts = NULL;

    return msg;
}

void lte_rrc_cu_msg_add_context(LTE_RRC_CU_MSG_T* msg, int id, int state_transition_flag) {
    RRC_UC_Context* context = (RRC_UC_Context*)malloc(sizeof(RRC_UC_Context));
    if (!context) return; // Error: out of memory

    context->id = id;
    context->state_transition_flag = state_transition_flag;

    msg->contexts = realloc(msg->contexts, sizeof(RRC_UC_Context*) * (msg->num_contexts + 1));
    if (!msg->contexts) return; // Error: out of memory

    msg->contexts[msg->num_contexts] = context;
    msg->num_contexts++;
}

void lte_rrc_cu_msg_remove_context(LTE_RRC_CU_MSG_T* msg, int id) {
    for (int i = 0; i < msg->num_contexts; i++) {
        if (msg->contexts[i]->id == id) {
            free(msg->contexts[i]);
            break;
        }
    }

    msg->num_contexts--;
}

void lte_rrc_cu_msg_update_context(LTE_RRC_CU_MSG_T* msg, int id, int state_transition_flag) {
    for (int i = 0; i < msg->num_contexts; i++) {
        if (msg->contexts[i]->id == id) {
            msg->contexts[i]->state_transition_flag = state_transition_flag;
            break;
        }
    }
}

void lte_rrc_cu_msg_free(LTE_RRC_CU_MSG_T* msg) {
    for (int i = 0; i < msg->num_contexts; i++) {
        free(msg->contexts[i]);
    }

    free(msg->contexts);
    free(msg);
}
