void* lte_rrc_cu_msg_array;
int array_size;
int array_count;
pthread_mutex_t array_lock;
pthread_cond_t update_contexts_cond;

// Initialize the dynamically allocated array and synchronization primitives.
void init_lte_rrc_cu_msg_array(int size) {
    array_size = size;
    array_count = 0;
    lte_rrc_cu_msg_array = malloc(array_size * sizeof(LTE_RRC_CU_MSG_T));
    pthread_mutex_init(&array_lock, NULL);
    pthread_cond_init(&update_contexts_cond, NULL);
}

// Add a new LTE RRC CU MSG to the array.
void add_lte_rrc_cu_msg(LTE_RRC_CU_MSG_T* new_msg) {
    pthread_mutex_lock(&array_lock);
    if (array_count >= array_size) {
        // Resize the array and re-lock.
        array_size *= 2;
        lte_rrc_cu_msg_array = realloc(lte_rrc_cu_msg_array, array_size * sizeof(LTE_RRC_CU_MSG_T));
        pthread_mutex_unlock(&array_lock);
        add_lte_rrc_cu_msg(new_msg); // Recursively call the function with the updated array.
    } else {
        lte_rrc_cu_msg_array[array_count] = *new_msg;
        array_count++;
    }
    pthread_mutex_unlock(&array_lock);
}

// Remove an LTE RRC CU MSG from the array.
void remove_lte_rrc_cu_msg(uint32_t rrc_message_id) {
    pthread_mutex_lock(&array_lock);
    for (int i = 0; i < array_count; i++) {
        if (lte_rrc_cu_msg_array[i].rrc_message_id == rrc_message_id) {
            // Move the last context to the current position and decrement the count.
            lte_rrc_cu_msg_array[i] = lte_rrc_cu_msg_array[--array_count];
            break;
        }
    }
    pthread_mutex_unlock(&array_lock);
}

// Update an LTE RRC CU MSG in the array.
void update_lte_rrc_cu_msg(uint32_t rrc_message_id, LTE_RRC_CU_MSG_T* new_msg) {
    pthread_mutex_lock(&array_lock);
    for (int i = 0; i < array_count; i++) {
        if (lte_rrc_cu_msg_array[i].rrc_message_id == rrc_message_id) {
            lte_rrc_cu_msg_array[i] = *new_msg;
            break;
        }
    }
    pthread_mutex_unlock(&array_lock);
}

// Release any locks and free dynamically allocated memory.
void cleanup_lte_rrc_cu_msg_array() {
    pthread_mutex_destroy(&array_lock);
    pthread_cond_destroy(&update_contexts_cond);
    free(lte_rrc_cu_msg_array);
}
