```c
#include <stdio.h>
#include <stdlib.h>

// Define structure for a session
typedef struct {
    int sessionId;
    int* activeUsers; // List of active users
    time_t lastActivity; // Timestamp for the last activity
} Session;

// Define structure for a linked list node
typedef struct Node {
    Session session;
    struct Node* next;
} Node;

// Function to add a new user to an existing session
void addUserToSession(Session* session, int userId) {
    // Allocate memory for the user ID if necessary
    int* newUsers = realloc(session->activeUsers, (session->activeUsers ? sizeof(int) * (session->activeUsers[0] + 1) : sizeof(int)));

    // Add the user ID to the list of active users
    session->activeUsers[newUsers[0]++] = userId;
}

// Function to remove a user from an existing session
void removeUserFromSession(Session* session, int userId) {
    // Find the index of the user ID in the list of active users
    int i;
    for (i = 0; i < session->activeUsers[0]; i++) {
        if (session->activeUsers[i] == userId) break;
    }

    // Remove the user ID from the list of active users
    memmove(&session->activeUsers[i], &session->activeUsers[i + 1], sizeof(int) * (session->activeUsers[0] - i));
    session->activeUsers[0]--;
}

// Function to update the last activity timestamp for a session
void updateSessionActivity(Session* session, time_t newTime) {
    session->lastActivity = newTime;
}

// Function to create a new linked list node
Node* newNode(Session* session) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->session = *session;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new session to the linked list
void addSessionToLinkedList(Node** head, Session* session) {
    Node* newNode = newNode(session);

    // Add the new node to the front of the linked list if it's empty or update the head pointer if necessary
    if (*head == NULL || newNode->session.sessionId < (*head)->session.sessionId) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current && newNode->session.sessionId > current->session.sessionId) {
            current = current->next;
        }

        // Insert the new node after the correct position
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to remove a session from the linked list
void removeSessionFromLinkedList(Node** head, int sessionId) {
    Node* current = *head;
    Node* previous = NULL;

    // Find the node with the matching session ID
    while (current && current->session.sessionId != sessionId) {
        previous = current;
        current = current->next;
    }

    // Remove the node from the linked list if found
    if (current) {
        if (previous) {
            previous->next = current->next;
        } else {
            *head = current->next;
        }

        free(current);
    }
}

// Function to print the linked list
void printLinkedList(Node* head) {
    Node* current = head;

    // Traverse the linked list and print each node's contents
    while (current) {
        printf("Session ID: %d, Users: ", current->session.sessionId);

        int i;
        for (i = 0; i < current->session.activeUsers[0]; i++) {
            printf("%d ", current->session.activeUsers[i]);
        }
        printf(", Last Activity: %lu\n", current->session.lastActivity);

        current = current->next;
    }
}
