    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T_List;

void nfa_pi_crc_indication_pdu_list_init(NFAPI_CRC_INDICATION_PDU_T_List* list, size_t initial_capacity) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->used = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void nfa_pi_crc_indication_pdu_list_insert(NFAPI_CRC_INDICATION_PDU_T_List* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->used == list->capacity) {
        // Resize the list
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    // Check for duplicate RNTI
    for (size_t i = 0; i < list->used; i++) {
        if (list->elements[i].RNTI == element.RNTI) {
            // Merge the elements
            element.CRCFLAG |= list->elements[i].CRCFLAG;
            free(list->elements[i]);
            break;
        }
    }

    // Insert the new element
    list->elements[list->used++] = element;

    pthread_mutex_unlock(&list->lock);
}

void nfa_pi_crc_indication_pdu_list_free(NFAPI_CRC_INDICATION_PDU_T_List* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->used; i++) {
        free(list->elements[i]);
    }

    free(list->elements);
    pthread_mutex_unlock(&list->lock);
