    if ((list = malloc(struct_size)) != NULL) {
        memset(list, 0, struct_size);
    } else {
        return NULL; // Handle memory allocation failure
    }

    // Initialize the current position pointer to point to the start of the list
    current = list;

    // Loop until the maximum number of structures is reached or an error occurs
