    struct DL_CCCH_PDU_T** subpackets;
} LTE_PHY_RX_PDU_T;

void* lte_phy_rx_pdu_collection_realloc(void* ptr, size_t old_size, size_t new_size) {
    void* new_ptr = realloc(ptr, new_size);
    if (new_ptr == NULL && old_size > 0) {
        printf("Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

void lte_phy_rx_pdu_collection_init(LTE_PHY_RX_PDU_T** collection, int* size) {
    *collection = (LTE_PHY_RX_PDU_T*)lte_phy_rx_pdu_collection_realloc(NULL, 0, sizeof(LTE_PHY_RX_PDU_T)*MAX_COLLECTION_SIZE);
    *size = MAX_COLLECTION_SIZE;
}

int lte_phy_rx_pdu_collection_validate(LTE_PHY_RX_PDU_T** collection, int size) {
    for (int i = 0; i < size; i++) {
        if (!collection[i]->phich_tag || !collection[i]->num_subpackets) {
            printf("Invalid LTE_PHY_RX_PDU_T structure at index %d!\n", i);
            return -1;
        }
    }
    return 0;
}

void lte_phy_rx_pdu_collection_add(LTE_PHY_RX_PDU_T** collection, int* size, LTE_PHY_RX_PDU_T new_pdu) {
    if (*size >= MAX_COLLECTION_SIZE) {
        printf("Collection is full. Cannot add more items.\n");
        return;
    }
    memcpy(&collection[*size], &new_pdu, sizeof(LTE_PHY_RX_PDU_T));
    (*size)++;
}

void lte_phy_rx_pdu_collection_remove(LTE_PHY_RX_PDU_T** collection, int* size) {
    if (*size > 0) {
        for (int i = 0; i < *size - 1; i++) {
            memcpy(&collection[i], &collection[i + 1], sizeof(LTE_PHY_RX_PDU_T));
        }
        free(collection[*size]);
        (*size]--;
    } else {
        printf("Collection is empty. Cannot remove items.\n");
    }
}

void lte_phy_rx_pdu_collection_log(LTE_PHY_RX_PDU_T** collection, int size) {
    FILE* log_file = fopen("lte_phy_rx_pdu_collection.log", "a+");
    for (int i = 0; i < size; i++) {
        fprintf(log_file, "Added PDU at index %d: PHICH_TAG: %02x, Number of subpackets: %d\n", i, collection[i]->phich_tag, collection[i]->num_subpackets);
    }
    fclose(log_file);
}

void* lte_phy_rx_pdu_collection_iterate(void* ptr) {
    LTE_PHY_RX_PDU_T** collection = (LTE_PHY_RX_PDU_T**)ptr;
    int size = *(int*)collection[0];
    for (int i = 0; i < size; i++) {
        printf("Processing PDU at index %d: PHICH_TAG: %02x, Number of subpackets: %d\n", i, collection[i]->phich_tag, collection[i]->num_subpackets);
    }
    return NULL;
}

void* lte_phy_rx_pdu_collection_lock(void* ptr) {
    pthread_mutex_lock((pthread_mutex_t*)ptr);
    return NULL;
}

void* lte_phy_rx_pdu_collection_unlock(void* ptr) {
    pthread_mutex_unlock((pthread_mutex_t*)ptr);
    return NULL;
}

int main() {
    LTE_PHY_RX_PDU_T* collection = NULL;
    int size = 0;

    // Initialize the collection
    lte_phy_rx_pdu_collection_init(&collection, &size);

    // Add some PDUs to the collection
    for (int i = 0; i < 5; i++) {
        LTE_PHY_RX_PDU_T new_pdu;
        new_pdu.phich_tag = i % 256;
        new_pdu.num_subpackets = rand() % 4 + 1;
        // Simulate some sub-packets
