            // Initialize the sub-packets
            new_pdu.subpackets[j]->packet_type = rand() % 2;
            new_pdu.subpackets[j]->data_length = rand() % 1024 + 1;
        }
        lte_phy_rx_pdu_collection_add(&collection, &size, new_pdu);
    }

    // Remove some PDUs from the collection
    for (int i = size - 1; i >= 0; i--) {
        lte_phy_rx_pdu_collection_remove(&collection, &size);
    }

    // Validate the remaining PDUs in the collection
    if (lte_phy_rx_pdu_collection_validate(&collection, size) < 0) {
        printf("Validation failed!\n");
    } else {
        printf("Collection validated successfully.\n");
    }

