// Structure for the dynamic list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;         // Mutex for thread-safe access
} NFAPI_CRC_INDICATION_PDU_LIST;

// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_LIST* create_list() {
    NFAPI_CRC_INDICATION_PDU_LIST* list = (NFAPI_CRC_INDICATION_PDU_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    if (!list) {
        return NULL;                   // Handle memory allocation failure
    }

    list->elements = NULL;
    list->size = 0;
    list->capacity = CAPACITY_LIMIT;
    pthread_mutex_init(&list->mutex, NULL);   // Initialize mutex

    return list;
}

// Function to add an NFAPI_CRC_INDICATION_PDU_T element to the list
int add_element(NFAPI_CRC_INDICATION_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&list->mutex);           // Lock for thread-safe access

    if (list->size >= list->capacity) {          // Check capacity limit
        if (!remove_oldest_element(list)) {      // Remove oldest element to maintain size
            pthread_mutex_unlock(&list->mutex);
            return -1;                           // Handle error
        }
    }

    list->elements = realloc(list->elements, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        pthread_mutex_unlock(&list->mutex);
        return -1;                               // Handle memory allocation failure
    }

    list->elements[list->size++] = new_element;

    pthread_mutex_unlock(&list->mutex);           // Unlock for thread-safe access

    return 0;                                       // Successful addition
}

// Function to remove the oldest element from the list
int remove_oldest_element(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    if (list->size == 0) {                         // Check list size
        return -1;                                   // Handle error
    }

    free(list->elements);                             // Free memory for removed element

    list->size--;

    return 0;                                       // Successful removal
}

// Function to print the NFAPI_CRC_INDICATION_PDU_T elements in the list
void print_list(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    pthread_mutex_lock(&list->mutex);           // Lock for thread-safe access

    for (size_t i = 0; i < list->size; i++) {
        printf("%p: %d\n", &list->elements[i], list->elements[i].crcflag);
    }

    pthread_mutex_unlock(&list->mutex);           // Unlock for thread-safe access
}

int main() {
    NFAPI_CRC_INDICATION_PDU_LIST* list = create_list();      // Create the dynamic list

    // Add elements to the list
    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T new_element;
        // Initialize new_element here...

        if (add_element(list, new_element) != 0) {         // Add element to the list
            printf("Error adding element: %d\n", i);
            break;
        }
    }

    print_list(list);                                  // Print the elements in the list

    remove_oldest_element(list);                         // Remove the oldest element from the list

    free(list->elements);                                 // Free memory for removed element

    return 0;                                            // Successful execution
}

