NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationPDU(int N, int maxRNTI) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = &structures[i];

        // ensure no two consecutive structures have the same RNTI value
        int rnti;
        do {
            rnti = rand() % maxRNTI;
        } while (i > 0 && rnti == structures[i-1].RNTI);

        strcpy(structure->RX_UE_INFORMATION_TAG, "Tag"); // populate RX_UE_INFORMATION_TAG
        structure->RNTI = rnti; // assign RNTI

        // populate CRC_INDICATION_REL8_TAG and CRCFLAG
        sprintf(structure->CRC_INDICATION_REL8_TAG, "Flag-%d", i);
        structure->CRCFLAG = (unsigned short) rand();

        logStructureCreation(structure); // log creation

        if (structure->RNTI < 0 || structure->RNTI >= maxRNTI) {
            printf("Invalid RNTI value: %d. Abort.\n");
            return NULL; // handle error
        }
    }

    return structures;
}

