};

NFAPI_CRC_INDICATION_PDU_T* create_array_manager() {
    struct array_manager* arr = (struct array_manager*)malloc(sizeof(struct array_manager));
    arr->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(10000, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size = 0;
    arr->capacity = 10000;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_array_manager(struct array_manager* arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_element(struct array_manager* arr, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (arr->size >= arr->capacity) {
        // resize the array
        arr->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->data, (arr->capacity * 2 + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arr->capacity *= 2;
    }
    arr->data[arr->size] = new_element;
    arr->size++;
    return arr->size - 1; // return the index of the newly added element
}

int update_element(struct array_manager* arr, int index, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (index < 0 || index >= arr->size) {
        printf("Invalid index\n");
        return -1;
    }
    arr->data[index] = new_element;
    return 0; // successful update
}

int remove_element(struct array_manager* arr, int index) {
    if (index < 0 || index >= arr->size) {
        printf("Invalid index\n");
        return -1;
    }
    for (int i = index; i < arr->size - 1; i++) {
        arr->data[i] = arr->data[i + 1];
    }
    arr->size--;
    return 0; // successful removal
}

double get_average_crc_flag(struct array_manager* arr) {
    double sum = 0;
    for (int i = 0; i < arr->size; i++) {
        sum += arr->data[i].crc_indication.CRCFLAG;
    }
    return sum / arr->size;
}

int main() {
    struct array_manager* arr = create_array_manager();

    // add, update and remove elements here
    NFAPI_CRC_INDICATION_PDU_T new_element;
    int index = add_element(arr, new_element);
    int result = update_element(arr, index, new_element);
    int removed_index = remove_element(arr, 0);

    double average_crc_flag = get_average_crc_flag(arr);

    // serialize the array to a binary file
    FILE* file = fopen("data.bin", "wb");
    fwrite(&arr->data[0], sizeof(NFAPI_CRC_INDICATION_PDU_T), arr->size, file);
    fclose(file);

    return 0;
}
