// List structure to manage dynamic list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T_LIST;

NFAPI_CRC_INDICATION_PDU_T_LIST* nfaapi_crc_indication_pdu_list_create() {
    NFAPI_CRC_INDICATION_PDU_T_LIST* list = (NFAPI_CRC_INDICATION_PDU_T_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_LIST));
    if (!list) return NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    list->capacity = 1;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    return list;
}

void nfaapi_crc_indication_pdu_list_free(NFAPI_CRC_INDICATION_PDU_T_LIST* list) {
    if (list) {
        pthread_mutex_lock(&list->mutex);
        for (int i = 0; i < list->size; i++) {
            free(&list->data[i]);
        }
        free(list->data);
        list->data = NULL;
        pthread_mutex_unlock(&list->mutex);
        free(list);
    }
}

void nfaapi_crc_indication_pdu_list_append(NFAPI_CRC_INDICATION_PDU_T_LIST* list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (!list || !new_element) return;
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->capacity = new_capacity;
        list->data = new_data;
    }
    memcpy(&list->data[list->size], &new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void nfaapi_crc_indication_pdu_list_serialize(NFAPI_CRC_INDICATION_PDU_T_LIST* list, FILE* file) {
    if (!list || !file) return;
    pthread_mutex_lock(&list->mutex);
    fwrite(&list->size, sizeof(int), 1, file);
    for (int i = 0; i < list->size; i++) {
        fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->mutex);
}

void nfaapi_crc_indication_pdu_list_deserialize(NFAPI_CRC_INDICATION_PDU_T_LIST* list, FILE* file) {
    if (!list || !file) return;
    int size = 0;
    fread(&size, sizeof(int), 1, file);
    list->size = size;
    pthread_mutex_lock(&list->mutex);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        fread(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->mutex);
}
