class RandomGenerator {
private:
    int minRange;
    int maxRange;
    float minFloatRange;
    float maxFloatRange;

public:
    RandomGenerator(int min, int max, float minFloat, float maxFloat) {
        this->minRange = min;
        this->maxRange = max;
        this->minFloatRange = minFloat;
        this->maxFloatRange = maxFloat;
    }

    int generateRandomInt() {
        return (rand() % ((this->maxRange - this->minRange) + 1)) + this->minRange;
    }

    float generateRandomFloat() {
        return ((double) rand()) / (RAND_MAX * (this->maxFloatRange - this->minFloatRange));
    }

    std::string toString() {
        return std::to_string(this->minRange) + "-" + std::to_string(this->maxRange);
    }
};

NFAPI_CRC_INDICATION_PDU_T* generateNfalogs(int N, RandomGenerator* generator) {
    NFAPI_CRC_INDICATION_PDU_T* nfaPduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T nfaPdu;
        nfaPdu.RX_UE_INFORMATION_TAG = generator->generateRandomInt();
        nfaPdu.RNTI = generator->generateRandomInt();
        nfaPdu.CRC_INDICATION_REL8_TAG = (uint8_t)generator->generateRandomFloat() * 256;

        nfaPduList[i] = nfaPdu;
    }

    return nfaPduList;
}
