// Define the structure for TX_UE_INFORMATION_TAG
typedef struct {
    RRC_CONNECTION_CONTEXT connection_context;
    CELL_ID cell_id;
    TRANSPORT_FORMAT_COMBINATION transport_format_combination;
    SRS_FLAG srs_flag;
    PUSCH_GRANT pusch_grant;
