// Function to dynamically manage the collection of TX_UE_INFORMATION_TAG structures
TX_UE_INFORMATION_TAG** tx_ue_info_tags = NULL; // Initialize an array to store TX_UE_INFORMATION_TAG pointers

void add_tx_ue_info_tag(RRC_CONNECTION_CONTEXT connection_context, CELL_ID cell_id, TRANSPORT_FORMAT_COMBINATION transport_format_combination, SRS_FLAG srs_flag, PUSCH_GRANT pusch_grant) {
    int max_size = 10; // Initialize the maximum size of the array
    if (!tx_ue_info_tags) { // Check if the array is not initialized yet
        tx_ue_info_tags = (TX_UE_INFORMATION_TAG**)malloc(max_size * sizeof(TX_UE_INFORMATION_TAG*)); // Dynamically allocate memory for the array
        for (int i = 0; i < max_size; i++) {
            tx_ue_info_tags[i] = NULL; // Initialize each pointer to NULL
        }
    }

    int current_size = 0;
    if (current_size >= max_size) { // Check if the array has reached its maximum size
        max_size *= 2; // Double the maximum size of the array
        TX_UE_INFORMATION_TAG** new_array = (TX_UE_INFORMATION_TAG**)realloc(tx_ue_info_tags, max_size * sizeof(TX_UE_INFORMATION_TAG*)); // Dynamically reallocate memory for the increased size
        tx_ue_info_tags = new_array;
        for (int i = current_size; i < max_size; i++) {
            tx_ue_info_tags[i] = NULL; // Initialize each pointer to NULL
        }
    }

    TX_UE_INFORMATION_TAG* tag = (TX_UE_INFORMATION_TAG*)malloc(sizeof(TX_UE_INFORMATION_TAG)); // Dynamically allocate memory for the new TX_UE_INFORMATION_TAG structure
    if (!tag) {
        printf("Memory allocation failed for adding a new TX_UE_INFORMATION_TAG.\n");
        return;
    }

    tag->connection_context = connection_context;
    tag->cell_id = cell_id;
    tag->transport_format_combination = transport_format_combination;
    tag->srs_flag = srs_flag;
    tag->pusch_grant = pusch_grant;

    tx_ue_info_tags[current_size] = tag; // Add the new TX_UE_INFORMATION_TAG structure to the array
    current_size++;
}

void serialize_tx_ue_info_tags_to_json(char* json_string) {
    json_object* root = json_object_new_object();
    for (int i = 0; i < current_size; i++) {
        TX_UE_INFORMATION_TAG* tag = tx_ue_info_tags[i];
        json_object* sub_obj = json_object_new_object();
        json_object_object_add(sub_obj, "connection_context", json_object_new_string(json_object_to_json_string(tag->connection_context)));
        json_object_object_add(sub_obj, "cell_id", json_object_new_int(tag->cell_id));
        json_object_object_add(sub_obj, "transport_format_combination", json_object_new_string(json_object_to_json_string(tag->transport_format_combination)));
        json_object_object_add(sub_obj, "srs_flag", json_object_new_bool(tag->srs_flag));
        json_object_object_add(sub_obj, "pusch_grant", json_object_new_int(tag->pusch_grant));
        json_object_object_add(root, json_object_get_string(json_object_to_json_string(tag)), sub_obj);
    }
    // Convert the JSON object to a string
    char* result = json_object_to_json_string(root);
    strcpy(json_string, result);
}
