void validateStringAndAppend(char* str, int maxLength) {
    if (strlen(str) > maxLength) {
        char* trimmedStr = strtok(str, "");
        while (strlen(trimmedStr) > maxLength) {
            strcat(trimmedStr, "");
            trimmedStr = strtok(NULL, "");
        }
        strcpy(str, trimmedStr);
    } else {
        uint32_t uniqueId = (uint32_t)hash(str) ^ time(NULL);
        sprintf(str + strlen(str), ":%u", uniqueId);
