            continue;
        }

        // Initialize and populate the frame PDU structure
        frame_pdu->raw_data = malloc(frame_pdu_size);
        if (!frame_pdu->raw_data) {
            log_error("Failed to allocate memory for raw data");
            free(frame_pdu);
            continue;
        }

        // Compress the raw data buffer if required
        if (compress_data) {
            compress_frame_pdu(frame_pdu, frame_pdu_size);
        }

