#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Define structure for network device context
typedef struct {
    struct sockaddr_in ip_addr;
    uint32_t subnet_mask;
    char *routing_table[5]; // Assuming 5 routing table entries max
    int num_routing_entries;
    void *config_updates; // Dynamically allocated list of updates
} net_device_ctx;

// Define structure for network device configuration
typedef struct {
    char *ip_addr_str;
    uint32_t subnet_mask_val;
    char **routing_table_entries;
    int num_routing_entries;
} net_device_config;

// Initialize and configure a series of network devices
net_device_ctx *init_net_devices(int num_devices, const net_device_config *configs) {
    // Allocate memory for the device contexts
    net_device_ctx *devices = (net_device_ctx *)malloc(num_devices * sizeof(net_device_ctx));

    if (!devices) {
        return NULL; // Handle memory allocation failure
    }

    // Initialize and configure each network device context
    for (int i = 0; i < num_devices; i++) {
        net_device_config *config = &configs[i];

        devices[i].ip_addr.sin_family = AF_INET;
        devices[i].ip_addr.sin_port = htons(0); // Use default port

        inet_pton(AF_INET, config->ip_addr_str, &devices[i].ip_addr.sin_addr);
        devices[i].subnet_mask = config->subnet_mask_val;

        // Initialize routing table entries
        for (int j = 0; j < config->num_routing_entries; j++) {
            devices[i].routing_table[j] = strdup(config->routing_table_entries[j]);
        }
        devices[i].num_routing_entries = config->num_routing_entries;

        // Dynamically allocate memory for configuration updates
        devices[i].config_updates = malloc(sizeof(void *));
        *devices[i].config_updates = NULL; // Initialize update list
    }

    return devices;
}

// Free allocated resources and device contexts
void free_net_devices(net_device_ctx *devices, int num_devices) {
    for (int i = 0; i < num_devices; i++) {
        free(devices[i].config_updates);

        // Free routing table entries
        for (int j = 0; j < devices[i].num_routing_entries; j++) {
            free(devices[i].routing_table[j]);
        }
    }

    free(devices);
}
