} ue_context;

ue_context* initialize_ue_context(int cell_id, int tac) {
    ue_context* context = (ue_context*)malloc(sizeof(ue_context));
    if (!context) {
        return NULL;
    }
    context->cell_id = cell_id;
    context->tac = tac;
    context->rrc_status = 0; // disconnected
    for (int i = 0; i < MAX_RRC_MESSAGES; i++) {
        context->messages[i] = NULL;
    }
    return context;
}

void free_ue_context(ue_context* context) {
    if (!context) {
        return;
    }
    for (int i = 0; i < MAX_RRC_MESSAGES; i++) {
        free(context->messages[i]);
    }
    free(context);
}

ue_context** allocate_ue_contexts(int num_contexts) {
    ue_context** contexts = (ue_context**)malloc(num_contexts * sizeof(ue_context*));
    if (!contexts) {
        return NULL;
    }
    for (int i = 0; i < num_contexts; i++) {
        contexts[i] = initialize_ue_context(i, i); // default TAC
    }
    return contexts;
}

void deallocate_ue_contexts(ue_context** contexts, int num_contexts) {
    if (!contexts || !num_contexts) {
        return;
    }
    for (int i = 0; i < num_contexts; i++) {
        free_ue_context(contexts[i]);
    }
    free(contexts);
