typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    unsigned int timestamp;
    uuid_t UUID;
} NFAPI_CRC_INDICATION_PDU_T;

void* list_allocator(size_t size) {
    void* memory = malloc(size);
    if (memory == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return memory;
}

void list_free(void** list, size_t size) {
    free(*list);
}

int find_duplicate_RNTI(void* list, size_t size) {
    for (size_t i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = ((NFAPI_CRC_INDICATION_PDU_T*) list + i);
        for (size_t j = i + 1; j < size; j++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu2 = ((NFAPI_CRC_INDICATION_PDU_T*) list + j);
            if (pdu->RNTI == pdu2->RNTI) {
                return 1;
            }
        }
    }
    return 0;
}

void serialize_list(void* list, size_t size, FILE* file) {
    for (size_t i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = ((NFAPI_CRC_INDICATION_PDU_T*) list + i);
        fwrite(&pdu->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&pdu->RNTI, sizeof(int), 1, file);
        fwrite(pdu->CRC_INDICATION_REL8_TAG, sizeof(char) * 16, 1, file);
        fwrite(&pdu->timestamp, sizeof(unsigned int), 1, file);
        uuid_unparse(pdu->UUID, pdu->UUID_str, 37);
        fwrite(pdu->UUID_str, sizeof(char) * 37, 1, file);
    }
}

int deserialize_list(void** list, size_t* size, FILE* file) {
    size_t newSize = *size;
    void* newMemory = realloc(*list, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newMemory == NULL) {
        printf("Memory reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    *list = newMemory;

    for (size_t i = 0; i < newSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = ((NFAPI_CRC_INDICATION_PDU_T*) *list + i);
        fread(&pdu->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fread(&pdu->RNTI, sizeof(int), 1, file);
        fread(pdu->CRC_INDICATION_REL8_TAG, sizeof(char) * 16, 1, file);
        fread(&pdu->timestamp, sizeof(unsigned int), 1, file);
        uuid_parse(NULL, pdu->UUID, pdu->UUID_str, 37);
        fread(pdu->UUID_str, sizeof(char) * 37, 1, file);
    }
    return 0;
}

int main() {
    // Example usage:
    size_t listSize = 10; // User-specified parameter
    void* list = list_allocator(listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < listSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i % 256;
        pdu.RNTI = i + 1;
        strcpy(pdu.CRC_INDICATION_REL8_TAG, "Example Tag");
        pdu.timestamp = time(NULL);
        uuid_generate_random(UUID);

        // Ensure no duplicate RNTIs
        if (find_duplicate_RNTI(list, listSize)) {
            printf("Duplicate RNTI detected. Exiting.\n");
            exit(EXIT_FAILURE);
        }

        ((NFAPI_CRC_INDICATION_PDU_T*)list + i) = &pdu;
    }

    // Serialize the list for storage
    FILE* file = fopen("data.bin", "wb");
    serialize_list(list, listSize, file);
    fclose(file);

    // Deserialize the list from storage
    file = fopen("data.bin", "rb");
    void* deserializedList = list_allocator(listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    deserialize_list(&deserializedList, &listSize, file);
    fclose(file);

    list_free(&list, listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list_free(&deserializedList, listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}
