NFAPI_CRC_INDICATION_PDU_T* create_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    srand(time(NULL)); // initialize random seed
    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        int rnti = rand() % 10000;
        while (rnti <= i) { // ensure uniqueness of RNTI values
            rnti = rand() % 10000;
        }
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        int crcflag = (rand() % 2) ? 1 : 0; // random CRCFLAG
        list[i].CRCFLAG = crcflag;

        if ((i + 1) % 10000 == 0) { // filter by CRCFLAG value, every 10,000th entry
            for (int j = i - 9999; j >= 0; j--) {
                if (list[j].CRCFLAG == crcflag) {
                    free(list);
                    return NULL;
                }
            }
        }
    }

    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    for (int i = 0; i < n; i++) {
        free(list[i].RX_UE_INFORMATION_TAG); // handle memory allocation failure
        free(list[i]);
    }
    free(list);
}
