        } while (i > 0 && find_duplicate(structures, i));

        structures[i].CRC_INDICATION_REL8_TAG = rand();
        structures[i].CRCFLAG = rand() % 2;
    }

    return structures;
}

int find_duplicate(NFAPI_CRC_INDICATION_PDU_T* structures, int N) {
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (structures[i].RNTI == structures[j].RNTI) return 1;
        }
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* filter_structures(NFAPI_CRC_INDICATION_PDU_T* structures, int N, int target_crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* filtered_structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!filtered_structures) return NULL;

    for (int i = 0; i < N; i++) {
        if (structures[i].CRCFLAG == target_crcflag)
            filtered_structures[i] = structures[i];
        else
            filtered_structures[i].RNTI = -1; // invalid RNTI, remove this structure from consideration
    }

    return filtered_structures;
}

int validate_integrity(NFAPI_CRC_INDICATION_PDU_T* structures, int N) {
