            pdus[i].RNTI = rand() % 10000;
        } while (find_RNTI(pdus, i) != -1);
        pdus[i].CRCFLAG = rand() % 2;
    }

    return pdus;
}

int find_RNTI(NFAPI_CRC_INDICATION_PDU_T *pdus, int index) {
    for (int i = 0; i < index; i++) {
        if (pdus[i].RNTI == pdus[index].RNTI)
            return i;
    }
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* filter_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T *pdus, int N, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *filtered_pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc((N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int j = 0;

    for (int i = 0; i < N; i++) {
        if (pdus[i].CRCFLAG == CRCFLAG) {
            filtered_pdus[j] = pdus[i];
            j++;
        }
    }

    free(pdus);
    return filtered_pdus;
}

void free_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T *pdus, int N) {
