#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    char protocol[8];
    int packetSize;
} DataTransferObject;

void initializeArray(DataTransferObject **array, int *size) {
    *array = (DataTransferObject *)calloc(1, sizeof(DataTransferObject));
    *size = 0;
}

int addEntry(DataTransferObject **array, int *size, char sourceIP[], char destinationIP[], char protocol[], int packetSize) {
    if (*size == 0 || !(*array)) {
        DataTransferObject *newArray = (DataTransferObject *)calloc(2, sizeof(DataTransferObject));
        memcpy(newArray->sourceIP, sourceIP, strlen(sourceIP)+1);
        memcpy(newArray->destinationIP, destinationIP, strlen(destinationIP)+1);
        memcpy(newArray->protocol, protocol, strlen(protocol)+1);
        newArray->packetSize = packetSize;
        (*array) = newArray;
        *size = 1;
    } else {
        DataTransferObject *tempArray = (DataTransferObject *)calloc((*size+1), sizeof(DataTransferObject));
        memcpy(tempArray, *array, (*size)*sizeof(DataTransferObject));
        free(*array);
        *array = tempArray;
        DataTransferObject *newEntry = &tempArray[(*size)-1];
        memcpy(newEntry->sourceIP, sourceIP, strlen(sourceIP)+1);
        memcpy(newEntry->destinationIP, destinationIP, strlen(destinationIP)+1);
        memcpy(newEntry->protocol, protocol, strlen(protocol)+1);
        newEntry->packetSize = packetSize;
        (*size)++;
    }
}

int updateEntry(DataTransferObject **array, int *size, int index, char sourceIP[], char destinationIP[], char protocol[], int packetSize) {
    if (index < 0 || index >= *size)
        return -1; // invalid index
    DataTransferObject *tempArray = (DataTransferObject *)calloc((*size+1), sizeof(DataTransferObject));
    memcpy(tempArray, *array, (*size)*sizeof(DataTransferObject));
    free(*array);
    *array = tempArray;
    DataTransferObject *entry = &tempArray[index];
    memcpy(entry->sourceIP, sourceIP, strlen(sourceIP)+1);
    memcpy(entry->destinationIP, destinationIP, strlen(destinationIP)+1);
    memcpy(entry->protocol, protocol, strlen(protocol)+1);
    entry->packetSize = packetSize;
    return 0; // successful update
}

int printStatistics(DataTransferObject *array, int size) {
    printf("Total packets: %d\n", size);
    int totalPacketSize = 0;
    char *protocols[256] = {0}; // assuming 256 unique protocols max
    int protocolCounts[256] = {0};
    for (int i = 0; i < size; i++) {
        DataTransferObject *entry = &array[i];
        totalPacketSize += entry->packetSize;
        char *protocol = entry->protocol;
        if (!protocols[atoi(protocol)])
            protocols[atoi(protocol)] = strdup(protocol);
        protocolCounts[atoi(protocol)]++;
    }
    printf("Average packet size: %d\n", totalPacketSize / size);
    for (int i = 0; i < 256; i++) {
        if (protocols[i])
            printf("Protocol %s used %d times.\n", protocols[i], protocolCounts[i]);
        free(protocols[i]);
    }
}

void handleData(DataTransferObject **array, int *size) {
    // integration logic with external data source
    char sourceIP[] = "192.168.1.100";
    char destinationIP[] = "8.8.8.8";
    char protocol[] = "TCP";
    int packetSize = 1024;
    addEntry(array, size, sourceIP, destinationIP, protocol, packetSize);
}

int main() {
    DataTransferObject *array = NULL;
    int size = 0;
    initializeArray(&array, &size);

    // handle data
    for (int i = 0; i < 100000; i++) {
        char sourceIP[] = "192.168.1.100";
        char destinationIP[] = "8.8.8.8";
        char protocol[] = "TCP";
        int packetSize = rand() % 1024 + 1;
        addEntry(&array, &size, sourceIP, destinationIP, protocol, packetSize);
    }

    // print statistics
    printStatistics(array, size);

    return 0;
}
