    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int list_size = 0;

void* generate_random_crcflag() {
    return (void*) rand();
}

void create_and_populate_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&lock);
        if (list_size >= MAX_SIZE) break;
        NFAPI_CRC_INDICATION_PDU_T* p = &new_list[i];
        // Generate random RX_UE_INFORMATION_TAG and RNTI
        sprintf(p->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_%d", i);
        p->RNTI = rand() % 1000;
        // Generate random CRC_INDICATION_REL8_TAG with a set CRCFLAG
        sprintf(p->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG_%x", (unsigned int) *generate_random_crcflag());
        p->CRCFLAG = (int) *(void*) generate_random_crcflag();
        // Check for uniqueness based on RX_UE_INFORMATION_TAG and RNTI
        int is_unique = 1;
        for (int j = 0; j < list_size; j++) {
            if (strcmp(p->RX_UE_INFORMATION_TAG, list[j].RX_UE_INFORMATION_TAG) == 0 && p->RNTI == list[j].RNTI) {
                is_unique = 0;
                break;
            }
        }
        if (!is_unique) i--; // skip this iteration
        pthread_mutex_unlock(&lock);
    }
    free(new_list);
}

int main() {
    int n = 100; // adjust the size as needed
    create_and_populate_list(n);
    return 0;
}
