int allocate_stats(int count, int max_size) {
    if (count < MIN_STATS || count > MAX_STATS) {
        printf("Invalid statistics count. Please enter a value between %d and %d.\n", MIN_STATS, MAX_STATS);
        return -1;
    }

    UeStats* new_list = (UeStats*) malloc(count * sizeof(UeStats));
