        printf("Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < count; i++) {
        new_list[i].Rnti = rand() % 1000000;
        new_list[i].Mcs = rand() % 10 + 1;
        new_list[i].Cqi = rand() % 20 + 1;

        new_list[i].UCI = (char*) malloc(MAX_UCI_SIZE);
        if (!new_list[i].UCI) {
            printf("Memory allocation for UCI failed.\n");
            free(new_list);
            return -1;
