// Define the structure for DEVICE_STATUS_UPDATE_T
typedef struct {
    int device_id;
    time_t timestamp;
    int status_flag;
} DEVICE_STATUS_UPDATE_T;

// Function to manage dynamic list of structured data
void manage_device_status_updates() {
    // Initialize a custom memory pool allocator
    void* memory_pool = malloc(5000 * sizeof(DEVICE_STATUS_UPDATE_T));
    void* current_ptr = memory_pool;

    // Allocate a fixed-size array for the dynamic list
    DEVICE_STATUS_UPDATE_T* device_status_updates = (DEVICE_STATUS_UPDATE_T*)current_ptr;
    current_ptr += 5000 * sizeof(DEVICE_STATUS_UPDATE_T);

    int num_updates = 0;

    // Function to populate the dynamic list with new updates
    void add_device_status_update(int device_id, time_t timestamp, int status_flag) {
        if (num_updates < 5000) {
            device_status_updates[num_updates].device_id = device_id;
            device_status_updates[num_updates].timestamp = timestamp;
            device_status_updates[num_updates].status_flag = status_flag;
            num_updates++;
        }
    }

    // Function to retrieve a specific update from the dynamic list
    DEVICE_STATUS_UPDATE_T* get_device_status_update(int index) {
        if (index < num_updates) {
            return &device_status_updates[index];
        } else {
            return NULL;  // Update not found or out of range
        }
