void* custom_malloc(size_t size) {
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

int dynamic_array_init(NFAPI_CRC_INDICATION_PDU_T*** arr, int* capacity, pthread_mutex_t* lock) {
    *arr = (NFAPI_CRC_INDICATION_PDU_T**)custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (*capacity));
    if (!(*arr)) {
        return -1; // Memory allocation failed
    }
    *lock = pthread_mutex_init(lock, NULL);
    return 0;
}

int dynamic_array_resize(NFAPI_CRC_INDICATION_PDU_T*** arr, int* capacity, pthread_mutex_t lock) {
    pthread_mutex_lock(&lock);
    int new_capacity = (*capacity) * 2; // New capacity is double the current size
    NFAPI_CRC_INDICATION_PDU_T** new_arr = (NFAPI_CRC_INDICATION_PDU_T**)custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_capacity);
    if (!new_arr) {
        pthread_mutex_unlock(&lock); // Memory allocation failed
        return -1;
    }
    for (int i = 0; i < (*capacity); i++) {
        new_arr[i] = arr[i];
    }
    free(*arr);
    *arr = new_arr;
    (*capacity) = new_capacity;
    pthread_mutex_unlock(&lock);
    return 0;
}

void dynamic_array_free(NFAPI_CRC_INDICATION_PDU_T*** arr, int capacity, pthread_mutex_t lock) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < capacity; i++) {
        custom_free(arr[i]);
    }
    free(*arr);
    pthread_mutex_unlock(&lock);
}

void set_crc_flag(NFAPI_CRC_INDICATION_PDU_T* element, double probability) {
    if (rand() / (double)RAND_MAX < probability) {
        element->crc_indication_rel8_tag.crcflag = true;
    } else {
        element->crc_indication_rel8_tag.crcflag = false;
    }
}

void manage_array(NFAPI_CRC_INDICATION_PDU_T*** arr, int capacity, pthread_mutex_t lock, double crc_probability) {
    for (int i = 0; i < capacity; i++) {
        set_crc_flag(&arr[i][0], crc_probability);
    }
}

