    int capacity = 16;
    NFAPI_CRC_INDICATION_PDU_T*** arr;
    pthread_mutex_t lock;

    if (dynamic_array_init(&arr, &capacity, &lock) < 0) {
        printf("Memory allocation failed.\n");
        return -1; // Initialization failed
    }

    for (int i = 0; i < capacity; i++) {
        arr[i] = (NFAPI_CRC_INDICATION_PDU_T*)custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!arr[i]) {
            printf("Memory allocation failed.\n");
            dynamic_array_free(&arr, capacity, lock);
            return -1;
        }
    }

    // Manage array
    manage_array(arr, capacity, lock, 0.7); // Set CRC flag with probability 70%

    // Periodic updates
    pthread_t thread;
    pthread_create(&thread, NULL, update_crc_flags, (void*)arr);
    pthread_join(thread, NULL);

    dynamic_array_free(&arr, capacity, lock);

    return 0;
}

void* update_crc_flags(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T*** arr = (NFAPI_CRC_INDICATION_PDU_T***)arg;

