typedef struct LTEUEContext {
    int ue_id;
    int active_resources[5]; // assume 5 is a reasonable number of resources
    float power_control_config[3]; // assume 3 configuration parameters
} LTEUEContext;

typedef struct LTEUEContextArray {
    LTEUEContext* contexts;
    size_t size;
    size_t capacity;
} LTEUEContextArray;

void lte_ue_context_array_init(LTEUEContextArray* array) {
    array->size = 0;
    array->capacity = 5; // start with a small initial capacity
    array->contexts = (LTEUEContext*)malloc(array->capacity * sizeof(LTEUEContext));
}

int lte_ue_context_array_add(LTEUEContextArray* array, int ue_id) {
    if (array->size >= array->capacity) { // check for overflow
        array->capacity *= 2; // double the capacity when necessary
        array->contexts = (LTEUEContext*)realloc(array->contexts, array->capacity * sizeof(LTEUEContext));
    }
    LTEUEContext* context = &array->contexts[array->size++];
    context->ue_id = ue_id;
    memset(context->active_resources, 0, sizeof(context->active_resources)); // zero-initialize resources
    memset(context->power_control_config, 0.5f, sizeof(context->power_control_config)); // set default power control config
    return array->size - 1; // return the index of the new UE context
}

void lte_ue_context_array_update(LTEUEContextArray* array, int ue_id, int active_resources[5], float power_control_config[3]) {
    for (int i = 0; i < array->size; i++) {
        if (array->contexts[i].ue_id == ue_id) {
            memcpy(array->contexts[i].active_resources, active_resources, sizeof(array->contexts[i].active_resources));
            memcpy(array->contexts[i].power_control_config, power_control_config, sizeof(array->contexts[i].power_control_config));
            return;
        }
    }
}

LTEUEContext* lte_ue_context_array_get(LTEUEContextArray* array, int ue_id) {
    for (int i = 0; i < array->size; i++) {
        if (array->contexts[i].ue_id == ue_id) {
            return &array->contexts[i];
        }
    }
    return NULL;
}

void lte_ue_context_array_free(LTEUEContextArray* array) {
    free(array->contexts);
}
