#define MAX_STRUCTURES 10000
#define CACHE_SIZE 1000
#define CRCFLAG_RANGE 256

typedef struct {
    char rx_ue_info_tag[17];
    int rnti;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu = NULL;
int structure_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
char cache[CACHE_SIZE][17]; // UE information cache
int cache_hit_count = 0;

void* alloc_memory(int size) {
    void* mem = malloc(size);
    if (!mem) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    return mem;
}

void free_memory(void* mem) {
    free(mem);
}

NFAPI_CRC_INDICATION_PDU_T* create_structure() {
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)alloc_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) return NULL;
    // Initialize CRC flag with a random value
    structure->crcflag = rand() % CRCFLAG_RANGE;
    return structure;
}

int cache_ue_info(char* tag) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(tag, cache[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_ue_info_from_cache(char* tag) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(tag, cache[i]) == 0) {
            NFAPI_CRC_INDICATION_PDU_T* structure = &nfapi_crc_indication_pdu[i];
            return structure;
        }
    }
    return NULL;
}

void add_ue_info_to_cache(char* tag, int rnti) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(cache[i], "") == 0) {
            strcpy(cache[i], tag);
            // Associate RNTI with the cached UE information
            cache[i][16] = (char)(rnti % 256); // Store RNTI in the last byte of the tag
            return;
        }
    }
}

void release_ue_info_from_cache(char* tag) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(tag, cache[i]) == 0) {
            strcpy(cache[i], "");
            return;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* manage_structures() {
    pthread_mutex_lock(&lock);

    // Check if the cache has reached its maximum size
    if (structure_count >= MAX_STRUCTURES / 2) {
        // Remove half of the cached UE information to free up memory
        for (int i = 0; i < CACHE_SIZE / 2; i++) {
            release_ue_info_from_cache(cache[i]);
        }
        structure_count /= 2;
    }

    NFAPI_CRC_INDICATION_PDU_T* structure = create_structure();
    if (!structure) return NULL;

    char rx_ue_info_tag[17];
    int rnti = rand() % (1 << 24);
    // Simulate UE information retrieval from external data sources
    // ...
    strcpy(rx_ue_info_tag, "RX_UE_INFO_TAG");
    structure->rx_ue_info_tag = rx_ue_info_tag;
    structure->rnti = rnti;

    if (!cache_ue_info(rx_ue_info_tag)) {
        add_ue_info_to_cache(rx_ue_info_tag, rnti);
    }

    pthread_mutex_unlock(&lock);
    return structure;
}
