void manage_dynamic_list(int *n, NFAPI_CRC_INDICATION_PDU_T ***list) {
    // Initialize random seed
    srand(time(NULL));

    // Define cache size and invalidation policy
    const int cache_size = 10000;
    bool invalidate_cache = true;

    for (int i = 0; i < *n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *current = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            return;
        }

        current->RX_UE_INFORMATION_TAG[19] = '\0';
        current->RNTI = rand() % 1000;

        // Caching strategy: LRU (Least Recently Used)
        if (*list) {
            for (int j = 0; j < cache_size; j++) {
                if (!(*list)[j]->RX_UE_INFORMATION_TAG[19]) {
                    *list[i] = (*list)[j];
                    break;
                }
            }

            if (invalidate_cache && i >= cache_size) {
                // Invalidate cache when it reaches the maximum size
                for (int j = 0; j < cache_size; j++) {
                    free((*list)[j]);
                }
                *list = NULL;
                invalidate_cache = false;
            }
        } else {
            *list = (NFAPI_CRC_INDICATION_PDU_T **)malloc((cache_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
            (*list)[i] = current;
        }
    }

    // Update cache with external API data
    for (int i = 0; i < *n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *current = (*list)[i];
        // Call external API to update UE information and RNTI
        current->RX_UE_INFORMATION_TAG[19] = '\0';
        current->RNTI = rand() % 1000;
    }

    return;
}
