typedef struct {
    int connection_id;
    char source_ip[16];
    char dest_ip[16];
} TCP_CONNECTION_RECORD_T;

int connections_count = 0;
TCP_CONNECTION_RECORD_T *connections_list = NULL;

void add_connection(int connection_id, const char* source_ip, const char* dest_ip) {
    if (connection_id > CONNECTION_ID_RANGE || connection_id <= 0) {
        return; // invalid connection id
    }

    for (int i = 0; i < connections_count; i++) {
        if (connections_list[i].connection_id == connection_id) {
            return; // duplicate connection id
        }
    }

    TCP_CONNECTION_RECORD_T* new_connection = malloc(sizeof(TCP_CONNECTION_RECORD_T));
    if (!new_connection) {
        return; // memory allocation failed
    }

    new_connection->connection_id = connection_id;
    strcpy(new_connection->source_ip, source_ip);
    strcpy(new_connection->dest_ip, dest_ip);

    connections_list = realloc(connections_list, (connections_count + 1) * sizeof(TCP_CONNECTION_RECORD_T));
    if (!connections_list) {
        free(new_connection);
        return; // memory reallocation failed
    }

    connections_list[connections_count] = *new_connection;
    connections_count++;

    return;
}

void remove_connection(int connection_id) {
    for (int i = 0; i < connections_count; i++) {
        if (connections_list[i].connection_id == connection_id) {
            // shift the rest of the list down by one
            memmove(&connections_list[i], &connections_list[i + 1], (connections_count - i - 1) * sizeof(TCP_CONNECTION_RECORD_T));
            connections_count--;
            free(&connections_list[i]);
            return;
        }
    }
}

void reset_connections() {
    if (!connections_list) {
        return; // nothing to clear
    }

    for (int i = 0; i < connections_count; i++) {
        free(&connections_list[i]);
    }

    free(connections_list);
    connections_list = NULL;
    connections_count = 0;
}

void update_connection_state(int connection_id, int new_state) {
    // implement logic to update the state of a specific connection
}

int get_connections_count() {
    return connections_count;
}

TCP_CONNECTION_RECORD_T* get_connection_by_id(int connection_id) {
    for (int i = 0; i < connections_count; i++) {
        if (connections_list[i].connection_id == connection_id) {
            return &connections_list[i];
        }
    }

    return NULL;
}
