void* nfaapi_crc_indication_pdu_array_manager(int* count, int** array) {
    // Define internal linked list node structure
    typedef struct Node {
        NFAPI_CRC_INDICATION_PDU_T* data;
        struct Node* next;
    } Node;

    // Function to allocate and initialize a new node
    static Node* create_node() {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) return NULL;
        node->next = NULL;
        return node;
    }

    // Function to delete a node
    static void free_node(Node* node) {
        if (!node) return;
        free(node);
    }

    // Define the dynamic array structure
    static Node* head = NULL;
    static Node* tail = NULL;

    // Allocate memory for the initial capacity (10,000 elements)
    static NFAPI_CRC_INDICATION_PDU_T** buffer = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * 10000);

    // Check if array has been previously initialized
    if (!buffer) return NULL;

    // Initialize internal linked list and dynamic array
    head = create_node();
    tail = head;
    *count = 0;
    *array = buffer;

    // Function to add new elements
    void add(int index, NFAPI_CRC_INDICATION_PDU_T* data) {
        if (index < 0 || index > *count) return; // Check bounds

        // If the array needs to grow, allocate a new block and resize
        if (index >= *array[1]) {
            // Allocate a new chunk of memory
            NFAPI_CRC_INDICATION_PDU_T** new_buffer = (NFAPI_CRC_INDICATION_PDU_T**)realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * 2 * (*array[1] + 1));
            if (!new_buffer) return; // Check for allocation failure

            // Update the dynamic array
            *array = new_buffer;
        }

        // Insert the element at the given index
        data = &((*array)[index]);
    }

    // Function to retrieve elements by index
    NFAPI_CRC_INDICATION_PDU_T* get(int index) {
        if (index < 0 || index >= *count) return NULL; // Check bounds

        // Return the element at the given index
        return &((*array)[index]);
    }

    // Function to remove elements by index
    void remove(int index) {
        if (index < 0 || index >= *count) return; // Check bounds

        // If removing from the beginning, update head and adjust capacity
        if (index == 0) {
            NFAPI_CRC_INDICATION_PDU_T* temp = get(1);
            free(get(0));
            for (int i = 0; i < *count - 1; i++) {
                (*array)[i] = temp;
                temp = &((*array)[i + 1]);
            }
        } else { // Remove an element from the middle or end
            NFAPI_CRC_INDICATION_PDU_T* temp = get(index);
            for (int i = index; i < *count - 1; i++) {
                (*array)[i] = &((*array)[i + 1]);
            }
        }

        // Update count and adjust capacity if necessary
        (*count)--;
    }

