typedef struct {
    int size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t lock;
} Dataset;

// Function to create a new dataset
Dataset* create_dataset(int max_size) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) return NULL;  // Handle memory allocation failure

    dataset->size = 0;
    dataset->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dataset->data) {
        free(dataset);  // Free the Dataset struct
        return NULL;  // Handle memory allocation failure
    }

    pthread_mutex_init(&dataset->lock, NULL);

    return dataset;
}

// Function to add a new structure to an existing dataset
int add_structure(Dataset* dataset, NFAPI_CRC_INDICATION_PDU_T structure) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->size >= dataset->data->length) {
        // Reallocate memory for the dataset if it's full
        int new_size = 2 * dataset->size + 1;
        dataset->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dataset->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    dataset->data[dataset->size++] = structure;
    pthread_mutex_unlock(&dataset->lock);

    return 0;  // Success
}

// Function to query the total number of structures across all datasets
int get_total_structures(Dataset* datasets[], int num_datasets) {
    int total_size = 0;
    for (int i = 0; i < num_datasets; i++) {
        pthread_mutex_lock(&datasets[i]->lock);
        total_size += datasets[i]->size;
        pthread_mutex_unlock(&datasets[i]->lock);
    }
    return total_size;
}

// Function to sort the structures in a dataset by RNTI values
void sort_dataset(Dataset* dataset) {
    qsort(dataset->data, dataset->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), (int (*)(const void*, const void*))compare_RNTI);
}

// Helper function for sorting
int compare_RNTI(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* struct_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* struct_b = (NFAPI_CRC_INDICATION_PDU_T*)b;

    if (struct_a->RNTI < struct_b->RNTI) return -1;
    else if (struct_a->RNTI > struct_b->RNTI) return 1;
    else return 0;  // Equal RNTI values
}

// Example usage:
int main() {
    int num_datasets = 5;
    Dataset* datasets[num_datasets];

    for (int i = 0; i < num_datasets; i++) {
        datasets[i] = create_dataset(10000);
        add_structure(datasets[i], /* structure initialization */);
