        return NULL;
    }

    int* crcflag_bits = (int*) malloc((n + 1) * sizeof(int));
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**) malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!array || !crcflag_bits) {
        // Log initialization failure
        printf("Initialization failed: Memory allocation failed.\n");
        free(array);
        free(crcflag_bits);
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            // Log initialization failure
            printf("Initialization failed: Memory allocation failed.\n");
            for (int j = 0; j <= i; j++) {
                free(array[j]);
            }
            free(array);
            free(crcflag_bits);
            return NULL;
        }

        array[i]->rx_ue_info_tag = i;
        array[i]->rnti = i;
        array[i]->crc_indication_rel8_tag.crcflag = (1 << i);

        crcflag_bits[i + 1] = 0;
    }

    free(crcflag_bits);
