    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            printf("Error: Memory allocation failed.\n");
            // Handle memory allocation failure and return an empty list
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
