        // Sort the list based on RNTI values in ascending order
        for (int j = 1; j < N; j++) {
            NFAPI_CRC_INDICATION_PDU_T* temp = list[j];
            int k;
            for (k = j; k > 0 && (temp->RNTI > list[k - 1]->RNTI); k--)
                list[k] = list[k - 1];
            list[k] = temp;
        }
        pthread_mutex_unlock(&lock);
    }

    return list;
