Node* head = NULL; // Head of the linked list
int total_elements = 0; // Total number of elements in the list

// Function to dynamically manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
Node* manage_linked_list(int num_elements) {
    int probability = 80; // Initial allocation probability
    Node* current = NULL;
    for (int i = 0; i < num_elements; i++) {
        if (rand() % 100 < probability) { // Randomly allocate memory based on probability
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (new_node == NULL) {
                printf("Memory allocation failed! Error: %s\n", strerror(errno));
                return NULL; // Handle memory allocation failure and log the error
            }
            new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
            new_node->data.RNTI = rand() % 500;
            new_node->data.CRC_INDICATION_REL8_TAG = rand() % 2000;
            new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            if (head == NULL) {
                head = new_node;
                current = head;
            } else {
                current->next = new_node;
                current = current->next;
            }
            total_elements++;
        }
        if (total_elements >= 7500) { // Linearly decrease allocation probability when list reaches 7,500 elements
            probability -= (probability - 50) / 3750; // Calculate new probability
        }
    }
    return head;
}

int main() {
    srand(time(NULL)); // Seed random number generator for reproducibility

    Node* result = manage_linked_list(10000);
    if (result != NULL) {
        printf("Linked list successfully created with %d elements.\n", total_elements);
    } else {
        printf("Failed to create linked list.\n");
    }

    // Free allocated memory
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    return 0;
