void lte_phy_rx_frame_init(LTE_PHY_RX_FRAME** frames, size_t max_frames) {
    *frames = (LTE_PHY_RX_FRAME*)malloc(max_frames * sizeof(LTE_PHY_RX_FRAME));
}

void lte_phy_rx_frame_add(LTE_PHY_RX_FRAME** frames, int frame_index, LTE_RX_TF_INFO* info) {
    if(frame_index < 0 || frame_index >= *frames_size(*frames)) {
        printf("Error: Out of bounds\n");
        return;
    }
    (*frames)[frame_index].info = *info;
}

void lte_phy_rx_frame_update(LTE_PHY_RX_FRAME** frames, int frame_index, LTE_RX_TF_INFO* info) {
    if(frame_index < 0 || frame_index >= *frames_size(*frames)) {
        printf("Error: Out of bounds\n");
        return;
    }
    memcpy(&((*frames)[frame_index].info), info, sizeof(LTE_RX_TF_INFO));
}

void lte_phy_rx_frame_remove(LTE_PHY_RX_FRAME** frames, int frame_index) {
    if(frame_index < 0 || frame_index >= *frames_size(*frames)) {
        printf("Error: Out of bounds\n");
        return;
    }
    free(((LTE_PHY_RX_FRAME*)((*frames)[frame_index].info.payload)));
    memset(&((*frames)[frame_index]), 0, sizeof(LTE_PHY_RX_FRAME));
}

int lte_phy_rx_frame_verify_checksum(LTE_PHY_RX_FRAME* frame) {
    // Compute checksum
    int checksum = 0;
    for(size_t i = 0; i < frame->info.payload_len; i++) {
        checksum += ((unsigned char*)frame->info.payload)[i];
    }
    return checksum;
}

