    LTE_PHY_RX_FRAME* frames;
    lte_phy_rx_frame_init(&frames, 10000);

    // Add frames
    for(int i = 0; i < 10; i++) {
        LTE_RX_TF_INFO info = { /* initialize tf_info */ };
        lte_phy_rx_frame_add(&frames, i, &info);
    }

    // Update frames
    for(int i = 0; i < 5; i++) {
        LTE_RX_TF_INFO info = { /* initialize tf_info */ };
        lte_phy_rx_frame_update(&frames, i, &info);
    }

    // Remove frames
    for(int i = 9; i >= 4; i--) {
        lte_phy_rx_frame_remove(&frames, i);
    }

    int checksum;
    for(size_t i = 0; i < *frames_size(frames); i++) {
        checksum = lte_phy_rx_frame_verify_checksum((&frames)[i]);
        // Verify checksum
    }

    return 0;
}
