pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* head = NULL;
int count = 0;

void addElement(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *temp = *element;

    if(count == 0) {
        head = temp;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* last = head;
        while(last->next != NULL) {
            last = last->next;
        }
        last->next = temp;
    }

    count++;

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    clock_t now = clock();
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;

    while(current != NULL) {
        if((now - clock()) > 5000) { // 5 seconds
            if(prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            count--;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* findElement(int RNTI) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while(current != NULL) {
        if(current->RNTI == RNTI) {
            pthread_mutex_unlock(&lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void deleteElement(int RNTI) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;

    while(current != NULL) {
        if(current->RNTI == RNTI) {
            if(prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            count--;
            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

