#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned char CRCFLAG;
    time_t timestamp;
    int reference_count;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

// Dynamic linked list with thread-safe operations
typedef struct {
    struct Node* head;
    struct Node* tail;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST;

NFAPI_CRC_INDICATION_LIST nfa_pi_crc_indication_list = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER};

void init_list() {
    pthread_mutex_init(&nfa_pi_crc_indication_list.lock, NULL);
}

// Add a new element to the list
void add_element(NFAPI_CRC_INDICATION_PDU_T* data) {
    struct Node* node = malloc(sizeof(struct Node));
    node->data = *data;
    node->next = NULL;

    pthread_mutex_lock(&nfa_pi_crc_indication_list.lock);

    if (nfa_pi_crc_indication_list.head == NULL)
        nfa_pi_crc_indation_list.head = node;
    else
        nfa_pi_crc_indication_list.tail->next = node;

    nfa_pi_crc_indication_list.tail = node;

    pthread_mutex_unlock(&nfa_pi_crc_indication_list.lock);
}

// Remove elements older than 5 seconds from the current timestamp
void clean_up() {
    struct Node* temp = NULL;
    time_t current_timestamp = time(NULL);

    pthread_mutex_lock(&nfa_pi_crc_indication_list.lock);

    for (struct Node* node = nfa_pi_crc_indication_list.head; node != NULL;) {
        if ((current_timestamp - node->data.timestamp) > 5) {
            temp = node;
            node = node->next;
            free(temp);
        } else
            break;
    }

    pthread_mutex_unlock(&nfa_pi_crc_indication_list.lock);
}

// Retrieve elements by RNTI
NFAPI_CRC_INDICATION_PDU_T* retrieve_element(unsigned int rnti) {
    struct Node* node = nfa_pi_crc_indication_list.head;

    pthread_mutex_lock(&nfa_pi_crc_indication_list.lock);

    while (node != NULL) {
