    return node ? &node->data : NULL;
}

// Sort structures by timestamp in ascending order
void sort_elements() {
    struct Node* current = nfa_pi_crc_indication_list.head;
    struct Node* next = NULL;

    for (current = nfa_pi_crc_indication_list.head; current != NULL; current = next) {
        next = current->next;
        while (next != NULL && (next->data.timestamp - current->data.timestamp) < 0)
            break;
        if (next == current) {
            current = next;
        } else {
            NFAPI_CRC_INDICATION_PDU_T temp = current->data;
            current->data = next->data;
            next->data = temp;
        }
    }
}

