    EVP_EncryptUpdate(ctx, *ciphertext, &ciphertext_length, plaintext, length);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to implement CRC calculation
void crc_calc(const unsigned char* data, size_t length, unsigned char** crc) {
    // Calculate the CRC
    uint32_t crc_value = 0;
    for (size_t i = 0; i < length; i++)
        crc_value = ((crc_value >> 8) ^ (data[i] & 0xFF)) * 0x10001;
    memcpy(*crc, (unsigned char*)&crc_value, 4);
}

