// Function to manage dynamic array of LTE PHY layer metrics structures
LTE_PHY_Metrics** manage_phy_metrics(int* num_metrics) {
    // Initialize the maximum number of metrics
    const int MAX_METRICS = 1000;

    // Allocate memory for the dynamic array
    LTE_PHY_Metrics** phy_metrics = (LTE_PHY_Metrics**)malloc(MAX_METRICS * sizeof(LTE_PHY_Metrics*));
    if (!phy_metrics) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    int i = 0;
    while (i < MAX_METRICS && *num_metrics > i) {
        phy_metrics[i] = (LTE_PHY_Metrics*)malloc(sizeof(LTE_PHY_Metrics));
        if (!phy_metrics[i]) {
            printf("Error allocating memory.\n");
            break;
        }

        // Populate the LTE_PHY_Metrics structure
        phy_metrics[i]->timestamp = i;
        phy_metrics[i]->downlink_throughput = (double)(i * 100) / 100.0;
        phy_metrics[i]->uplink_error_rate = (double)i / 10.0;

        i++;
    }

    // Filter metrics based on throughput threshold
    int filtered_metrics = 0;
    for (int j = 0; j < i; j++) {
        if (phy_metrics[j]->downlink_throughput > 500) {
            phy_metrics[filtered_metrics++] = phy_metrics[j];
        } else {
            free(phy_metrics[j]);
        }
    }

    // Reallocate memory for the filtered metrics
    LTE_PHY_Metrics** filtered_phy_metrics = (LTE_PHY_Metrics**)realloc(phy_metrics, sizeof(LTE_PHY_Metrics*) * (filtered_metrics + 1));
    if (!filtered_phy_metrics) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    // Reset the dynamic array
    for (int j = filtered_metrics; j < i; j++) {
        free(phy_metrics[j]);
    }
    for (int j = 0; j < i; j++) {
        phy_metrics[j] = NULL;
    }

    *num_metrics = filtered_metrics;

    return filtered_phy_metrics;
}

int main() {
    int num_metrics = 0;
    LTE_PHY_Metrics** phy_metrics = manage_phy_metrics(&num_metrics);

    // Print the filtered metrics
    for (int i = 0; i < num_metrics; i++) {
        printf("Timestamp: %d, Downlink Throughput: %.2f, Uplink Error Rate: %.2f\n", 
               phy_metrics[i]->timestamp, phy_metrics[i]->downlink_throughput, phy_metrics[i]->uplink_error_rate);
    }

    // Free the memory
    for (int i = 0; i < num_metrics; i++) {
        free(phy_metrics[i]);
    }
    free(phy_metrics);

    return 0;
}

