typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random RNTI
int generateRNTI() {
    return rand();
}

// Function to verify the integrity of an NFAPI_CRC_INDICATION_PDU_T structure
int validateStructure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Calculate checksum
    int checksum = 0;
    for (int i = 0; i < strlen(pdu->RX_UE_INFORMATION_TAG); i++) {
        checksum += pdu->RX_UE_INFORMATION_TAG[i];
    }
    checksum += pdu->RNTI;
    for (int i = 0; i < strlen(pdu->CRC_INDICATION_REL8_TAG); i++) {
        checksum += pdu->CRC_INDICATION_REL8_TAG[i];
    }
    checksum += pdu->CRCFLAG;

    // Check if checksum matches expected value
    return checksum % 256 == pdu->RNTI;
}

NFAPI_CRC_INDICATION_PDU_T* initPduList(int N, int* list) {
    // Initialize cache for UE information tags
    char* ueInfoTags[1024];
    int cacheIndex = 0;

    // Asynchronous processing to minimize latency
    pthread_t threads[N];

    for (int i = 0; i < N; i++) {
        // Generate RNTI and initialize pdu structure
        int rnti = generateRNTI();
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        strcpy(pdu->RX_UE_INFORMATION_TAG, ueInfoTags[cacheIndex++ % 1024]);
        pdu->RNTI = rnti;
        strcpy(pdu->CRC_INDICATION_REL8_TAG, ueInfoTags[cacheIndex++ % 1024]);
        pdu->CRCFLAG = rand() & 1;

        // Verify integrity of pdu structure
        for (int j = 0; j < 3; j++) {
            if (validateStructure(pdu)) {
                break;
            }
            else {
                free(pdu);
                pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                strcpy(pdu->RX_UE_INFORMATION_TAG, ueInfoTags[cacheIndex++ % 1024]);
                pdu->RNTI = generateRNTI();
                strcpy(pdu->CRC_INDICATION_REL8_TAG, ueInfoTags[cacheIndex++ % 1024]);
                pdu->CRCFLAG = rand() & 1;
            }
        }

        // If pdu structure fails integrity check after three attempts, discard it
        if (!validateStructure(pdu)) {
            free(pdu);
            i--;
            continue;
        }

        // Add pdu structure to list and thread
        list[i] = pdu;
        pthread_create(&threads[i], NULL, (void*)0, NULL);

        // Simulate asynchronous processing
        pthread_join(threads[i], NULL);
    }

    return list;
}
