TrafficStats **traffic_array = NULL;
int array_size = 0;
int current_index = 0;

void add_traffic_stats(int packets, long bytes, float errors) {
    if (current_index >= array_size) {
        array_size *= 2;
        traffic_array = realloc(traffic_array, array_size * sizeof(TrafficStats *));
        memset(&traffic_array[current_index], 0, sizeof(TrafficStats));
    }
    traffic_array[current_index]->packet_count += packets;
    traffic_array[current_index]->byte_count += bytes;
    traffic_array[current_index]->error_rate += errors;
    current_index++;
}

float calculate_average_error_rate() {
    float sum = 0.0f;
    for (int i = 0; i < current_index; i++) {
        sum += traffic_array[i]->error_rate;
    }
    return sum / current_index;
}

void update_aggregated_stats() {
    printf("Average error rate: %.2f%%\n", calculate_average_error_rate());
