void export_stats_to_file(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        return;
    }
    for (int i = 0; i < current_index; i++) {
        fprintf(fp, "%ld %d %.2f\n", traffic_array[i]->timestamp, traffic_array[i]->packet_count,
                traffic_array[i]->error_rate);
    }
    fclose(fp);
}

