int create_crc_indication_pdu_list(int N, int seed, int* list_size) {
    if (N <= 0) {
        printf("Invalid number of structures. Must be a positive integer.\n");
        return -1;
    }

    srand(seed);

    *list_size = N;

    NFAPI_CRC_INDICATION_PDU_T** list = malloc_sized(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list == NULL) {
        return -1;
    }

    for (int i = 0; i < N; i++) {
        int RNTI = rand() % 1000000; // Randomly generate RNTI
        list[i] = malloc_sized(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list[i] == NULL) {
            return -1;
        }
        list[i]->RX_UE_INFORMATION_TAG = i;
        list[i]->RNTI = RNTI; // Ensure no two consecutive structures share the same RNTI
        list[i]->CRC_INDICATION_REL8_TAG = i + 1000; // Initialize CRCFLAG
        list[i]->CRCFLAG = (i % 2) == 0 ? 1 : 0;
    }

    free(list);

    return 0;
}

