NFAPI_CRC_INDICATION_PDU_T* create_list(int num_elements) {
    if (num_elements <= 0 || !num_elements) return NULL;

    int *crc_flags = (int *)malloc(sizeof(int) * num_elements);
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        crc_flags[i] = rand() % 2;
