void init_data_packet_list(int N, DataPacket **list, int *size) {
    srand(time(NULL));

    // Create the list with N packets
    *size = N;
    *list = (DataPacket *)malloc(sizeof(DataPacket) * N);

    for (int i = 0; i < N; i++) {
        DataPacket packet = {
            .SourceID = rand(),
            .DestinationID = rand(),
            .Payload = (char *)malloc(rand() % 100 + 1)
        };

        // Fill payload with random data from Gaussian distribution
        for (int j = 0; j < strlen(packet.Payload); j++) {
            packet.Payload[j] = (char)(rand_gaussian(50, 5) % 256);
        }

        hash_function(&packet);  // Validate the integrity of each packet

        (*list)[i] = packet;
    }
}

void hash_function(DataPacket *packet) {
    int hash = packet->SourceID + packet->DestinationID + strlen(packet->Payload);

    for (int i = 0; i < strlen(packet->Payload); i++) {
        hash += (int)packet->Payload[i];
    }

    printf("Hash value: %d\n", hash);
}

int rand_gaussian(int mean, int std_dev) {
    static double last_random;
    static int first_time = 1;

    if (first_time) {
        last_random = (double)rand() / RAND_MAX;
        first_time = 0;
    } else {
        double new_random = (double)rand() / RAND_MAX;
        double ratio = last_random * 9 + new_random * 10;
        while (ratio > 1.0)
            ratio -= 1.0;
        while (ratio < 0.0)
            ratio += 1.0;
        last_random = new_random - ((double)rand() / RAND_MAX - 0.5) * 2.0 * std_dev / mean;        
    }

    return (int)(last_random * mean + std_dev);
}

