#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

void *nfapi_crc_indication_pdu_t_init(void **data) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    strcpy(pdu->RX_UE_INFORMATION_TAG, "INITIAL_VALID_VALUE");
    pdu->RNTI = 0;
    char crcbuf[32];
    sprintf(crcbuf, "%x", (int)pdu);
    strncpy(pdu->CRC_INDICATION_REL8_TAG, crcbuf, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    return pdu;
}

void *nfapi_crc_indication_pdu_t_init_all(int num_pdus, void ***pdus) {
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    pthread_t threads[num_pdus];
    for (int i = 0; i < num_pdus; i++) {
        int *pdata = malloc(sizeof(int));
        *pdata = i;
        pthread_create(&threads[i], &attr, nfapi_crc_indication_pdu_t_init, pdata);
    }

    for (int i = 0; i < num_pdus; i++) {
        pthread_join(threads[i], NULL);
    }
}

void log_error(char *msg) {
    FILE *fp = fopen("log.txt", "a");
    if (!fp) fp = stderr;
    fprintf(fp, "%s\n", msg);
    fclose(fp);
}
