#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to represent an LTE_RRC connexionSetupComplete message
typedef struct {
    int ue_id;
    int config_update_status;
    char **measurement_objects; // dynamically allocated array of strings
} LTERRCCONNMessage;

// Define a struct to represent a dynamic list of LTERRCCONN messages for a given cell ID
typedef struct {
    int cell_id;
    LTERRCCONMessage *messages; // dynamically allocated array of LTERRCCON messages
    int latest_config_version;
} LTECell;

// Function prototypes
LTECell* lte_cell_new(int cell_id);
void lte_cell_add_message(LTECell* cell, int ue_id, int config_update_status, char **measurement_objects);
void lte_cell_remove_message(LTECell* cell, int ue_id);
int lte_cell_update_config_version(LTECell* cell, int new_config_version);
LTECell* lte_cell_new(int cell_id) {
    LTECell* cell = (LTECell*)malloc(sizeof(LTECell));
    cell->cell_id = cell_id;
    cell->messages = NULL; // initialize as empty
    cell->latest_config_version = -1; // mark as unknown
    return cell;
}

void lte_cell_add_message(LTECell* cell, int ue_id, int config_update_status, char **measurement_objects) {
    // Check if a message with the same UE ID already exists in the cell
    for (int i = 0; i < cell->messages && i > 0; i++) {
        if (cell->messages[i]->ue_id == ue_id) {
            // Update existing message instead of adding a new one
            return;
        }
    }

    // Add a new message to the dynamic list
    LTERRCCONMessage* new_message = (LTERRCCONMessage*)malloc(sizeof(LTERRCCONMessage));
    new_message->ue_id = ue_id;
    new_message->config_update_status = config_update_status;
    new_message->measurement_objects = measurement_objects; // copy the array

    // Append to the existing list
    if (!cell->messages) {
        cell->messages = (LTERRCCONMessage**)malloc(sizeof(LTERRCCONMessage*));
        cell->messages[0] = new_message;
    } else {
        LTERRCCONMessage** temp = (LTERRCCONMessage**)realloc(cell->messages, sizeof(LTERRCCONMessage*) * (cell->messages ? (int)strlen((char*)cell->messages) : 1));
        temp[(int)strlen((char*)cell->messages)] = new_message;
        cell->messages = temp;
    }
}

void lte_cell_remove_message(LTECell* cell, int ue_id) {
    // Find and remove the message with the specified UE ID
    for (int i = 0; i < cell->messages; i++) {
        if (cell->messages[i]->ue_id == ue_id) {
            free(cell->messages[i]->measurement_objects);
            free(cell->messages[i]);
            memmove(&cell->messages[i], &cell->messages[i + 1], sizeof(LTERRCCONMessage*) * (int)(strlen((char*)cell->messages) - i));
            cell->messages = (LTERRCCONMessage**)realloc(cell->messages, sizeof(LTERRCCONMessage*) * (int)strlen((char*)cell->messages) - 1);
        }
    }
}

int lte_cell_update_config_version(LTECell* cell, int new_config_version) {
    // Update the latest configuration version for all messages in the cell
    if (new_config_version > cell->latest_config_version) {
        cell->latest_config_version = new_config_version;
        return 0; // successful update
    }
    return -1; // failed to update, likely due to concurrent modification
}
