void* dynamic_array_init(size_t capacity) {
    void* arr = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) return NULL;
    return arr;
}

void dynamic_array_resize(void** arr, size_t newCapacity) {
    if (!*arr) return;
    void* newArr = realloc(*arr, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArr) {
        free(*arr);
        *arr = NULL;
    } else {
        *arr = newArr;
    }
}

void dynamic_array_insert(void** arr, size_t capacity, NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (capacity <= 0) return;
    *elem = (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = rand() % 100, .RNTI = rand() % 10000, .CRC_INDICATION_REL8_TAG = rand() % 1000000, .CRCFLAG = rand() % 2};
    for (size_t i = capacity - 1; i > 0; --i) {
        arr[i] = arr[i-1];
    }
    memcpy(arr + capacity - 1, elem, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void dynamic_array_remove(void** arr, size_t capacity, NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (capacity <= 0 || !*arr) return;
    for (size_t i = 0; i < capacity - 1; ++i) {
        arr[i] = arr[i+1];
    }
    free(*arr);
    *arr = NULL;
}

void dynamic_array_free(void** arr) {
    if (!*arr) return;
    free(*arr);
    *arr = NULL;
}
