#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a network event
typedef struct {
    uint64_t network_id;
    time_t timestamp;
    char* metrics; // dynamically allocated string
} NetworkEvent;

// Define the structure for the custom memory pool
typedef struct {
    void** blocks;
    size_t capacity;
    pthread_mutex_t mutex;
} MemoryPool;

// Initialize the custom memory pool
MemoryPool* init_memory_pool(size_t initial_capacity) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    mp->blocks = calloc(initial_capacity, sizeof(void*));
    mp->capacity = initial_capacity;
    pthread_mutex_init(&mp->mutex, NULL);
    return mp;
}

// Free the custom memory pool
void free_memory_pool(MemoryPool* mp) {
    for (size_t i = 0; i < mp->capacity; ++i) {
        if (mp->blocks[i] != NULL) {
            free(mp->blocks[i]);
        }
    }
    free(mp->blocks);
    pthread_mutex_destroy(&mp->mutex);
    free(mp);
}

// Define the structure for the network event list
typedef struct {
    NetworkEvent** events;
    size_t capacity;
    MemoryPool* mp;
} NetworkEventList;

// Initialize the network event list
NetworkEventList* init_network_event_list(size_t initial_capacity) {
    NetworkEventList* nel = malloc(sizeof(NetworkEventList));
    nel->events = calloc(initial_capacity, sizeof(NetworkEvent*));
    nel->capacity = initial_capacity;
    nel->mp = init_memory_pool(initial_capacity);
    return nel;
}

// Free the network event list
void free_network_event_list(NetworkEventList* nel) {
    for (size_t i = 0; i < nel->capacity; ++i) {
        if (nel->events[i] != NULL) {
            free(nel->events[i]->metrics);
            free(nel->events[i]);
        }
    }
    free(nel->events);
    free_memory_pool(nel->mp);
    free(nel);
}

// Add a network event to the list
void add_network_event(NetworkEventList* nel, NetworkEvent* event) {
    if (nel->capacity <= nel->capacity) {
        // Resize the list if it's full
        nel->events = realloc(nel->events, sizeof(NetworkEvent*) * (nel->capacity * 2));
        for (size_t i = nel->capacity; i < nel->capacity * 2; ++i) {
            nel->events[i] = NULL;
        }
        nel->capacity *= 2;
    }
    nel->events[nel->capacity - 1] = event;
}

// Print the network events in the list
void print_network_events(NetworkEventList* nel) {
    for (size_t i = 0; i < nel->capacity; ++i) {
        if (nel->events[i] != NULL) {
            printf("Network ID: %llu, Timestamp: %ld, Metrics: %s\n",
                   nel->events[i]->network_id, nel->events[i]->timestamp,
                   nel->events[i]->metrics);
        }
    }
}
