// Pool size and allocation size for memory pool management
const int POOL_SIZE = 1024;
const int ALLOCATION_SIZE = MAX_ENTRIES / 2;

void create_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** list, int num_entries) {
    *list = (NFAPI_CRC_INDINATION_PDU_T*)malloc(POOL_SIZE * NFAPI_CRC_INDICATION_PDU_T_STRUCT_SIZE);
    if (*list == NULL) {
        printf("Error allocating memory for NFAPI CRC indication PDU list.\n");
        return;
    }

    int pool_index = 0;
    int allocation_index = 0;

    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (*list) + pool_index * ALLOCATION_SIZE;
        if (allocation_index >= ALLOCATION_SIZE || pool_index >= POOL_SIZE / ALLOCATION_SIZE) {
            // Reallocate memory for the next allocation
            pool_index++;
            allocation_index = 0;
            if (pool_index >= POOL_SIZE / ALLOCATION_SIZE) {
                printf("Error: NFAPI CRC indication PDU list memory exhausted.\n");
                return;
