int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // thread safety mechanism

void add_record(long int timestamp, double signal_strength, char* frequency_band, char* network_operator_id) {
    pthread_mutex_lock(&lock);

    SignalQualityRecord* new_record = (SignalQualityRecord*)malloc(sizeof(SignalQualityRecord));
    if(new_record == NULL) {
        printf("Error: Out of memory\n");
        return;
    }
    new_record->timestamp = timestamp;
    new_record->signal_strength = signal_strength;
    strcpy(new_record->frequency_band, frequency_band);
    strcpy(new_record->network_operator_id, network_operator_id);

    if(record_count == 0) {
        signal_quality_records = (SignalQualityRecord**)malloc(sizeof(SignalQualityRecord*));
        signal_quality_records[0] = new_record;
        record_count++;
    } else {
        SignalQualityRecord** temp = (SignalQualityRecord**)realloc(signal_quality_records, sizeof(SignalQualityRecord*) * (record_count + 1));
        if(temp == NULL) {
            printf("Error: Out of memory\n");
            free(new_record);
            pthread_mutex_unlock(&lock);
            return;
        }
        signal_quality_records = temp;
        signal_quality_records[record_count] = new_record;
        record_count++;
    }

    pthread_mutex_unlock(&lock);
}

void update_record(char* frequency_band, double signal_strength) {
    pthread_mutex_lock(&lock);

    for(int i = 0; i < record_count; i++) {
        if(strcmp(signal_quality_records[i]->frequency_band, frequency_band) == 0) {
            signal_quality_records[i]->signal_strength = signal_strength;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

SignalQualityRecord* get_record(long int timestamp_start, long int timestamp_end) {
    SignalQualityRecord* result = NULL;
    pthread_mutex_lock(&lock);

    for(int i = 0; i < record_count; i++) {
        if(record_quality_records[i]->timestamp >= timestamp_start && record_quality_records[i]->timestamp <= timestamp_end) {
            if(result == NULL) {
                result = (SignalQualityRecord*)malloc(sizeof(SignalQualityRecord));
                *result = *signal_quality_records[i];
            } else {
                SignalQualityRecord* temp = (SignalQualityRecord*)malloc(sizeof(SignalQualityRecord));
                *temp = *signal_quality_records[i];
                // Append to the list of records
            }
        }
    }

    pthread_mutex_unlock(&lock);
    return result;
}

