// Define the rolling buffer size across multiple calls
#define ROLLING_BUFFER_SIZE 5000

// Define the total memory footprint limit per batch
#define BATCH_MEMORY_FOOTPRINT_LIMIT (2 * 1024 * 1024)

// Define the number of entries to consider for CRC flag consistency
#define CRC_FLAG_WINDOW_SIZE 100

// Define the logging levels
#define DEBUG_LOGGING 1
#define INFO_LOGGING 2
#define ERROR_LOGGING 3

// Function prototypes
void* allocate_memory(size_t);
NFAPI_CRC_INDICATION_PDU_T* manage_list(int, NFAPI_CRC_INDICATION_PDU_T**);
int check_crc_flag_consistency(NFAPI_CRC_INDICATION_PDU_T**, int);

