#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int size;
    long long timestamp;
    int sequence_number;
} DataPacket;

typedef struct {
    time_t session_start_time;
    char session_id[32];
    pthread_mutex_t lock;
    list<DataPacket*> packets;
} TrafficMeasurementRecord;

TrafficMeasurementRecord* initialize_record(char* session_id) {
    TrafficMeasurementRecord* record = (TrafficMeasurementRecord*)malloc(sizeof(TrafficMeasurementRecord));
    record->session_start_time = time(NULL);
    strcpy(record->session_id, session_id);
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void add_packet_to_record(TrafficMeasurementRecord* record, int size, long long timestamp, int sequence_number) {
    pthread_mutex_lock(&record->lock);
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    packet->size = size;
    packet->timestamp = timestamp;
    packet->sequence_number = sequence_number;
    list_append(record->packets, &packet);
    pthread_mutex_unlock(&record->lock);
}

int validate_record(TrafficMeasurementRecord* record) {
    pthread_mutex_lock(&record->lock);
    for (list_node<DataPacket*>* node = record->packets; node != NULL; node = node->next) {
        DataPacket* packet = node->data;
        if (packet->timestamp < record->session_start_time) {
            // Timestamp is invalid, record is corrupted
            pthread_mutex_unlock(&record->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&record->lock);
    return 1;
}

void free_record(TrafficMeasurementRecord* record) {
    pthread_mutex_lock(&record->lock);
    for (list_node<DataPacket*>* node = record->packets; node != NULL; ) {
        DataPacket* packet = node->data;
        node = node->next;
        free(packet);
    }
    list_free(record->packets);
    pthread_mutex_unlock(&record->lock);
    free(record);
}
