void add_signal_quality_record(int timestamp, float signal_strength, int frequency_band, char network_operator[], int signal_quality_rating) {
    SignalQualityRecord* record = (SignalQualityRecord*)malloc(sizeof(SignalQualityRecord));
    record->timestamp = timestamp;
    record->signal_strength = signal_strength;
    record->frequency_band = frequency_band;
    strcpy(record->network_operator, network_operator);
    record->signal_quality_rating = signal_quality_rating;
    record->access_points_count = 0;

    pthread_mutex_lock(&lock);
    signal_quality_records[records_count] = record;
    records_count++;
    pthread_mutex_unlock(&lock);

    pthread_cond_signal(&cond_var);
}

void update_signal_quality_record(int frequency_band, int timestamp, float signal_strength) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < records_count; i++) {
        if (signal_quality_records[i]->frequency_band == frequency_band) {
            signal_quality_records[i]->timestamp = timestamp;
            signal_quality_records[i]->signal_strength = signal_strength;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

SignalQualityRecord* get_signal_quality_record(int timestamp, int proximity_threshold) {
    SignalQualityRecord* record = NULL;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < records_count; i++) {
        if (abs(signal_quality_records[i]->timestamp - timestamp) <= proximity_threshold) {
            record = signal_quality_records[i];
            break;
        }
    }
    pthread_mutex_unlock(&lock);

    return record;
}

void archive_old_records(int threshold) {
    int i = 0, j = 0;

    pthread_mutex_lock(&lock);
    while (i < records_count) {
        if (signal_quality_records[i]->timestamp <= threshold) {
            free(signal_quality_records[i]);
            signal_quality_records[i] = signal_quality_records[j];
            j++;
        } else {
            i++;
        }
    }

    for (; j < records_count; j++) {
        free(signal_quality_records[j]);
    }

    records_count -= (records_count - j);
    pthread_mutex_unlock(&lock);
}

void diagnostic_tool() {
    int memory_usage = 0, latency_statistics[10] = {0};

    pthread_mutex_lock(&lock);
    for (int i = 0; i < records_count; i++) {
        memory_usage += sizeof(SignalQualityRecord) + signal_quality_records[i]->access_points_count * sizeof(int);
    }

    printf("Memory usage: %d bytes\n", memory_usage);

    // Calculate latency statistics
    pthread_mutex_unlock(&lock);
}

