        pthread_mutex_lock(&lock);
        for (; i < records_count; i++) {
            if (signal_quality_records[i]->timestamp <= threshold) {
                // Perform archival or logging operations
                break;
            }
        }

        pthread_mutex_unlock(&lock);

        sleep(1);  // Simulate processing time
