#include <string.h>

typedef struct {
    int timestamp;
    float signal_strength;
    char frequency_band[16];
    char network_operator[16];
    char metadata[128];
} SignalQualityRecord;

typedef struct {
    SignalQualityRecord* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SignalQualityArray;

void signal_quality_array_init(SignalQualityArray* array, size_t initial_capacity) {
    array->records = (SignalQualityRecord*)malloc(initial_capacity * sizeof(SignalQualityRecord));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void signal_quality_array_add_record(SignalQualityArray* array, SignalQualityRecord record) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->records = (SignalQualityRecord*)realloc(array->records, array->capacity * sizeof(SignalQualityRecord));
    }
    pthread_mutex_lock(&array->lock);
    array->records[array->size] = record;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

void signal_quality_array_update_record_by_frequency_band(SignalQualityArray* array, char frequency_band[], SignalQualityRecord new_record) {
    for (int i = 0; i < array->size; i++) {
        if (strcmp(array->records[i].frequency_band, frequency_band) == 0) {
            pthread_mutex_lock(&array->lock);
            memcpy(&array->records[i], &new_record, sizeof(SignalQualityRecord));
            pthread_mutex_unlock(&array->lock);
            break;
        }
    }
}

void signal_quality_array_filter_by_network_operator(SignalQualityArray* array, char network_operator[]) {
    SignalQualityRecord* new_records = (SignalQualityRecord*)malloc(array->size * sizeof(SignalQualityRecord));
    size_t new_size = 0;
    for (int i = 0; i < array->size; i++) {
        if (strcmp(array->records[i].network_operator, network_operator) == 0) {
            memcpy(&new_records[new_size], &array->records[i], sizeof(SignalQualityRecord));
            new_size++;
        }
    }
    free(array->records);
    array->records = new_records;
    array->size = new_size;
}

void signal_quality_array_destroy(SignalQualityArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->records);
    array->records = NULL;
}
