// dependencies.js - manages dependencies among multiple JavaScript files

let loadedFiles = [];
let executionOrder = [];

function loadAndExecuteFile(filename) {
    if (loadedFiles.includes(filename)) return; // file already loaded

    console.log(`Loading ${filename}...`);
    let scriptTag = document.createElement('script');
    scriptTag.src = filename;
    document.head.appendChild(scriptTag);

    // wait for the file to finish loading and executing
    setTimeout(() => {
        executionOrder.push(filename);
        console.log(`File ${filename} loaded and executed successfully!`);
    }, 0);
}

function checkExecutionOrder() {
    if (executionOrder.length !== loadedFiles.length) {
        console.error('Inconsistent execution order detected!');
        // re-order files as needed
        loadedFiles.sort((a, b) => executionOrder.indexOf(a) - executionOrder.indexOf(b));
        executionOrder = loadedFiles.map(file => file);
    }
}

function handleFileLoadError(filename) {
    console.error(`Failed to load ${filename}!`);
    // fallback strategy: try to execute a backup file or provide an error message
}

// example usage:
loadedFiles = ['file1.js', 'file2.js', 'file3.js'];
executionOrder = [];

loadedFiles.forEach(file => {
    loadAndExecuteFile(file);
});

checkExecutionOrder();
