#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int session_id;
    long start_timestamp;
    struct NetworkEvent* events; // dynamically allocated array
    pthread_mutex_t event_lock;
} UserSession;

typedef struct {
    enum { CONNECT, DISCONNECT, DATA_RECV } type;
    long timestamp;
    int payload_size;
} NetworkEvent;

// Function to initialize and manage an array of UserSession structures
void* init_session_array(int num_sessions) {
    // Allocate memory for the sessions array
    UserSession** sessions = (UserSession**) malloc(num_sessions * sizeof(UserSession*));

    // Initialize each session with a unique ID, start timestamp, and event list
    for (int i = 0; i < num_sessions; i++) {
        sessions[i] = (UserSession*) malloc(sizeof(UserSession));
        sessions[i]->session_id = i;
        sessions[i]->start_timestamp = time(NULL);
        sessions[i]->events = NULL;

        // Initialize the event lock
        pthread_mutex_init(&sessions[i]->event_lock, NULL);
    }

    return sessions;
}

// Function to add a new network event to a session
void add_event(UserSession* session, enum NetworkEvent_type type, long timestamp, int payload_size) {
    // Lock the event list for exclusive access
    pthread_mutex_lock(&session->event_lock);

    // Allocate memory for the new event
    NetworkEvent* new_event = (NetworkEvent*) malloc(sizeof(NetworkEvent));
    new_event->type = type;
    new_event->timestamp = timestamp;
    new_event->payload_size = payload_size;

    // Add the event to the session's list
    if (!session->events) {
        session->events = new_event;
    } else {
        NetworkEvent* current = session->events;
        while (current && current->next) {
            current = current->next;
        }
        current->next = new_event;
    }

    // Unlock the event list
    pthread_mutex_unlock(&session->event_lock);
}

// Function to validate a UserSession structure
int validate_session(UserSession* session) {
    if (!session->events) return 0; // No events, so no inconsistencies

    NetworkEvent* current = session->events;
    long min_timestamp = current->timestamp;
    int max_payload_size = current->payload_size;

    while (current && current->next) {
        if (current->timestamp < min_timestamp || current->payload_size > max_payload_size) {
            return 0; // Inconsistencies found, invalid session
        }

        current = current->next;
    }

    return 1; // Valid session with consistent events
}

// Example usage:
int main() {
    int num_sessions = 5;
    UserSession** sessions = init_session_array(num_sessions);

    for (int i = 0; i < num_sessions; i++) {
        add_event(sessions[i], CONNECT, time(NULL), 1024);
        add_event(sessions[i], DATA_RECV, time(NULL) + 10, 512);
        add_event(sessions[i], DISCONNECT, time(NULL) + 20, 0);
    }

    for (int i = 0; i < num_sessions; i++) {
        if (!validate_session(sessions[i])) {
            printf("Session %d is invalid due to inconsistencies in events.\n", sessions[i]->session_id);
        } else {
            printf("Session %d is valid with consistent events.\n", sessions[i]->session_id);
        }
    }

    // Free the memory allocated for each session
    for (int i = 0; i < num_sessions; i++) {
        free(sessions[i]);
    }
    free(sessions);

    return 0;
}
