#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Configuration file parameters
int N = 0; // Initial number of elements
int M = 0; // Maximum capacity

// Thread-safe list management structure
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} List;

// Lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Serialize the list to a binary file
void serialize_list(const char* filename, const List* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        // Handle error
    }
    fwrite(&list->size, sizeof(int), 1, file);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    fclose(file);
}

// Deserialize the list from a binary file
List* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        // Handle error
    }
    List* list = (List*)malloc(sizeof(List));
    int size;
    fread(&size, sizeof(int), 1, file);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    fclose(file);
    return list;
}

// Initialize the list with initial elements
void init_list(List* list) {
    list->size = N;
    list->capacity = M;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        // Initialize structures with random CRCFLAG values
        list->data[i].RX_UE_INFORMATION_TAG = ...;
        list->data[i].RNTI = ...;
        list->data[i].CRC_INDICATION_REL8_TAG = ...;
    }
}

// Add an element to the list (thread-safe)
void add_element(List* list, NFAPI_CRC_INDICATION_PDU_T* elem) {
    pthread_mutex_lock(&lock);
    if (list->size >= list->capacity) {
        // Handle overflow
        log_error("List overflow");
        return;
    }
    list->data[list->size++] = *elem;
    pthread_mutex_unlock(&lock);
}

// Remove an element from the list (thread-safe)
void remove_element(List* list, int index) {
    pthread_mutex_lock(&lock);
    if (index >= list->size) {
        // Handle out-of-bounds access
        log_error("Invalid index");
        return;
    }
    memmove(list->data + index, list->data + index + 1, (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;
    pthread_mutex_unlock(&lock);
}

// Free the list and its contents
void free_list(List* list) {
    for (int i = 0; i < list->size; i++) {
        // Free individual structures
        free(list->data[i].RX_UE_INFORMATION_TAG);
        free(list->data[i].RNTI);
        free(list->data[i].CRC_INDICATION_REL8_TAG);
    }
    free(list->data);
    free(list);
}
