    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T **crc_indications = NULL;
pthread_mutex_t crc_indications_lock = PTHREAD_MUTEX_INITIALIZER;
int crc_indications_count = 0;

void *create_crc_indication(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_crc_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_crc_indication) {
        return NULL;
    }

    new_crc_indication->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_crc_indication->RNTI = RNTI;
    new_crc_indication->CRC_INDICATION_REL8_TAG = rand() % 1000; // Randomly set CRCFLAG
    new_crc_indication->CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRC flag

    return new_crc_indication;
}

int crc_indication_populate(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_crc_indication = create_crc_indication(RX_UE_INFORMATION_TAG, RNTI);

    if (!new_crc_indication) {
        return -1; // Memory allocation failed
    }

    pthread_mutex_lock(&crc_indications_lock);

    crc_indications = (NFAPI_CRC_INDICATION_PDU_T **)realloc(crc_indications, (crc_indications_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!crc_indications) {
        free(new_crc_indication);
        pthread_mutex_unlock(&crc_indications_lock);
        return -1; // Memory reallocation failed
    }

    crc_indications[crc_indications_count] = new_crc_indication;
    crc_indications_count++;

    pthread_mutex_unlock(&crc_indications_lock);

    return 0; // CRC indication populated successfully
}

void log_crc_indication(int RX_UE_INFORMATION_TAG, int RNTI) {
    // Record the population of each structure with a timestamp and error details
    struct timeval tv;
    gettimeofday(&tv, NULL);
    printf("CRC Indication Populated: TX_%lu, RNTI=%d, RX_UE_INFORMATION_TAG=%d\n", tv.tv_sec, RNTI, RX_UE_INFORMATION_TAG);
}

int crc_indication_validate(int index) {
    if (index < 0 || index >= crc_indications_count) {
        return -1; // Invalid CRC indication index
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_indication = crc_indications[index];

    if (!crc_indication || crc_indication->RX_UE_INFORMATION_TAG < 0 || crc_indication->RNTI < 0) {
        return -1; // CRC indication contains invalid data
    }

    return 0; // CRC indication is valid
}

int get_crc_indications_statistics() {
    int successful_count = 0;
    int failed_count = 0;

    for (int i = 0; i < crc_indications_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *crc_indication = crc_indications[i];

        if (!crc_indication || !crc_indication_validate(i)) {
            failed_count++;
        } else {
            successful_count++;
        }
    }

    printf("CRC Indications Statistics: Successful=%d, Failed=%d\n", successful_count, failed_count);

