int* nfapi_crc_indication_pdu_list_init(int num_sessions) {
    // Initialize the error code
    int error_code = 0;

    // Calculate the total memory required for the session information
    size_t total_memory_required = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_sessions;
    size_t max_memory_usage_threshold = (size_t)(available_system_memory() * 0.5);

    if (total_memory_required > max_memory_usage_threshold) {
        error_code = ERESOURCE_EXCEEDED_MAX_MEMORY_USAGE;
        return NULL; // Return an error code and indicate the function failed
    }

    // Allocate memory for the session information
    NFAPI_CRC_INDICATION_PDU_T** pSessionInfoList = (NFAPI_CRC_INDICATION_PDU_T**)malloc(total_memory_required);
    if (!pSessionInfoList) {
        error_code = EMEMORY_ALLOCATION_FAILURE;
        return NULL; // Return an error code and indicate the function failed
    }

    // Initialize each session information structure with default values
