        pSessionInfoList[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pSessionInfoList[i]) {
            error_code = EMEMORY_ALLOCATION_FAILURE;
            for (int j = 0; j < i; j++) {
                free(pSessionInfoList[j]);
            }
            free(pSessionInfoList);
