void init_srs_rx_info_array(int* size, NFAPI_SRS_RX_INFO_T** array) {
    // Initialize memory for the array
    *array = (NFAPI_SRS_RX_INFO_T*)malloc(*size * sizeof(NFAPI_SRS_RX_INFO_T));

    if (*array == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    int i;
    for (i = 0; i < *size; i++) {
        // Initialize each structure with random power and timestamp
        (*array)[i].UE_ID = rand();
        (*array)[i].TX_ID = rand();
        (*array)[i].SRS_INFO_REL16_TAG.SRS_POWER = ((double)rand()) / RAND_MAX;
        (*array)[i].SRS_INFO_REL16_TAG.SRS_TIMESTAMP = rand();
    }
}

void resize_srs_rx_info_array(int* size, NFAPI_SRS_RX_INFO_T** array) {
    // Free previously allocated memory
    free(*array);

    *array = (NFAPI_SRS_RX_INFO_T*)malloc(*size * sizeof(NFAPI_SRS_RX_INFO_T));
}

void print_srs_rx_info_array(NFAPI_SRS_RX_INFO_T* array, int size) {
    int i;
    for (i = 0; i < size; i++) {
        printf("UE_ID: %d, TX_ID: %d, SRS_POWER: %.2f, SRS_TIMESTAMP: %lld\n", 
               array[i].UE_ID, array[i].TX_ID, array[i].SRS_INFO_REL16_TAG.SRS_POWER, 
               (long long)array[i].SRS_INFO_REL16_TAG.SRS_TIMESTAMP);
    }
}

void clean_srs_rx_info_array(NFAPI_SRS_RX_INFO_T** array, int* size) {
    // Free unused entries
    for (int i = *size - 1; i >= 0; i--) {
        if (array[i]->UE_ID == 0 && array[i]->TX_ID == 0) {
            free(array[i]);
            (*size]--;
        } else {
            break;
        }
    }
}

void export_srs_rx_info_array(NFAPI_SRS_RX_INFO_T* array, int size, const char* filename) {
    FILE* file = fopen(filename, "w");

    if (file == NULL) {
        printf("Failed to open file.\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        fprintf(file, "UE_ID: %d, TX_ID: %d, SRS_POWER: %.2f, SRS_TIMESTAMP: %lld\n", 
                array[i].UE_ID, array[i].TX_ID, array[i].SRS_INFO_REL16_TAG.SRS_POWER, 
                (long long)array[i].SRS_INFO_REL16_TAG.SRS_TIMESTAMP);
    }

    fclose(file);
}

int main() {
    int size = 10;
    NFAPI_SRS_RX_INFO_T* array;

    init_srs_rx_info_array(&size, &array);
    print_srs_rx_info_array(array, size);

    // Perform some operations...
    // Clean up unused entries
    clean_srs_rx_info_array(&array, &size);
    print_srs_rx_info_array(array, size);

    // Export the array to a file
    export_srs_rx_info_array(array, size, "srs_rx_info.txt");

    // Free allocated memory
    free(array);

    return 0;
}

