int checkRNTIUniqueness(NFAPI_CRC_INDICATION_PDU_T** list, unsigned long RNTI) {
    for (int i = 0; i < DEFAULT_SIZE; i++) {
        if (((*list)[i])->RNTI == RNTI) {
            return UNIQUE_RNTI_CHECK;
        }
    }
    return 0;
}

void addElementTo(struct NFAPI_CRC_INDICATION_PDU_T** list, unsigned long RNTI, int CRCFLAG) {
