    (*list)[DEFAULT_SIZE].RNTI = RNTI;
    strcpy((*list)[DEFAULT_SIZE].CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
    (*list)[DEFAULT_SIZE].CRCFLAG = CRCFLAG;
