    int numSamples = tiff->samplesPerPixel;
    NFAPI_CRC_INDICATION_PDU_T* crcList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numSamples * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate the list with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < numSamples; i++) {
        crcList[i].RNTI = rand() % 100;
        crcList[i].CRCFLAG = rand() % 65536;
